INSERT INTO "supabase_migrations"."schema_migrations" ("version", "statements", "name", "created_by", "idempotency_key", "rollback") VALUES ('20260730053146', '{"-- ============================================================
-- Controlled vocabularies
-- ============================================================
create type product_category as enum (
  ''slide'',''barrel'',''frame'',''trigger'',''compensator'',''light'',''optic''
);

create type fitment_confidence as enum (''verified'',''likely'',''unverified'');

create type optic_mounting as enum (''direct'',''plate'',''plate-system'',''none'');

create type barrel_type as enum (''standard'',''threaded'',''ported'',''threaded-and-ported'');

create type footprint_fit as enum (''direct'',''via-plate'');

create type light_fitment_type as enum (
  ''direct'',''adapter-included'',''adapter-required'',''no-fit''
);

create type install_difficulty as enum (''easy'',''moderate'',''hard'',''gunsmith'');

-- ============================================================
-- updated_at helper
-- ============================================================
create or replace function set_updated_at()
returns trigger
language plpgsql
security definer
set search_path = ''''
as $$
begin
  new.updated_at := now();
  return new;
end;
$$;

-- ============================================================
-- Brands and affiliate partners
-- ============================================================
create table manufacturers (
  id          uuid primary key default gen_random_uuid(),
  slug        text not null unique,
  name        text not null,
  website_url text,
  logo_url    text,
  is_oem      boolean not null default false,
  notes       text,
  created_at  timestamptz not null default now(),
  updated_at  timestamptz not null default now(),
  constraint manufacturers_slug_format check (slug ~ ''^[a-z0-9]+(-[a-z0-9]+)*$'')
);

create table partners (
  id              uuid primary key default gen_random_uuid(),
  slug            text not null unique,
  name            text not null,
  base_url        text,
  commission_pct  numeric(5,2),
  tracking_param  text,
  notes           text,
  created_at      timestamptz not null default now(),
  updated_at      timestamptz not null default now(),
  constraint partners_slug_format check (slug ~ ''^[a-z0-9]+(-[a-z0-9]+)*$''),
  constraint partners_commission_range check (commission_pct is null or commission_pct between 0 and 100)
);

-- ============================================================
-- Grip housing taxonomy
--   magazine_family is the fact underneath housing_class:
--   xmacro and fuse are different classes but share one magazine.
-- ============================================================
create table magazine_families (
  magazine_family text primary key,
  display_name    text not null,
  notes           text
);

create table housing_classes (
  housing_class          text primary key,
  display_name           text not null,
  magazine_family        text not null references magazine_families(magazine_family),
  grip_length            text,
  typical_slide_length_in numeric(3,1),
  -- Shortest slide the grip can run without the grip overhanging the slide.
  -- Drives the slide<->frame fit view. See notes in seed data.
  min_slide_length_in    numeric(3,1),
  notes                  text
);

comment on column housing_classes.typical_slide_length_in is
  ''Buyer recognition only. Does NOT gate fit. Use min_slide_length_in for fit logic.'';
comment on column housing_classes.min_slide_length_in is
  ''Fit gate: a slide shorter than this leaves the grip overhanging. Slide longer is fine (intentional overhang).'';

-- ============================================================
-- Platforms (housing-level, not SKU-level)
-- ============================================================
create table platforms (
  id              uuid primary key default gen_random_uuid(),
  slug            text not null unique,
  name            text not null,
  housing_class   text not null references housing_classes(housing_class),
  frame_material  text,
  slide_length_in numeric(3,1),
  oem_capacity    text,
  integrated_comp boolean not null default false,
  notes           text
);

-- Normalizes the semicolon-delimited sku_platform_ids column.
-- One row per gun-DB SKU id that rolls up to a platform.
create table platform_skus (
  platform_id       uuid not null references platforms(id) on delete cascade,
  gun_db_platform_id text not null,
  primary key (platform_id, gun_db_platform_id)
);

-- ============================================================
-- Optic cuts and footprints
-- ============================================================
create table optic_cuts (
  optic_cut    text primary key,
  display_name text not null,
  mounting     optic_mounting not null,
  notes        text
);

create table footprints (
  id                uuid primary key default gen_random_uuid(),
  slug              text not null unique,
  common_name       text not null,
  also_known_as     text,
  originating_optic text,
  notes             text
);

-- Normalizes optic_cuts.fits_footprints. Cut-level, never SKU-level.
create table optic_cut_footprints (
  optic_cut    text not null references optic_cuts(optic_cut) on delete cascade,
  footprint_id uuid not null references footprints(id) on delete cascade,
  fit          footprint_fit not null default ''direct'',
  notes        text,
  primary key (optic_cut, footprint_id)
);

-- ============================================================
-- Accessory rail standards
-- ============================================================
create table rail_types (
  rail_type    text primary key,
  display_name text not null,
  spec         text,
  description  text,
  example_guns text
);

create trigger manufacturers_updated_at before update on manufacturers
  for each row execute function set_updated_at();
create trigger partners_updated_at before update on partners
  for each row execute function set_updated_at();"}', 'enums_and_reference_tables', 'ag.gamboa94@gmail.com', NULL, NULL);
INSERT INTO "supabase_migrations"."schema_migrations" ("version", "statements", "name", "created_by", "idempotency_key", "rollback") VALUES ('20260730053220', '{"-- ============================================================
-- PRODUCTS — one row per MODEL, all categories
-- Category-specific columns live in the *_specs tables.
-- ============================================================
create table products (
  id                    uuid primary key default gen_random_uuid(),
  slug                  text not null unique,
  category              product_category not null,
  brand_id              uuid not null references manufacturers(id) on delete restrict,

  name                  text not null,
  family                text,
  url                   text,

  -- Fitment / safety
  fitment_confidence    fitment_confidence not null default ''unverified'',
  build_warning         text,
  fitment_notes         text,
  build_notes           text,
  installation_difficulty install_difficulty,

  -- Shared physical attributes
  material              text,
  weight_oz             numeric(6,2),

  -- Editorial
  description           text,
  best_for              text[] not null default ''{}'',
  pros                  text,
  cons                  text,
  editor_rating         numeric(2,1),

  -- Display price only. Real price is per variant.
  base_price            numeric(10,2),

  is_discontinued       boolean not null default false,
  internal_notes        text,

  -- Written by the scheduled repricing job, NOT by hand.
  lowest_price          numeric(10,2),
  lowest_price_variant_id uuid,
  lowest_price_updated_at timestamptz,

  created_at            timestamptz not null default now(),
  updated_at            timestamptz not null default now(),

  constraint products_slug_format check (slug ~ ''^[a-z0-9]+(-[a-z0-9]+)*$''),
  constraint products_rating_range check (editor_rating is null or editor_rating between 0 and 5),
  constraint products_weight_positive check (weight_oz is null or weight_oz > 0),
  constraint products_base_price_positive check (base_price is null or base_price >= 0)
);

comment on column products.base_price is ''Display only. Authoritative price is product_variants.msrp.'';
comment on column products.lowest_price is ''Machine-written by the repricing job. Do not hand-edit.'';

-- ============================================================
-- PRODUCT_VARIANTS — one row per BUYABLE SKU
-- Slides: (color, finish, optic_cut). Others: (color, finish).
-- ============================================================
create table product_variants (
  id                    uuid primary key default gen_random_uuid(),
  slug                  text not null unique,
  product_id            uuid not null references products(id) on delete cascade,

  color                 text,
  finish                text,

  -- Variant axis for slides only; null elsewhere.
  optic_cut             text references optic_cuts(optic_cut),

  -- Variant axis for frames and triggers.
  manual_safety_variant boolean,

  -- Variant axes for lights.
  bundle                text,
  clamp                 text,
  mount_system          text,

  sku                   text,
  upc                   text,
  msrp                  numeric(10,2),

  is_default            boolean not null default false,
  is_discontinued       boolean not null default false,

  primary_image_url     text,
  notes                 text,

  created_at            timestamptz not null default now(),
  updated_at            timestamptz not null default now(),

  constraint variants_slug_format check (slug ~ ''^[a-z0-9]+(-[a-z0-9]+)*$''),
  constraint variants_msrp_positive check (msrp is null or msrp >= 0),
  constraint variants_upc_digits check (upc is null or upc ~ ''^[0-9]{8,14}$'')
);

-- Exactly one default variant per product.
create unique index variants_one_default_per_product
  on product_variants (product_id) where is_default;

-- No duplicate SKU axes within a product.
create unique index variants_unique_axes
  on product_variants (product_id, color, finish, optic_cut, manual_safety_variant, bundle, clamp)
  nulls not distinct;

create index variants_product_idx on product_variants (product_id);

-- Close the circular reference from products.
alter table products
  add constraint products_lowest_price_variant_fkey
  foreign key (lowest_price_variant_id)
  references product_variants(id) on delete set null;

-- ============================================================
-- VARIANT_IMAGES — normalizes gallery_image_1..3
-- ============================================================
create table variant_images (
  id         uuid primary key default gen_random_uuid(),
  variant_id uuid not null references product_variants(id) on delete cascade,
  url        text not null,
  position   smallint not null default 1,
  alt_text   text,
  unique (variant_id, position),
  constraint variant_images_position_positive check (position > 0)
);

-- ============================================================
-- AFFILIATE_LINKS — one row per VARIANT per partner
-- ============================================================
create table affiliate_links (
  id            uuid primary key default gen_random_uuid(),
  variant_id    uuid not null references product_variants(id) on delete cascade,
  partner_id    uuid references partners(id) on delete set null,

  url           text not null,
  affiliate_url text,
  street_price  numeric(10,2),
  in_stock      boolean,
  is_primary    boolean not null default false,
  last_checked  date,
  notes         text,

  created_at    timestamptz not null default now(),
  updated_at    timestamptz not null default now(),

  constraint affiliate_street_price_positive check (street_price is null or street_price >= 0)
);

create unique index affiliate_one_primary_per_variant
  on affiliate_links (variant_id) where is_primary;

create index affiliate_variant_idx on affiliate_links (variant_id);
create index affiliate_partner_idx on affiliate_links (partner_id);

-- ============================================================
-- Indexes for site browse / filter
-- ============================================================
create index products_category_idx on products (category) where not is_discontinued;
create index products_brand_idx on products (brand_id);
create index products_best_for_idx on products using gin (best_for);
create index products_confidence_idx on products (fitment_confidence);

-- Site-wide search
alter table products add column search_vector tsvector
  generated always as (
    setweight(to_tsvector(''english'', coalesce(name, '''')), ''A'') ||
    setweight(to_tsvector(''english'', coalesce(family, '''')), ''B'') ||
    setweight(to_tsvector(''english'', coalesce(description, '''')), ''C'')
  ) stored;

create index products_search_idx on products using gin (search_vector);

create trigger products_updated_at before update on products
  for each row execute function set_updated_at();
create trigger variants_updated_at before update on product_variants
  for each row execute function set_updated_at();
create trigger affiliate_updated_at before update on affiliate_links
  for each row execute function set_updated_at();"}', 'product_spine', 'ag.gamboa94@gmail.com', NULL, NULL);
INSERT INTO "supabase_migrations"."schema_migrations" ("version", "statements", "name", "created_by", "idempotency_key", "rollback") VALUES ('20260730053315', '{"-- Enables composite FKs that pin each spec table to the right category,
-- so a trigger product can never receive a slide_specs row.
create unique index products_id_category_key on products (id, category);

-- ============================================================
-- SLIDES
-- slide_length_in = published slide BODY length (drives fit).
-- barrel_length_in = actual barrel; shorter on a comp slide.
-- ============================================================
create table slide_specs (
  product_id            uuid primary key references products(id) on delete cascade,
  category              product_category not null default ''slide'',

  slide_length_in       numeric(3,1) not null,
  slide_class           text generated always as (
                          case slide_length_in
                            when 3.1 then ''p365''
                            when 3.7 then ''xl''
                            when 4.3 then ''fuse''
                          end
                        ) stored,
  barrel_length_in      numeric(3,1),

  comes_with_sights     boolean,
  barrel_included       boolean,
  window_cuts           boolean,
  internally_ported     boolean,
  port_style            text,
  port_count            smallint,
  integrated_comp       boolean,
  threaded_barrel_ok    boolean,
  required_spring_weight text,

  constraint slide_specs_category check (category = ''slide''),
  constraint slide_specs_product_fkey
    foreign key (product_id, category) references products(id, category),
  constraint slide_length_valid check (slide_length_in in (3.1, 3.7, 4.3)),
  constraint slide_barrel_not_longer check (
    barrel_length_in is null or barrel_length_in <= slide_length_in
  )
);

comment on column slide_specs.slide_length_in is
  ''Published slide body length. A comp slide is 3.7 even when its internal barrel is 3.1.'';
comment on column slide_specs.slide_class is ''Derived from slide_length_in. Never hand-typed.'';

-- ============================================================
-- BARRELS
-- ============================================================
create table barrel_specs (
  product_id            uuid primary key references products(id) on delete cascade,
  category              product_category not null default ''barrel'',

  barrel_length_in      numeric(3,1) not null,
  barrel_class          text generated always as (
                          case barrel_length_in
                            when 3.1 then ''p365''
                            when 3.7 then ''xl''
                            when 4.3 then ''fuse''
                          end
                        ) stored,

  caliber               text not null default ''9mm'',
  barrel_type           barrel_type not null,
  thread_pitch          text,
  port_style            text,
  is_lci                boolean,
  ballistic_loss        text,

  -- Human-readable, word-for-word from the maker. The machine-enforceable
  -- version is the barrel_slide_requirements table.
  requires_slide_text   text,

  -- Proprietary non-threaded mounts (e.g. Radian INTRA-LOK) pair with ONE comp.
  pairs_with_comp_id    uuid references products(id) on delete set null,

  constraint barrel_specs_category check (category = ''barrel''),
  constraint barrel_specs_product_fkey
    foreign key (product_id, category) references products(id, category),
  constraint barrel_length_valid check (barrel_length_in in (3.1, 3.7, 4.3)),
  -- Threads must be specified when the barrel claims to have them.
  constraint barrel_thread_consistency check (
    barrel_type not in (''threaded'',''threaded-and-ported'') or thread_pitch is not null
  )
);

-- ============================================================
-- FRAMES / GRIP MODULES
-- No compatibility table: housing_class says everything.
-- magazine_family is derived through housing_classes, never stored here.
-- ============================================================
create table frame_specs (
  product_id            uuid primary key references products(id) on delete cascade,
  category              product_category not null default ''frame'',

  housing_class         text not null references housing_classes(housing_class),
  frame_material        text,

  has_rail              boolean,
  rail_type             text references rail_types(rail_type),

  has_beaver_tail       boolean,
  undercut_trigger_guard boolean,
  palm_swell            boolean,
  magwell_type          text,
  grip_texture          text,
  finger_grooves        boolean,
  thumb_rest            boolean,
  thumb_stippling       boolean,

  includes_hardware     boolean,
  hardware_notes        text,

  constraint frame_specs_category check (category = ''frame''),
  constraint frame_specs_product_fkey
    foreign key (product_id, category) references products(id, category),
  constraint frame_rail_consistency check (
    has_rail is not true or rail_type is not null
  )
);

-- ============================================================
-- TRIGGERS
-- ============================================================
create table trigger_specs (
  product_id       uuid primary key references products(id) on delete cascade,
  category         product_category not null default ''trigger'',

  profile          text,
  pull_weight_lb   numeric(4,2),
  pull_weight_text text,
  adjustable       boolean not null default false,
  adjustment_type  text,
  safety_type      text,

  constraint trigger_specs_category check (category = ''trigger''),
  constraint trigger_specs_product_fkey
    foreign key (product_id, category) references products(id, category),
  constraint trigger_pull_range check (pull_weight_lb is null or pull_weight_lb between 1 and 15)
);

-- ============================================================
-- COMPENSATORS
-- ============================================================
create table compensator_specs (
  product_id               uuid primary key references products(id) on delete cascade,
  category                 product_category not null default ''compensator'',

  caliber                  text not null default ''9mm'',
  mounting_type            text,
  requires_threaded_barrel boolean not null default false,
  thread_pitch             text,

  comes_with_barrel        boolean not null default false,
  included_barrel          text,
  barrel_length_in         numeric(3,1),

  port_design              text,
  muzzle_flip_reduction    text,
  length_in                numeric(4,2),

  constraint comp_specs_category check (category = ''compensator''),
  constraint comp_specs_product_fkey
    foreign key (product_id, category) references products(id, category),
  constraint comp_thread_consistency check (
    not requires_threaded_barrel or thread_pitch is not null
  ),
  -- A barrel length only makes sense when a barrel is actually included.
  constraint comp_barrel_length_consistency check (
    comes_with_barrel or barrel_length_in is null
  )
);

-- ============================================================
-- WEAPON LIGHTS
-- ============================================================
create table light_specs (
  product_id    uuid primary key references products(id) on delete cascade,
  category      product_category not null default ''light'',

  series        text,
  config_note   text,
  mount_system  text,

  lumens_max    integer,
  candela_max   integer,
  beam_type     text,

  has_laser     boolean not null default false,
  laser_color   text,

  battery_type  text,
  rechargeable  boolean,
  length_in     numeric(4,2),
  ipx_rating    text,

  constraint light_specs_category check (category = ''light''),
  constraint light_specs_product_fkey
    foreign key (product_id, category) references products(id, category),
  constraint light_lumens_positive check (lumens_max is null or lumens_max > 0),
  constraint light_candela_positive check (candela_max is null or candela_max > 0),
  constraint light_laser_consistency check (has_laser or laser_color is null)
);

-- ============================================================
-- OPTICS / RED DOTS
-- ============================================================
create table optic_specs (
  product_id          uuid primary key references products(id) on delete cascade,
  category            product_category not null default ''optic'',

  footprint_id        uuid not null references footprints(id) on delete restrict,
  optic_type          text,
  mount_height        text,

  reticle             text,
  selectable_reticle  boolean,
  reticle_type        text,
  dot_size_moa        numeric(4,1),
  magnification       text,
  window_size         text,

  emitter             text,
  enclosed_emitter    boolean,
  brightness_settings text,
  auto_on_off         boolean,
  shake_awake         boolean,
  adjustment_per_click text,

  battery_type        text,
  battery_location    text,
  removable_battery   boolean,
  battery_life        text,
  solar_power         boolean,

  housing_material    text,

  constraint optic_specs_category check (category = ''optic''),
  constraint optic_specs_product_fkey
    foreign key (product_id, category) references products(id, category),
  constraint optic_dot_size_positive check (dot_size_moa is null or dot_size_moa > 0)
);

create index barrel_specs_pairs_comp_idx on barrel_specs (pairs_with_comp_id);
create index frame_specs_housing_idx on frame_specs (housing_class);
create index optic_specs_footprint_idx on optic_specs (footprint_id);"}', 'category_spec_tables', 'ag.gamboa94@gmail.com', NULL, NULL);
INSERT INTO "supabase_migrations"."schema_migrations" ("version", "statements", "name", "created_by", "idempotency_key", "rollback") VALUES ('20260730053335', '{"-- ============================================================
-- BARREL -> SLIDE hard requirement
-- Normalizes requires_slide_slugs. Ported barrels are frequently designed
-- for ONE slide and are dangerous in the wrong one, so this powers a
-- hard block, not a warning.
-- Absence of rows = fits any slide of matching barrel length.
-- ============================================================
create table barrel_slide_requirements (
  barrel_product_id uuid not null references barrel_specs(product_id) on delete cascade,
  slide_product_id  uuid not null references slide_specs(product_id) on delete cascade,
  source            text,
  primary key (barrel_product_id, slide_product_id)
);

create index barrel_slide_req_slide_idx on barrel_slide_requirements (slide_product_id);

comment on table barrel_slide_requirements is
  ''Whitelist. If a barrel has ANY row here, it fits ONLY those slides.'';

-- ============================================================
-- OPTIC -> extra footprints reachable via an included/available plate
-- Normalizes adapter_footprints. The optic''''s native footprint stays on
-- optic_specs.footprint_id.
-- ============================================================
create table optic_adapter_footprints (
  optic_product_id uuid not null references optic_specs(product_id) on delete cascade,
  footprint_id     uuid not null references footprints(id) on delete cascade,
  plate_included   boolean not null default false,
  notes            text,
  primary key (optic_product_id, footprint_id)
);

-- ============================================================
-- LIGHT -> RAIL / PLATFORM compatibility
-- Genuinely enumerated and hand-verified, so it stays a table.
-- platform_id is set when the target is a known P365 platform;
-- gun_model_text carries everything outside the P365 family.
-- ============================================================
create table light_compatibility (
  id               uuid primary key default gen_random_uuid(),
  light_product_id uuid not null references light_specs(product_id) on delete cascade,
  rail_type        text not null references rail_types(rail_type),

  fitment_type     light_fitment_type not null,
  key_or_adapter   text,

  gun_make         text,
  platform_id      uuid references platforms(id) on delete set null,
  gun_model_text   text,

  confirmed        boolean not null default false,
  notes            text,
  created_at       timestamptz not null default now(),

  -- An adapter-required fit is meaningless without naming the adapter.
  constraint light_compat_adapter_named check (
    fitment_type <> ''adapter-required'' or key_or_adapter is not null
  ),
  -- Must identify the target somehow.
  constraint light_compat_target_present check (
    platform_id is not null or gun_model_text is not null
  )
);

create unique index light_compat_unique_fit
  on light_compatibility (light_product_id, rail_type, platform_id, gun_model_text)
  nulls not distinct;

create index light_compat_light_idx on light_compatibility (light_product_id);
create index light_compat_rail_idx on light_compatibility (rail_type);
create index light_compat_platform_idx on light_compatibility (platform_id);

-- ============================================================
-- ADAPTER / SPARE PARTS
-- part_type distinguishes parts that ADD fitment from spares that don''''t.
-- ============================================================
create table adapter_parts (
  id               uuid primary key default gen_random_uuid(),
  slug             text not null unique,
  name             text not null,
  brand_id         uuid references manufacturers(id) on delete set null,
  sku_or_source    text,
  part_type        text not null,

  light_product_id uuid references light_specs(product_id) on delete set null,
  fits_lights_text text,
  enables          text,

  approx_price_low  numeric(10,2),
  approx_price_high numeric(10,2),
  notes            text,

  constraint adapter_slug_format check (slug ~ ''^[a-z0-9]+(-[a-z0-9]+)*$''),
  constraint adapter_price_order check (
    approx_price_high is null or approx_price_low is null
    or approx_price_high >= approx_price_low
  )
);

create index adapter_parts_light_idx on adapter_parts (light_product_id);"}', 'compatibility_tables', 'ag.gamboa94@gmail.com', NULL, NULL);
INSERT INTO "supabase_migrations"."schema_migrations" ("version", "statements", "name", "created_by", "idempotency_key", "rollback") VALUES ('20260730053420', '{"-- ============================================================
-- SLIDE <-> FRAME
-- Every slide fits every frame mechanically (shared FCU rails).
-- The only question is the length comparison, so this returns ALL pairs
-- with a verdict rather than filtering.
-- ============================================================
create view v_slide_frame_fit with (security_invoker = true) as
select
  sl.product_id                       as slide_product_id,
  fr.product_id                       as frame_product_id,
  sl.slide_length_in,
  sl.slide_class,
  fr.housing_class,
  hc.min_slide_length_in,
  (sl.slide_length_in >= hc.min_slide_length_in) as fits,
  case
    when sl.slide_length_in < hc.min_slide_length_in
      then ''Grip module extends past the slide. Not a usable build.''
    when sl.slide_length_in > hc.min_slide_length_in
      then ''Slide overhangs the grip. Intentional and fine.''
    else ''Flush fit.''
  end                                 as verdict
from slide_specs sl
cross join frame_specs fr
join housing_classes hc on hc.housing_class = fr.housing_class;

-- ============================================================
-- BARREL <-> SLIDE
-- Length must match the slide''''s ACTUAL barrel length (not its body
-- length -- comp slides carry a shorter internal barrel).
-- A barrel with any requirement rows fits ONLY those slides.
-- ============================================================
create view v_barrel_slide_fit with (security_invoker = true) as
select
  b.product_id as barrel_product_id,
  s.product_id as slide_product_id,
  b.barrel_length_in as barrel_length_in,
  s.barrel_length_in as slide_barrel_length_in,
  b.barrel_type,
  case
    when s.barrel_length_in is null then ''unknown''
    when exists (select 1 from barrel_slide_requirements r
                 where r.barrel_product_id = b.product_id)
     and not exists (select 1 from barrel_slide_requirements r
                     where r.barrel_product_id = b.product_id
                       and r.slide_product_id = s.product_id)
      then ''blocked''
    when b.barrel_length_in <> s.barrel_length_in then ''length-mismatch''
    else ''fits''
  end as fit_status,
  case
    when s.barrel_length_in is null
      then ''Slide barrel length not recorded. Verify before building.''
    when exists (select 1 from barrel_slide_requirements r
                 where r.barrel_product_id = b.product_id)
     and not exists (select 1 from barrel_slide_requirements r
                     where r.barrel_product_id = b.product_id
                       and r.slide_product_id = s.product_id)
      then ''Maker specifies this barrel for other slides only. Do not build.''
    when b.barrel_length_in <> s.barrel_length_in
      then ''Barrel length does not match the slide.''
    else ''Compatible.''
  end as verdict
from barrel_specs b
cross join slide_specs s;

-- ============================================================
-- OPTIC <-> SLIDE VARIANT
-- Footprint logic is cut-level, so it joins through the slide VARIANT
-- (optic_cut is a variant axis) rather than the slide product.
-- Returns matches only.
-- ============================================================
create view v_optic_slide_variant_fit with (security_invoker = true) as
select distinct
  o.product_id     as optic_product_id,
  v.id             as slide_variant_id,
  v.product_id     as slide_product_id,
  v.optic_cut,
  oc.mounting,
  fp.slug          as footprint_slug,
  case
    when ocf.footprint_id = o.footprint_id and ocf.fit = ''direct'' then ''direct''
    else ''plate''
  end              as mount_method,
  (ocf.footprint_id <> o.footprint_id) as uses_optic_adapter
from optic_specs o
join product_variants v on v.optic_cut is not null
join optic_cuts oc on oc.optic_cut = v.optic_cut
join optic_cut_footprints ocf on ocf.optic_cut = v.optic_cut
join footprints fp on fp.id = ocf.footprint_id
where oc.mounting <> ''none''
  and (
    ocf.footprint_id = o.footprint_id
    or exists (
      select 1 from optic_adapter_footprints oaf
      where oaf.optic_product_id = o.product_id
        and oaf.footprint_id = ocf.footprint_id
    )
  );

-- ============================================================
-- COMPENSATOR <-> BARREL
-- Standard 1/2x28 threads = any comp fits. Proprietary mounts pair with
-- exactly one comp, recorded on barrel_specs.pairs_with_comp_id.
-- ============================================================
create view v_comp_barrel_fit with (security_invoker = true) as
select
  c.product_id as comp_product_id,
  b.product_id as barrel_product_id,
  c.thread_pitch as comp_thread_pitch,
  b.thread_pitch as barrel_thread_pitch,
  case
    when b.pairs_with_comp_id = c.product_id then ''fits-proprietary''
    when b.pairs_with_comp_id is not null then ''blocked-proprietary''
    when not c.requires_threaded_barrel then ''fits''
    when b.barrel_type not in (''threaded'',''threaded-and-ported'') then ''needs-threaded-barrel''
    when c.thread_pitch is distinct from b.thread_pitch then ''thread-mismatch''
    else ''fits''
  end as fit_status
from compensator_specs c
cross join barrel_specs b;

-- ============================================================
-- Frames with magazine_family resolved through the housing taxonomy.
-- This is why magazine_family is not stored on frame_specs: a fuse and an
-- xmacro module are different classes that MUST resolve to one magazine.
-- ============================================================
create view v_frame_fitment with (security_invoker = true) as
select
  f.product_id,
  p.slug,
  p.name,
  f.housing_class,
  hc.display_name as housing_display_name,
  hc.magazine_family,
  hc.min_slide_length_in,
  f.rail_type
from frame_specs f
join products p on p.id = f.product_id
join housing_classes hc on hc.housing_class = f.housing_class;

-- ============================================================
-- Live pricing rollup. The lowest_price columns on products stay for the
-- scheduled job, but this is always correct without waiting for it.
-- ============================================================
create view v_product_pricing with (security_invoker = true) as
select
  p.id as product_id,
  p.slug,
  p.category,
  min(al.street_price) filter (where al.in_stock) as lowest_in_stock_price,
  min(al.street_price)                            as lowest_any_price,
  min(v.msrp)                                     as lowest_msrp,
  count(distinct v.id) filter (where not v.is_discontinued) as active_variant_count,
  max(al.last_checked)                            as price_last_checked
from products p
left join product_variants v on v.product_id = p.id
left join affiliate_links al on al.variant_id = v.id
group by p.id, p.slug, p.category;"}', 'fit_rule_views', 'ag.gamboa94@gmail.com', NULL, NULL);
INSERT INTO "supabase_migrations"."schema_migrations" ("version", "statements", "name", "created_by", "idempotency_key", "rollback") VALUES ('20260730053449', '{"-- ============================================================
-- Internal notes move to their own table.
-- Reason: with RLS, a public read policy on products would expose
-- internal_notes to anon. Column-level revokes break select(''*'') in the
-- client. A separate table with NO anon policy is leak-proof and keeps
-- the client query simple.
-- ============================================================
create table product_internal (
  product_id     uuid primary key references products(id) on delete cascade,
  internal_notes text,
  updated_at     timestamptz not null default now()
);

insert into product_internal (product_id, internal_notes)
select id, internal_notes from products where internal_notes is not null;

alter table products drop column internal_notes;

create trigger product_internal_updated_at before update on product_internal
  for each row execute function set_updated_at();

-- ============================================================
-- Enable RLS everywhere
-- ============================================================
alter table manufacturers              enable row level security;
alter table partners                   enable row level security;
alter table magazine_families          enable row level security;
alter table housing_classes            enable row level security;
alter table platforms                  enable row level security;
alter table platform_skus              enable row level security;
alter table optic_cuts                 enable row level security;
alter table footprints                 enable row level security;
alter table optic_cut_footprints       enable row level security;
alter table rail_types                 enable row level security;
alter table products                   enable row level security;
alter table product_variants           enable row level security;
alter table variant_images             enable row level security;
alter table affiliate_links            enable row level security;
alter table slide_specs                enable row level security;
alter table barrel_specs               enable row level security;
alter table frame_specs                enable row level security;
alter table trigger_specs              enable row level security;
alter table compensator_specs          enable row level security;
alter table light_specs                enable row level security;
alter table optic_specs                enable row level security;
alter table barrel_slide_requirements  enable row level security;
alter table optic_adapter_footprints   enable row level security;
alter table light_compatibility        enable row level security;
alter table adapter_parts              enable row level security;
alter table product_internal           enable row level security;

-- ============================================================
-- Public catalog: read-only for anon + authenticated.
-- All writes go through the service_role key, which bypasses RLS.
-- ============================================================
do $$
declare t text;
begin
  foreach t in array array[
    ''manufacturers'',''partners'',''magazine_families'',''housing_classes'',
    ''platforms'',''platform_skus'',''optic_cuts'',''footprints'',
    ''optic_cut_footprints'',''rail_types'',''products'',''product_variants'',
    ''variant_images'',''affiliate_links'',''slide_specs'',''barrel_specs'',
    ''frame_specs'',''trigger_specs'',''compensator_specs'',''light_specs'',
    ''optic_specs'',''barrel_slide_requirements'',''optic_adapter_footprints'',
    ''light_compatibility'',''adapter_parts''
  ]
  loop
    execute format(
      ''create policy %I on public.%I for select to anon, authenticated using (true)'',
      t || ''_public_read'', t
    );
  end loop;
end $$;

-- product_internal deliberately gets NO policy.
-- RLS on with zero policies = nobody reads it except service_role.

comment on table product_internal is
  ''Staff-only. RLS enabled with no policies, so anon and authenticated cannot read it.'';"}', 'rls_and_internal_notes_split', 'ag.gamboa94@gmail.com', NULL, NULL);
INSERT INTO "supabase_migrations"."schema_migrations" ("version", "statements", "name", "created_by", "idempotency_key", "rollback") VALUES ('20260730053629', '{"-- set_updated_at is a trigger helper, not an API endpoint. Triggers run as
-- the table owner regardless of EXECUTE grants, so revoking is safe.
revoke execute on function public.set_updated_at() from anon, authenticated, public;"}', 'harden_trigger_function', 'ag.gamboa94@gmail.com', NULL, NULL);
INSERT INTO "supabase_migrations"."schema_migrations" ("version", "statements", "name", "created_by", "idempotency_key", "rollback") VALUES ('20260730055043', '{"-- The platforms table conflated slide body length with barrel length on
-- comp guns. Split them, same convention as slide_specs.
alter table platforms add column barrel_length_in numeric(3,1);

comment on column platforms.slide_length_in is
  ''Published slide BODY length. A comp gun is 3.7 even when its barrel is 3.1 -- the comp lives inside the body.'';
comment on column platforms.barrel_length_in is
  ''Actual barrel length. Shorter than slide_length_in on integrated-comp platforms.'';

alter table platforms
  add constraint platforms_barrel_not_longer check (
    barrel_length_in is null or slide_length_in is null
    or barrel_length_in <= slide_length_in
  );

-- Backfill: barrel equals slide except on the integrated-comp AXG Legion.
update platforms set barrel_length_in = slide_length_in where not integrated_comp;

-- AXG Legion: 3.7 slide body, 3.1 barrel behind the integrated comp.
update platforms
   set slide_length_in = 3.7, barrel_length_in = 3.1
 where slug = ''p365-axg'';

-- xmacro grips need a 3.7 slide. No factory 3.1 xmacro config exists.
update housing_classes
   set min_slide_length_in = 3.7,
       notes = ''Macro magazine. Runs a 3.7 slide; the COMP and AXG Legion variants are 3.7 slides with a 3.1 barrel behind the comp.''
 where housing_class = ''xmacro'';"}', 'fix_xmacro_slide_length_and_platform_barrel', 'ag.gamboa94@gmail.com', NULL, NULL);
INSERT INTO "supabase_migrations"."schema_migrations" ("version", "statements", "name", "created_by", "idempotency_key", "rollback") VALUES ('20260730144551', '{"-- ============================================================
-- 1. New manufacturers
-- ============================================================
insert into manufacturers (slug, name, website_url, is_oem, notes) values
  (''trijicon'',''Trijicon'',''https://www.trijicon.com'',false,''Red dot optics (RMR, RMRcc, SRO)''),
  (''zaffiri-precision'',''Zaffiri Precision'',''https://zaffiriprecision.com'',false,''Slides and barrels''),
  (''inception-defense'',''Inception Defense'',null,false,''Light rail adapters''),
  (''mie-productions'',''MIE Productions'',null,false,''Light rail adapters'')
on conflict (slug) do nothing;

-- ============================================================
-- 2. Footprint dictionary now lives in shared reference. Resync.
-- ============================================================
update footprints f set
  also_known_as     = v.aka,
  originating_optic = v.orig,
  notes             = v.note
from (values
  (''holosun-507k'',''EPS Carry, 507K X2, 407K, 507Comp, Staccato XL'',''Holosun 507K'',''K-Footprint. EPS Carry ships with RMSc adapter plate.''),
  (''rmr'',''SRO, RMR Type 2, RM06, RCR, RMR HD'',''Trijicon RMR'',''Full-size footprint. Most common on duty/competition guns.''),
  (''rmsc'',''Holosun 407K (stand-alone RMSc), Shield RMSc'',''Trijicon RMSc'',''Compact/micro. 507K K-footprint shares this on many slides.''),
  (''rmrcc'',''RMRcc, CC06, CC07'',''Trijicon RMRcc'',''Smaller/slimmer than RMR -- NOT interchangeable. CC-specific.''),
  (''deltapoint-pro'',''DPP'',''Leupold DeltaPoint Pro'',''Wide low-profile window. Unique pattern -- verify slide.''),
  (''acro-p2'',''ACRO P-1'',''Aimpoint ACRO'',''Enclosed emitter, sealed. Growing LE/military adoption.''),
  (''romeo1pro'',''Romeo2 (partial)'',''Sig Sauer Romeo1 Pro'',''Common on P320/P365 family. Sig proprietary.''),
  (''shield-sms'',''Shield RMSw'',''Shield Sights SMS'',''UK-made compact. SMS2 adds waterproofing.''),
  (''venom'',''Burris Fastfire 3'',''Vortex Venom'',''Budget footprint shared with Burris FF3. Common on aftermarket slides.''),
  (''c-more'',''C-More Serendipity, Railway'',''C-More Systems STS'',''Large window, open emitter. Popular in USPSA/IPSC.''),
  (''jpoint'',''Redfield Accelerator, Doctor'',''JPoint Optics'',''Older micro footprint, less common on new slides.''),
  (''universal'',null,null,''Only when optic truly fits any standard mount. Rare for pistol RDS.'')
) as v(slug, aka, orig, note)
where f.slug = v.slug;

-- ============================================================
-- 3. Grip rail vocabulary -- SEPARATE from light rail_types.
-- A grip advertises ''picatinny'' or ''proprietary''; a light clamps to
-- ''1913-short'' or ''sig-365''. Collapsing them loses the fact that an
-- XMACRO factory pic rail takes a short-1913 clamp and NOT a SIG-365 one.
-- ============================================================
create table grip_rail_types (
  grip_rail_type text primary key,
  display_name   text not null,
  description    text
);

insert into grip_rail_types values
  (''picatinny'',''Picatinny'',''Grip module with a Picatinny accessory rail.''),
  (''proprietary'',''Proprietary'',''Manufacturer-specific rail profile, not Picatinny.''),
  (''none'',''No rail'',''Railless grip module. Takes no weapon light.'');

-- Repoint frame_specs at the grip vocabulary.
alter table frame_specs drop constraint frame_specs_rail_type_fkey;
alter table frame_specs rename column rail_type to grip_rail_type;

-- Undo the earlier lossy mapping of ''proprietary'' -> ''sig-365''.
update frame_specs set grip_rail_type = ''proprietary'' where grip_rail_type = ''sig-365'';
update frame_specs set grip_rail_type = ''none'' where has_rail is false;

alter table frame_specs
  add constraint frame_specs_grip_rail_fkey
  foreign key (grip_rail_type) references grip_rail_types(grip_rail_type);

alter table frame_specs drop constraint frame_rail_consistency;
alter table frame_specs add constraint frame_rail_consistency check (
  (has_rail is not true or grip_rail_type is not null)
  and (has_rail is not false or grip_rail_type is null or grip_rail_type = ''none'')
);

-- ============================================================
-- 4. RAIL BRIDGE -- resolves a grip module to the light rail standard
-- its rail actually presents. This is what connects the Frames DB to
-- the Lights DB; they share no vocabulary otherwise.
-- ============================================================
create table rail_bridge (
  grip_housing_class text not null references housing_classes(housing_class) on delete cascade,
  grip_rail_type     text not null references grip_rail_types(grip_rail_type) on delete cascade,
  light_rail_type    text not null references rail_types(rail_type) on delete restrict,
  fit_confidence     fitment_confidence not null default ''unverified'',
  notes              text,
  primary key (grip_housing_class, grip_rail_type)
);

comment on table rail_bridge is
  ''Grip rail vocabulary -> light rail vocabulary. Absence of a row means that housing/rail combination has no known light fitment.'';

insert into rail_bridge values
  (''p365'',  ''proprietary'',''sig-365'',   ''verified'',''P365 proprietary rail = SIG-365 light clamp. Base/X.''),
  (''p365xl'',''proprietary'',''sig-365'',   ''verified'',''P365XL proprietary rail = SIG-365 clamp. Same as base/X.''),
  (''xmacro'',''proprietary'',''sig-365'',   ''likely'',  ''Rare XMacro proprietary-rail SKU (WC XMacro-SG) uses SIG-365 clamp.''),
  (''p365'',  ''picatinny'',  ''1913-short'',''verified'',''Aftermarket P365 pic-rail grip takes short-1913 light clamp.''),
  (''p365xl'',''picatinny'',  ''1913-short'',''verified'',''Aftermarket P365XL pic-rail grip takes short-1913 clamp.''),
  (''xmacro'',''picatinny'',  ''1913-short'',''verified'',''XMacro factory pic rail = short 1913. NOT the SIG-365 clamp.''),
  (''fuse'',  ''picatinny'',  ''1913-short'',''verified'',''Fuse (XMacro-length) pic rail = short 1913.'');

-- ============================================================
-- 5. Views
-- ============================================================
drop view if exists v_frame_fitment;

create view v_frame_fitment with (security_invoker = true) as
select
  f.product_id,
  p.slug,
  p.name,
  f.housing_class,
  hc.display_name    as housing_display_name,
  hc.magazine_family,
  hc.min_slide_length_in,
  f.has_rail,
  f.grip_rail_type,
  rb.light_rail_type,
  rb.fit_confidence  as rail_bridge_confidence
from frame_specs f
join products p on p.id = f.product_id
join housing_classes hc on hc.housing_class = f.housing_class
left join rail_bridge rb
  on rb.grip_housing_class = f.housing_class
 and rb.grip_rail_type = f.grip_rail_type;

-- Which lights fit which grip module, resolved through the bridge.
create view v_frame_light_fit with (security_invoker = true) as
select
  f.product_id      as frame_product_id,
  lc.light_product_id,
  f.housing_class,
  f.grip_rail_type,
  rb.light_rail_type,
  lc.fitment_type,
  lc.key_or_adapter,
  -- The chain is only as strong as its weakest link.
  case
    when rb.fit_confidence = ''verified'' and lc.confirmed then ''verified''
    else ''likely''
  end               as confidence,
  rb.notes          as bridge_notes,
  lc.notes          as compatibility_notes
from frame_specs f
join rail_bridge rb
  on rb.grip_housing_class = f.housing_class
 and rb.grip_rail_type = f.grip_rail_type
join light_compatibility lc on lc.rail_type = rb.light_rail_type
where lc.fitment_type <> ''no-fit'';

alter table grip_rail_types enable row level security;
alter table rail_bridge     enable row level security;
create policy grip_rail_types_public_read on grip_rail_types for select to anon, authenticated using (true);
create policy rail_bridge_public_read     on rail_bridge     for select to anon, authenticated using (true);"}', 'rail_bridge_and_reference_sync', 'ag.gamboa94@gmail.com', NULL, NULL);
INSERT INTO "supabase_migrations"."schema_migrations" ("version", "statements", "name", "created_by", "idempotency_key", "rollback") VALUES ('20260730223345', '{"-- handle_new_user and prevent_role_self_escalation are trigger-only
-- functions and should never be callable directly via PostgREST RPC.
revoke execute on function public.handle_new_user() from public, anon, authenticated;
revoke execute on function public.prevent_role_self_escalation() from public, anon, authenticated;

-- is_admin() must stay executable by `authenticated` because the builds
-- RLS policies call it during normal queries -- but `anon` never hits a
-- policy branch that calls it, so drop that unnecessary grant.
revoke execute on function public.is_admin() from anon;"}', 'lock_down_trigger_and_helper_function_execute_grants', 'ag.gamboa94@gmail.com', NULL, NULL);
INSERT INTO "supabase_migrations"."schema_migrations" ("version", "statements", "name", "created_by", "idempotency_key", "rollback") VALUES ('20260730224014', '{"-- Persist Builder Agreement consent captured at signup.
alter table public.profiles
  add column builder_agreement_accepted boolean not null default false,
  add column builder_agreement_version text,
  add column builder_agreement_signed_at timestamptz;

-- Copy the agreement fields from signup metadata, stamping signed_at with
-- the server''s own clock (never a client-supplied timestamp).
create or replace function public.handle_new_user()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
  accepted boolean := coalesce((new.raw_user_meta_data ->> ''builder_agreement_accepted'')::boolean, false);
begin
  insert into public.profiles (
    id, username, marketing_consent,
    builder_agreement_accepted, builder_agreement_version, builder_agreement_signed_at
  )
  values (
    new.id,
    new.raw_user_meta_data ->> ''username'',
    coalesce((new.raw_user_meta_data ->> ''marketing_consent'')::boolean, false),
    accepted,
    new.raw_user_meta_data ->> ''builder_agreement_version'',
    case when accepted then now() else null end
  );
  return new;
end;
$$;

-- Extend the existing protected-column guard: agreement fields are a
-- consent record and must not be editable via a normal profile update,
-- same reasoning as role.
create or replace function public.prevent_role_self_escalation()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  if new.role is distinct from old.role and not public.is_admin() then
    raise exception ''Only admins can change role'';
  end if;

  if (new.builder_agreement_accepted is distinct from old.builder_agreement_accepted
      or new.builder_agreement_version is distinct from old.builder_agreement_version
      or new.builder_agreement_signed_at is distinct from old.builder_agreement_signed_at)
     and not public.is_admin() then
    raise exception ''Builder agreement fields cannot be edited directly'';
  end if;

  return new;
end;
$$;"}', 'add_builder_agreement_fields_to_profiles', 'ag.gamboa94@gmail.com', NULL, NULL);
INSERT INTO "supabase_migrations"."schema_migrations" ("version", "statements", "name", "created_by", "idempotency_key", "rollback") VALUES ('20260730225351', '{"-- ============================================================
-- The Builder Agreement checkbox moved from signup to the build
-- submission flow (gunforma-post-build-v6.html): a builder accepts
-- it contextually, tied to their first real build+photo, not
-- hypothetically at signup. Rework the schema to match:
--   - profiles.builder_agreement_* still records whether/when a
--     user has ever accepted (site-wide fact), but is now only
--     ever set by a trusted server-side cascade off a build
--     submission -- never directly by the client.
--   - builds gets its own per-submission consent record
--     (content_license_confirmed, legal_confirmed, confirmed_at,
--     builder_agreement_version), stamped at insert time and
--     immutable after.
-- ============================================================

-- ------------------------------------------------------------
-- PROFILES: rename to match the naming used in the new frontend
-- comment, and simplify handle_new_user() since signup no longer
-- sends builder agreement metadata at all (it naturally lands on
-- the column defaults: accepted=false, version/accepted_at=null).
-- ------------------------------------------------------------
alter table public.profiles
  rename column builder_agreement_signed_at to builder_agreement_accepted_at;

alter table public.profiles
  add constraint builder_agreement_version_not_blank
  check (builder_agreement_version is null or length(builder_agreement_version) > 0);

create or replace function public.handle_new_user()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  insert into public.profiles (id, username, marketing_consent)
  values (
    new.id,
    new.raw_user_meta_data ->> ''username'',
    coalesce((new.raw_user_meta_data ->> ''marketing_consent'')::boolean, false)
  );
  return new;
end;
$$;

-- ------------------------------------------------------------
-- PROFILES GUARD: builder_agreement_* fields can now ONLY be set
-- by the trusted cascade trigger below (via a transaction-local
-- flag the client can never set through PostgREST), or by an
-- admin correcting a record. A direct client update -- even a
-- well-intentioned false->true -- is rejected, so acceptance is
-- always tied to a real build submission, never a bare profile
-- edit.
-- ------------------------------------------------------------
create or replace function public.prevent_role_self_escalation()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  if new.role is distinct from old.role and not public.is_admin() then
    raise exception ''Only admins can change role'';
  end if;

  if (new.builder_agreement_accepted is distinct from old.builder_agreement_accepted
      or new.builder_agreement_version is distinct from old.builder_agreement_version
      or new.builder_agreement_accepted_at is distinct from old.builder_agreement_accepted_at)
     and not public.is_admin()
     and coalesce(current_setting(''app.bypass_consent_guard'', true), ''false'') <> ''true''
  then
    raise exception ''Builder agreement fields can only be set via a build submission'';
  end if;

  return new;
end;
$$;

-- ------------------------------------------------------------
-- BUILDS: per-submission consent record, matching the
-- consentRecord object gunforma-post-build-v6.html builds today
-- (contentLicenseConfirmed, legalConfirmed, confirmedAt).
-- ------------------------------------------------------------
alter table public.builds
  add column content_license_confirmed boolean not null default false,
  add column legal_confirmed boolean not null default false,
  add column confirmed_at timestamptz,
  add column builder_agreement_version text;

alter table public.builds
  add constraint builds_consent_required_unless_draft
  check (status = ''draft'' or (content_license_confirmed and legal_confirmed));

alter table public.builds
  add constraint builds_builder_agreement_version_not_blank
  check (builder_agreement_version is null or length(builder_agreement_version) > 0);

-- Stamp confirmed_at with the server''s own clock -- never trust the
-- client''s `confirmedAt` value (the frontend TODO explicitly calls
-- this out).
create or replace function public.stamp_build_consent()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  if new.content_license_confirmed or new.legal_confirmed then
    new.confirmed_at := now();
  else
    new.confirmed_at := null;
  end if;
  return new;
end;
$$;

create trigger trg_stamp_build_consent
before insert on public.builds
for each row execute function public.stamp_build_consent();

-- Once a build''s consent record is written at insert, it''s evidence
-- of what the builder confirmed at that moment -- block edits to it
-- afterward (own-build edit flow otherwise allows changing any
-- column while status is draft/pending).
create or replace function public.prevent_build_consent_tampering()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  if (new.content_license_confirmed is distinct from old.content_license_confirmed
      or new.legal_confirmed is distinct from old.legal_confirmed
      or new.confirmed_at is distinct from old.confirmed_at
      or new.builder_agreement_version is distinct from old.builder_agreement_version)
     and not public.is_admin()
  then
    raise exception ''Consent fields cannot be edited after submission'';
  end if;
  return new;
end;
$$;

create trigger trg_prevent_build_consent_tampering
before update on public.builds
for each row execute function public.prevent_build_consent_tampering();

-- The actual cascade: a build whose content_license_confirmed is true
-- is, per the frontend''s own logic, the builder''s Builder Agreement
-- acceptance IF they haven''t already accepted it. This only ever
-- flips profiles.builder_agreement_accepted false -> true, once --
-- if it''s already true, this update matches zero rows and does
-- nothing (exactly the \"don''t re-stamp the profile\" requirement).
create or replace function public.cascade_builder_agreement_to_profile()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  if new.content_license_confirmed then
    perform set_config(''app.bypass_consent_guard'', ''true'', true);
    update public.profiles
    set builder_agreement_accepted = true,
        builder_agreement_version = new.builder_agreement_version,
        builder_agreement_accepted_at = new.confirmed_at
    where id = new.user_id
      and builder_agreement_accepted = false;
    perform set_config(''app.bypass_consent_guard'', ''false'', true);
  end if;
  return new;
end;
$$;

create trigger trg_cascade_builder_agreement
after insert on public.builds
for each row execute function public.cascade_builder_agreement_to_profile();"}', 'move_builder_agreement_consent_to_build_submission', 'ag.gamboa94@gmail.com', NULL, NULL);
