INSERT INTO "supabase_migrations"."schema_migrations" ("version", "statements", "name", "created_by", "idempotency_key", "rollback") VALUES ('20260731042938', '{"-- Parts stay as a JSON snapshot for now rather than a normalized
-- build_parts -> products relation: the live products/product_variants
-- catalog (3 rows, 7 categories) doesn''t yet cover what the build
-- form''s picker offers (~50 items across 13 categories, several of
-- which -- holsters, magazines, paint job, knife, misc -- aren''t even
-- in the product_category enum). Revisit once the catalog is populated.
alter table public.builds
  add column parts_snapshot jsonb not null default ''[]''::jsonb,
  add column photo_count smallint not null default 0;

alter table public.builds
  add constraint builds_parts_snapshot_is_array
  check (jsonb_typeof(parts_snapshot) = ''array'');

alter table public.builds
  add constraint builds_photo_count_nonnegative
  check (photo_count >= 0);

-- Every real submission path (submit or save-as-draft) already
-- requires a platform to be chosen client-side before insert is
-- reachable; enforce it at the DB level too now that this is live.
alter table public.builds
  alter column platform_id set not null;"}', 'add_build_parts_snapshot_and_photo_count', 'ag.gamboa94@gmail.com', NULL, NULL);
INSERT INTO "supabase_migrations"."schema_migrations" ("version", "statements", "name", "created_by", "idempotency_key", "rollback") VALUES ('20260806065138', '{"-- ============================================================
-- Storage bucket for build photos. Public read (these are meant to
-- appear on public build pages once approved); writes are restricted
-- to the uploader''s own folder. Server-side backstop on format/size
-- in addition to client-side canvas normalization (JPEG/PNG/WebP,
-- re-encoded to strip EXIF/GPS before upload).
-- ============================================================
insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values (''build-photos'', ''build-photos'', true, 8388608, array[''image/jpeg'',''image/png'',''image/webp''])
on conflict (id) do nothing;

-- Path convention: {auth.uid()}/{draft-or-build-id}/{slot}.jpg —
-- only the first folder segment is checked, so photos can be uploaded
-- before the build row exists (using a client-generated draft id) and
-- linked to the real build afterward.
create policy \"build_photos_public_read\"
on storage.objects for select
to anon, authenticated
using (bucket_id = ''build-photos'');

create policy \"build_photos_owner_insert\"
on storage.objects for insert
to authenticated
with check (
  bucket_id = ''build-photos''
  and (storage.foldername(name))[1] = auth.uid()::text
);

create policy \"build_photos_owner_update\"
on storage.objects for update
to authenticated
using (
  bucket_id = ''build-photos''
  and (storage.foldername(name))[1] = auth.uid()::text
)
with check (
  bucket_id = ''build-photos''
  and (storage.foldername(name))[1] = auth.uid()::text
);

create policy \"build_photos_owner_or_admin_delete\"
on storage.objects for delete
to authenticated
using (
  bucket_id = ''build-photos''
  and ((storage.foldername(name))[1] = auth.uid()::text or public.is_admin())
);

-- ============================================================
-- BUILD_PHOTOS TABLE — one row per photo, so admins can moderate a
-- single bad photo instead of the whole build.
-- ============================================================
create table public.build_photos (
  id uuid primary key default gen_random_uuid(),
  build_id uuid not null references public.builds(id) on delete cascade,
  user_id uuid not null references auth.users(id) on delete cascade,
  storage_path text not null unique,
  is_hero boolean not null default false,
  position smallint not null default 1 check (position > 0),
  created_at timestamptz not null default now()
);

create unique index build_photos_one_hero_per_build
  on public.build_photos(build_id)
  where is_hero;

-- builds.photo_count is superseded by this table (it was a client-set
-- integer with no relationship to real data) — drop it rather than
-- keep two sources of truth that can drift.
alter table public.builds drop column photo_count;

alter table public.build_photos enable row level security;

-- Cap 4 photos per build (matches the 4 slots the form offers) at the
-- DB level, not just client-side.
create or replace function public.enforce_build_photo_limit()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  if (select count(*) from public.build_photos where build_id = new.build_id) >= 4 then
    raise exception ''A build can have at most 4 photos'';
  end if;
  return new;
end;
$$;

create trigger trg_enforce_build_photo_limit
before insert on public.build_photos
for each row execute function public.enforce_build_photo_limit();

-- storage_path/build_id/user_id are set once at upload time and
-- shouldn''t be swappable afterward — only is_hero/position (picking a
-- different hero photo, reordering) should be editable by the owner.
create or replace function public.prevent_build_photo_path_tampering()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  if (new.storage_path is distinct from old.storage_path
      or new.build_id is distinct from old.build_id
      or new.user_id is distinct from old.user_id)
     and not public.is_admin()
  then
    raise exception ''storage_path, build_id, and user_id cannot be changed after upload'';
  end if;
  return new;
end;
$$;

create trigger trg_prevent_build_photo_path_tampering
before update on public.build_photos
for each row execute function public.prevent_build_photo_path_tampering();

-- SELECT — mirrors the builds visibility policy exactly: public sees
-- approved builds'' photos, owners see their own regardless of status,
-- admins see everything.
create policy \"Public can view photos of approved builds\"
on public.build_photos for select
to anon, authenticated
using (exists (select 1 from public.builds b where b.id = build_photos.build_id and b.status = ''approved''));

create policy \"Owners can view their own build photos\"
on public.build_photos for select
to authenticated
using (auth.uid() = user_id);

create policy \"Admins can view all build photos\"
on public.build_photos for select
to authenticated
using (public.is_admin());

-- INSERT/UPDATE/DELETE — owner only while their build is still
-- draft/pending (same edit window as the build row itself).
create policy \"Owners can add photos to their own unreviewed builds\"
on public.build_photos for insert
to authenticated
with check (
  auth.uid() = user_id
  and exists (
    select 1 from public.builds b
    where b.id = build_photos.build_id and b.user_id = auth.uid() and b.status in (''draft'',''pending'')
  )
);

create policy \"Owners can edit photo metadata on their own unreviewed builds\"
on public.build_photos for update
to authenticated
using (
  auth.uid() = user_id
  and exists (select 1 from public.builds b where b.id = build_photos.build_id and b.status in (''draft'',''pending''))
)
with check (
  auth.uid() = user_id
  and exists (select 1 from public.builds b where b.id = build_photos.build_id and b.status in (''draft'',''pending''))
);

create policy \"Admins can edit any build photo\"
on public.build_photos for update
to authenticated
using (public.is_admin())
with check (public.is_admin());

create policy \"Owners can delete photos from their own unreviewed builds\"
on public.build_photos for delete
to authenticated
using (
  auth.uid() = user_id
  and exists (select 1 from public.builds b where b.id = build_photos.build_id and b.status in (''draft'',''pending''))
);

create policy \"Admins can delete any build photo\"
on public.build_photos for delete
to authenticated
using (public.is_admin());"}', 'add_build_photos_storage_and_table', 'ag.gamboa94@gmail.com', NULL, NULL);
INSERT INTO "supabase_migrations"."schema_migrations" ("version", "statements", "name", "created_by", "idempotency_key", "rollback") VALUES ('20260806065146', '{"revoke execute on function public.enforce_build_photo_limit() from public, anon, authenticated;
revoke execute on function public.prevent_build_photo_path_tampering() from public, anon, authenticated;"}', 'lock_down_build_photos_trigger_grants', 'ag.gamboa94@gmail.com', NULL, NULL);
INSERT INTO "supabase_migrations"."schema_migrations" ("version", "statements", "name", "created_by", "idempotency_key", "rollback") VALUES ('20260806123058', '{"-- Table is currently empty, so a NOT NULL column needs no default/backfill.
alter table public.build_photos
  add column thumb_path text not null,
  add constraint build_photos_thumb_path_unique unique (thumb_path);

-- Extend the existing tamper guard to cover thumb_path too.
create or replace function public.prevent_build_photo_path_tampering()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  if (new.storage_path is distinct from old.storage_path
      or new.thumb_path is distinct from old.thumb_path
      or new.build_id is distinct from old.build_id
      or new.user_id is distinct from old.user_id)
     and not public.is_admin()
  then
    raise exception ''storage_path, thumb_path, build_id, and user_id cannot be changed after upload'';
  end if;
  return new;
end;
$$;"}', 'add_build_photos_thumb_path', 'ag.gamboa94@gmail.com', NULL, NULL);
INSERT INTO "supabase_migrations"."schema_migrations" ("version", "statements", "name", "created_by", "idempotency_key", "rollback") VALUES ('20260806221504', '{"-- Repoint to profiles so PostgREST can embed the submitter''s username
-- directly (builds.user_id -> auth.users.id has no path for that join).
-- Safe: profiles.id is always auth.users.id 1:1 via handle_new_user().
alter table public.builds drop constraint builds_user_id_fkey;
alter table public.builds add constraint builds_user_id_fkey
  foreign key (user_id) references public.profiles(id) on delete cascade;

-- Admin review attribution should reflect who actually clicked
-- approve/reject and when, not whatever the client sends.
create or replace function public.stamp_build_review()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  if new.status is distinct from old.status and new.status in (''approved'',''rejected'') then
    new.reviewed_by := auth.uid();
    new.reviewed_at := now();
  end if;
  if new.status = ''pending'' and old.status in (''approved'',''rejected'') then
    new.reviewed_by := null;
    new.reviewed_at := null;
    new.rejection_reason := null;
  end if;
  return new;
end;
$$;

create trigger trg_stamp_build_review
before update on public.builds
for each row execute function public.stamp_build_review();

revoke execute on function public.stamp_build_review() from public, anon, authenticated;"}', 'repoint_builds_user_fk_and_stamp_review', 'ag.gamboa94@gmail.com', NULL, NULL);
INSERT INTO "supabase_migrations"."schema_migrations" ("version", "statements", "name", "created_by", "idempotency_key", "rollback") VALUES ('20260806222357', '{"-- current_user is ''postgres'' (SQL editor / management API / migrations)
-- for trusted server-side sessions, and ''anon''/''authenticated'' for every
-- PostgREST client request. This lets a superuser bootstrap the very
-- first admin (there''s no admin yet to authorize it otherwise) without
-- loosening what a client can do — a client request can never run as
-- current_user = ''postgres''.
create or replace function public.prevent_role_self_escalation()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  if current_user in (''postgres'', ''service_role'') then
    return new;
  end if;

  if new.role is distinct from old.role and not public.is_admin() then
    raise exception ''Only admins can change role'';
  end if;

  if (new.builder_agreement_accepted is distinct from old.builder_agreement_accepted
      or new.builder_agreement_version is distinct from old.builder_agreement_version
      or new.builder_agreement_accepted_at is distinct from old.builder_agreement_accepted_at)
     and not public.is_admin()
     and coalesce(current_setting(''app.bypass_consent_guard'', true), ''false'') <> ''true''
  then
    raise exception ''Builder agreement fields can only be set via a build submission'';
  end if;

  return new;
end;
$$;"}', 'allow_direct_sql_bootstrap_for_role_changes', 'ag.gamboa94@gmail.com', NULL, NULL);
INSERT INTO "supabase_migrations"."schema_migrations" ("version", "statements", "name", "created_by", "idempotency_key", "rollback") VALUES ('20260807021900', '{"-- Append-only correction log layered on top of parts_snapshot, which
-- stays untouched as the original submission. Shape per entry:
-- { part_index, field, from_value, to_value, edited_by, edited_at, status }
-- status is ''active'' | ''contested''. Admin writes already covered by the
-- existing \"Admins can review and edit any build\" UPDATE policy.
alter table public.builds
  add column edit_history jsonb not null default ''[]''::jsonb;

comment on column public.builds.edit_history is
  ''Append-only admin correction log. Each entry: {part_index, field, from_value, to_value, edited_by, edited_at, status: active|contested}. Never overwrite parts_snapshot.'';

-- Lets any visitor contest a specific corrected part on a live build,
-- without granting any broader write access. Only flips the status of
-- the single most recent edit_history entry for that part_index to
-- ''contested'' -- everything else about the row is unreachable through
-- this function, and it only acts on already-approved builds.
create or replace function public.contest_build_part(p_build_id uuid, p_part_index int)
returns void
language plpgsql
security definer
set search_path = public
as $$
declare
  target_idx int;
begin
  select (ord - 1) into target_idx
  from public.builds b, jsonb_array_elements(b.edit_history) with ordinality as e(elem, ord)
  where b.id = p_build_id
    and b.status = ''approved''
    and (e.elem ->> ''part_index'')::int = p_part_index
  order by ord desc
  limit 1;

  if target_idx is null then
    return;
  end if;

  update public.builds
  set edit_history = jsonb_set(edit_history, array[target_idx::text, ''status''], ''\"contested\"''::jsonb)
  where id = p_build_id and status = ''approved'';
end;
$$;

revoke all on function public.contest_build_part(uuid, int) from public;
grant execute on function public.contest_build_part(uuid, int) to anon, authenticated;"}', 'add_builds_edit_history_and_contest_rpc', 'ag.gamboa94@gmail.com', NULL, NULL);
