INSERT INTO "supabase_migrations"."schema_migrations" ("version", "statements", "name", "created_by", "idempotency_key", "rollback") VALUES ('20260808062647', '{"
-- Stage 1-5: Full P365 slides import from spreadsheet v3 (8/8/2026)
-- Wraps products, slide_specs, variants, affiliate_links, barrel placeholders

-- We use a DO block with dynamic SQL to keep this as one atomic migration.
-- All slug lookups use subselects against products/manufacturers/partners.

-- ===== HELPER: Temporarily disable the RLS policies for the migration =====
-- (Migration runs as superuser so RLS is bypassed anyway)

-- ===== PRODUCTS (40 slides) =====
-- First two already existed, will be updated via ON CONFLICT

DO $migrate$
BEGIN
  RAISE NOTICE ''P365 slides migration starting'';
END;
$migrate$;
"}', 'p365_slides_import', 'ag.gamboa94@gmail.com', NULL, NULL);
INSERT INTO "supabase_migrations"."schema_migrations" ("version", "statements", "name", "created_by", "idempotency_key", "rollback") VALUES ('20260808062734', '{"INSERT INTO products (slug, category, brand_id, name, url, fitment_confidence, build_warning, fitment_notes, build_notes, material, weight_oz, description, best_for, is_discontinued) VALUES (''killer-innovations-velo-v1-p365'', ''slide'', (SELECT id FROM manufacturers WHERE slug = ''killer-innovations''), ''Killer Innovations Velocity V1 Sig P365'', ''https://killer-innovations.com/shop/velocity-v1-slide-for-sig-p365/'', ''verified''::fitment_confidence, NULL, NULL, ''Fits any P365 frame requires P365 Recoil Spring Assembly.'', ''17-4 stainless'', NULL, ''Machined from 17-4 stainless billet rather than the factory MIM slide, the Velocity V1 adds a dual-cut optic footprint that accepts a wide range of micro red dots plus E.G.F. texturing for a more secure grip when racking. Made in the USA to tight tolerances, it drops onto a stock P365 frame with no custom fitting, giving owners a stronger, more capable slide.'', ''{}'', FALSE) ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, url = EXCLUDED.url, fitment_confidence = EXCLUDED.fitment_confidence, build_warning = EXCLUDED.build_warning, fitment_notes = EXCLUDED.fitment_notes, build_notes = EXCLUDED.build_notes, material = EXCLUDED.material, weight_oz = EXCLUDED.weight_oz, description = EXCLUDED.description, is_discontinued = EXCLUDED.is_discontinued, updated_at = now(); INSERT INTO products (slug, category, brand_id, name, url, fitment_confidence, build_warning, fitment_notes, build_notes, material, weight_oz, description, best_for, is_discontinued) VALUES (''killer-innovations-velo-v1-p365-xl'', ''slide'', (SELECT id FROM manufacturers WHERE slug = ''killer-innovations''), ''Killer Innovations Velocity V1 Sig P365XL'', ''https://killer-innovations.com/shop/velocity-v1-slide-for-sig-p365/'', ''verified''::fitment_confidence, NULL, NULL, ''Fits any P365XL/XMacro frame requires P365XL/X-Macro Recoil Spring Assembly.'', ''17-4 stainless'', NULL, ''Machined from 17-4 stainless billet rather than the factory MIM slide, the Velocity V1 adds a dual-cut optic footprint that accepts a wide range of micro red dots plus E.G.F. texturing for a more secure grip when racking. Made in the USA to tight tolerances, it drops onto a stock P365XL/X-Macro frame with no custom fitting, giving owners a stronger, more capable slide.'', ''{}'', FALSE) ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, url = EXCLUDED.url, fitment_confidence = EXCLUDED.fitment_confidence, build_warning = EXCLUDED.build_warning, fitment_notes = EXCLUDED.fitment_notes, build_notes = EXCLUDED.build_notes, material = EXCLUDED.material, weight_oz = EXCLUDED.weight_oz, description = EXCLUDED.description, is_discontinued = EXCLUDED.is_discontinued, updated_at = now(); INSERT INTO products (slug, category, brand_id, name, url, fitment_confidence, build_warning, fitment_notes, build_notes, material, weight_oz, description, best_for, is_discontinued) VALUES (''norsso-bentham-p365'', ''slide'', (SELECT id FROM manufacturers WHERE slug = ''norsso''), ''Norsso P365 Bentham'', ''https://norsso.com/p365-bentham/'', ''verified''::fitment_confidence, NULL, ''Compatible with P365 3.1\" barrels ONLY. 3.7\" barrels NOT compatible. Threaded barrels are compatible.'', ''Fits any P365 frame. On XL/XMacro frame requires P365XL/X-Macro Recoil Spring Assembly.'', ''17-4 stainless'', NULL, ''Bentham strips away window cuts for a clean, understated profile machined from 17-4 stainless billet and heat treated to H900, giving the P365 a noticeably lighter, more refined feel than the factory slide. It''''s a strong OEM replacement for owners who want the material and machining upgrade of an aftermarket slide without an aggressive tactical look.'', ''{}'', FALSE) ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, url = EXCLUDED.url, fitment_confidence = EXCLUDED.fitment_confidence, build_warning = EXCLUDED.build_warning, fitment_notes = EXCLUDED.fitment_notes, build_notes = EXCLUDED.build_notes, material = EXCLUDED.material, weight_oz = EXCLUDED.weight_oz, description = EXCLUDED.description, is_discontinued = EXCLUDED.is_discontinued, updated_at = now();"}', 'p365_slides_batch_1_products_1_14', 'ag.gamboa94@gmail.com', NULL, NULL);
