INSERT INTO "supabase_migrations"."schema_migrations" ("version", "statements", "name", "created_by", "idempotency_key", "rollback") VALUES ('20260808120828', '{"INSERT INTO products (slug,category,brand_id,name,url,fitment_confidence,build_warning,fitment_notes,build_notes,material,weight_oz,description,best_for,is_discontinued) VALUES (''killer-innovations-velo-v1-p365'', ''slide'', (SELECT id FROM manufacturers WHERE slug=''killer-innovations''), ''Killer Innovations Velocity V1 Sig P365'', ''https://killer-innovations.com/shop/velocity-v1-slide-for-sig-p365/'', ''verified''::fitment_confidence, NULL, NULL, ''Fits any P365 frame requires P365 Recoil Spring Assembly.'', ''17-4 stainless'', NULL, ''Machined from 17-4 stainless billet rather than the factory MIM slide, the Velocity V1 adds a dual-cut optic footprint that accepts a wide range of micro red dots plus E.G.F. texturing for a more secure grip when racking. Made in the USA to tight tolerances, it drops onto a stock P365 frame with no custom fitting, giving owners a stronger, more capable slide.'', ''{}'', FALSE), (''killer-innovations-velo-v1-p365-xl'', ''slide'', (SELECT id FROM manufacturers WHERE slug=''killer-innovations''), ''Killer Innovations Velocity V1 Sig P365XL'', ''https://killer-innovations.com/shop/velocity-v1-slide-for-sig-p365/'', ''verified''::fitment_confidence, NULL, NULL, ''Fits any P365XL/XMacro frame requires P365XL/X-Macro Recoil Spring Assembly.'', ''17-4 stainless'', NULL, ''Machined from 17-4 stainless billet rather than the factory MIM slide, the Velocity V1 adds a dual-cut optic footprint that accepts a wide range of micro red dots plus E.G.F. texturing for a more secure grip when racking. Made in the USA to tight tolerances, it drops onto a stock P365XL/X-Macro frame with no custom fitting, giving owners a stronger, more capable slide.'', ''{}'', FALSE), (''norsso-bentham-p365'', ''slide'', (SELECT id FROM manufacturers WHERE slug=''norsso''), ''Norsso P365 Bentham'', ''https://norsso.com/p365-bentham/'', ''verified''::fitment_confidence, NULL, ''Compatible with P365 3.1\" barrels ONLY. 3.7\" barrels NOT compatible. Threaded barrels are compatible.'', ''Fits any P365 frame. On XL/XMacro frame requires P365XL/X-Macro Recoil Spring Assembly.'', ''17-4 stainless'', NULL, ''Bentham strips away window cuts for a clean, understated profile machined from 17-4 stainless billet and heat treated to H900, giving the P365 a noticeably lighter, more refined feel than the factory slide. It''''s a strong OEM replacement for owners who want the material and machining upgrade of an aftermarket slide without an aggressive tactical look.'', ''{}'', FALSE), (''norsso-rail-edc-p365'', ''slide'', (SELECT id FROM manufacturers WHERE slug=''norsso''), ''Norsso P365 Rail EDC'', ''https://norsso.com/slides/p365-rail-edc/'', ''verified''::fitment_confidence, NULL, ''Compatible with P365 3.1\" barrels ONLY. 3.7\" barrels NOT compatible. Threaded barrels are compatible.'', ''Fits any P365 frame. On XL/XMacro frame requires P365XL/X-Macro Recoil Spring Assembly.'', ''17-4 stainless'', NULL, ''The Rail EDC pairs Norsso''''s billet 17-4 stainless construction with forward and rear serrations sized for everyday carry, replacing the factory slide''''s softer MIM material and shallow cocking cuts. It''''s a solid choice for shooters who want a tougher, better-gripping slide for a duty-style carry gun without extra machining features like porting.'', ''{}'', FALSE), (''norsso-reptile-edc-p365'', ''slide'', (SELECT id FROM manufacturers WHERE slug=''norsso''), ''Norsso P365 Reptile EDC'', ''https://norsso.com/p365-reptile-edc/'', ''verified''::fitment_confidence, NULL, ''Compatible with P365 3.1\" barrels ONLY. 3.7\" barrels NOT compatible. Threaded barrels are compatible.'', ''Fits any P365 frame. On XL/XMacro frame requires P365XL/X-Macro Recoil Spring Assembly.'', ''17-4 stainless'', NULL, ''The Reptile EDC brings Norsso''''s signature deep, scale-like side texturing to a carry-focused cut, offering far more purchase for slide manipulation than the smooth factory OEM slide. Built from heat-treated 17-4 stainless billet, it''''s a durable, better-handling replacement aimed at everyday carry rather than range/duty aesthetics.'', ''{}'', FALSE), (''norsso-reptile-og-p365'', ''slide'', (SELECT id FROM manufacturers WHERE slug=''norsso''), ''Norsso P365 Reptile OG'', ''https://norsso.com/p365-reptile/'', ''verified''::fitment_confidence, NULL, ''Compatible with P365 3.1\" barrels ONLY. 3.7\" barrels NOT compatible. Threaded barrels are compatible.'', ''Fits any P365 frame. On XL/XMacro frame requires P365XL/X-Macro Recoil Spring Assembly.'', ''17-4 stainless'', NULL, ''Reptile OG is Norsso''''s original design, using CNC-surfaced 3D side windows along with forward and top serrations for easier press-checks and slide racking than the stock slide allows. Machined from 17-4 stainless and heat treated to H900, it''''s a proven, well-reviewed upgrade for owners who want both weight savings and an aggressive, distinctive look.'', ''{}'', FALSE), (''norsso-spec-ops-p365'', ''slide'', (SELECT id FROM manufacturers WHERE slug=''norsso''), ''Norsso P365 Spec Ops'', ''https://norsso.com/slides/sig-p365/p365/p365-spec-ops/'', ''verified''::fitment_confidence, NULL, ''Compatible with P365 3.1\" barrels ONLY. 3.7\" barrels NOT compatible. Threaded barrels are compatible.'', ''Fits any P365 frame. On XL/XMacro frame requires P365XL/X-Macro Recoil Spring Assembly.'', ''17-4 stainless'', NULL, ''Spec Ops is one of Norsso''''s duty-focused patterns, with deep forward and rear serrations built for confident manipulation under stress, unlike the shallower cuts on a factory P365 slide. Owners frequently report it running noticeably lighter than the stock slide while holding up to hard use, making it a dependable OEM replacement for a duty or EDC build.'', ''{}'', FALSE), (''norsso-rail-edc-cport-p365'', ''slide'', (SELECT id FROM manufacturers WHERE slug=''norsso''), ''Norsso P365 Rail EDC C'', ''https://norsso.com/new-norsso/p365-rail-edc-c/'', ''verified''::fitment_confidence, ''Ported slide — requires the P365 Recoil Spring Assembly or it may short-stroke.'', ''Compatible with P365 3.1\" barrels ONLY. 3.7\" barrels NOT compatible. Threaded barrels are NOT compatible.'', ''Fits any P365 frame. On XL/XMacro frame requires P365XL/X-Macro Recoil Spring Assembly.'', ''17-4 stainless'', NULL, ''This C-ported version of the Rail EDC adds two top-mounted ports that vent gas upward to tame muzzle rise, a capability the factory slide simply doesn''''t offer. Machined from 17-4 stainless billet, it pairs with a Norsso ported barrel to bring performance gains beyond what any stock P365 slide swap can provide.'', ''{}'', FALSE), (''norsso-reptile-cport-p365'', ''slide'', (SELECT id FROM manufacturers WHERE slug=''norsso''), ''Norsso P365 Reptile C'', ''https://norsso.com/slides/sig-p365-365dg-365xl/p365-365x/p365-reptile-c/'', ''verified''::fitment_confidence, ''Ported slide — requires the P365 Recoil Spring Assembly or it may short-stroke.'', ''Compatible with P365 3.1\" barrels ONLY. 3.7\" barrels NOT compatible. Threaded barrels are NOT compatible.'', ''Fits any P365 frame. On XL/XMacro frame requires P365XL/X-Macro Recoil Spring Assembly.'', ''17-4 stainless'', NULL, ''The Reptile C combines Norsso''''s aggressive scale-textured grip cuts with dual top ports for reduced muzzle flip, giving shooters both better handling and flatter recoil control than the smooth, unported factory slide. It''''s a strong choice for owners who want a performance-oriented replacement rather than a purely cosmetic upgrade.'', ''{}'', FALSE), (''norsso-spec-ops-cport-p365'', ''slide'', (SELECT id FROM manufacturers WHERE slug=''norsso''), ''Norsso P365 Spec Ops C'', ''https://norsso.com/slides/p365-spec-ops-c/'', ''verified''::fitment_confidence, ''Ported slide — requires the P365 Recoil Spring Assembly or it may short-stroke.'', ''Compatible with P365 3.1\" barrels ONLY. 3.7\" barrels NOT compatible. Threaded barrels are NOT compatible.'', ''Fits any P365 frame. On XL/XMacro frame requires P365XL/X-Macro Recoil Spring Assembly.'', ''17-4 stainless'', NULL, ''Spec Ops C takes Norsso''''s duty-grade serration pattern and adds dual integrated top ports, venting gas to cut muzzle rise without needing an external compensator or threaded barrel. Machined from heat-treated 17-4 stainless, it''''s built for shooters who want a functional performance upgrade over the stock slide, not just a cosmetic one.'', ''{}'', FALSE), (''norsso-bentham-p365-xl'', ''slide'', (SELECT id FROM manufacturers WHERE slug=''norsso''), ''Norsso P365XL Bentham'', ''https://norsso.com/slides/sig-p365-365dg-365xl/p365xl/p365xl-bentham/'', ''verified''::fitment_confidence, NULL, ''Compatible with P365XL 3.7\" barrels ONLY. 3.1\" barrels NOT compatible. Threaded barrels are compatible.'', ''Fits any P365XL/XMacro frame requires P365XL/X-Macro Recoil Spring Assembly.'', ''17-4 stainless'', NULL, ''The XL Bentham carries over the clean, window-free profile and 17-4 stainless billet construction of the standard Bentham, giving the P365XL a lighter, more refined replacement for its factory slide. It''''s a good fit for owners who want the fit-and-finish and weight benefits of an aftermarket slide without aggressive machining.'', ''{}'', FALSE), (''norsso-rail-p365-xl'', ''slide'', (SELECT id FROM manufacturers WHERE slug=''norsso''), ''Norsso P365XL Rail'', ''https://norsso.com/slides/sig-p365-365xl/p365xl/p365xl-rail/'', ''verified''::fitment_confidence, NULL, ''Compatible with P365XL 3.7\" barrels ONLY. 3.1\" barrels NOT compatible. Threaded barrels are compatible.'', ''Fits any P365XL/XMacro frame requires P365XL/X-Macro Recoil Spring Assembly.'', ''17-4 stainless'', NULL, ''The XL Rail slide adds side window cuts and Norsso''''s precision 17-4 stainless machining to the P365XL, offering better slide-racking grip and a lighter feel than the stock slide. It''''s a dependable, no-frills OEM replacement for owners upgrading an XL for carry or range use.'', ''{}'', FALSE), (''norsso-rail-edc-p365-xl'', ''slide'', (SELECT id FROM manufacturers WHERE slug=''norsso''), ''Norsso P365XL Rail EDC'', ''https://norsso.com/slides/sig-p365-365xl/p365xl/p365xl-rail-edc/'', ''verified''::fitment_confidence, NULL, ''Compatible with P365XL 3.7\" barrels ONLY. 3.1\" barrels NOT compatible. Threaded barrels are compatible.'', ''Fits any P365XL/XMacro frame requires P365XL/X-Macro Recoil Spring Assembly.'', ''17-4 stainless'', NULL, ''Rail EDC for the XL brings the same billet 17-4 stainless build and carry-oriented serration pattern as the standard-frame version, sized correctly for the XL''''s 3.7\" barrel. It''''s a straightforward upgrade for XL owners who want a tougher, better-gripping slide without window cuts or porting.'', ''{}'', FALSE), (''norsso-reptile-edc-p365-xl'', ''slide'', (SELECT id FROM manufacturers WHERE slug=''norsso''), ''Norsso P365XL Reptile EDC'', ''https://norsso.com/slides/sig-p365-365xl/p365xl/p365xl-reptile-edc/'', ''verified''::fitment_confidence, NULL, ''Compatible with P365XL 3.7\" barrels ONLY. 3.1\" barrels NOT compatible. Threaded barrels are compatible.'', ''Fits any P365XL/XMacro frame requires P365XL/X-Macro Recoil Spring Assembly.'', ''17-4 stainless'', NULL, ''The XL Reptile EDC delivers Norsso''''s deep scale-textured grip surface on the longer XL slide, giving noticeably more purchase when racking than the factory slide''''s smooth finish. Machined from heat-treated 17-4 stainless, it''''s a solid everyday-carry replacement for XL owners who prioritize handling over window cuts.'', ''{}'', FALSE), (''norsso-reptile-og-p365-xl'', ''slide'', (SELECT id FROM manufacturers WHERE slug=''norsso''), ''Norsso P365XL Reptile OG'', ''https://norsso.com/slides/sig-p365/p365xl/p365xl-reptile-og/'', ''verified''::fitment_confidence, NULL, ''Compatible with P365XL 3.7\" barrels ONLY. 3.1\" barrels NOT compatible. Threaded barrels are compatible.'', ''Fits any P365XL/XMacro frame requires P365XL/X-Macro Recoil Spring Assembly.'', ''17-4 stainless'', NULL, ''Reptile OG for the XL brings the original 3D dynamic side-window design and aggressive top/forward serrations to the longer slide, the same pattern that made the standard Reptile a well-reviewed upgrade. It''''s a good choice for XL owners who want both weight reduction and a distinctive, aggressive look.'', ''{}'', FALSE), (''norsso-spec-ops-p365-xl'', ''slide'', (SELECT id FROM manufacturers WHERE slug=''norsso''), ''Norsso P365XL Spec Ops'', ''https://norsso.com/slides/sig-p365-365xl/p365xl/p365xl-spec-ops/'', ''verified''::fitment_confidence, NULL, ''Compatible with P365XL 3.7\" barrels ONLY. 3.1\" barrels NOT compatible. Threaded barrels are compatible.'', ''Fits any P365XL/XMacro frame requires P365XL/X-Macro Recoil Spring Assembly.'', ''17-4 stainless'', NULL, ''The XL Spec Ops slide applies Norsso''''s duty-focused deep serration pattern to the P365XL, giving a more positive grip during manipulation than the stock slide''''s shallower cuts. It''''s a proven, well-regarded OEM replacement for owners building a duty or EDC XL.'', ''{}'', FALSE), (''norsso-rail-n365dg-p365-xl'', ''slide'', (SELECT id FROM manufacturers WHERE slug=''norsso''), ''Norsso N365DG Rail'', ''https://norsso.com/slides/n365dg-rail/'', ''verified''::fitment_confidence, ''Integrated compensator slide — requires the P365XL/X-MACRO Recoil Spring Assembly or it may short-stroke.'', ''Compatible with P365 3.1\" barrels ONLY. 3.7\" barrels NOT compatible. Threaded barrels are NOT compatible.'', ''Fits any P365XL/XMacro frame requires P365XL/X-Macro Recoil Spring Assembly.'', ''17-4 stainless'', NULL, ''The N365DG Rail is part of Norsso''''s Dragon Comp series, pairing window-cut serrations with an integrated compensator machined directly into the slide, something no factory Sig slide offers. It''''s built for XL/X-Macro owners who want reduced muzzle rise without adding an external comp or threaded barrel, using a 3.1\" Dragon Comp barrel setup.'', ''{}'', FALSE), (''norsso-rail-edc-n365dg-p365-xl'', ''slide'', (SELECT id FROM manufacturers WHERE slug=''norsso''), ''Norsso N365DG Rail EDC'', ''https://norsso.com/slides/sig-p365-365xl/p365-dragon-comp/n365dg-rail-edc/'', ''verified''::fitment_confidence, ''Integrated compensator slide — requires the P365XL/X-MACRO Recoil Spring Assembly or it may short-stroke.'', ''Compatible with P365 3.1\" barrels ONLY. 3.7\" barrels NOT compatible. Threaded barrels are NOT compatible.'', ''Fits any P365XL/XMacro frame requires P365XL/X-Macro Recoil Spring Assembly.'', ''17-4 stainless'', NULL, ''Rail EDC N365DG combines carry-style serrations with the Dragon Comp line''''s built-in compensator, giving XL/X-Macro owners flat-shooting performance the stock slide can''''t match. Because the comp is machined into the slide itself, there''''s no external attachment to catch on a holster during the draw.'', ''{}'', FALSE), (''norsso-reptile-og-n365dg-p365-xl'', ''slide'', (SELECT id FROM manufacturers WHERE slug=''norsso''), ''Norsso N365DG Reptile OG'', ''https://norsso.com/slides/sig-p365-365xl/p365-dragon-comp/n365dg-reptile-og/'', ''verified''::fitment_confidence, ''Integrated compensator slide — requires the P365XL/X-MACRO Recoil Spring Assembly or it may short-stroke.'', ''Compatible with P365 3.1\" barrels ONLY. 3.7\" barrels NOT compatible. Threaded barrels are NOT compatible.'', ''Fits any P365XL/XMacro frame requires P365XL/X-Macro Recoil Spring Assembly.'', ''17-4 stainless'', NULL, ''Reptile OG N365DG pairs Norsso''''s original aggressive side-window texture with an integrated compensator, combining better grip with reduced muzzle flip in one factory-slide replacement. It''''s aimed at XL/X-Macro owners who want the Reptile look along with genuine recoil-control performance.'', ''{}'', FALSE), (''norsso-spec-ops-n365dg-p365-xl'', ''slide'', (SELECT id FROM manufacturers WHERE slug=''norsso''), ''Norsso N365DG Spec Ops'', ''https://norsso.com/new-norsso/n365dg-spec-ops/'', ''verified''::fitment_confidence, ''Integrated compensator slide — requires the P365XL/X-MACRO Recoil Spring Assembly or it may short-stroke.'', ''Compatible with P365 3.1\" barrels ONLY. 3.7\" barrels NOT compatible. Threaded barrels are NOT compatible.'', ''Fits any P365XL/XMacro frame requires P365XL/X-Macro Recoil Spring Assembly.'', ''17-4 stainless'', NULL, ''Spec Ops N365DG brings the duty-grade serration pattern to Norsso''''s Dragon Comp platform, adding an integrated compensator for flatter follow-up shots without external hardware. It''''s a strong replacement for owners who want both a hard-use grip texture and built-in muzzle control the OEM slide can''''t provide.'', ''{}'', FALSE), (''norsso-rail-cport-p365-xl'', ''slide'', (SELECT id FROM manufacturers WHERE slug=''norsso''), ''Norsso P365XL Rail C'', ''https://norsso.com/slides/sig-p365-365dg-365xl/p365xl-xmacro/p365xl-rail-c/'', ''verified''::fitment_confidence, ''Ported slide — requires the P365XL/X-MACRO Recoil Spring Assembly or it may short-stroke.'', ''Compatible with P365XL 3.7\" barrels ONLY. 3.1\" barrels NOT compatible. Threaded barrels are NOT compatible.'', ''Fits any P365XL/XMacro frame requires P365XL/X-Macro Recoil Spring Assembly.'', ''17-4 stainless'', NULL, ''The XL Rail C adds window cuts and dual top ports to Norsso''''s precision-machined 17-4 stainless slide, giving XL owners reduced muzzle rise and a lighter feel than the unported factory slide. It pairs with a compatible ported barrel for a genuine performance upgrade over stock.'', ''{}'', FALSE), (''norsso-rail-edc-cport-p365-xl'', ''slide'', (SELECT id FROM manufacturers WHERE slug=''norsso''), ''Norsso P365XL Rail EDC C'', ''https://norsso.com/slides/sig-p365-365dg-365xl/p365xl-xmacro/p365xl-rail-edc-c/'', ''verified''::fitment_confidence, ''Ported slide — requires the P365XL/X-MACRO Recoil Spring Assembly or it may short-stroke.'', ''Compatible with P365XL 3.7\" barrels ONLY. 3.1\" barrels NOT compatible. Threaded barrels are NOT compatible.'', ''Fits any P365XL/XMacro frame requires P365XL/X-Macro Recoil Spring Assembly.'', ''17-4 stainless'', NULL, ''Rail EDC C for the XL combines carry-oriented serrations with dual C-ports that vent gas upward, tempering muzzle flip in a way the stock slide simply cannot. It''''s a good pick for XL owners who want both everyday-carry ergonomics and porting performance in one slide.'', ''{}'', FALSE), (''norsso-reptile-cport-p365-xl'', ''slide'', (SELECT id FROM manufacturers WHERE slug=''norsso''), ''Norsso P365XL Reptile C'', ''https://norsso.com/slides/sig-p365/p365xl/p365xl-reptile-c/'', ''verified''::fitment_confidence, ''Ported slide — requires the P365XL/X-MACRO Recoil Spring Assembly or it may short-stroke.'', ''Compatible with P365XL 3.7\" barrels ONLY. 3.1\" barrels NOT compatible. Threaded barrels are NOT compatible.'', ''Fits any P365XL/XMacro frame requires P365XL/X-Macro Recoil Spring Assembly.'', ''17-4 stainless'', NULL, ''The XL Reptile C pairs Norsso''''s aggressive scale texture with dual integrated top ports, giving shooters both a superior grip and flatter recoil than the smooth, unported factory slide. It''''s built for owners chasing performance as much as looks in their P365XL build.'', ''{}'', FALSE), (''norsso-spec-ops-cport-p365-xl'', ''slide'', (SELECT id FROM manufacturers WHERE slug=''norsso''), ''Norsso P365XL Spec Ops C'', ''https://norsso.com/slides/sig-p365-365xl/p365xl/p365xl-spec-ops-c/'', ''verified''::fitment_confidence, ''Ported slide — requires the P365XL/X-MACRO Recoil Spring Assembly or it may short-stroke.'', ''Compatible with P365XL 3.7\" barrels ONLY. 3.1\" barrels NOT compatible. Threaded barrels are not compatible.'', ''Fits any P365XL/XMacro frame requires P365XL/X-Macro Recoil Spring Assembly.'', ''17-4 stainless'', NULL, ''Spec Ops C for the XL adds dual top ports to the duty-focused serration pattern, cutting muzzle rise for faster follow-up shots without a threaded barrel or external comp. It''''s a strong OEM replacement for owners who want a functional, not just cosmetic, upgrade from the stock slide.'', ''{}'', FALSE), (''norsso-rail-edc-n365dg-xp-p365-xl'', ''slide'', (SELECT id FROM manufacturers WHERE slug=''norsso''), ''Norsso N365DG Rail EDC XP'', ''https://norsso.com/new-norsso/n365dg-rail-edc-xp/'', ''verified''::fitment_confidence, ''Ported slide with an integrated compensator — requires the P365XL/X-MACRO Recoil Spring Assembly or it may short-stroke.'', ''Compatible with P365 3.1\" barrels ONLY. 3.7\" barrels NOT compatible. Threaded barrels are NOT compatible.'', ''Fits any P365XL/XMacro frame requires P365XL/X-Macro Recoil Spring Assembly.'', ''17-4 stainless'', NULL, ''The N365DG Rail EDC XP combines Norsso''''s Dragon Comp integrated compensator with dual additional top ports for extra muzzle control, stacking two recoil-reduction features the factory slide can''''t touch. It''''s aimed at XL/X-Macro owners chasing the flattest possible shooting experience from a P365-based platform.'', ''{}'', FALSE), (''norsso-reptile-n365dg-xp-p365-xl'', ''slide'', (SELECT id FROM manufacturers WHERE slug=''norsso''), ''Norsso N365DG Reptile XP'', ''https://norsso.com/slides/sig-p365-365dg-365xl/p365-dragon-xmacro-comp/n365dg-reptile-xp/'', ''verified''::fitment_confidence, ''Ported slide with an integrated compensator — requires the P365XL/X-MACRO Recoil Spring Assembly or it may short-stroke.'', ''Compatible with P365 3.1\" barrels ONLY. 3.7\" barrels NOT compatible. Threaded barrels are NOT compatible.'', ''Fits any P365XL/XMacro frame requires P365XL/X-Macro Recoil Spring Assembly.'', ''17-4 stainless'', NULL, ''Reptile N365DG XP layers Norsso''''s aggressive Reptile texture, a built-in compensator, and dual top ports into one slide, giving XL/X-Macro owners the brand''''s most performance-focused muzzle control alongside its most aggressive grip pattern. It''''s a top-tier replacement for shooters building a dedicated competition- or performance-oriented P365.'', ''{}'', FALSE), (''true-precision-axiom-p365'', ''slide'', (SELECT id FROM manufacturers WHERE slug=''true-precision''), ''True Precision Axiom P365'', ''https://true-precision.com/sig-p365-axiom-slide-with-rmsc-romeo-zero-optic-cut/'', ''verified''::fitment_confidence, NULL, ''Compatible with P365 3.1\" barrels ONLY. 3.7\" barrels NOT compatible. Threaded barrels are compatible.'', ''Fits any P365 frame. On XL/XMacro frame requires P365XL/X-Macro Recoil Spring Assembly.'', ''17-4 stainless'', NULL, ''The True Precision Axiom replaces the factory MIM slide with a billet 17-4ph steel design featuring lightweight side-cut windows, a top-milled pocket, and scalloped front/angled rear serrations for a more secure grip when racking. Its optic footprint accepts Shield RMSc, Holosun 507K/EPS Carry, Sig RomeoZero, and several other micro red dots, giving P365 owners far more optic flexibility than the stock slide allows, and it''''s 100% US manufactured.'', ''{}'', FALSE), (''true-precision-axiom-p365-xl'', ''slide'', (SELECT id FROM manufacturers WHERE slug=''true-precision''), ''True Precision Axiom P365XL'', ''https://true-precision.com/axiom-sig-p365-xl-xmacro-9mm-optic-cut-slide/'', ''verified''::fitment_confidence, NULL, ''Compatible with P365XL 3.7\" barrels ONLY. 3.1\" barrels NOT compatible. Threaded barrels are compatible.'', ''Fits any P365XL/XMacro frame requires P365XL/X-Macro Recoil Spring Assembly.'', ''17-4 stainless'', NULL, ''Sized for the P365XL, the Axiom carries over True Precision''''s billet 17-4ph construction, side-cut windows, and scalloped serration pattern while adding a wide-compatibility optic cut for RMSc, Holosun, and RomeoZero-pattern red dots. It''''s a US-made, well-reviewed upgrade for XL owners who want both a lighter, better-finished slide and broad optic support the factory slide doesn''''t offer.'', ''{}'', FALSE), (''grey-ghost-precision-v1-p365'', ''slide'', (SELECT id FROM manufacturers WHERE slug=''grey-ghost-precision''), ''Grey Ghost Precision GGP365 V1'', ''https://greyghostprecision.com/ggp365-slides/'', ''verified''::fitment_confidence, NULL, ''Compatible with P365 3.1\" barrels ONLY. 3.7\" barrels NOT compatible. Threaded barrels are compatible.'', ''Fits any P365 frame. On XL/XMacro frame requires P365XL/X-Macro Recoil Spring Assembly.'', ''17-4 stainless'', NULL, ''The GGP365 V1 is a stripped 17-4 stainless slide with aggressive front and rear serrations for a firm grip in high-stress situations, plus an optic cut compatible with the Shield RMS-C and Sig RomeoZero (a G10 cover plate is included for running it optics-off). It''''s a durable, purpose-built replacement for shooters who want maximum grip texture over the factory slide''''s more modest checkering.'', ''{}'', FALSE), (''grey-ghost-precision-v2-p365'', ''slide'', (SELECT id FROM manufacturers WHERE slug=''grey-ghost-precision''), ''Grey Ghost Precision GGP365 V2'', ''https://greyghostprecision.com/ggp365-slides/'', ''verified''::fitment_confidence, NULL, ''Compatible with P365 3.1\" barrels ONLY. 3.7\" barrels NOT compatible. Threaded barrels are compatible.'', ''Fits any P365 frame. On XL/XMacro frame requires P365XL/X-Macro Recoil Spring Assembly.'', ''17-4 stainless'', NULL, ''The GGP365 V2 uses the same 17-4 stainless construction and RMS-C/RomeoZero optic cut as the V1, but with a recessed, fine-serration pattern front and rear for a cleaner look while still improving on the factory slide''''s grip and material. It''''s a good fit for owners who want Grey Ghost Precision''''s build quality with a less aggressive aesthetic.'', ''{}'', FALSE), (''norsso-rail-edc-p365-fuse'', ''slide'', (SELECT id FROM manufacturers WHERE slug=''norsso''), ''Norsso P365-FUSE Rail EDC'', ''https://norsso.com/new-norsso/p365-fuse-rail-edc/'', ''verified''::fitment_confidence, NULL, ''Compatible with P365-FUSE 4.3\" barrels ONLY. Threaded barrels are compatible.'', ''Fits any P365 frame. Requires P365-FUSE Recoil Spring Assembly.'', ''17-4 stainless'', NULL, ''Sized for the 4.3\" P365-FUSE, the Rail EDC slide brings Norsso''''s precision 17-4 stainless machining and carry-oriented serrations to the platform''''s longer format, giving FUSE owners a tougher, better-gripping alternative to the factory slide. It''''s a solid everyday-carry replacement without ports or an integrated comp.'', ''{}'', FALSE), (''norsso-barracuda-edc-p365-fuse'', ''slide'', (SELECT id FROM manufacturers WHERE slug=''norsso''), ''Norsso P365-FUSE Barracuda EDC'', ''https://norsso.com/new-norsso/p365-fuse-barracuda-edc/'', ''verified''::fitment_confidence, NULL, ''Compatible with P365-FUSE 4.3\" barrels ONLY. Threaded barrels are compatible.'', ''Fits any P365 frame. Requires P365-FUSE Recoil Spring Assembly.'', ''17-4 stainless'', NULL, ''The Barracuda EDC offers a distinct texture pattern within Norsso''''s FUSE lineup, combining 17-4 stainless billet construction with a carry-focused serration design for better slide manipulation than the stock FUSE slide. It''''s a good choice for FUSE owners who want Norsso''''s build quality in a different aesthetic from the Rail or Reptile patterns.'', ''{}'', FALSE), (''norsso-rail-kp-p365-fuse'', ''slide'', (SELECT id FROM manufacturers WHERE slug=''norsso''), ''Norsso P365-FUSE Rail KP'', ''https://norsso.com/new-norsso/p365-fuse-rail-kp/'', ''verified''::fitment_confidence, ''Ported slide — requires the P365-FUSE Recoil Spring Assembly or it may short-stroke.'', ''Compatible with P365-FUSE 4.3\" E Port barrels ONLY. Threaded barrels are NOT compatible.'', ''Fits any P365 frame. Requires P365-FUSE Recoil Spring Assembly.'', ''17-4 stainless'', NULL, ''The Rail KP pairs window cuts and a single top E-port with Norsso''''s rail-style serrations, venting gas to reduce muzzle rise on the longer FUSE slide, something the factory slide can''''t do. It requires a Norsso E-Port compatible barrel and is a strong pick for FUSE owners chasing flatter recoil.'', ''{}'', FALSE), (''norsso-reptile-edc-p365-fuse'', ''slide'', (SELECT id FROM manufacturers WHERE slug=''norsso''), ''Norsso P365-FUSE Reptile EDC'', ''https://norsso.com/new-norsso/p365-fuse-reptile-edc/'', ''verified''::fitment_confidence, NULL, ''Compatible with P365-FUSE 4.3\" barrels ONLY. Threaded barrels are compatible.'', ''Fits any P365 frame. Requires P365-FUSE Recoil Spring Assembly.'', ''17-4 stainless'', NULL, ''Reptile EDC for the FUSE brings Norsso''''s deep scale-textured grip surface to the platform''''s 4.3\" slide, giving noticeably better purchase when racking than the smooth factory finish. It''''s a solid everyday-carry replacement built from heat-treated 17-4 stainless without added porting.'', ''{}'', FALSE), (''norsso-reptile-kp-p365-fuse'', ''slide'', (SELECT id FROM manufacturers WHERE slug=''norsso''), ''Norsso P365-FUSE Reptile KP'', ''https://norsso.com/new-norsso/p365-fuse-reptile-kp/'', ''verified''::fitment_confidence, ''Ported slide — requires the P365-FUSE Recoil Spring Assembly or it may short-stroke.'', ''Compatible with P365-FUSE 4.3\" E Port barrels ONLY. Threaded barrels are NOT compatible.'', ''Fits any P365 frame. Requires P365-FUSE Recoil Spring Assembly.'', ''17-4 stainless'', NULL, ''Reptile KP combines the aggressive Reptile texture with a single top E-port for reduced muzzle rise, giving FUSE owners both superior grip and flatter recoil in one factory-slide replacement. It requires an E-Port compatible barrel and suits shooters who want both looks and ported performance.'', ''{}'', FALSE), (''norsso-reptile-cport-p365-fuse'', ''slide'', (SELECT id FROM manufacturers WHERE slug=''norsso''), ''Norsso P365-FUSE Reptile C'', ''https://norsso.com/new-norsso/p365-fuse-reptile-c/'', ''verified''::fitment_confidence, ''Ported slide — requires the P365-FUSE Recoil Spring Assembly or it may short-stroke.'', ''Compatible with P365-FUSE 4.3\" barrels ONLY. Threaded barrels are NOT compatible.'', ''Fits any P365 frame. Requires P365-FUSE Recoil Spring Assembly.'', ''17-4 stainless'', NULL, ''The Reptile C for FUSE pairs the deep scale-textured grip pattern with dual top C-ports, tempering muzzle flip on the platform''''s longer slide well beyond what the stock, unported slide offers. It''''s aimed at FUSE owners who want both aggressive grip texture and genuine porting performance.'', ''{}'', FALSE), (''norsso-piranha-cport-p365-fuse'', ''slide'', (SELECT id FROM manufacturers WHERE slug=''norsso''), ''Norsso P365-FUSE Piranha C'', ''https://norsso.com/slides/p365-fuse-piranha-c/'', ''verified''::fitment_confidence, ''Ported slide — requires the P365-FUSE Recoil Spring Assembly or it may short-stroke.'', ''Compatible with P365-FUSE 4.3\" barrels ONLY. Threaded barrels are NOT compatible.'', ''Fits any P365 frame. Requires P365-FUSE Recoil Spring Assembly.'', ''17-4 stainless'', NULL, ''The Piranha C is a distinct Norsso FUSE pattern featuring dual top C-ports for reduced muzzle rise, giving the platform a flatter-shooting alternative to the smooth factory slide. It''''s a strong choice for FUSE owners prioritizing recoil control in their slide upgrade.'', ''{}'', FALSE), (''zaffiri-zps2-p365-xl'', ''slide'', (SELECT id FROM manufacturers WHERE slug=''zaffiri-precision''), ''Zaffiri Precision ZPS.2 P365XL'', ''https://zaffiriprecision.com/product/zps-2-slide-for-sig-p365-xl-rmsc-optic-cut/'', ''verified''::fitment_confidence, NULL, ''Compatible with P365XL 3.7\" barrels ONLY. 3.1\" barrels NOT compatible. Threaded barrels are compatible.'', ''Fits any P365XL/XMacro frame requires P365XL/X-Macro Recoil Spring Assembly. Designed for NEW STYLE Sig P365 Extractor.'', ''17-4 stainless'', NULL, ''The Zaffiri Precision ZPS.2 is machined from a single billet of 17-4 stainless steel with tight tolerances, direct-cut for RMSc-pattern optics so red dots mount low and close to the bore without an adapter plate. Its clean, window-free lines and low optic height make it a refined, accuracy-focused replacement for the factory XL slide, whether for daily carry or a competition-leaning build.'', ''{}'', FALSE), (''zaffiri-zpsp-p365-xl'', ''slide'', (SELECT id FROM manufacturers WHERE slug=''zaffiri-precision''), ''Zaffiri Precision ZPS.P Ported P365XL'', ''https://zaffiriprecision.com/product/zps-p-ported-slide-for-sig-p365-xl-rmsc/'', ''verified''::fitment_confidence, ''Ported slide — requires the P365XL/X-MACRO Recoil Spring Assembly or it may short-stroke.'', ''Compatible with P365XL 3.7\" barrels ONLY. 3.1\" barrels NOT compatible. ZP ported barrels only compatible with ZPS.P and ZPS.4 slides.'', ''Fits any P365XL/XMacro frame requires P365XL/X-Macro Recoil Spring Assembly. Designed for NEW STYLE Sig P365 Extractor.'', ''17-4 stainless'', NULL, ''The ZPS.P adds Norsso-style side-window cuts and dual C-ports to Zaffiri''''s billet 17-4 stainless slide, pairing improved grip texture with genuine muzzle-rise reduction when run with a compatible ZP ported barrel. It''''s a performance-oriented replacement for XL owners who want porting benefits the factory slide can''''t provide, though it does require a matching ported barrel.'', ''{}'', FALSE), (''true-precision-p365-fuse'', ''slide'', (SELECT id FROM manufacturers WHERE slug=''true-precision''), ''True Precision P365-FUSE'', ''https://true-precision.com/sig-p365-fuse-optic-cut-slide/'', ''verified''::fitment_confidence, NULL, ''Compatible with P365-FUSE 4.3\" barrels. Also fits P365 (3.1\") and P365XL (3.7\") lowers/FCUs with the correct barrel and recoil spring.'', ''Blends True Precision''''s Duty and Axiom slide designs into a hybrid pattern unique to the FUSE.'', ''416R stainless'', NULL, ''True Precision''''s Duty slide for the P365-FUSE blends its Duty and Axiom lines into a hybrid design cut from 416R stainless, with lightweight side-cut windows, a top-milled pocket, and scalloped front/angled rear serrations for a far more secure grip than the factory slide. It carries an RMSc-pattern optic cut compatible with Holosun and RomeoZero red dots, giving FUSE owners the same US-made material and optic upgrade path already available on the standard P365 and XL Axiom slides.'', ''{}'', FALSE);"}', 'p365_slides_clean_insert_products', 'ag.gamboa94@gmail.com', NULL, NULL);
