INSERT INTO "supabase_migrations"."schema_migrations" ("version", "statements", "name", "created_by", "idempotency_key", "rollback") VALUES ('20260810001048', '{"
-- Remove placeholder barrel data in FK order
DELETE FROM barrel_slide_requirements WHERE barrel_product_id IN (SELECT id FROM products WHERE category = ''barrel'');
DELETE FROM barrel_specs WHERE product_id IN (SELECT id FROM products WHERE category = ''barrel'');
DELETE FROM products WHERE category = ''barrel'';
-- Verify
SELECT count(*) AS remaining FROM products WHERE category = ''barrel'';
"}', 'p365_barrels_clean_placeholders', 'ag.gamboa94@gmail.com', NULL, NULL);
