(''norsso-p365-threaded-lvl1-5'', ''barrel''::product_category, (SELECT id FROM manufacturers WHERE slug=''norsso''), ''Norsso P365 3.1\" LVL1.5 Threaded Barrel'', ''p365'', ''https://norsso.com/parts/sig-p365-parts/barrels/n365-3-75-length-9mm-threaded-barrel-satin-stainless-lvl-1-5/'', ''verified''::fitment_confidence, NULL, ''Fits P365/P365X/SAS slides. Accepts any 1/2x28 compensator.'', ''Pairs with any 1/2x28 comp.'', ''17-4 PH stainless steel'', ''Threaded barrel for compensator or suppressor builds.'', ARRAY[''compensator-builds'',''suppressor-builds''], NULL, NULL, FALSE),
(''norsso-n365-cport'', ''barrel''::product_category, (SELECT id FROM manufacturers WHERE slug=''norsso''), ''Norsso N365 3.1\" C Port Barrel'', ''p365'', ''https://norsso.com/barrels/n365-3-1-9mm-c-port-barrel/'', ''verified''::fitment_confidence, ''Norsso C-Port slides only: P365 Spec Ops C, P365 Rail EDC C, P365 Reptile C, N365DG Rail EDC C, N365DG Reptile XP'', ''Ports align with Norsso C-Port slides ONLY. Dangerous in non-matching slides.'', ''Must pair with a Norsso C-Port slide.'', ''17-4 PH stainless steel'', ''C-port barrel that aligns with Norsso C-port slide ports.'', ARRAY[''competition'',''range''], NULL, NULL, FALSE),
(''norsso-p365-xl-standard-lvl1-5'', ''barrel''::product_category, (SELECT id FROM manufacturers WHERE slug=''norsso''), ''Norsso P365-XL/XMACRO 3.7\" LVL1.5 Standard Barrel'', ''p365'', ''https://norsso.com/barrels/sig-p365-p365xl-9mm-barrels/3-7-p365xl-xmacro/n365xl-3-7-9mm-standard-barrel-black-lvl1-5/'', ''verified''::fitment_confidence, NULL, ''Drop-in fit for standard P365XL/XMACRO 3.7\" slides. Non-LCI.'', NULL, ''17-4 PH stainless steel'', ''Drop-in flush & crown barrel for the P365XL/XMACRO'', ARRAY[''concealed-carry'',''range''], NULL, NULL, FALSE),
(''norsso-p365-xl-threaded-lvl1-5'', ''barrel''::product_category, (SELECT id FROM manufacturers WHERE slug=''norsso''), ''Norsso P365-XL/XMACRO 3.7\" LVL1.5 Threaded Barrel'', ''p365'', ''https://norsso.com/parts/sig-p365xl-parts/barrels/n365xl-4-35-length-9mm-threaded-barrel-black-lvl-1-5/'', ''verified''::fitment_confidence, NULL, ''Fits P365XL/XMACRO slides. Accepts any 1/2x28 compensator.'', ''Pairs with any 1/2x28 comp.'', ''17-4 PH stainless steel'', ''Threaded barrel for compensator or suppressor builds.'', ARRAY[''compensator-builds'',''suppressor-builds''], NULL, NULL, FALSE),
(''norsso-n365xl-cport'', ''barrel''::product_category, (SELECT id FROM manufacturers WHERE slug=''norsso''), ''Norsso N365XL 3.7\" C Port Barrel'', ''p365'', ''https://norsso.com/barrels/n365xl-3-7-9mm-c-port-barrel/'', ''verified''::fitment_confidence, ''Norsso C-Port slides only: P365XL Spec Ops C, P365XL Rail C, P365XL Rail EDC C, P365XL Reptile C'', ''Ports align with Norsso C-Port slides ONLY. Dangerous in non-matching slides.'', ''Must pair with a Norsso C-Port slide.'', ''17-4 PH stainless steel'', ''C-port barrel that aligns with Norsso C-port slide ports.'', ARRAY[''competition'',''range''], NULL, NULL, FALSE),
(''true-precision-p365-non-threaded'', ''barrel''::product_category, (SELECT id FROM manufacturers WHERE slug=''true-precision''), ''True Precision P365 3.1\" Non-Threaded Barrels'', ''p365'', ''https://true-precision.com/sig-p365-non-threaded/'', ''verified''::fitment_confidence, NULL, ''Drop-in fit for standard P365 3.1\" slides. Non-LCI.'', NULL, ''416R stainless steel'', ''Drop-in flush & crown barrel for the P365.'', ARRAY[''concealed-carry'',''range''], NULL, NULL, FALSE),
(''true-precision-p365-threaded'', ''barrel''::product_category, (SELECT id FROM manufacturers WHERE slug=''true-precision''), ''True Precision P365 3.1\" Threaded Barrels'', ''p365'', ''https://true-precision.com/sig-p365-threaded/'', ''verified''::fitment_confidence, NULL, ''Fits P365/P365X/SAS slides. Accepts any 1/2x28 compensator.'', ''Pairs with any 1/2x28 comp.'', ''416R stainless steel'', ''Threaded barrel for compensator or suppressor builds.'', ARRAY[''compensator-builds'',''suppressor-builds''], NULL, NULL, FALSE),
(''true-precision-p365-xl-non-threaded'', ''barrel''::product_category, (SELECT id FROM manufacturers WHERE slug=''true-precision''), ''True Precision P365 3.7\" Non-Threaded Barrels'', ''p365'', ''https://true-precision.com/sig-p365-xl-non-threaded/'', ''verified''::fitment_confidence, NULL, ''Drop-in fit for standard P365XL/XMACRO 3.7\" slides. Non-LCI.'', NULL, ''416R stainless steel'', ''Drop-in flush & crown barrel for the P365XL/XMACRO'', ARRAY[''concealed-carry'',''range''], NULL, NULL, FALSE),
(''true-precision-p365-xl-threaded'', ''barrel''::product_category, (SELECT id FROM manufacturers WHERE slug=''true-precision''), ''True Precision P365XL 3.7\" Threaded Barrels'', ''p365'', ''https://true-precision.com/sig-p365-xl-threaded/'', ''verified''::fitment_confidence, NULL, ''Fits P365XL/XMACRO slides. Accepts any 1/2x28 compensator.'', ''Pairs with any 1/2x28 comp.'', ''416R stainless steel'', ''Threaded barrel for compensator or suppressor builds.'', ARRAY[''compensator-builds'',''suppressor-builds''], NULL, NULL, FALSE),
(''true-precision-p365-fuse-non-threaded'', ''barrel''::product_category, (SELECT id FROM manufacturers WHERE slug=''true-precision''), ''True Precision P365 Fuse 4.3\" Non-Threaded Barrels'', ''p365'', ''https://true-precision.com/sig-p365-fuse-non-threaded-barrels-for-4-3-pistols/'', ''verified''::fitment_confidence, NULL, ''Drop-in fit for P365-FUSE 4.3\" slides.  NOT FOR USE WITH P365-FUSE COMP SLIDE PISTOLS (per True Precision''''s product page).'', NULL, ''416R stainless steel'', ''Drop-in flush & crown barrel for the P365 FUSE'', ARRAY[''concealed-carry'',''range''], NULL, NULL, FALSE),
(''true-precision-p365-fuse-threaded'', ''barrel''::product_category, (SELECT id FROM manufacturers WHERE slug=''true-precision''), ''True Precision P365 Fuse 4.3\" Threaded Barrels'', ''p365'', ''https://true-precision.com/sig-p365-fuse-threaded-barrels'', ''verified''::fitment_confidence, NULL, ''Drop-in fit for P365-FUSE 4.3\" slides. Accepts any 1/2x28 compensator. NOT FOR USE WITH P365-FUSE COMP SLIDE PISTOLS (per True Precision''''s product page).'', ''Pairs with any 1/2x28 comp.'', ''416R stainless steel'', ''Threaded barrel for compensator or suppressor builds.'', ARRAY[''compensator-builds'',''suppressor-builds''], NULL, NULL, FALSE),
(''radian-afterburner-p365'', ''barrel''::product_category, (SELECT id FROM manufacturers WHERE slug=''radian-weapons''), ''Radian Ramjet Barrel + Afterburner Compensator Combo — P365'', ''p365'', ''https://radianweapons.com/product/afterburner-ramjet-for-sig-sauer'', ''verified''::fitment_confidence, ''Not slide-specific in the port-matched sense — the AFTERBURNER compensator clamps onto the RAMJET barrel itself (INTRA-LOK mount), not into slide-cut ports. Per Norsso''''s own fitment test, it''''s compatible with all of their P365 slide profiles, and should fit any standard (non-integrally-compensated) P365-length slide. NOT compatible with SIG factory XMACRO COMP / Spectre Comp / FUSE COMP integrally-compensated slides (can''''t stack two comps), and NOT compatible with LCI (loaded chamber indicator) equipped models.'', ''Sold as a barrel+compensator combo kit, not a barrel alone. Requires the 3.1\" barrel-length recoil spring even when run on a longer (XL) frame, since the RAMJET barrel itself is 3.1\"; adjust spring weight to taste. Installing it on a P365/P365X extends slide length to XL proportions (fits XL holsters).'', ''Barrel and Ramjet comp are a matched system — sold and used together.'', ''416R stainless steel'', ''The barrel half of the Radian Afterburner + Ramjet system for the P365. Uses the INTRA-LOK taper-lock mount to pair exclusively with the Radian Ramjet compensator.'', ARRAY[''compensator-builds'',''competition'',''concealed-carry''], NULL, NULL, FALSE),
(''radian-afterburner-p365-xl'', ''barrel''::product_category, (SELECT id FROM manufacturers WHERE slug=''radian-weapons''), ''Radian Ramjet Barrel + Afterburner Compensator Combo — P365XL'', ''p365'', ''https://radianweapons.com/product/afterburner-ramjet-for-sig-sauer'', ''verified''::fitment_confidence, ''Not slide-specific in the port-matched sense — the AFTERBURNER compensator clamps onto the RAMJET barrel itself (INTRA-LOK mount), not into slide-cut ports. Should fit any standard (non-integrally-compensated) P365XL/X-Macro-length slide. NOT compatible with SIG factory XMACRO COMP / FUSE COMP integrally-compensated slides (can''''t stack two comps), and NOT compatible with LCI (loaded chamber indicator) equipped models.'', ''Sold as a barrel+compensator combo kit, not a barrel alone. Installing it on a P365XL/X-Macro extends slide length to P365-FUSE proportions (fits FUSE holsters). Will NOT work with XMACRO-length integrally-compensated slides (dual top comp ports at the muzzle).'', ''Barrel and Ramjet comp are a matched system — sold and used together.'', ''416R stainless steel'', ''The barrel half of the Radian Afterburner + Ramjet system for the P365XL. Uses the INTRA-LOK taper-lock mount to pair exclusively with the Radian Ramjet compensator.'', ARRAY[''compensator-builds'',''competition'',''concealed-carry''], NULL, NULL, FALSE),
(''norsso-p365-fuse-standard'', ''barrel''::product_category, (SELECT id FROM manufacturers WHERE slug=''norsso''), ''Norsso P365-FUSE 4.3\" Standard Barrel, LVL1.5'', ''p365'', ''https://norsso.com/barrels/p365-fuse-4-3-standard-barrel-satin-stainless-lvl1-5/'', ''verified''::fitment_confidence, NULL, ''Drop-in fit for P365-FUSE 4.3\" slides (non-LCI only -- no LCI slot on this barrel). Works best with Norsso N365-FUSE slides but also drop-in compatible with factory P365-FUSE slides.'', NULL, ''17-4 PH stainless steel'', ''Norsso''''s flush & crowned 4.3\" standard barrel for the P365-FUSE platform. CNC machined in-house from 17-4 PH stainless for greater longevity than 416 SS.'', ARRAY[''concealed-carry'',''range''], NULL, NULL, FALSE),
(''norsso-n365-fuse-cport'', ''barrel''::product_category, (SELECT id FROM manufacturers WHERE slug=''norsso''), ''Norsso N365-FUSE 4.3\" 9mm C Port Barrel'', ''p365'', ''https://norsso.com/barrels/n365-fuse-4-3-9mm-c-port-barrel/'', ''verified''::fitment_confidence, ''P365-FUSE Piranha C, P365-FUSE Reptile C. NOT compatible with any SIG factory slide or any other manufacturer''''s slide.'', ''Two diagonally-positioned C-pattern gas ports, cut for the matching Norsso comp slides only.'', ''Recommend black iron sights with no fiber optic/tritium -- ported gas can foul or damage them.'', ''17-4 PH stainless steel'', ''Norsso''''s C-port 4.3\" barrel for the P365-FUSE platform. CNC machined in-house from 17-4 PH stainless.'', ARRAY[''competition'',''range''], NULL, NULL, FALSE),
(''norsso-n365-fuse-eport'', ''barrel''::product_category, (SELECT id FROM manufacturers WHERE slug=''norsso''), ''Norsso N365-FUSE 4.3\" 9mm E Port Barrel'', ''p365'', ''https://norsso.com/barrels/n365-fuse-4-3-9mm-e-port-barrel/'', ''verified''::fitment_confidence, ''P365-FUSE Reptile KP, P365-FUSE Rail KP. NOT compatible with any SIG factory slide or any other manufacturer''''s slide.'', ''Inline elliptical (E-pattern) gas ports, cut for the matching Norsso comp slides only.'', ''Recommend black iron sights with no fiber optic/tritium -- ported gas can foul or damage them.'', ''17-4 PH stainless steel'', ''Norsso''''s E-port 4.3\" barrel for the P365-FUSE platform. CNC machined in-house from 17-4 PH stainless.'', ARRAY[''competition'',''range''], NULL, NULL, FALSE),
(''zaffiri-p365-threaded'', ''barrel''::product_category, (SELECT id FROM manufacturers WHERE slug=''zaffiri-precision''), ''Zaffiri Precision P365 Threaded Barrel'', ''p365'', ''https://zaffiriprecision.com/product/threaded-barrel-for-sig-sauer-p365/'', ''verified''::fitment_confidence, NULL, ''Drop-in fit for standard P365 3.1\" slides. Compatible with Zaffiri slide models (ZPS.2, ZPS.3, Z Series, IBS) as well as OEM/aftermarket. Has an LCI notch -- check state LCI requirements.'', ''Pairs with any 1/2x28 comp/suppressor.'', ''416R stainless steel'', ''Zaffiri Precision''''s threaded barrel for the P365, machined from 416R stainless in Largo, FL.'', ARRAY[''compensator-builds'',''suppressor-builds''], NULL, NULL, FALSE),
(''zaffiri-p365-flush-crown'', ''barrel''::product_category, (SELECT id FROM manufacturers WHERE slug=''zaffiri-precision''), ''Zaffiri Precision P365 Flush & Crown Barrel'', ''p365'', ''https://zaffiriprecision.com/product/flush-and-crown-barrel-for-sig-sauer-p365/'', ''verified''::fitment_confidence, NULL, ''Drop-in fit for standard P365 3.1\" slides. Compatible with Zaffiri slide models (ZPS.2, ZPS.3, Z Series, IBS) as well as OEM/aftermarket. Has an LCI notch -- check state LCI requirements.'', NULL, ''416R stainless steel'', ''Zaffiri Precision''''s flush & crown (non-threaded) barrel for the P365, machined from 416R stainless in Largo, FL.'', ARRAY[''concealed-carry'',''range''], NULL, NULL, FALSE),
(''zaffiri-p365-xl-threaded'', ''barrel''::product_category, (SELECT id FROM manufacturers WHERE slug=''zaffiri-precision''), ''Zaffiri Precision P365XL Threaded Barrel'', ''p365'', ''https://zaffiriprecision.com/product/p365xl-barrel-threaded-stainless/'', ''verified''::fitment_confidence, NULL, ''Drop-in fit for P365XL 3.7\" slides. Explicitly listed as NO LCI on the product page.'', ''Thread protector included. Pairs with any 1/2x28 comp/suppressor.'', ''416R stainless steel'', ''Zaffiri Precision''''s threaded barrel for the P365XL. This was a single-finish (Stainless) listing -- generalized here per catalog convention, color moved to Variants.'', ARRAY[''compensator-builds'',''suppressor-builds''], NULL, NULL, FALSE),
(''zaffiri-p365-xl-flush-crown'', ''barrel''::product_category, (SELECT id FROM manufacturers WHERE slug=''zaffiri-precision''), ''Zaffiri Precision P365XL Flush & Crown Barrel'', ''p365'', ''https://zaffiriprecision.com/product/flush-and-crown-barrel-for-sig-sauer-p365xl/'', ''verified''::fitment_confidence, NULL, ''Drop-in fit for P365XL 3.7\" slides. Compatible with Zaffiri slide models (ZPS.2, ZPS.3, Z Series, IBS) as well as OEM/aftermarket.'', NULL, ''416R stainless steel'', ''Zaffiri Precision''''s flush & crown (non-threaded) barrel for the P365XL, machined from 416R stainless in Largo, FL.'', ARRAY[''concealed-carry'',''range''], NULL, NULL, FALSE);"}', 'p365_barrels_insert_products', 'ag.gamboa94@gmail.com', NULL, NULL);
