INSERT INTO "supabase_migrations"."schema_migrations" ("version", "statements", "name", "created_by", "idempotency_key", "rollback") VALUES ('20260810021934', '{"
DELETE FROM affiliate_links WHERE variant_id IN (SELECT id FROM product_variants WHERE product_id IN (SELECT id FROM products WHERE category = ''barrel''));
DELETE FROM product_variants WHERE product_id IN (SELECT id FROM products WHERE category = ''barrel'');
DELETE FROM barrel_slide_requirements;
DELETE FROM barrel_specs;
DELETE FROM products WHERE category = ''barrel'';

-- Verify
SELECT count(*) AS remaining_barrels FROM products WHERE category = ''barrel'';
"}', 'p365_barrels_delete_all', 'ag.gamboa94@gmail.com', NULL, NULL);
INSERT INTO "supabase_migrations"."schema_migrations" ("version", "statements", "name", "created_by", "idempotency_key", "rollback") VALUES ('20260810025257', '{"INSERT INTO products (slug,category,brand_id,name,family,url,fitment_confidence,build_warning,fitment_notes,build_notes,material,description,best_for,base_price,editor_rating,is_discontinued) VALUES
(''norsso-p365-standard-lvl1-5'', ''barrel''::product_category, (SELECT id FROM manufacturers WHERE slug=''norsso''), ''Norsso P365 3.1\" LVL1.5 Standard Barrel'', ''p365'', ''https://norsso.com/barrels/p365-3-1-9mm-standard-barrel-black-lvl1-5/'', ''verified''::fitment_confidence, NULL, ''Drop-in fit for standard P365 3.1\" slides. Non-LCI.'', NULL, ''17-4 PH stainless steel'', ''Machined in-house from solid 17-4 PH stainless steel bar stock rather than the factory''''s cast/MIM construction, this Norsso barrel drops straight into a standard P365 slide and skips the loaded chamber indicator slot entirely, which keeps carbon and gas fouling off your optic glass. It''''s a durable, better-finished replacement for owners who just want a stronger non-threaded barrel without changing anything else about the build.'', ARRAY[''concealed-carry'',''range''], 169.0, NULL, FALSE),
(''norsso-p365-threaded-lvl1-5'', ''barrel''::product_category, (SELECT id FROM manufacturers WHERE slug=''norsso''), ''Norsso P365 3.1\" LVL1.5 Threaded Barrel'', ''p365'', ''https://norsso.com/parts/sig-p365-parts/barrels/n365-3-75-length-9mm-threaded-barrel-satin-stainless-lvl-1-5/'', ''verified''::fitment_confidence, NULL, ''Fits P365/P365X/SAS slides. Accepts any 1/2x28 compensator.'', ''Pairs with any 1/2x28 comp.'', ''17-4 PH stainless steel'', ''This 17-4 PH stainless barrel adds 1/2x28 threading the factory Sig barrel doesn''''t have, opening the door to any standard compensator or suppressor while still dropping into P365/P365X slides as a factory replacement. It''''s built in-house to the same non-LCI standard as Norsso''''s other P365 barrels, so gas and carbon stay off your sight glass.'', ARRAY[''compensator-builds'',''suppressor-builds''], 179.0, NULL, FALSE),
(''norsso-n365-cport'', ''barrel''::product_category, (SELECT id FROM manufacturers WHERE slug=''norsso''), ''Norsso N365 3.1\" C Port Barrel'', ''p365'', ''https://norsso.com/barrels/n365-3-1-9mm-c-port-barrel/'', ''verified''::fitment_confidence, ''Norsso C-Port slides only: P365 Spec Ops C, P365 Rail EDC C, P365 Reptile C, N365DG Rail EDC C, N365DG Reptile XP'', ''Ports align with Norsso C-Port slides ONLY. Dangerous in non-matching slides.'', ''Must pair with a Norsso C-Port slide.'', ''17-4 PH stainless steel'', ''This C-Port barrel cuts two diagonally-placed gas ports directly into a 17-4 stainless barrel to knock down muzzle flip without adding a threaded compensator, something no OEM Sig barrel offers. It only works with Norsso''''s matching C-Port slides, but for owners running one of those slides it''''s a real performance upgrade over the smooth factory barrel, not just a cosmetic swap.'', ARRAY[''competition'',''range''], 209.0, NULL, FALSE),
(''norsso-p365-xl-standard-lvl1-5'', ''barrel''::product_category, (SELECT id FROM manufacturers WHERE slug=''norsso''), ''Norsso P365-XL/XMACRO 3.7\" LVL1.5 Standard Barrel'', ''p365'', ''https://norsso.com/barrels/sig-p365-p365xl-9mm-barrels/3-7-p365xl-xmacro/n365xl-3-7-9mm-standard-barrel-black-lvl1-5/'', ''verified''::fitment_confidence, NULL, ''Drop-in fit for standard P365XL/XMACRO 3.7\" slides. Non-LCI.'', NULL, ''17-4 PH stainless steel'', ''The XL version of Norsso''''s standard barrel brings the same in-house 17-4 PH stainless construction and non-LCI design to the P365XL/X-Macro, giving owners a tougher, better-finished replacement for the factory barrel without changing fitment. Skipping the LCI slot also means less gas and carbon blowback onto your optic glass.'', ARRAY[''concealed-carry'',''range''], 169.0, NULL, FALSE),
(''norsso-p365-xl-threaded-lvl1-5'', ''barrel''::product_category, (SELECT id FROM manufacturers WHERE slug=''norsso''), ''Norsso P365-XL/XMACRO 3.7\" LVL1.5 Threaded Barrel'', ''p365'', ''https://norsso.com/parts/sig-p365xl-parts/barrels/n365xl-4-35-length-9mm-threaded-barrel-black-lvl-1-5/'', ''verified''::fitment_confidence, NULL, ''Fits P365XL/XMACRO slides. Accepts any 1/2x28 compensator.'', ''Pairs with any 1/2x28 comp.'', ''17-4 PH stainless steel'', ''This threaded 17-4 stainless barrel gives the P365XL/X-Macro 1/2x28 threading the factory barrel lacks, letting owners run any standard compensator or suppressor while keeping drop-in fitment. Like Norsso''''s other P365 barrels it omits the LCI slot, reducing gas and carbon exposure to your optic.'', ARRAY[''compensator-builds'',''suppressor-builds''], 179.0, NULL, FALSE),
(''norsso-n365xl-cport'', ''barrel''::product_category, (SELECT id FROM manufacturers WHERE slug=''norsso''), ''Norsso N365XL 3.7\" C Port Barrel'', ''p365'', ''https://norsso.com/barrels/n365xl-3-7-9mm-c-port-barrel/'', ''verified''::fitment_confidence, ''Norsso C-Port slides only: P365XL Spec Ops C, P365XL Rail C, P365XL Rail EDC C, P365XL Reptile C'', ''Ports align with Norsso C-Port slides ONLY. Dangerous in non-matching slides.'', ''Must pair with a Norsso C-Port slide.'', ''17-4 PH stainless steel'', ''The XL C-Port barrel brings the same diagonally-ported gas system to the P365XL platform, reducing muzzle rise without a threaded comp attachment. It''''s slide-specific — only fitting Norsso''''s matching C-Port XL slides — but delivers genuine recoil-control performance the stock barrel simply can''''t match.'', ARRAY[''competition'',''range''], 209.0, NULL, FALSE),
(''true-precision-p365-non-threaded'', ''barrel''::product_category, (SELECT id FROM manufacturers WHERE slug=''true-precision''), ''True Precision P365 3.1\" Non-Threaded Barrels'', ''p365'', ''https://true-precision.com/sig-p365-non-threaded/'', ''verified''::fitment_confidence, NULL, ''Drop-in fit for standard P365 3.1\" slides. Non-LCI.'', NULL, ''416R stainless steel'', ''Machined from 416R stainless with True Precision''''s proprietary broach-cut rifling, an enhanced feed ramp, and tighter chamfers than the factory barrel, this is a straightforward accuracy and reliability upgrade for owners who don''''t need threading. It''''s built to feed a wider range of ammunition, including defensive rounds, more consistently than the OEM barrel.'', ARRAY[''concealed-carry'',''range''], 180.0, NULL, FALSE),
(''true-precision-p365-threaded'', ''barrel''::product_category, (SELECT id FROM manufacturers WHERE slug=''true-precision''), ''True Precision P365 3.1\" Threaded Barrels'', ''p365'', ''https://true-precision.com/sig-p365-threaded/'', ''verified''::fitment_confidence, NULL, ''Fits P365/P365X/SAS slides. Accepts any 1/2x28 compensator.'', ''Pairs with any 1/2x28 comp.'', ''416R stainless steel'', ''This 416R stainless barrel adds True Precision''''s broach-cut rifling and improved feed ramp to a 1/2x28 threaded design, giving P365/P365X owners suppressor or compensator readiness the factory barrel doesn''''t offer along with better overall accuracy. It''''s a proven, widely-used upgrade path for anyone planning to run a comp or can.'', ARRAY[''compensator-builds'',''suppressor-builds''], 190.0, NULL, FALSE),
(''true-precision-p365-xl-non-threaded'', ''barrel''::product_category, (SELECT id FROM manufacturers WHERE slug=''true-precision''), ''True Precision P365 3.7\" Non-Threaded Barrels'', ''p365'', ''https://true-precision.com/sig-p365-xl-non-threaded/'', ''verified''::fitment_confidence, NULL, ''Drop-in fit for standard P365XL/XMACRO 3.7\" slides. Non-LCI.'', NULL, ''416R stainless steel'', ''Sized for the P365XL, this 416R stainless barrel carries over True Precision''''s broach-cut rifling and refined feed ramp for a drop-in accuracy upgrade over the factory barrel, with no threading needed. It''''s a solid pick for XL owners who just want a better-built, more accurate barrel without adding hardware.'', ARRAY[''concealed-carry'',''range''], 190.0, NULL, FALSE),
(''true-precision-p365-xl-threaded'', ''barrel''::product_category, (SELECT id FROM manufacturers WHERE slug=''true-precision''), ''True Precision P365XL 3.7\" Threaded Barrels'', ''p365'', ''https://true-precision.com/sig-p365-xl-threaded/'', ''verified''::fitment_confidence, NULL, ''Fits P365XL/XMACRO slides. Accepts any 1/2x28 compensator.'', ''Pairs with any 1/2x28 comp.'', ''416R stainless steel'', ''This threaded XL barrel pairs True Precision''''s 416R stainless construction and broach-cut rifling with 1/2x28 threads, giving P365XL/X-Macro owners a path to any standard compensator or suppressor while upgrading feed reliability and accuracy over the stock barrel.'', ARRAY[''compensator-builds'',''suppressor-builds''], 190.0, NULL, FALSE),
(''true-precision-p365-fuse-non-threaded'', ''barrel''::product_category, (SELECT id FROM manufacturers WHERE slug=''true-precision''), ''True Precision P365 Fuse 4.3\" Non-Threaded Barrels'', ''p365'', ''https://true-precision.com/sig-p365-fuse-non-threaded-barrels-for-4-3-pistols/'', ''verified''::fitment_confidence, NULL, ''Drop-in fit for P365-FUSE 4.3\" slides.  NOT FOR USE WITH P365-FUSE COMP SLIDE PISTOLS (per True Precision''''s product page).'', NULL, ''416R stainless steel'', ''Built for the 4.3\" P365-FUSE, this 416R stainless barrel brings True Precision''''s broach-cut rifling and enhanced feed ramp to the platform''''s longest factory slide length, delivering a more accurate, better-fed replacement for the stock FUSE barrel. It''''s not compatible with FUSE comp-slide pistols, so confirm your slide type before ordering.'', ARRAY[''concealed-carry'',''range''], 189.0, NULL, FALSE),
(''true-precision-p365-fuse-threaded'', ''barrel''::product_category, (SELECT id FROM manufacturers WHERE slug=''true-precision''), ''True Precision P365 Fuse 4.3\" Threaded Barrels'', ''p365'', ''https://true-precision.com/sig-p365-fuse-threaded-barrels'', ''verified''::fitment_confidence, NULL, ''Drop-in fit for P365-FUSE 4.3\" slides. Accepts any 1/2x28 compensator. NOT FOR USE WITH P365-FUSE COMP SLIDE PISTOLS (per True Precision''''s product page).'', ''Pairs with any 1/2x28 comp.'', ''416R stainless steel'', ''This threaded FUSE barrel adds 1/2x28 threading to True Precision''''s 416R stainless, broach-cut-rifled design, giving P365-FUSE owners suppressor or compensator compatibility the factory barrel doesn''''t have. It''''s not for use with FUSE comp-slide pistols, so it''''s meant for standard (non-integrally-compensated) FUSE builds.'', ARRAY[''compensator-builds'',''suppressor-builds''], 179.0, NULL, FALSE),
(''radian-ramjet-afterburner-p365'', ''barrel''::product_category, (SELECT id FROM manufacturers WHERE slug=''radian-weapons''), ''Radian Ramjet Barrel + Afterburner Compensator Combo — P365'', ''p365'', ''https://radianweapons.com/product/afterburner-ramjet-for-sig-sauer'', ''verified''::fitment_confidence, ''Not slide-specific in the port-matched sense — the AFTERBURNER compensator clamps onto the RAMJET barrel itself (INTRA-LOK mount), not into slide-cut ports. Per Norsso''''s own fitment test, it''''s compatible with all of their P365 slide profiles, and should fit any standard (non-integrally-compensated) P365-length slide. NOT compatible with SIG factory XMACRO COMP / Spectre Comp / FUSE COMP integrally-compensated slides (can''''t stack two comps), and NOT compatible with LCI (loaded chamber indicator) equipped models.'', ''Sold as a barrel+compensator combo kit, not a barrel alone. The 3.1\" Ramjet barrel only pairs with a 3.1\"-length P365/P365X slide (matches this row''''s barrel_length). If that slide is mounted on a longer grip module/frame (a separate, swappable part from the slide in custom P365 builds), the recoil spring still must match the 3.1\" barrel, not the grip length. Installing it on a P365/P365X extends slide length to XL proportions (fits XL holsters).'', ''Barrel and Ramjet comp are a matched system — sold and used together.'', ''416R stainless steel'', ''The Radian''''s Ramjet barrel and Afterburner compensator sold as a matched combo sized for the 3.1\" P365/P365X slide. A threadless INTRA-LOK mounting system replaces standard threads and is built to meaningfully cut felt recoil and muzzle rise compared to a stock Sig barrel, while also extending the slide to XL-length holster compatibility. It requires a standard (non-comp, non-LCI) slide, and how much recoil reduction you''''ll actually feel depends on your ammunition and grip.'', ARRAY[''compensator-builds'',''competition'',''concealed-carry''], 390.0, NULL, FALSE),
(''radian-ramjet-afterburner-p365-xl'', ''barrel''::product_category, (SELECT id FROM manufacturers WHERE slug=''radian-weapons''), ''Radian Ramjet Barrel + Afterburner Compensator Combo — P365XL'', ''p365'', ''https://radianweapons.com/product/afterburner-ramjet-for-sig-sauer'', ''verified''::fitment_confidence, ''Not slide-specific in the port-matched sense — the AFTERBURNER compensator clamps onto the RAMJET barrel itself (INTRA-LOK mount), not into slide-cut ports. Should fit any standard (non-integrally-compensated) P365XL/X-Macro-length slide. NOT compatible with SIG factory XMACRO COMP / FUSE COMP integrally-compensated slides (can''''t stack two comps), and NOT compatible with LCI (loaded chamber indicator) equipped models.'', ''Sold as a barrel+compensator combo kit, not a barrel alone. Installing it on a P365XL/X-Macro extends slide length to P365-FUSE proportions (fits FUSE holsters). Will NOT work with XMACRO-length integrally-compensated slides (dual top comp ports at the muzzle).'', ''Barrel and Ramjet comp are a matched system — sold and used together.'', ''416R stainless steel'', ''The XL version of Radian''''s Ramjet barrel + Afterburner compensator combo brings the same threadless INTRA-LOK mount to the P365XL/X-Macro, reducing felt recoil and muzzle rise compared to a stock barrel while extending the slide to FUSE-length holster compatibility. It''''s a real upgrade for owners who want flatter shooting without running a separate threaded comp, provided the slide isn''''t a factory integrally-compensated model.'', ARRAY[''compensator-builds'',''competition'',''concealed-carry''], 390.0, NULL, FALSE),
(''norsso-p365-fuse-standard'', ''barrel''::product_category, (SELECT id FROM manufacturers WHERE slug=''norsso''), ''Norsso P365-FUSE 4.3\" Standard Barrel, LVL1.5'', ''p365'', ''https://norsso.com/barrels/p365-fuse-4-3-standard-barrel-satin-stainless-lvl1-5/'', ''verified''::fitment_confidence, NULL, ''Drop-in fit for P365-FUSE 4.3\" slides (non-LCI only -- no LCI slot on this barrel). Works best with Norsso N365-FUSE slides but also drop-in compatible with factory P365-FUSE slides.'', NULL, ''17-4 PH stainless steel'', ''This 4.3\" barrel is CNC machined in-house from 17-4 PH stainless for greater long-term durability than the factory FUSE barrel, and skips the LCI slot to keep gas and carbon off your optic. It works best with Norsso''''s own N365-FUSE slides but is also a drop-in fit for factory P365-FUSE slides, making it a flexible barrel upgrade regardless of which slide you''''re running.'', ARRAY[''concealed-carry'',''range''], 149.0, NULL, FALSE),
(''norsso-n365-fuse-cport'', ''barrel''::product_category, (SELECT id FROM manufacturers WHERE slug=''norsso''), ''Norsso N365-FUSE 4.3\" 9mm C Port Barrel'', ''p365'', ''https://norsso.com/barrels/n365-fuse-4-3-9mm-c-port-barrel/'', ''verified''::fitment_confidence, ''P365-FUSE Piranha C, P365-FUSE Reptile C. NOT compatible with any SIG factory slide or any other manufacturer''''s slide.'', ''Two diagonally-positioned C-pattern gas ports, cut for the matching Norsso comp slides only.'', ''Recommend black iron sights with no fiber optic/tritium -- ported gas can foul or damage them.'', ''17-4 PH stainless steel'', ''This FUSE-length barrel cuts diagonal C-pattern gas ports into 17-4 stainless to reduce muzzle rise without threading, giving the platform real recoil control the stock barrel can''''t provide. It''''s strictly compatible with Norsso''''s matching Piranha C and Reptile C FUSE slides — not any factory or other manufacturer''''s slide — so slide compatibility is critical before installing.'', ARRAY[''competition'',''range''], 189.0, NULL, FALSE),
(''norsso-n365-fuse-eport'', ''barrel''::product_category, (SELECT id FROM manufacturers WHERE slug=''norsso''), ''Norsso N365-FUSE 4.3\" 9mm E Port Barrel'', ''p365'', ''https://norsso.com/barrels/n365-fuse-4-3-9mm-e-port-barrel/'', ''verified''::fitment_confidence, ''P365-FUSE Reptile KP, P365-FUSE Rail KP. NOT compatible with any SIG factory slide or any other manufacturer''''s slide.'', ''Inline elliptical (E-pattern) gas ports, cut for the matching Norsso comp slides only.'', ''Recommend black iron sights with no fiber optic/tritium -- ported gas can foul or damage them.'', ''17-4 PH stainless steel'', ''This FUSE barrel uses Norsso''''s inline E-pattern gas ports instead of the C-port layout, cut into 17-4 stainless for a flatter-shooting, better-controlled follow-up shot than the factory barrel offers. It only fits Norsso''''s matching Reptile KP and Rail KP FUSE slides, so it''''s built for a specific ported-slide setup rather than a universal upgrade.'', ARRAY[''competition'',''range''], 189.0, NULL, FALSE),
(''zaffiri-p365-threaded'', ''barrel''::product_category, (SELECT id FROM manufacturers WHERE slug=''zaffiri-precision''), ''Zaffiri Precision P365 Threaded Barrel'', ''p365'', ''https://zaffiriprecision.com/product/threaded-barrel-for-sig-sauer-p365/'', ''verified''::fitment_confidence, NULL, ''Drop-in fit for standard P365 3.1\" slides. Compatible with Zaffiri slide models (ZPS.2, ZPS.3, Z Series, IBS) as well as OEM/aftermarket. Has an LCI notch -- check state LCI requirements.'', ''Pairs with any 1/2x28 comp/suppressor.'', ''416R stainless steel'', ''Machined from 416R stainless with broach-cut rifling and a fully supported, polished chamber, this threaded barrel gives the P365 1/2x28 compensator/suppressor compatibility along with match-grade accuracy the factory barrel doesn''''t deliver. It includes the LCI notch, so it''''s a straight swap for owners who need to keep that feature for state compliance.'', ARRAY[''compensator-builds'',''suppressor-builds''], 179.0, NULL, FALSE),
(''zaffiri-p365-flush-crown'', ''barrel''::product_category, (SELECT id FROM manufacturers WHERE slug=''zaffiri-precision''), ''Zaffiri Precision P365 Flush & Crown Barrel'', ''p365'', ''https://zaffiriprecision.com/product/flush-and-crown-barrel-for-sig-sauer-p365/'', ''verified''::fitment_confidence, NULL, ''Drop-in fit for standard P365 3.1\" slides. Compatible with Zaffiri slide models (ZPS.2, ZPS.3, Z Series, IBS) as well as OEM/aftermarket. Has an LCI notch -- check state LCI requirements.'', NULL, ''416R stainless steel'', ''This 416R stainless barrel upgrades the P365 with Zaffiri''''s broach-cut rifling, polished SAAMI-spec chamber, and improved feed ramp for noticeably better accuracy and reliability than the factory barrel, all without adding threads. It keeps the LCI notch intact, making it a drop-in option for owners who need to retain that factory feature.'', ARRAY[''concealed-carry'',''range''], 159.0, NULL, FALSE),
(''zaffiri-p365-xl-threaded'', ''barrel''::product_category, (SELECT id FROM manufacturers WHERE slug=''zaffiri-precision''), ''Zaffiri Precision P365XL Threaded Barrel'', ''p365'', ''https://zaffiriprecision.com/product/p365xl-barrel-threaded-stainless/'', ''verified''::fitment_confidence, NULL, ''Drop-in fit for P365XL 3.7\" slides. Explicitly listed as NO LCI on the product page.'', ''Thread protector included. Pairs with any 1/2x28 comp/suppressor.'', ''416R stainless steel'', ''This XL threaded barrel brings the same 416R stainless, broach-cut rifling, and improved feed ramp as Zaffiri''''s other P365 barrels to the longer XL platform, adding 1/2x28 threading for a comp or suppressor. It''''s explicitly built without an LCI notch, giving owners a cleaner sight picture with less gas blowback onto their optic.'', ARRAY[''compensator-builds'',''suppressor-builds''], 189.0, NULL, FALSE),
(''zaffiri-p365-xl-flush-crown'', ''barrel''::product_category, (SELECT id FROM manufacturers WHERE slug=''zaffiri-precision''), ''Zaffiri Precision P365XL Flush & Crown Barrel'', ''p365'', ''https://zaffiriprecision.com/product/flush-and-crown-barrel-for-sig-sauer-p365xl/'', ''verified''::fitment_confidence, NULL, ''Drop-in fit for P365XL 3.7\" slides. Compatible with Zaffiri slide models (ZPS.2, ZPS.3, Z Series, IBS) as well as OEM/aftermarket.'', NULL, ''416R stainless steel'', ''This XL flush and crown barrel delivers Zaffiri''''s 416R stainless construction, broach-cut rifling, and polished match-grade chamber as a straightforward accuracy upgrade over the factory P365XL barrel, with no threading or LCI notch to worry about. It''''s a solid all-around replacement for owners who just want better fit, finish, and downrange performance.'', ARRAY[''concealed-carry'',''range''], 159.0, NULL, FALSE);"}', 'p365_barrels_final_products', 'ag.gamboa94@gmail.com', NULL, NULL);
