INSERT INTO "supabase_migrations"."schema_migrations" ("version", "statements", "name", "created_by", "idempotency_key", "rollback") VALUES ('20260810183417', '{"INSERT INTO products (slug, category, brand_id, name, family, url, fitment_confidence, build_warning, fitment_notes, build_notes, material, description, best_for, editor_rating, is_discontinued) VALUES
(''armory-craft-comp-p365'', ''compensator''::product_category, (SELECT id FROM manufacturers WHERE slug=''armory-craft''), ''Armory Craft P365 Compensator'', ''p365'', ''https://www.armorycraft.com/product-page/365'', ''verified''::fitment_confidence, NULL, ''Requires 1/2x28 threaded barrel. Universal fit on any P365 with a threaded barrel.'', NULL, ''solid steel billet'', ''Channels muzzle gas through upward-tuned ports to counter the P365''''s flip, so the sights settle back on target quicker between shots. That translates into tighter, faster follow-up strings on a pistol known for snappy recoil.'', ''{}'', NULL, FALSE),
(''faxon-firearms-exos-comp-p365'', ''compensator''::product_category, (SELECT id FROM manufacturers WHERE slug=''faxon-firearms''), ''Faxon Exos P365 Compensator'', ''p365'', ''https://faxonfirearms.com/FF-P-A-COMP-SS-S-01'', ''verified''::fitment_confidence, ''Compensator for SIG® P365 & P365 XL'', ''Flush fit profile'', NULL, ''Aluminum'', ''An angled single-chamber port design smooths out muzzle climb from shot to shot, keeping point of aim more consistent through a full string of fire. The result is a flatter-shooting P365 that''''s easier to stay on target with under rapid strings.'', ''{}'', NULL, FALSE),
(''herrington-arms-hc365-p365'', ''compensator''::product_category, (SELECT id FROM manufacturers WHERE slug=''herrington-arms''), ''Herrington Arms HC365 Compensator P365'', ''p365'', ''https://herringtonarms.com/products/hc365-sig-sauer-p365-p365xl-compensator'', ''verified''::fitment_confidence, ''p365, p365x, and p365xl, P365 fuse - fits 1/2-28 threaded barrels and most aftermarket barrels.'', ''Requires 1/2x28 threaded barrel. Universal fit on any P365 with a threaded barrel.'', NULL, ''Aluminum'', ''Manages recoil in two directions at once, knocking down vertical muzzle rise while also settling the side-to-side arc that makes the P365 feel snappy. Shooters get faster sight recovery and more predictable follow-up shots across a full string.'', ''{}'', NULL, FALSE),
(''herrington-arms-hc365p-p365'', ''compensator''::product_category, (SELECT id FROM manufacturers WHERE slug=''herrington-arms''), ''Herrington Arms HC365P Compensator P365'', ''p365'', ''https://herringtonarms.com/products/hc3652p-sig-p365-p365xl-compensator'', ''verified''::fitment_confidence, ''p365, p365x, and p365xl, P365 fuse - fits 1/2-28 threaded barrels and most aftermarket barrels.'', ''Requires 1/2x28 threaded barrel. Universal fit on any P365 with a threaded barrel.'', NULL, ''Aluminum'', ''Concentrates its porting entirely on vertical muzzle rise instead of splitting the venting in multiple directions, giving a more focused flip-reduction effect. That efficiency makes it a strong choice for shooters who prioritize fast sight recovery above all else.'', ''{}'', NULL, FALSE),
(''herrington-arms-zero-p365'', ''compensator''::product_category, (SELECT id FROM manufacturers WHERE slug=''herrington-arms''), ''Herrington Arms Zero Series Compensator P365'', ''p365'', ''https://herringtonarms.com/limited-edition-zero-series-compensator-for-sig-p365/'', ''verified''::fitment_confidence, ''p365, p365x, and p365xl, P365 fuse - fits 1/2-28 threaded barrels and most aftermarket barrels.'', ''Requires 1/2x28 threaded barrel. Universal fit on any P365 with a threaded barrel.'', NULL, ''Aluminum'', ''A refined, top-port-only design that puts all of its venting effort into pure muzzle-flip reduction rather than splitting the job across multiple directions, for a crisper, more immediate return to target between shots. It secures to the barrel through an O-ring instead of set screws, giving it a cleaner look while focusing purely on taming muzzle flip.'', ''{}'', NULL, FALSE),
(''mcarbo-comp-p365'', ''compensator''::product_category, (SELECT id FROM manufacturers WHERE slug=''mcarbo''), ''MCARBO P365 Compensator'', ''p365'', ''https://www.mcarbo.com/Sig-P365-Compensator.aspx'', ''verified''::fitment_confidence, ''p365, p365x, and p365xl - fits 1/2-28 threaded barrels and most aftermarket barrels.'', ''Requires 1/2x28 threaded barrel. Fits and functions in all P365 Models with slides made for a 3.1\" and 3.7\" barrels.'', NULL, ''Aluminum'', ''Combines a top port with angled side ports on both sides to knock down muzzle flip and the P365''''s characteristically snappy recoil, helping shooters get back on target faster for follow-up shots.'', ''{}'', NULL, FALSE),
(''mcarbo-tbarrel-comp-p365'', ''compensator''::product_category, (SELECT id FROM manufacturers WHERE slug=''mcarbo''), ''MCARBO P365 Threaded Barrel and Compensator'', ''p365'', ''https://www.mcarbo.com/Sig-P365-Threaded-Barrel-and-Compensator.aspx'', ''verified''::fitment_confidence, ''ONLY Compatible with Sig Sauer P365, P365 SAS, and P365X Length Slides.
Fits and functions in all P365 Models with slides made for a 3.1\" barrel.'', NULL, NULL, ''Aluminum'', ''The barrel and compensator are engineered together as a matched pair, gas flow and port timing are dialed in for consistent, predictable recoil control rather than the guesswork of mixing a separate aftermarket barrel with a comp. That precision adds up to a calmer, faster-recovering pistol across rapid strings.'', ''{}'', NULL, FALSE),
(''pmm-tbarrel-comp-p365'', ''compensator''::product_category, (SELECT id FROM manufacturers WHERE slug=''parker-mountain-machine''), ''PMM P365 Compensator'', ''p365'', ''https://www.parkermountainmachine.com/product/pmm-p365p365xp365xl-micro-jttc-and-barrel-combo/'', ''verified''::fitment_confidence, ''ONLY Compatible with Sig Sauer P365, P365 SAS, and P365X Length Slides.
Fits and functions in all P365 Models with slides made for a 3.1\" barrel.'', NULL, NULL, NULL, ''A single top-port design concentrates all of its venting effort into pushing the muzzle down, giving the slide a faster, flatter track back into position after each shot. The compensator locks onto its matched barrel through a captured, set-screw-free interface, so that porting stays precisely aligned and keeps delivering consistent muzzle control shot after shot.'', ''{}'', NULL, FALSE),
(''pmm-tbarrel-comp-p365xl'', ''compensator''::product_category, (SELECT id FROM manufacturers WHERE slug=''parker-mountain-machine''), ''PMM P365XL Compensator'', ''p365'', ''https://www.parkermountainmachine.com/product/pmm-p365p365xp365xl-micro-jttc-and-barrel-combo/'', ''verified''::fitment_confidence, ''Only compatible with Sig Sauer P365XL, P365XL Spectre, and P365 X-Macro (non-comped models). Fits and functions in all P365 models with slides made for a 3.7\" barrel; not compatible with factory-comped slides.'', NULL, NULL, NULL, ''Delivers the same focused, top-port venting as the standard-length version, scaled for the P365XL''''s longer platform for fast muzzle recovery and a flatter-tracking slide. Like its shorter counterpart, it uses PMM''''s captured, set-screw-free mounting to keep that port alignment locked in for reliably repeatable recoil control.'', ''{}'', NULL, FALSE),
(''radian-ramjet-afterburner-p365-comp'', ''compensator''::product_category, (SELECT id FROM manufacturers WHERE slug=''radian-weapons''), ''Radian Ramjet + Afterburner Compensator P365'', ''p365'', ''https://radianweapons.com/product/afterburner-ramjet-for-sig-sauer'', ''verified''::fitment_confidence, ''This combination kit is for: SIG SAUER® P365® & P365X™ (3.1” SLIDE)'', ''The INTRA-LOK® mounting system uses the taper lock principle; a tapered locking screw interfaces with an angled V-groove on the underside of the barrel. This perfectly times the compensator as it locks down onto the upper barrel profile on the muzzle end of the barrel.'', ''Installed onto a Sig Sauer® P365® or P365X™, the AFTERBURNER™ + RAMJET™ combo increases the overall length of the slide to a P365XL™ allowing compatibility with all P365XL™ holsters.'', ''Stainless Steel'', ''A ported barrel and micro-compensator engineered as one matched system, punching well above its compact size to flatten muzzle rise and help the sights settle back on target faster between shots. It mounts through Radian''''s tool-minimal INTRA-LOK system, and as a bonus extends the P365/P365X slide out to XL length for a wider range of holster options.'', ''{}'', NULL, FALSE),
(''radian-ramjet-afterburner-p365-xl-comp'', ''compensator''::product_category, (SELECT id FROM manufacturers WHERE slug=''radian-weapons''), ''Radian Ramjet + Afterburner Compensator P365XL'', ''p365'', ''https://radianweapons.com/product/afterburner-ramjet-for-sig-sauer'', ''verified''::fitment_confidence, ''This combination kit is for: SIG SAUER® P365XL® & P365-XMACRO™ (3.7” SLIDE)'', ''The INTRA-LOK® mounting system uses the taper lock principle; a tapered locking screw interfaces with an angled V-groove on the underside of the barrel. This perfectly times the compensator as it locks down onto the upper barrel profile on the muzzle end of the barrel.'', NULL, ''Stainless Steel'', ''The XL/X-Macro-length version of Radian''''s matched ported barrel and micro-compensator, carrying the same outsized recoil control into a package built for shooters already running the longer slide. It still mounts through the tool-minimal INTRA-LOK system, finished in a hardened, corrosion-resistant coating built to hold up over sustained use.'', ''{}'', NULL, FALSE),
(''true-precision-tl-comp-p365'', ''compensator''::product_category, (SELECT id FROM manufacturers WHERE slug=''true-precision''), ''True Precision True-Lock Compensator P365'', ''p365'', ''https://true-precision.com/sig-p365-p365x-p365xl-p365-x-macro-p365-fuse-true-lock-compensator/'', ''verified''::fitment_confidence, NULL, NULL, NULL, ''Aluminum'', ''Uses an integrated locking block instead of set screws or thread-locking compound, so it installs and removes cleanly without risking damage to the barrel''''s threads. A convenient option for shooters who want to reduce muzzle rise and swap muzzle devices between barrels without extra tools or mess.'', ''{}'', NULL, FALSE);"}', 'p365_compensators_insert_products', 'ag.gamboa94@gmail.com', NULL, NULL);
