((SELECT id FROM products WHERE slug=''radian-ramjet-afterburner-p365-xl-comp''), ''compensator''::product_category, ''9mm'', ''intra-lok'', FALSE, ''ramjet'', TRUE, ''P365 3.7\" Ramjet Barrel'', 3.7, ''Top port only'', NULL, NULL),
