INSERT INTO "supabase_migrations"."schema_migrations" ("version", "statements", "name", "created_by", "idempotency_key", "rollback") VALUES ('20260810185750', '{"
create trigger builds_updated_at
  before update on public.builds
  for each row execute function public.set_updated_at();

create trigger platforms_updated_at
  before update on public.platforms
  for each row execute function public.set_updated_at();

create trigger guns_updated_at
  before update on public.guns
  for each row execute function public.set_updated_at();

-- build_photos has no updated_at column; skip
"}', 'add_updated_at_triggers_community_tables', 'ag.gamboa94@gmail.com', NULL, NULL);
INSERT INTO "supabase_migrations"."schema_migrations" ("version", "statements", "name", "created_by", "idempotency_key", "rollback") VALUES ('20260810185805', '{"
create index if not exists builds_user_idx      on public.builds(user_id);
create index if not exists builds_platform_idx  on public.builds(platform_id);
create index if not exists build_photos_build_idx on public.build_photos(build_id);
create index if not exists guns_platform_idx    on public.guns(platform_id);
"}', 'add_missing_fk_indexes', 'ag.gamboa94@gmail.com', NULL, NULL);
INSERT INTO "supabase_migrations"."schema_migrations" ("version", "statements", "name", "created_by", "idempotency_key", "rollback") VALUES ('20260810185824', '{"
create table public.product_platforms (
  product_id  uuid not null references public.products(id)  on delete cascade,
  platform_id uuid not null references public.platforms(id) on delete restrict,
  created_at  timestamptz not null default now(),
  primary key (product_id, platform_id)
);

comment on table public.product_platforms is
  ''Many-to-many: which gun platforms (P320, P365, …) each product fits. Drives the \"P365-only\" builder picker filter and admin-side catalog scoping.'';

-- Reverse-direction lookups: \"give me every product for platform X\"
create index product_platforms_platform_idx on public.product_platforms(platform_id);

alter table public.product_platforms enable row level security;

create policy \"product_platforms_public_read\"
  on public.product_platforms for select
  to anon, authenticated
  using (true);
"}', 'create_product_platforms_junction', 'ag.gamboa94@gmail.com', NULL, NULL);
INSERT INTO "supabase_migrations"."schema_migrations" ("version", "statements", "name", "created_by", "idempotency_key", "rollback") VALUES ('20260812031226', '{"INSERT INTO products (id, slug, category, brand_id, name, family, url, fitment_confidence, build_warning, fitment_notes, build_notes, installation_difficulty, material, weight_oz, description, best_for, pros, cons, editor_rating, base_price, is_discontinued) VALUES
(''c36ab318-9db0-53e1-a41c-9ba1181371b3'', ''tyrant-cnc-intellifire-p365'', ''trigger'', ''2de98682-689f-460f-b990-2648bbcd24cb'', ''Tyrant CNC P365 Intellifire Trigger'', ''p365'', ''https://www.tyrantcnc.com/sig-sauer-p365-intellifiretm-trigger.html'', ''verified'', NULL, NULL, NULL, ''moderate'', ''stainless steel'', NULL, ''The IntelliFire is built around a patent-pending dual-blade trigger safety, a feature the OEM P365 trigger does not have at all. It gives owners a mechanical safeguard against accidental discharge that the factory design leaves out entirely, while also shortening pre-travel for a more consistent break.'', ''{}'', NULL, NULL, NULL, NULL, FALSE),
(''af2121d3-6e19-5e11-bed3-2ef0a74ec58c'', ''tactical-development-dual-flat-face-p365'', ''trigger'', ''61d7284b-df70-4944-869a-b0b4e44a9f6e'', ''Tactical Development Enhanced Dual Flat Faced'', ''p365'', ''https://tactical.dev/products/dual-face-flat-trigger-for-sig-sauer-p365'', ''verified'', NULL, NULL, NULL, ''moderate'', ''stainless steel'', NULL, ''This dual flat-faced trigger reshapes the pull surface into two distinct angled faces, giving the shooter a more defined finger rest than the OEM curved or single flat trigger offers. It doesn''''t alter pull weight, so the upgrade is purely about consistent finger placement and a cleaner tactile break rather than a lighter trigger pull.'', ''{}'', NULL, NULL, NULL, NULL, FALSE),
(''cc991e84-7493-5125-ab4e-4b8626c7c25b'', ''mcarbo-short-stroke-flat-p365'', ''trigger'', ''83144fd7-85f4-42d6-8632-e829c22398be'', ''MCarbo Short Stroke Flat Trigger'', ''p365'', ''https://www.mcarbo.com/sig-p365-short-stroke-flat-trigger'', ''verified'', NULL, NULL, NULL, ''moderate'', ''4140 steel billet'', NULL, ''Where the factory P365 trigger is metal-injection-molded, this one is CNC machined from solid steel, addressing a common complaint about MIM parts on this platform. The shortened stroke also cuts down on take-up and over-travel compared to OEM, giving a noticeably crisper reset.'', ''{}'', NULL, NULL, NULL, NULL, FALSE),
(''a8d7b8b0-a0aa-561c-a572-f88b1a74cc91'', ''ramm-tactical-leverage-nc-p365'', ''trigger'', ''8935dcfa-003e-4a27-be52-281d35a86791'', ''Ramm Tactical Leverage P365 non comp'', ''p365'', ''https://thetriggerguyusa.com/product/ramm-tactical-sig-p365-leverage-trigger-kit/'', ''verified'', ''Choose this if the FCU (Fire Control Unit) comes from a factory gun that (does not) have the comp slots in the slide or if the FCU is a Custom Works'', NULL, NULL, ''gunsmith'', ''4140 steel billet'', NULL, ''Unlike triggers that lighten pull weight by swapping in a weaker striker spring, RAMM Tactical keeps the factory spring in place and instead reduces pull weight through the trigger''''s leverage geometry, avoiding the ignition reliability concerns that lightened springs can introduce. This non-comped kit also replaces the sear, takedown lever, and related pins as a complete system rather than a single-part swap, which the OEM trigger alone can''''t offer.'', ''{}'', NULL, NULL, NULL, NULL, FALSE),
(''e91942f3-2a9a-53e0-9e7c-b755da12d96d'', ''ramm-tactical-leverage-c-p365'', ''trigger'', ''8935dcfa-003e-4a27-be52-281d35a86791'', ''Ramm Tactical Leverage P365 comp'', ''p365'', ''https://thetriggerguyusa.com/product/ramm-tactical-sig-p365-leverage-trigger-kit/'', ''verified'', ''Choose comped if the FCU (Fire Control Unit) comes from a factory gun that (does) have the comp slots in the slide.'', NULL, NULL, ''gunsmith'', ''4140 steel billet'', NULL, ''This is the same leverage-based, factory-spring-preserving trigger system as RAMM''''s non-comped kit, built instead for FCUs pulled from a comped slide. Selecting the correct comped or non-comped version matters here in a way it never does with a stock OEM trigger, since the two kits are not interchangeable.'', ''{}'', NULL, NULL, NULL, NULL, FALSE),
(''6c97a18f-18a4-5377-99f1-42c4623a0d76'', ''true-precision-flat-p365'', ''trigger'', ''72ee170a-a129-49e8-aa63-e9015816063b'', ''True Precision Flat P365'', ''p365'', ''https://true-precision.com/true-sig-p365-drop-in-flat-trigger/'', ''verified'', NULL, NULL, NULL, ''moderate'', NULL, NULL, ''True Precision machines this trigger from billet stainless steel with chamfered edges and a refined angle that the OEM trigger''''s stamped geometry doesn''''t match, giving a smoother, more confident feel in the guard. It''''s built to coordinate finish-wise with the rest of True Precision''''s P365 lineup, appealing to shooters building out a matched parts set.'', ''{}'', NULL, NULL, NULL, NULL, FALSE),
(''6cfecc5c-080d-5021-99bb-cd0f48f73f0e'', ''sig-sauer-flat-oem-p365'', ''trigger'', ''01c196c0-8fae-41df-9b3d-12578408a206'', ''Sig Sauer Flat OEM P365'', ''p365'', ''https://www.sigsauer.com/p365-flat-trigger.html'', ''verified'', NULL, NULL, NULL, ''moderate'', NULL, NULL, ''This is SIG''''s factory flat-faced trigger, included as the baseline reference for anyone comparing aftermarket flat triggers on this list. It has no added safety blade, no travel reduction, and no adjustability, representing the stock experience every upgrade above is measured against.'', ''{}'', NULL, NULL, NULL, NULL, FALSE),
(''2b160547-c1c8-5970-bdf7-16bfc7d986e0'', ''sig-sauer-curved-p365'', ''trigger'', ''01c196c0-8fae-41df-9b3d-12578408a206'', ''Sig Sauer Curved P365'', ''p365'', ''https://www.sigsauer.com/trigger-365-pin-spring.html'', ''verified'', NULL, NULL, NULL, ''moderate'', NULL, NULL, ''The original curved trigger SIG ships on the standard P365, included here as the stock baseline for shooters weighing whether a flat-faced or feature-added aftermarket trigger is worth the switch.'', ''{}'', NULL, NULL, NULL, NULL, FALSE);"}', 'p365_trigger_insert_products', 'ag.gamboa94@gmail.com', NULL, NULL);
INSERT INTO "supabase_migrations"."schema_migrations" ("version", "statements", "name", "created_by", "idempotency_key", "rollback") VALUES ('20260907223019', '{"-- Compatibility rows will be inserted via execute_sql in batches
-- This is a placeholder migration marker
SELECT 1;"}', 'lights_stage6a_compat_first_half', 'ag.gamboa94@gmail.com', NULL, NULL);
INSERT INTO "supabase_migrations"."schema_migrations" ("version", "statements", "name", "created_by", "idempotency_key", "rollback") VALUES ('20260810185842', '{"
-- All current 75 products are P365-family:
--   slide_specs, barrel_specs, compensator_specs all use lengths 3.1/3.7/4.3
--   frame_specs housing_class values are p365 and p365xl
-- Map each product to the P365 platform.
insert into public.product_platforms (product_id, platform_id)
select p.id, plat.id
from public.products p
cross join lateral (select id from public.platforms where slug = ''p365'') plat
on conflict do nothing;
