INSERT INTO "supabase_migrations"."schema_migrations" ("version", "statements", "name", "created_by", "idempotency_key", "rollback") VALUES ('20260811054805', '{"INSERT INTO products (id, slug, category, brand_id, name, url, fitment_confidence, build_warning, fitment_notes, installation_difficulty, material, weight_oz, description, is_discontinued)
VALUES (''7d6d2ca7-e23e-5017-8726-775f8861c003'', ''wilson-combat-wcp365'', ''frame'', ''cadb1a10-c47d-4967-a753-b701d034a75b'', ''Wilson Combat WCP365 Grip Module'', ''https://wilsoncombat.com/grip-module-wcp365.html'', ''verified'', E''Module is NOT COMPATABILE with SIG SAUER 12rd extended magazines\\nImportant Note:  Wilson Combat SIG SAUER Grip Modules are not compatible with California versions of the SIG SAUER P365.'', ''Replaces the P365/ XL OEM module.'', ''easy'', ''polymer'', 1.4, ''The WCP365 replaces the factory P365 housing with a polymer module built specifically for concealment, adding an aggressive palm swell texture and an undercut trigger guard that the stock frame lacks.'', FALSE),
(''b7f9c263-f0f3-56f4-ab16-df8cbcbbbdc0'', ''wilson-combat-wcp365-xl'', ''frame'', ''cadb1a10-c47d-4967-a753-b701d034a75b'', ''Wilson Combat WCP365 XL Grip Module'', ''https://wilsoncombat.com/grip-module-wcp365-xl.html'', ''verified'', ''Important Note:  Wilson Combat SIG SAUER Grip Modules are not compatible with California versions of the SIG SAUER P365.'', ''Replaces the P365/ XL OEM module.'', ''easy'', ''polymer'', 1.6, ''The WCP365 XL applies Wilson Combat''''s sharper texture and refined grip geometry to the X/XL housing, giving shooters who already carry the larger P365 frame the same ergonomic upgrade found on the standard module.'', FALSE),
(''1a7464aa-d1a4-568c-b810-f7bd53902f9d'', ''wilson-combat-wcp365-xmacro'', ''frame'', ''cadb1a10-c47d-4967-a753-b701d034a75b'', ''Wilson Combat WCP365 XMacro Grip Module'', ''https://wilsoncombat.com/grip-module-wcp365-xmacro-no-manual-safety.html'', ''verified'', ''Important Note:  Wilson Combat SIG SAUER Grip Modules are not compatible with California versions of the SIG SAUER P365.'', ''Replaces the XMACRO OEM module.'', ''easy'', ''polymer'', 2.4, ''Wilson Combat brings its signature aggressive texture and undercut trigger guard to the XMacro platform in polymer rather than aluminum, giving shooters who want the ergonomic upgrade without the added weight of a metal frame a legitimate option in a housing class otherwise dominated by CNC builds.'', FALSE),
(''7e6e72ef-3de3-520a-ac5c-e693a20c47d5'', ''wilson-combat-wcp365-xmacro-sg'', ''frame'', ''cadb1a10-c47d-4967-a753-b701d034a75b'', ''Wilson Combat WCP365 XMacro Short Grip Module'', ''https://wilsoncombat.com/grip-module-wcp365-xmacro-short-no-manual-safety.html'', ''verified'', ''Important Note:  Wilson Combat SIG SAUER Grip Modules are not compatible with California versions of the SIG SAUER P365.'', ''Replaces the XMACRO OEM module. XL slides (6.6 inches) will protrude past the end of the dust cover'', ''easy'', ''polymer'', 2.4, ''This short grip variant delivers the same Wilson Combat texture and geometry as their standard XMacro module in a more compact profile, built for shooters pairing it with a shorter slide where the full length grip would otherwise protrude past the dust cover.'', FALSE),
(''ed806fcc-4ac5-515f-adc0-5cc59c13c278'', ''sig-sauer-p365-gm-oem'', ''frame'', ''01c196c0-8fae-41df-9b3d-12578408a206'', ''Sig Sauer P365 OEM'', ''https://www.sigsauer.com/grip-module-365-magazine-release-stop-spring.html'', ''verified'', NULL, ''OEM P365'', ''easy'', ''polymer'', 1.4, ''The factory module for the p365 housing, included as the baseline reference point so shoppers can see exactly what aftermarket p365 options are being compared against and improved upon.'', FALSE),
(''dbc63dd2-5b12-5c2b-a715-7b34331a1c92'', ''sig-sauer-p365-xl-gm-oem'', ''frame'', ''01c196c0-8fae-41df-9b3d-12578408a206'', ''Sig Sauer P365 XL OEM'', ''https://www.sigsauer.com/grip-module-365xl-standard-blk-1.html'', ''verified'', NULL, ''OEM P365 X / XL'', ''easy'', ''polymer'', 1.6, ''The factory X/XL module, serving as the reference baseline that most aftermarket p365xl-class grips are designed to replace or improve on.'', FALSE),
(''9ea56cf0-84f1-5ede-b65e-0d4361db5d9f'', ''sig-sauer-p365-xmacro-gm-oem'', ''frame'', ''01c196c0-8fae-41df-9b3d-12578408a206'', ''Sig Sauer P365 X-Macro OEM'', ''https://www.sigsauer.com/p365-xmacro-grip-standard-module-black.html'', ''verified'', ''Does not work with the CA P365 FCU due to the magazine disconnect safety.'', ''OEM P365 XMACRO'', ''easy'', ''polymer'', 2.5, ''The factory XMacro module, useful as the reference point buyers compare aftermarket XMacro grip modules against for texture, rail, and ergonomics.'', FALSE),
(''31705a2b-9b6c-5c37-b981-6928859efba5'', ''sig-sauer-p365-fuse-xmacro-gm-oem'', ''frame'', ''01c196c0-8fae-41df-9b3d-12578408a206'', ''Sig Sauer P365 Fuse/X-Macro OEM'', ''https://www.sigsauer.com/p365-xmacro-9mm-380-laser-engraved-grip-module-black.html'', ''verified'', ''Does not work with the CA P365 FCU due to the magazine disconnect safety.'', ''OEM P365 Fuse/ XMACRO'', ''easy'', ''polymer'', 3.5, ''The factory module for the Fuse platform, giving shoppers a stock baseline to weigh against the aftermarket Fuse-compatible modules in the lineup.'', FALSE),
(''cef114ff-9ca5-5076-a29a-c553e4403815'', ''grayguns-p365-gm'', ''frame'', ''e2c300a5-9630-4857-ac59-a0e20f0e0851'', ''Grayguns P365 Laser-Sculpted Grip Module'', ''https://www.sigsauer.com/p365-laser-sculpted-sniper-gray-grip-module-grayguns.html'', ''verified'', ''Does not work with the CA P365 FCU due to the magazine disconnect safety.'', ''Replaces the P365/ XL OEM module.'', ''easy'', ''polymer'', 1.3, ''A laser-textured polymer module that replaces the factory surface pattern with Grayguns'''' own sculpted grip texture, offering p365 owners a refined ergonomic upgrade without the added weight of an aluminum frame.'', FALSE),
(''1e2bd3e0-e415-5052-b491-d0272a969099'', ''grayguns-p365-xl-gm'', ''frame'', ''e2c300a5-9630-4857-ac59-a0e20f0e0851'', ''Grayguns P365XL Laser-Sculpted Grip Module'', ''https://www.sigsauer.com/p365xl-laser-sculpted-black-grip-module-grayguns.html'', ''verified'', NULL, ''Replaces the P365/ XL OEM module.'', ''easy'', ''polymer'', 1.6, ''Extends Grayguns'''' laser-sculpted texture treatment to the X/XL housing, letting owners upgrade feel and hand-fill while keeping the module in lightweight polymer.'', FALSE),
(''aebef462-9546-5c72-beed-00bb2fa91635'', ''grayguns-p365-xmacro-gm'', ''frame'', ''e2c300a5-9630-4857-ac59-a0e20f0e0851'', ''Grayguns P365 XMACRO Laser-Sculpted Grip Module'', ''https://grayguns.com/product/laser-sculpted-grip-modules-p365-x-macro/'', ''verified'', NULL, ''Replaces the XMACRO OEM module.'', ''easy'', ''polymer'', 2.5, ''A laser-sculpted, aggressively textured polymer XMacro module, appealing to shooters who want XMacro ergonomics without moving to the heavier aluminum builds that dominate this housing class.'', FALSE),
(''4840a337-7c96-5e0f-afc2-8289300ffb5a'', ''shalotek-p365-flex-xr-10'', ''frame'', ''137f8518-c1e9-418c-bb28-532678842d58'', ''Shalotek FLEX XR-10 Grip Module'', ''https://shalotek.com/products/flex-frame-xr-10-black.html'', ''verified'', NULL, ''Replaces the P365/ XL OEM module.'', ''easy'', ''aluminum'', 5.1, ''The XR-10 anchors Shalotek''''s modular FLEX system, a design built so frame length, magazine housing, trigger guard, and grip panels are all independent, swappable components rather than fixed into one shape. This configuration keeps the standard length frame paired with a 10 round magazine housing, preserving the P365''''s original compact profile for shooters who prioritize concealment over capacity.'', FALSE),
(''885041d8-d540-56e9-aff4-9598a5654788'', ''shalotek-p365-flex-xr-17'', ''frame'', ''137f8518-c1e9-418c-bb28-532678842d58'', ''Shalotek FLEX XR-17 Grip Module'', ''https://shalotek.com/products/flex-frame-xr-17-black.html'', ''verified'', NULL, ''Replaces the XMACRO OEM module.'', ''easy'', ''aluminum'', 6.3, ''The XR-17 retains that same standard length frame but swaps in a 17 round magazine housing, giving shooters full macro capacity without sizing up to a larger grip. This is where Shalotek''''s modular platform earns its distinction: frame size and magazine capacity are decoupled, so a compact grip can still run high capacity magazines.'', FALSE),
(''3df783ed-294c-57e1-93c1-4b054273bb21'', ''shalotek-p365-flex-xlr-12'', ''frame'', ''137f8518-c1e9-418c-bb28-532678842d58'', ''Shalotek FLEX XLR-12 Grip Module'', ''https://shalotek.com/products/flex-frame-xlr-12-black.html'', ''verified'', NULL, ''Replaces the P365/ XL OEM module.'', ''easy'', ''aluminum'', 6.0, ''The XLR-12 pairs Shalotek''''s XL length frame with a 12 round magazine housing, drawing from the same interchangeable FLEX platform where frame length and magazine capacity are configured independently rather than bundled together as they are on every fixed grip module.'', FALSE),
(''5f752ce9-739c-5a0c-a958-a5d315106601'', ''shalotek-p365-flex-xlr-17'', ''frame'', ''137f8518-c1e9-418c-bb28-532678842d58'', ''Shalotek FLEX XLR-17 Grip Module'', ''https://shalotek.com/products/flex-frame-xlr-17-black.html'', ''verified'', NULL, ''Replaces the XMACRO OEM module.'', ''easy'', ''aluminum'', 6.5, ''The XLR-17 combines the XL length frame with a 17 round magazine housing, delivering full macro capacity on a grip sized between the standard and XXL frames in Shalotek''''s modular lineup, a configuration few competitors offer.'', FALSE),
(''264bba8d-a491-50e8-8906-e8a586cfeef7'', ''shalotek-p365-flex-xxlr-17'', ''frame'', ''137f8518-c1e9-418c-bb28-532678842d58'', ''Shalotek FLEX XXLR-17 Grip Module'', ''https://shalotek.com/products/flex-frame-xxlr-17-black.html'', ''verified'', NULL, ''Flush fit with P365 FUSE or P365 extended slide with comp'', ''easy'', ''aluminum'', 6.6, ''The XXLR-17 is the largest frame in Shalotek''''s modular FLEX system, built around an XXL length housing and a 17 round magazine module, engineered to sit flush with either the Fuse slide or an extended slide fitted with a compensator.'', FALSE),
(''2a82e806-63d7-5dcc-85fc-a449a810934b'', ''tyrant-cnc-p365-xmacro-gm'', ''frame'', ''2de98682-689f-460f-b990-2648bbcd24cb'', ''Tyrant CNC P365 XMacro'', ''https://www.tyrantcnc.com/sig-sauer-p365-xmacro-grip-module.html'', ''verified'', NULL, ''Replaces the XMACRO OEM module.'', ''easy'', ''polymer'', NULL, ''Tyrant CNC''''s XMacro module keeps the frame in polymer rather than aluminum, giving shooters a genuinely lighter option in a housing class where most competitors default to metal, while still including a rail and matching factory hardware compatibility for a clean install.'', FALSE),
(''947d13a6-5688-56f5-b68c-da66eb54d73f'', ''tyrant-cnc-p365-sn-gm'', ''frame'', ''2de98682-689f-460f-b990-2648bbcd24cb'', ''Tyrant CNC P365 Snub Nose'', ''https://www.tyrantcnc.com/sig-sauer-p365-grip-module-snub-nose-tyrant-cnc.html'', ''verified'', NULL, ''Replaces the XL/XMACRO OEM module.'', ''easy'', ''polymer'', NULL, ''An X/XL-housing module built around a shortened, snub-nose profile rather than the standard flush or extended geometry, giving shooters who want a more compact grip on the XL frame a genuine alternative to the standard flush or extended options.'', FALSE),
(''54238e93-4f4a-573d-9c19-e78dd97c7bae'', ''strike-industries-p365-gm'', ''frame'', ''0a9da4b0-dc28-4c5f-82d6-b9ae84f01718'', ''Strike Industries SIG P365/365XL Enhanced Grip Module'', ''https://www.strikeindustries.com/si-segm-p365-bk-fde1.html'', ''verified'', NULL, ''Replaces the P365/ XL OEM module.'', ''easy'', ''polymer'', 1.96, ''A budget-friendly polymer module for the X/XL housing with a rail and thumb stippling, giving shoppers a lower-cost alternative to the pricier metal options in this class.'', FALSE),
(''a650efb1-df0b-5a1c-890a-07e8da789507'', ''sharps-bros-p365-m01'', ''frame'', ''2f4b61c3-3292-49d0-992a-8c3eeea74316'', ''Sharps Bros P365X/ P365XL M01'', ''https://sharpsbros.com/sbgm01-g3-blk-sharps-bros-grip-module-for-the-p365x-p365xl-blacked-out-aluminum/'', ''verified'', NULL, ''Replaces the P365/ XL OEM module.'', ''easy'', ''aluminum'', 4.3, ''An aluminum X/XL module that combines a thumb rest with thumb stippling, a pairing not common among the other X/XL entries, aimed at shooters who want more grip utility on a metal frame.'', FALSE),
(''11300d81-fb8c-56e9-814c-438edaca45e1'', ''sharps-bros-p365-m05-g3'', ''frame'', ''2f4b61c3-3292-49d0-992a-8c3eeea74316'', ''Sharps Bros P365 X-Macro M05 G3'', ''https://sharpsbros.com/sbgm05-g3-sharps-bros-grip-module-for-the-p365-xmacro-black-anodize-with-brazilian-cherry-grips/'', ''verified'', NULL, ''Replaces the XMACRO OEM module.'', ''easy'', ''aluminum'', 5.3, ''An aluminum XMacro module pairing a thumb rest with aggressive stippling, giving buyers another all-metal XMacro option distinguished by its more sculpted, high-grip surface treatment.'', FALSE),
(''8f54f01a-f512-51a5-bfd8-18b3e25fa3e2'', ''icarus-precision-air-xmacro'', ''frame'', ''524256ba-8e32-4a5d-8032-c47593f433b6'', ''Icarus Precision Air Polymer XMacro'', ''https://www.icarusprecision.com/online-store/AIR-Polymer-XMACRO-Grip-Module-p649749283'', ''verified'', NULL, ''Replaces the XMACRO OEM module.'', ''easy'', ''polymer'', 2.1, ''A polymer XMacro module -- rather than the aluminum builds most competitors in this class offer, while still delivering an integrated magwell, thumb rest, and aggressive texture, appealing to shooters who want XMacro ergonomics without the added weight of metal.'', FALSE),
(''f94153e7-bdf6-516f-9a42-55aae687793c'', ''icarus-precision-pro-elite-ace-xmacro'', ''frame'', ''524256ba-8e32-4a5d-8032-c47593f433b6'', ''Icarus Precision Pro Elite A.C.E XMacro'', ''https://www.icarusprecision.com/online-store/PRO-Elite-A-C-E-365-p711693967'', ''verified'', NULL, ''Replaces the XMACRO OEM module.'', ''easy'', ''aluminum'', 4.37, ''An aluminum XMacro module with a flared magwell and thumb rest, sitting at the top of Icarus''''s A.C.E lineup for shooters seeking their most refined XMacro geometry.'', FALSE),
(''3c54ce15-3431-5949-9c1b-34418c668dfb'', ''icarus-precision-ace-xmacro'', ''frame'', ''524256ba-8e32-4a5d-8032-c47593f433b6'', ''Icarus Precision A.C.E. XMacro'', ''https://www.icarusprecision.com/online-store/A-C-E-365-X-MACRO-p742882599'', ''verified'', NULL, ''Replaces the XMACRO OEM module.'', ''easy'', ''aluminum'', 5.22, ''Icarus''''s standard aluminum A.C.E XMacro module with an integrated magwell and aggressive texture, offering a mid-tier option between the Air polymer build and the Pro Elite aluminum module.'', FALSE),
(''1cb77f04-390e-5981-be7b-ab7bd4989e9f'', ''icarus-precision-ace-fuse'', ''frame'', ''524256ba-8e32-4a5d-8032-c47593f433b6'', ''Icarus Precision A.C.E. Fuse'', ''https://www.icarusprecision.com/online-store/A-C-E-365-FUSE-MACRO-p711693872'', ''verified'', NULL, ''Flush fit with P365 FUSE or P365 extended slide with comp'', ''easy'', ''aluminum'', 5.4, ''An aluminum module built specifically for the Fuse housing with an integrated magwell and aggressive texture, extending Icarus''''s A.C.E line to Fuse owners with the same ergonomics as the XMacro version.'', FALSE),
(''8553d96f-a585-570a-afb0-00303c0d44d9'', ''icarus-precision-ace-fuse-evo'', ''frame'', ''524256ba-8e32-4a5d-8032-c47593f433b6'', ''Icarus Precision A.C.E. Fuse EVO'', ''https://www.icarusprecision.com/online-store/A-C-E-365-FUSE-EVO-p704349422'', ''verified'', NULL, ''Flush fit with P365 FUSE or P365 extended slide with comp'', ''easy'', ''aluminum'', 5.47, ''The Fuse EVO swaps the standard A.C.E Fuse''''s integrated magwell for a flared design, giving Fuse owners a second Icarus option with genuinely different magwell geometry rather than a cosmetic variant.'', FALSE),
(''d47664c6-b44d-52b1-8776-51bd8effff36'', ''icarus-precision-ace-xl-evo'', ''frame'', ''524256ba-8e32-4a5d-8032-c47593f433b6'', ''Icarus Precision A.C.E. XL EVO'', ''https://www.icarusprecision.com/online-store/A-C-E-365-XL-EVO-p709088862'', ''verified'', NULL, ''Replaces the XMACRO OEM module.'', ''easy'', ''aluminum'', 4.67, ''The XL EVO blends XL style proportions with XMacro class fitment in aluminum, giving shooters who want a more compact grip profile without leaving the metal frame category a distinct option from the rest of the A.C.E lineup.'', FALSE),
(''b5db2600-a4ea-5ade-8b64-1e3f928a6302'', ''icarus-precision-ace-axg-xmacro'', ''frame'', ''524256ba-8e32-4a5d-8032-c47593f433b6'', ''Icarus Precision A.C.E. AXG XMacro'', ''https://www.icarusprecision.com/online-store/ACE-365-AXG-MACRO-p704603867'', ''verified'', NULL, ''Replaces the XMACRO OEM module.'', ''easy'', ''aluminum'', 5.8, ''The AXG XMacro rounds out Icarus''''s aluminum lineup with a flared magwell alongside a thumb rest and stippling combination, adding yet another distinct geometry to the brand''''s already broad range of XMacro options.'', FALSE),
(''81ff51e4-851a-547a-b506-e66cb0df635b'', ''ecm-precision-r11-edge-xmacro'', ''frame'', ''2f0df8aa-a440-46a2-ad02-f8a213a31d5e'', ''ECM Precision R11 Edge XMacro'', ''https://ecmprecision.com/r11-edge-macro/'', ''verified'', NULL, ''Replaces the XMACRO OEM module.'', ''easy'', ''aluminum'', 6.65, ''ECM''''s Edge line brings aggressive texture and thumb stippling to an aluminum XMacro frame, giving buyers a genuine alternative to the Icarus and Shalotek builds that otherwise dominate this segment.'', FALSE),
(''1535a9fb-2edd-5478-858f-bdf1b5170c66'', ''ecm-precision-r11-edge-fuse'', ''frame'', ''2f0df8aa-a440-46a2-ad02-f8a213a31d5e'', ''ECM Precision R11 Edge Fuse'', ''https://ecmprecision.com/r11-edge-macro/'', ''verified'', NULL, ''Flush fit with P365 FUSE or P365 extended slide with comp'', ''easy'', ''aluminum'', 6.75, ''The Fuse sized counterpart to the Edge XMacro carries over the same texture and stippling, sized specifically to sit flush with the Fuse platform rather than adapted from the XMacro geometry.'', FALSE),
(''e36efb26-45f9-5b4c-b68f-a44ab129e75b'', ''ecm-precision-r11-edge-fuse-comp'', ''frame'', ''2f0df8aa-a440-46a2-ad02-f8a213a31d5e'', ''ECM Precision R11 Edge Fuse Comp'', ''https://ecmprecision.com/r11-edge-macro/'', ''verified'', NULL, ''P365 FUSE or P365 Fuse extended slide with comp'', ''easy'', ''aluminum'', 6.7, ''Built specifically for a compensated slide, this Fuse Edge variant ensures shooters running a comped setup get correct module fitment rather than guessing from the standard Fuse listing.'', FALSE),
(''5eaf2c41-a291-56b2-8fb5-ba071abe8195'', ''ecm-precision-r11-macro'', ''frame'', ''2f0df8aa-a440-46a2-ad02-f8a213a31d5e'', ''ECM Precision R11 Macro'', ''https://ecmprecision.com/r11-p365-macro-grip-module/'', ''verified'', NULL, ''Replaces the XMACRO OEM module.'', ''easy'', ''aluminum'', 7.6, ''ECM''''s standard R11 Macro module uses an integrated magwell rather than the flared design found on their Edge line, giving buyers a genuinely different geometry within the same aluminum XMacro category.'', FALSE),
(''d20b1360-629b-5c2e-a769-74f8b6d0feac'', ''ecm-precision-r11-fuse'', ''frame'', ''2f0df8aa-a440-46a2-ad02-f8a213a31d5e'', ''ECM Precision R11 Fuse'', ''https://ecmprecision.com/r11-p365-fuse-grip-module/'', ''verified'', NULL, ''Flush fit with P365 FUSE or P365 extended slide with comp'', ''easy'', ''aluminum'', 7.95, ''The R11 Fuse extends ECM''''s integrated magwell design to the Fuse housing, carrying the same aluminum construction and aggressive texture as the R11 Macro into a Fuse specific fit.'', FALSE),
(''aae47516-1ce9-5c55-b259-e2ee64706d5d'', ''ecm-precision-r11-fuse-comp'', ''frame'', ''2f0df8aa-a440-46a2-ad02-f8a213a31d5e'', ''ECM Precision R11 Fuse Comp'', ''https://ecmprecision.com/r11-p365-fuse-grip-module/'', ''verified'', NULL, ''P365 FUSE or P365 Fuse extended slide with comp'', NULL, ''aluminum'', 7.95, ''A compensator-slide-compatible version of the R11 Fuse, giving comped-Fuse shooters a correctly sized ECM option alongside the Edge Fuse Comp.'', FALSE),
(''c11b0827-5127-5e98-a209-0d1915c136c8'', ''mischief-machine-alpha-g3-xmacro'', ''frame'', ''e120bf61-7436-4ce0-ad58-645b7081f14e'', ''Mischief Machine Alpha Gen 3 XMacro'', ''https://mischiefmachine.com/alpha-gen-3/'', ''verified'', NULL, ''Replaces the XMACRO OEM module.'', ''easy'', ''aluminum'', 6.0, ''An aluminum XMacro module with a distinctive scale-pattern texture and thumb stippling, adding a visually different aesthetic to the XMacro lineup alongside its ergonomic upgrades.'', FALSE),
(''eafebf30-afc5-5bd8-b4cc-3a4da942c2f7'', ''mischief-machine-alpha-g3-fuse'', ''frame'', ''e120bf61-7436-4ce0-ad58-645b7081f14e'', ''Mischief Machine Alpha Gen 3 Fuse'', ''https://mischiefmachine.com/alpha-gen-3/'', ''verified'', NULL, ''Replaces the XMACRO/ FUSE OEM module.'', ''easy'', ''aluminum'', 6.0, ''The Fuse-sized version of the Alpha Gen 3, carrying the same scale texture and stippling over to Fuse owners.'', FALSE),
(''d78cea8e-1b35-5ce4-a172-6b187986164a'', ''mischief-machine-com-g2-xl'', ''frame'', ''e120bf61-7436-4ce0-ad58-645b7081f14e'', ''Mischief Machine Commander G2 X and XL'', ''https://mischiefmachine.com/gen-2-p365-commander-series-metal-grip-modules/'', ''verified'', NULL, ''XL/X ( X AND XL FRAMES ARE THE SAME SIZE) frames use the 12 round magazine and are flush with the 3.1\" slide and have the underbite look with the 3.7\" slide.'', ''easy'', ''aluminum'', 6.0, ''An aluminum module for the X/XL housing with the Commander series'''' scale texture, giving X/XL buyers a metal alternative styled to match the rest of the Mischief Machine lineup.'', FALSE),
(''55d51357-f6b1-5223-9319-5a95b86de87e'', ''mischief-machine-com-g2-xxl'', ''frame'', ''e120bf61-7436-4ce0-ad58-645b7081f14e'', ''Mischief Machine Commander G2 XXL'', ''https://mischiefmachine.com/gen-2-p365-commander-series-metal-grip-modules/'', ''verified'', NULL, ''XXL frames also take the 12 round flush magazines, but the rail is flush with the 3.7\" barreled slide.'', ''easy'', ''aluminum'', 6.0, ''The XXL variant delivers the largest grip footprint in the Commander series while still running on the XMacro magazine and rail, appealing to shooters who prioritize a fuller hand fill over a compact profile.'', FALSE),
(''63e75631-75c2-55b3-b4ab-a4740210af34'', ''mischief-machine-com-g2-xmacro'', ''frame'', ''e120bf61-7436-4ce0-ad58-645b7081f14e'', ''Mischief Machine Commander G2 XMacro'', ''https://mischiefmachine.com/gen-2-p365-commander-series-metal-grip-modules/'', ''verified'', NULL, ''Macro frames are the same size as the OEM X-Macro and the Fuse'', ''easy'', ''aluminum'', 6.0, ''The standard XMacro-sized entry in the Commander G2 series, matching the OEM XMacro/Fuse footprint for shooters who want Commander styling without changing grip size.'', FALSE),
(''a2b9da19-a288-5572-aac2-df92eacfb2ad'', ''mischief-machine-com-g2-fuse'', ''frame'', ''e120bf61-7436-4ce0-ad58-645b7081f14e'', ''Mischief Machine Commander G2 XMacro/Fuse Plus'', ''https://mischiefmachine.com/gen-2-p365-commander-series-metal-grip-modules/'', ''verified'', NULL, ''Macro PLUS frames are flush with the fuse slide, or a XL 3.7\" barreled slide and a PMM or similar compensator'', ''easy'', ''aluminum'', 6.0, ''A Fuse module sized to run flush with either the Fuse slide or an XL slide fitted with a compensator, giving shooters more slide-length flexibility than the standard Fuse-only options.'', FALSE);
"}', 'p365_grip_modules_insert_products', 'ag.gamboa94@gmail.com', NULL, NULL);
