INSERT INTO "supabase_migrations"."schema_migrations" ("version", "statements", "name", "created_by", "idempotency_key", "rollback") VALUES ('20260811181842', '{"-- Add mag_release category
ALTER TYPE product_category ADD VALUE IF NOT EXISTS ''mag_release'';

-- Create mag_release_specs table
CREATE TABLE IF NOT EXISTS mag_release_specs (
    product_id uuid REFERENCES products (id) PRIMARY KEY,
    category product_category NOT NULL,
    caliber text NOT NULL,
    style text,
    texture text,
    material text,
    length_added_in numeric,
    includes_spring_stop boolean
);

-- Add handedness column to product_variants
ALTER TABLE IF EXISTS product_variants
    ADD COLUMN IF NOT EXISTS handedness text;

-- Update variants_unique_axes index to include handedness
ALTER INDEX variants_unique_axes RENAME TO variants_unique_axes_old;

CREATE UNIQUE INDEX variants_unique_axes ON product_variants (
    product_id, color, finish, optic_cut, manual_safety_variant, bundle, clamp, handedness
) NULLS NOT DISTINCT;

DROP INDEX variants_unique_axes_old;

-- Backfill existing variants with ''ambidextrous'' handedness
UPDATE product_variants SET handedness = ''ambidextrous''
WHERE handedness IS NULL;"}', 'p365_mag_release_schema', 'ag.gamboa94@gmail.com', NULL, NULL);
