INSERT INTO "supabase_migrations"."schema_migrations" ("version", "statements", "name", "created_by", "idempotency_key", "rollback") VALUES ('20260811205642', '{"INSERT INTO products (id, slug, category, brand_id, name, url, fitment_confidence, build_warning, fitment_notes, installation_difficulty, material, weight_oz, description, is_discontinued) VALUES
(''0a01bfb4-d057-58f0-9706-cf78df89a1bb'', ''align-tactical-offset-mag-release-p365'', ''mag_release'', ''f27aa724-63ca-58db-8e2d-66f20cca2c62'', ''Align Tactical OFFSET P365 Extended Magazine Release'', ''https://www.aligntactical.com/products/offset-p365-extended-magazine-release'', ''verified'', ''Not a flush fit with wider OEM P365-XMACRO, P365 AXG Legion, or the new Icarus AIR Polymer grip module. Compatible XMACRO grip modules are sold separately by Icarus Precision (A.C.E. 365 XMACRO), ShaloTek (FLEX Macro), and Mischief Machine (XMACRO Commander). Holsters that cover the mag release may need minor relief.'', ''Compatible with OEM and most third-party grip modules — Icarus Precision (A.C.E. 365 series), Mischief Machine, ShaloTek, Sharps Bros., JL Billet, Juggernaut Tactical, and Wilson Combat WCP365 grip modules, 9mm/.380 Auto.'', NULL, ''Hardened steel, Black Oxide finish'', NULL, ''Moves the mag-release surface into a more ergonomic position for a two-handed grip, letting the support-hand middle finger rest flush instead of chafing on the OEM catch''''s edge. Reduces the pressure needed to drop the magazine without giving up retention, for faster, more confident reloads.'', FALSE),
(''5eae3c6e-0eac-5b36-b118-2633ebad1ce7'', ''tyrant-cnc-extended-mag-release-p365'', ''mag_release'', ''2de98682-689f-460f-b990-2648bbcd24cb'', ''Tyrant CNC P365 Extended Magazine Release'', ''https://www.tyrantcnc.com/sig-sauer-p365-extended-magazine-release.html'', ''verified'', NULL, ''Sig Sauer P365, P365 X, P365 XL, P365 MACRO, ALL P365 SPECTRE SERIES. Fits on California-compliant versions. Includes Mag Stop and Spring.'', NULL, ''17-4 stainless steel (MIM), bead-blasted, PVD coating'', NULL, ''Deep grooves give a confident thumb hold without being harsh, and the extended, raised button speeds up the release without interfering with IWB holsters.'', FALSE),
(''9dc5d83b-75e6-505b-9e98-b8efeb6a5f51'', ''ecm-precision-extended-aggressive-mag-release-p365'', ''mag_release'', ''2f0df8aa-a440-46a2-ad02-f8a213a31d5e'', ''ECM Precision Extended Aggressive OEM Style Mag Release'', ''https://ecmprecision.com/extended-aggressive-oem-style-mag-release/'', ''likely'', ''Built around ECM''''s own R11 grip module geometry. ECM states it \"installs cleanly in most OEM-compatible frames\" — confirm fit before running on a third-party grip module that isn''''t R11-based.'', ''Installs cleanly in most OEM-compatible frames; built to ECM''''s R11 grip module geometry.'', NULL, ''DLC (Diamond-Like Carbon) coated'', NULL, ''MACRO-style geometry with an aggressive thumb texture for instant, positive contact under stress. The extended button gives quicker reach during high-speed transitions, and the DLC coating adds long-term wear resistance with a discreet, low-reflective finish.'', FALSE),
(''758fb1f0-59c5-5672-aeda-d354531d03dc'', ''ecm-precision-extended-oem-mag-release-p365'', ''mag_release'', ''2f0df8aa-a440-46a2-ad02-f8a213a31d5e'', ''ECM Precision Extended OEM Style Mag Release'', ''https://ecmprecision.com/extended-oem-style-mag-release/'', ''likely'', ''Built around ECM''''s own R11 grip module geometry. ECM states it \"installs cleanly in most OEM-style frames\" — confirm fit before running on a third-party grip module that isn''''t R11-based.'', ''Installs cleanly in most OEM-style frames; built to ECM''''s R11 grip module geometry.'', NULL, ''DLC (Diamond-Like Carbon) coated'', NULL, ''Blends OEM familiarity with competition-ready ergonomics: a cross-hatch thumb texture for positive tactile feedback, an extended button for faster manipulation, and a rugged DLC coating for long-lasting, low-reflective wear resistance.'', FALSE),
(''e071fafc-9a8b-5db7-8726-7d31bc72ab44'', ''true-precision-stainless-mag-release-p365'', ''mag_release'', ''72ee170a-a129-49e8-aa63-e9015816063b'', ''True Precision Stainless Steel Extended Magazine Release for Sig Sauer ALL P365'', ''https://true-precision.com/true-precision-stainless-steel-extended-magazine-release-for-sig-sauer-all-p365/'', ''verified'', NULL, ''Sig P365 Line (listed by True Precision as fitting ALL P365 models).'', NULL, ''303 stainless steel'', NULL, ''A sculpted 303-stainless button that adds just 0.165\" of stick-out for quicker, more intuitive magazine swaps without an oversized profile. Finish-matches True Precision''''s other P365 parts for a cohesive custom build.'', FALSE),
(''a3030f20-a609-5731-a3d9-f0557979bbed'', ''strike-industries-mag-release-p365'', ''mag_release'', ''0a9da4b0-dc28-4c5f-82d6-b9ae84f01718'', ''Strike Industries Magazine Release for SIG SAUER P365'', ''https://www.strikeindustries.com/si-p365-magrelease.html'', ''verified'', ''NOT COMPATIBLE with SIG SAUER P365 XMACRO & P322.'', ''SIG SAUER P365/P365XL/P365 SAS/P365 X/P365XL Spectre & Spectre Comp. Aftermarket P365 grip modules with OEM magazine release fitment. NOT COMPATIBLE: SIG SAUER P365 XMACRO & P322.'', NULL, ''SUS630 hardened stainless steel'', NULL, ''Strike Industries button face provides enhanced grip for quick magazine changes. The extended design improves ergonomics over the OEM release. Reversible for ambidextrous use, constructed from SUS630 hardened stainless steel for lasting durability. Drop-in OEM fitment.'', FALSE),
(''33302f65-e87c-5562-88c3-44aa744a37f0'', ''strike-industries-mag-release-p365-xmacro'', ''mag_release'', ''0a9da4b0-dc28-4c5f-82d6-b9ae84f01718'', ''Strike Industries Mag Release for SIG P365 XMACRO'', ''https://www.strikeindustries.com/si-p365-xm-mr.html'', ''verified'', ''Designed for the P365 XMACRO. Will functionally work on non-XMACRO P365 models, but the rear piece may stick out slightly because the XMACRO uses a single-piece rear vs the standard P365''''s 2-piece system.'', ''Primary fit: SIG P365 XMACRO. Will functionally work with all P365 models, but non-XMACRO models may have the rear piece stick out slightly due to different mag-release geometry (XMACRO = single-piece rear, standard P365 = 2-piece).'', NULL, ''Hardened stainless steel'', NULL, ''Built specifically for the wider XMACRO grip module with Strike''''s enhanced button face for confident, fast magazine changes. Extended button length and improved ergonomics over OEM. Reversible for ambidextrous use, hardened stainless steel construction.'', FALSE),
(''329d19e2-ba1c-5706-ab4a-6f71cf337cb1'', ''timber-creek-extended-mag-release-p365'', ''mag_release'', ''45a0a01b-3b66-5257-9c07-e7b635ac2acd'', ''Timber Creek Sig Sauer P365 Extended Magazine Release'', ''https://www.opticsplanet.com/sig-sauer-p365-extended-magazine-release.html'', ''likely'', ''Sold on OpticsPlanet under a misleading title — this is manufactured by Timber Creek Outdoors, not SIG Sauer. Does NOT include spring or plastic retaining stop per user reviews — reuse your factory hardware.'', ''Fits SIG Sauer P365 series per OpticsPlanet listing.'', NULL, ''Not specified'', NULL, ''An extended, stippled mag release from Timber Creek Outdoors that provides a larger, textured thumb surface for quicker, more positive magazine drops. Available in multiple Cerakote colors for a custom aesthetic match.'', FALSE);"}', 'p365_mag_release_insert_products', 'ag.gamboa94@gmail.com', NULL, NULL);
