INSERT INTO "supabase_migrations"."schema_migrations" ("version", "statements", "name", "created_by", "idempotency_key", "rollback") VALUES ('20260812035944', '{"INSERT INTO products (id, slug, category, brand_id, name, family, url, fitment_confidence, build_warning, fitment_notes, build_notes, installation_difficulty, material, weight_oz, description, best_for, pros, cons, editor_rating, base_price, is_discontinued) VALUES
(''1a1ea54b-d57e-55b4-af6b-3e1acc822763'', ''true-precision-magwell-p365xmacro'', ''magwell'', ''72ee170a-a129-49e8-aa63-e9015816063b'', ''True Precision Stainless Steel Magwell for Sig Sauer P365 XMacro & FUSE'', ''p365'', ''https://true-precision.com/true-precision-stainless-steel-magwell-for-sig-sauer-p365-xmacro-fuse/'', ''verified'', NULL, ''XMacro/FUSE/AXG Legion Lowers.'', ''Drop-in, includes installation hardware. Designed to finish-match True Precision''''s other P365 parts.'', NULL, ''303 stainless steel'', 1.6, ''The stock XMACRO grip module has a flat, unguided magazine opening that can slow reloads under stress. This billet stainless magwell adds a smooth funnel and extra mass low on the grip, improving magazine guidance and giving the gun a more planted, balanced feel that the factory polymer baseplate does not provide.'', ''{}'', NULL, NULL, NULL, NULL, FALSE),
(''0cdfb9aa-c79e-5513-b22d-0e8925299426'', ''tyrant-cnc-magwell-p365xmacro'', ''magwell'', ''2de98682-689f-460f-b990-2648bbcd24cb'', ''Tyrant CNC Sig Sauer P365 XMacro Magwell'', ''p365'', ''https://www.tyrantcnc.com/sig-sauer-p365-x-macro-magwell.html'', ''verified'', NULL, ''Fits P365 XMacro & Tyrant CNC Grip Modules. Compatible with OEM 17rnd magazine. Compatible with Tyrant 365 magazine extension. Fits on California compliant versions.'', ''Attaches via supplied screw to the bottom of the P365 XMacro grip module. No modifications required. Includes screw/nut.'', NULL, ''6061 aluminum'', NULL, ''The OEM grip module leaves the magazine well unassisted and the pinky floating below the grip. This aluminum magwell adds a flared funnel for more forgiving reloads and extends the grip surface so your support hand can lock in fully, reducing felt recoil and print without adding significant bulk.'', ''{}'', NULL, NULL, NULL, NULL, FALSE),
(''90305239-5a83-5f86-aac0-9e3918f7385f'', ''herrington-arms-magwell-p365xmacro'', ''magwell'', ''4b10bbec-13d5-4fda-b3f7-874f5fe3fee4'', ''Herrington Arms HA Magwell for P365 X Macro'', ''p365'', ''https://herringtonarms.com/products/ha-magwell-for-p365-x-macro'', ''verified'', NULL, ''Sig P365 X Macro.'', ''Mid-size magwell. Drop-in installation.'', NULL, ''7075 aluminum'', NULL, ''Where the factory XMACRO grip offers no reload assistance, this mid-size aluminum magwell adds a durable, lightweight funnel that guides the magazine on insertion while keeping the overall footprint concealable — bridging the gap between a bare grip module and an oversized competition magwell.'', ''{}'', NULL, NULL, NULL, NULL, FALSE),
(''82d17dd2-1734-57d9-84a1-2d4d576a0a08'', ''radian-backstrap-magwell-p365xmacro'', ''magwell'', ''7ff69780-dd39-47c5-b2d2-f3125f9a9f5d'', ''Radian Weapons Backstrap + Magwell Combo for Sig P365 XMACRO'', ''p365'', ''https://radianweapons.com/product/backstrap-magwell-for-sig-sauer'', ''verified'', ''This is a COMBO kit — backstrap + magwell sold together. The magwell cannot be purchased separately. Adds width and length to the grip, which may affect concealment.'', ''Sig P365 XMACRO only. Does NOT fit standard P365/X/XL frames.'', ''Includes one backstrap, one magwell, retention stud and spring, and one retention stud tool. Drop-in — no fitting required.'', NULL, ''Aircraft-grade aluminum'', NULL, ''The stock XMACRO backstrap and flat magazine opening leave grip texture and reload speed on the table. This combo replaces both at once — the aggressive-channel backstrap locks the hand higher and tighter than any OEM insert, and the integrated magwell funnels magazines more consistently than the bare grip module allows.'', ''{}'', NULL, NULL, NULL, NULL, FALSE),
(''769147d3-f60e-529d-8347-b7b118c28870'', ''sig-sauer-mag-funnel-p365xmacro'', ''magwell'', ''01c196c0-8fae-41df-9b3d-12578408a206'', ''SIG SAUER P365-XMACRO Magazine Funnel - Black'', ''p365'', ''https://www.sigsauer.com/p365-xmacro-magazine-funnel-black.html'', ''verified'', ''Only compatible with the factory P365-XMACRO grip module per SIG SAUER.'', ''P365-XMACRO, P365-XMACRO COMP, P365-FUSE per SIG SAUER. Only compatible with the factory P365-XMACRO grip module.'', ''Includes installation hardware. OEM part from SIG SAUER.'', NULL, ''Polymer'', NULL, ''A factory-engineered funnel from SIG that gives the XMACRO a guided magazine opening it does not ship with out of the box. It adds minimal weight and keeps the stock profile, making it the lowest-commitment upgrade for shooters who want smoother reloads without changing the grip feel or holster fit.'', ''{}'', NULL, NULL, NULL, NULL, FALSE),
(''8b4986f1-c1e4-5247-9052-9e68c2812a96'', ''shalotek-flex-magwell-p365'', ''magwell'', ''137f8518-c1e9-418c-bb28-532678842d58'', ''ShaloTek FLEX Magwell'', ''p365'', ''https://shalotek.com/products/flex-magwell-black.html'', ''verified'', ''This magwell is EXCLUSIVELY compatible with the ShaloTek FLEX grip module''''s 17R magazine housing — it does NOT fit any OEM SIG grip module (P365, XMACRO, FUSE, etc.) or other aftermarket frames. Requires a complete ShaloTek FLEX frame build to use.'', ''Exclusively compatible with the ShaloTek FLEX grip module''''s 17R magazine housing and standard P365 17-round magazines. Does NOT fit any OEM SIG grip module.'', ''Installs with a single set screw — do not over-tighten. Compatible with Taran Tactical and Springer Precision extended baseplates per user reviews. Armory Craft too tight to drop free. Tyrant CNC extended baseplate does not fully seat.'', NULL, ''7075 aluminum'', 0.5, ''The FLEX Magwell only works within ShaloTek''''s modular FLEX ecosystem — but for builders already running that frame, it fills a gap the bare 17R magazine housing leaves open, adding a flared funnel for guided reloads with almost no additional bulk or print.'', ''{}'', NULL, NULL, NULL, NULL, FALSE);"}', 'p365_magwell_insert_products', 'ag.gamboa94@gmail.com', NULL, NULL);
