INSERT INTO "supabase_migrations"."schema_migrations" ("version", "statements", "name", "created_by", "idempotency_key", "rollback") VALUES ('20260812060241', '{"INSERT INTO products (id, slug, category, brand_id, name, family, url, fitment_confidence, build_warning, fitment_notes, build_notes, installation_difficulty, material, weight_oz, description, best_for, pros, cons, editor_rating, base_price, is_discontinued) VALUES
(''b35cab23-8135-51da-aabb-01710ac2d2b7'', ''radian-tru17-basepad-p365xmacro'', ''basepad'', ''7ff69780-dd39-47c5-b2d2-f3125f9a9f5d'', ''Radian TRU-17 Magazine Base Pad (2-Pack)'', ''p365'', ''https://radianweapons.com/product/tru-17-for-sig-sauer'', ''verified'', NULL, ''P365 XMACRO 17rd magazines only. NOT compatible with OEM 10rd mags or mags without removable base pads. Sold as 2-pack.'', ''Direct replacement — remove OEM base pad using the magazine spring detent and slide TRU-17 on. No tools required.'', NULL, ''Aircraft-grade aluminum'', NULL, ''The factory XMACRO base pad can make loading the last round difficult and offers minimal purchase for stripping a stuck magazine. The TRU-17 adds mass to help empty mags drop free, provides a larger grip surface for indexing spares from holsters, and eases full-capacity loading.'', ''{concealed-carry,range}'', NULL, NULL, NULL, NULL, FALSE),
(''2ee8c88c-7c48-584f-977a-c9b4786dc59c'', ''armory-craft-pinky-ext-p365-10rd'', ''basepad'', ''aa94f3e2-0c81-4015-9fa3-38854d0c9f09'', ''Armory Craft P365 Pinky Extension for 10-Round Magazines'', ''p365'', ''https://www.armorycraft.com/product-page/sig-sauer-p365-pinky-extension-for-10-round-magazines'', ''verified'', ''Fits ONLY 10rd P365 mags on P365 frames (NOT XL). Will NOT fit P365XL, P365X, 12rd, or 15rd mags. NOT for Wilson Combat P365 grip modules.'', ''Fits ONLY 10-round P365 magazines on P365 frames. Will NOT fit 365XL frames, 12rd or 15rd magazines, or 10rd restricted XL/X mags.'', ''Not designed for repetitive competition drops — the polymer is impact-resistant but not built for repeated hard impacts.'', NULL, ''Nylon polymer (additive manufactured)'', NULL, ''The short P365 grip with a 10-round magazine leaves the pinky dangling with no surface to grip. This extension adds a full finger groove for a more secure hold, giving the support hand something to lock onto for better control without adding capacity or bulk.'', ''{concealed-carry}'', NULL, NULL, NULL, NULL, FALSE),
(''793ff97a-2497-51e3-9f5f-863536b98b4d'', ''tyrant-cnc-mag-ext-p365xmacro-plus3'', ''basepad'', ''2de98682-689f-460f-b990-2648bbcd24cb'', ''Tyrant CNC P365 XMacro +3 Magazine Extension'', ''p365'', ''https://www.tyrantcnc.com/sig-sauer-p365-magazine-extension.html'', ''verified'', NULL, ''Fits only P365 XMacro 17-round magazine. Works with most magwells. Does NOT fit other Sig P365 lower-capacity magazines. Comes with power spring. Fits California-compliant versions.'', ''Tool-less install via Tyrant''''s NoBak retention plunger — slides on in seconds, push plunger to remove. Includes power spring.'', NULL, ''6061 aluminum'', NULL, ''The stock XMACRO magazine tops out at 17 rounds with no room to grow. This CNC-machined aluminum extension adds three rounds while matching the grip profile to minimize printing, and the NoBak retention plunger locks the extension in place without tools.'', ''{concealed-carry,competition,range}'', NULL, NULL, NULL, NULL, FALSE),
(''f0c5e673-843e-5595-aac5-bb620e77ae5d'', ''tyrant-cnc-baseplate-p365xmacro'', ''basepad'', ''2de98682-689f-460f-b990-2648bbcd24cb'', ''Tyrant CNC P365 XMacro Base Plate'', ''p365'', ''https://www.tyrantcnc.com/p365-xmacro-base-plate.html'', ''verified'', NULL, ''Compatible with 17-round XMACRO magazine only. Flush-fit replacement for OEM floor plate. Compatible with most P365 magwells.'', ''Quick install — direct swap for the OEM base pad. Enhanced geometry adds grip surface and weight.'', NULL, ''6061 aluminum'', NULL, ''The factory plastic floor plate is light, thin, and offers minimal grip surface for stripping a stuck magazine or indexing a spare from a pouch. This aluminum replacement adds weight to help mags drop free and a thicker, textured surface for more confident manipulation without changing capacity.'', ''{concealed-carry,range}'', NULL, NULL, NULL, NULL, FALSE),
(''677ff0c6-77d1-5f33-87df-effb2b4a1f4d'', ''jl-billet-17rd-adapter-p365-oem'', ''basepad'', ''7fd2e7ca-2187-5229-8de0-d1b857498592'', ''JL Billet 17-Round Mag Adaptor for SIG P365 OEM Grip'', ''p365'', ''https://jlbillet.com/jl-billet-17-round-mag-adaptor-for-sig-p365-oem-grip/'', ''verified'', ''Currently out of stock at JL Billet — more in process per their site.'', ''Allows use of 17-round XMACRO Macro magazines in the standard P365 OEM grip module.'', ''Available in slashed or smooth texture, in raw aluminum (cerakote-ready), hard black anodized, or Magpul FDE cerakote.'', NULL, ''Billet aluminum (CNC)'', NULL, ''The standard P365 grip module was never designed for 17-round XMACRO magazines — inserting one leaves an exposed gap between the grip and baseplate. This billet adapter fills the gap and lets P365 owners run the higher-capacity magazine with a clean fit and comfortable ergonomics.'', ''{concealed-carry,range}'', NULL, NULL, NULL, NULL, FALSE),
(''74c0049c-5fe7-5ab3-b18f-e6d1b7a3bfb3'', ''tti-xmacro-completed-mag-w-basepad'', ''basepad'', ''cb527eb6-669f-5abd-aac2-40387ec60cf7'', ''TTI SIG X-MACRO Completed Magazine w/ Versatile Basepad'', ''p365'', ''https://tarantacticalinnovations.com/sig-x-macro-completed-magazine-w-tti-versatile-basepad/'', ''verified'', ''This is a COMPLETED MAGAZINE (mag + basepad sold together), NOT a standalone basepad. Total capacity 20 rounds.'', ''P365-XMACRO and all P365 9mm models per TTI. Factory 17-round steel magazine with TTI Versatile Basepad pre-installed.'', ''Ships as a complete, ready-to-use magazine — no assembly needed. Available in Flat Black or Coyote Bronze basepad color.'', NULL, ''Aluminum basepad, steel magazine body'', NULL, ''Rather than buying a basepad and swapping it onto an existing magazine, this ships as a complete package — a factory 17-round steel XMACRO magazine with the TTI Versatile Basepad already installed, bringing total capacity to 20 rounds. The rounded basepad profile eliminates the sharp OEM corners that can dig in during concealed carry.'', ''{concealed-carry,competition}'', NULL, NULL, NULL, NULL, FALSE),
(''29aa6d8a-3a0f-5227-a151-95db763c2279'', ''hogue-rubber-basepad-p365xl-15rd'', ''basepad'', ''a0ead5c5-e7ff-5c57-a448-f88203320263'', ''Hogue OverMolded Rubber Grip Extension Base Pad (15-Round) for P365X/XL'', ''p365'', ''https://www.hogueinc.com/overmolded-rubber-grip-extension-base-pad-15-round-magazines-black-sig-sauer-p365-x-xl'', ''verified'', ''Compatible ONLY with 15-round magazines and P365X/XL with Hogue HandALL Beavertail Grip Sleeve.'', ''Precision fit for SIG SAUER P365X & XL with Hogue HandALL Beavertail Grip Sleeve. Compatible ONLY with 15-round magazines.'', ''Simple installation. Magazine not included. Best paired with Hogue''''s HandALL Beavertail Grip Sleeve for the P365X/XL.'', NULL, ''OverMolded thermoplastic elastomer (Cobblestone texture)'', NULL, ''The P365X/XL with a 15-round magazine can leave the bottom of the grip feeling incomplete. This rubber extension adds an extra finger groove for a full-hand grip, cushions reload drops, and uses Hogue''''s Cobblestone texture for a tacky, comfortable hold that the bare magazine floor plate doesn''''t provide.'', ''{concealed-carry,range}'', NULL, NULL, NULL, NULL, FALSE),
(''c421b665-c0c0-5f23-91d3-d513df8527ed'', ''hogue-rubber-basepad-p365-10rd'', ''basepad'', ''a0ead5c5-e7ff-5c57-a448-f88203320263'', ''Hogue OverMolded Rubber Grip Extension Base Pad (10-Round) for P365'', ''p365'', ''https://www.hogueinc.com/overmolded-rubber-grip-extension-base-pad-10-round-magazines-black-sig-sauer-p365-9mm'', ''verified'', ''Compatible ONLY with 10-round magazines and P365 (9MM) with Hogue HandALL Beavertail Grip Sleeve.'', ''Precision fit for SIG SAUER P365 (9MM) with Hogue HandALL Beavertail Grip Sleeve. Compatible ONLY with 10-round magazines.'', ''Simple installation. Magazine not included. Best paired with Hogue''''s HandALL Beavertail Grip Sleeve for the P365.'', NULL, ''OverMolded thermoplastic elastomer (Cobblestone texture)'', NULL, ''The compact P365 with a 10-round magazine offers the least grip surface in the entire lineup — the pinky has nothing to hold. This rubber extension adds a full finger groove, protects the magazine during reload drops, and uses Hogue''''s Cobblestone texture for a cushioned, high-traction hold the bare floor plate can''''t match.'', ''{concealed-carry}'', NULL, NULL, NULL, NULL, FALSE);"}', 'p365_basepad_insert_products', 'ag.gamboa94@gmail.com', NULL, NULL);
