INSERT INTO "supabase_migrations"."schema_migrations" ("version", "statements", "name", "created_by", "idempotency_key", "rollback") VALUES ('20260812184036', '{"INSERT INTO products (id,slug,category,brand_id,name,family,url,fitment_confidence,build_warning,fitment_notes,build_notes,installation_difficulty,material,weight_oz,description,best_for,pros,cons,editor_rating,base_price,is_discontinued) VALUES
(''d097691f-7bce-5ad6-b315-605e4b4252cb'',''tyrant-cnc-ext-slide-catch-p365'',''slide_release'',''2de98682-689f-460f-b990-2648bbcd24cb'',''Tyrant CNC P365 Extended Slide Catch Lever'',''p365'',''https://www.tyrantcnc.com/sig-sauer-p365-slide-catch-lever.html'',''verified'',''May not be compatible with 2019 and earlier FCUs. Holster fit may vary — most holsters will not require modification, but Kydex holsters that wrap tight around the slide catch area may need minor heat relief.'',''All post-2019 Sig Sauer P365 platform variants. Works on P365 Macro. Fits California-compliant versions. May not be compatible with 2019 and earlier FCUs. Uses existing OEM spring.'',''Drop-in replacement — no modifications needed. Uses existing OEM spring. CNC machined with slight geometry changes that allow the slide catch to also function as a slide release (no slide release function on empty magazines).'',NULL,''CNC-machined stainless steel, PVD finish'',NULL,''The factory P365 slide catch is small and recessed, making it difficult to reach and manipulate with one thumb. The Tyrant CNC extended lever adds surface area and a raised, textured contact point so you can actuate the slide catch confidently with a single thumb.'',''{concealed-carry,competition,range}'',NULL,NULL,NULL,NULL,FALSE),
(''3d16ba21-a43c-5098-9404-cf545f548b3b'',''armory-craft-ext-slide-release-p365'',''slide_release'',''aa94f3e2-0c81-4015-9fa3-38854d0c9f09'',''Armory Craft P365 Extended Slide Release'',''p365'',''https://www.armorycraft.com/product-page/armory-craft-sig-sauer-p365-extended-slide-release'',''verified'',''Holster fit may vary — most holsters will not require modification, but some may need minor relief on the Kydex edge near the slide catch. The part is only about 2mm wider and 2.4mm longer than OEM.'',''Fits ALL P365 variant pistols per Armory Craft. Manufacturing facility certified to ISO 9001/AS9100. Made in USA.'',''Drop-in replacement. Uses existing OEM spring. Gently serrated and uniquely shaped to improve reloads under stress without interfering with grip. About 2mm wider and 2.4mm longer than the factory part.'',NULL,''Medium carbon low alloy steel, hardened to SIG factory specifications'',NULL,''Armory Crafts grooved, extended lever provides better leverage and a more positive contact surface so the slide catch can be actuated reliably with one hand, improving reload speed under stress.'',''{concealed-carry,competition,range}'',NULL,NULL,NULL,NULL,FALSE);"}', 'p365_slide_release_insert_products', 'ag.gamboa94@gmail.com', NULL, NULL);
