INSERT INTO "supabase_migrations"."schema_migrations" ("version", "statements", "name", "created_by", "idempotency_key", "rollback") VALUES ('20260813000554', '{"INSERT INTO products (id,slug,category,brand_id,name,family,url,fitment_confidence,build_warning,fitment_notes,build_notes,installation_difficulty,material,weight_oz,description,best_for,pros,cons,editor_rating,base_price,is_discontinued) VALUES
(''e75ec946-b467-59ed-9c38-43111d64d8c7'',''anarchy-outdoors-slide-plate-p365'',''slide_plate'',''c2128636-56d8-5655-958a-959d0eb50817'',''Anarchy Outdoors Slide Plate for Sig 365'',''p365'',''https://www.opticsplanet.com/anarchy-outdoors-slide-plate-for-sig-365.html'',''verified'',NULL,''Sig 365 platform. Made in USA.'',''Direct drop-in replacement for the OEM rear slide plate. No tools beyond a punch needed.'',NULL,''Aluminum (anodized)'',NULL,''The factory MIM slide plate is purely functional with no visual distinction. This anodized aluminum replacement adds a color accent to the rear of the slide — a low-cost way to personalize the gun and match other aftermarket controls without affecting function.'',''{concealed-carry,range}'',NULL,NULL,NULL,NULL,FALSE),
(''bf7579cc-3f90-50e2-afff-aa2418544859'',''true-precision-slide-cap-p365'',''slide_plate'',''72ee170a-a129-49e8-aa63-e9015816063b'',''True Precision Stainless Steel Slide Cap Textured Back Plate'',''p365'',''https://true-precision.com/sig-p365-stainless-steel-slide-cap-textured-back-plate/'',''verified'',NULL,''Fits all 9mm P365 models: P365, SAS, P365XL, P365XL Spectre, P365 XMacro, P365 XMacro Tacops, P365 AXG Legion, P365-FUSE. 100% Made in USA.'',''Replaces the OEM MIM backplate. Embossed logo and rim for easier install and removal vs OEM. Machined from solid billet stainless for increased strength and durability over factory.'',NULL,''300-series solid billet stainless steel'',NULL,''The factory MIM backplate is a soft, featureless part that can be difficult to grip during removal and offers no upgrade in strength. This billet stainless replacement is machined from a stronger material, adds a textured rim for easier install and removal, and finish-matches True Precision''''s other P365 parts for a cohesive build.'',''{concealed-carry,competition,range}'',NULL,NULL,NULL,NULL,FALSE),
(''7161306d-f2b1-5618-a791-9466237fd6a2'',''tyrant-cnc-slide-cap-p365'',''slide_plate'',''2de98682-689f-460f-b990-2648bbcd24cb'',''Tyrant CNC Sig Sauer P365 Slide Cap'',''p365'',''https://www.tyrantcnc.com/sig-sauer-p365-slide-cap.html'',''verified'',NULL,''All SIG P365 platform variants per Tyrant CNC. Fits California-compliant versions.'',''Drop-in replacement. Pairs visually with other Tyrant CNC P365 controls (takedown lever, slide catch, mag release) for a matched look.'',NULL,''17-4 stainless steel (MIM), bead-blasted, PVD coating'',NULL,''The factory slide cap is a plain, unfinished MIM part that blends into the slide with no visual character. This PVD-coated stainless replacement adds a color accent to the rear of the slide and pairs with Tyrant''''s other P365 controls for a cohesive, finished appearance.'',''{concealed-carry,range}'',NULL,NULL,NULL,NULL,FALSE);"}', 'p365_slide_plate_insert_products', 'ag.gamboa94@gmail.com', NULL, NULL);
INSERT INTO "supabase_migrations"."schema_migrations" ("version", "statements", "name", "created_by", "idempotency_key", "rollback") VALUES ('20260812201735', '{"INSERT INTO products (id,slug,category,brand_id,name,family,url,fitment_confidence,build_warning,fitment_notes,build_notes,installation_difficulty,material,weight_oz,description,best_for,pros,cons,editor_rating,base_price,is_discontinued) VALUES
(''c0928335-4521-5a87-809d-e751750f12f3'',''sig-sauer-manual-safety-kit-p365'',''safety_selector'',''01c196c0-8fae-41df-9b3d-12578408a206'',''SIG SAUER P365X Manual Safety Controls Parts Kit'',''p365'',''https://www.sigsauer.com/p365x-manual-safety-controls-parts-kit-gold.html'',''verified'',''Requires a manual-safety FCU — will NOT work on non-safety P365 FCUs. SIG SAUER requires installation by a certified armorer. Disassembly beyond field-stripped condition is required. Any damage from incorrect installation is not covered by warranty. Do NOT substitute individual parts from this kit.'',''P365, P365X, P365-XL, P365-XMACRO, P365-XMACRO COMP, P365-AXG, P365-FUSE, P365-LUXE. Caliber: 9mm Luger, 380 AUTO. Requires manual-safety FCU.'',''Must be installed as a full kit — do not substitute individual parts. Requires disassembly beyond field-stripped condition. SIG SAUER recommends certified armorer installation only.'',NULL,''Gold-plated steel'',NULL,''The factory manual safety on P365 models ships in a matte black finish that disappears into the frame. This OEM gold-plated kit replaces the lever, detent, and spring as a matched set, giving the controls a high-polish accent that visually ties into other gold-finished P365 upgrades without changing the safety''''s function or feel.'',''{concealed-carry,range}'',NULL,NULL,NULL,NULL,FALSE),
(''ca21b249-5214-5e57-89ec-e56403a4b2de'',''tyrant-cnc-safety-selector-p365'',''safety_selector'',''2de98682-689f-460f-b990-2648bbcd24cb'',''Tyrant CNC P365 Safety Selector'',''p365'',''https://www.tyrantcnc.com/sig-sauer-p365-safety-lever.html'',''verified'',''Requires a manual-safety FCU — will NOT work on non-safety P365 FCUs. Some users report the OEM plunger may need minor fitting to seat into the replacement lever. Check fit before carrying.'',''P365, P365X, P365XL, P365 XMACRO per Tyrant CNC. Uses existing OEM detent, spring, and plunger. Made from 17-4 heat-treated stainless steel with PVD coating.'',''Lever-only replacement — reuses the factory detent, spring, and plunger. Some users report the OEM plunger may need minor fitting. CNC machined from 17-4 heat-treated stainless steel.'',NULL,''17-4 heat-treated stainless steel, PVD coating'',NULL,''Tyrant CNC machined lever provides a wider, textured contact surface with better grip so you can sweep the safety on or off with confidence, and the PVD-coated stainless steel construction resists corrosion and wear.'',''{concealed-carry,competition,range}'',NULL,NULL,NULL,NULL,FALSE);"}', 'p365_safety_selector_insert_products', 'ag.gamboa94@gmail.com', NULL, NULL);
INSERT INTO "supabase_migrations"."schema_migrations" ("version", "statements", "name", "created_by", "idempotency_key", "rollback") VALUES ('20260812201744', '{"INSERT INTO safety_selector_specs (product_id,category,is_ambidextrous,includes_detent_spring,kit_contents) VALUES
