INSERT INTO "supabase_migrations"."schema_migrations" ("version", "statements", "name", "created_by", "idempotency_key", "rollback") VALUES ('20260812214124', '{"INSERT INTO products (id,slug,category,brand_id,name,family,url,fitment_confidence,build_warning,fitment_notes,build_notes,installation_difficulty,material,weight_oz,description,best_for,pros,cons,editor_rating,base_price,is_discontinued) VALUES
(''9cf18dbe-2336-52d8-abca-0b503188c0f6'',''tyrant-cnc-takedown-lever-p365'',''takedown_lever'',''2de98682-689f-460f-b990-2648bbcd24cb'',''Tyrant CNC SIG SAUER P365 Takedown Lever'',''p365'',''https://www.tyrantcnc.com/sig-sauer-p365-takedown-lever.html'',''verified'',''One user review reports the round protruding detent (which prevents trigger pull when the lever is engaged) sheared off after extended use. Inspect the detent after initial rounds. P365 Tac Ops compatible when combining with OEM or Tyrant Slide Release.'',''All SIG P365 variants including P365 XL, P365 X-MACRO. Pairs best with Tyrant CNC Extended Slide Release for a seamless look. Fits California-compliant versions.'',''Drop-in replacement — remove the existing takedown lever and slide the Tyrant lever in. No tools or permanent modification required. Extended surface area and added serrations for enhanced grip.'',NULL,''17-4 stainless steel (MIM), bead-blasted, PVD coating'',NULL,''Tyrant CNC MIM stainless lever adds serrations and a larger contact area for a more positive pinch-and-rotate action, and the PVD coating visually upgrades the frame to match other aftermarket controls.'',''{concealed-carry,range}'',NULL,NULL,NULL,NULL,FALSE),
(''0d0e68bf-3640-56d0-9613-15230f71f2c2'',''align-tactical-thumb-rest-takedown-p365'',''takedown_lever'',''f27aa724-63ca-58db-8e2d-66f20cca2c62'',''Align Tactical P365 Thumb Rest Takedown Lever'',''p365'',''https://www.aligntactical.com/products/p365-thumb-rest-takedown-lever'',''verified'',''NOT COMPATIBLE with Romeo-X, Romeo-RS Compact, or Vortex Defender CCW optics — these require the special ''''notched'''' version sold exclusively by SIG SAUER. Holster must clear the extended thumb rest ledge (8mm / 0.32in protrusion from frame). See Align Tactical''''s list of compatible holster manufacturers.'',''All P365 models including Legion, FUSE, Luxe. Aftermarket grip modules: Icarus Precision (EVO & AXG), Mischief Machine, Sharps Bros, ECM Precision R11. Made in USA with lifetime warranty.'',''Drop-in replacement. The thumb rest extends forward of the center of rotation, directing thumb pressure toward an internal over-travel stop so the lever stays locked during firing. Protrudes 8mm (0.32in) from the frame. Requires holster with clearance for extended ledge.'',NULL,''Hardened S7 tool steel, Premium DLC (Diamond-Like Carbon) coating'',NULL,''Micro-compact P365 pistols are known for a snappy recoil impulse that can push the support hand off target between shots. The Align Tactical Thumb Rest gives the support thumb a firm, textured ledge to lock down against muzzle flip and providing a consistent index point for a high thumbs-forward grip.'',''{concealed-carry,competition,range}'',NULL,NULL,NULL,NULL,FALSE);"}', 'p365_takedown_lever_insert_products', 'ag.gamboa94@gmail.com', NULL, NULL);
INSERT INTO "supabase_migrations"."schema_migrations" ("version", "statements", "name", "created_by", "idempotency_key", "rollback") VALUES ('20260812214153', '{"
INSERT INTO takedown_lever_specs (product_id,category,takedown_type,has_thumb_rest,optic_compatibility_notes) VALUES
(''9cf18dbe-2336-52d8-abca-0b503188c0f6'',''takedown_lever'',''enhanced'',FALSE,NULL),
(''0d0e68bf-3640-56d0-9613-15230f71f2c2'',''takedown_lever'',''thumb-rest'',TRUE,''COMPATIBLE: Holosun 507K/407K/SCS Carry/EPS Carry, SIG RomeoZERO/ELITE (without metal shroud), Shield RMSc, Olight Osight, Bushnell RXC/RXU-200, Primary Arms Classic 21mm. NOT COMPATIBLE: SIG Romeo-X, Romeo-RS Compact, Vortex Defender CCW — use ''''notched'''' version from SIG SAUER. USPSA Production and CO approved. IDPA ESP and Carry Optics validated.'');

