INSERT INTO "supabase_migrations"."schema_migrations" ("version", "statements", "name", "created_by", "idempotency_key", "rollback") VALUES ('20260813053607', '{"
-- Remove the redundant base_price column from products.
-- Authoritative price is product_variants.msrp on the is_default variant.
-- Lowest real-world price lives in products.lowest_price (written by repricing job).
ALTER TABLE public.products DROP COLUMN base_price;
"}', 'drop_products_base_price', 'ag.gamboa94@gmail.com', NULL, NULL);
