INSERT INTO "supabase_migrations"."schema_migrations" ("version", "statements", "name", "created_by", "idempotency_key", "rollback") VALUES ('20260815054929', '{"
INSERT INTO products (id,slug,category,brand_id,name,family,url,fitment_confidence,build_warning,fitment_notes,build_notes,material,description,best_for,is_discontinued) VALUES
(''2df07af2-1456-56fa-8c9c-a546bdffbfde'',''zaffiri-p365-xl-ported'',''barrel'',''ff350ae7-d553-4f74-8705-3c1b446caba1'',''Zaffiri Precision P365XL Ported Barrel'',''p365'',''https://zaffiriprecision.com/product/p365xl-barrel-ported-black-nitride/'',''verified'',NULL,''Drop-in fit for Sig P365XL. PORTED barrel — compatible ONLY with Zaffiri Precision ZPS.4 and ZPS.P slides. Will NOT work with OEM or other aftermarket slides. Flush & crown (non-threaded). 416R stainless, broach-cut 6-groove rifling, 1:10 LH twist. SAAMI spec chamber. 3.64\" length. Made in USA.'',''Requires a Zaffiri Precision ZPS.4 or ZPS.P slide — the barrel ports must align with the slide port windows. Do not install in an OEM or non-ported slide. Also available in Stainless and TiN Gold finishes.'',''416R stainless steel, Black Nitride finish'',''The factory P365XL barrel is a non-ported, standard-profile part with no gas venting. This match-grade ported barrel redirects propellant gas upward through precision-cut ports, counteracting muzzle rise for faster follow-up shots — but it requires a Zaffiri Precision ported slide to function, making it part of a dedicated upper build rather than a standalone barrel swap.'',''{competition,range}'',FALSE);

INSERT INTO barrel_specs (product_id,category,barrel_length_in,caliber,barrel_type,thread_pitch,port_style,is_lci,ballistic_loss,requires_slide_text,pairs_with_comp_id) VALUES
