INSERT INTO "supabase_migrations"."schema_migrations" ("version", "statements", "name", "created_by", "idempotency_key", "rollback") VALUES ('20260817051051', '{"
-- 1. Create junction table
CREATE TABLE magwell_frame_requirements (
  magwell_product_id UUID NOT NULL REFERENCES products(id) ON DELETE CASCADE,
  frame_product_id UUID NOT NULL REFERENCES products(id) ON DELETE CASCADE,
  source TEXT DEFAULT ''manufacturer'',
  compatibility_note TEXT,
  PRIMARY KEY (magwell_product_id, frame_product_id)
);

COMMENT ON TABLE magwell_frame_requirements IS ''Whitelist: which frames a magwell fits. If a magwell has rows here, it ONLY fits those frames.'';
COMMENT ON COLUMN magwell_frame_requirements.compatibility_note IS ''User-facing text about this magwell+frame pairing.'';

ALTER TABLE magwell_frame_requirements ENABLE ROW LEVEL SECURITY;

