INSERT INTO "supabase_migrations"."schema_migrations" ("version", "statements", "name", "created_by", "idempotency_key", "rollback") VALUES ('20260817072150', '{"
create table public.build_fires (
  build_id   uuid        not null references public.builds(id)   on delete cascade,
  user_id    uuid        not null references public.profiles(id) on delete cascade,
  created_at timestamptz not null default now(),
  primary key (build_id, user_id)
);

comment on table public.build_fires is
  ''Community \"fires\" (likes) per build. Composite PK enforces one fire per user per build.'';

create index build_fires_build_idx on public.build_fires(build_id);
create index build_fires_user_idx  on public.build_fires(user_id);

alter table public.build_fires enable row level security;

-- Anyone can see counts; visibility of *which* build a fire references is
-- already gated by the builds table''s own RLS (only approved builds are
-- publicly visible), so listing fires publicly leaks nothing about drafts.
create policy \"build_fires_public_read\"
  on public.build_fires for select
  to anon, authenticated
  using (true);

-- Users can only fire on their own behalf, and only builds they can see —
-- the SELECT sub-check protects against firing an unapproved build id they
-- somehow guessed. auth.uid() reads the JWT.
create policy \"users_can_fire_builds\"
  on public.build_fires for insert
  to authenticated
  with check (
    user_id = auth.uid()
    and exists (select 1 from public.builds b where b.id = build_id)
  );

create policy \"users_can_unfire_builds\"
  on public.build_fires for delete
  to authenticated
  using (user_id = auth.uid());
"}', 'create_build_fires_table', 'ag.gamboa94@gmail.com', NULL, NULL);
INSERT INTO "supabase_migrations"."schema_migrations" ("version", "statements", "name", "created_by", "idempotency_key", "rollback") VALUES ('20260818150758', '{"
-- Public read access for product images (anyone can view)
CREATE POLICY \"Public read access for product images\"
ON storage.objects FOR SELECT
USING (bucket_id = ''product-images'');

-- Only authenticated admins can upload/update/delete product images
CREATE POLICY \"Admin upload product images\"
ON storage.objects FOR INSERT
WITH CHECK (
  bucket_id = ''product-images'' 
  AND auth.role() = ''authenticated''
  AND EXISTS (
    SELECT 1 FROM public.profiles 
    WHERE id = auth.uid() AND role = ''admin''
  )
);

CREATE POLICY \"Admin update product images\"
ON storage.objects FOR UPDATE
USING (
  bucket_id = ''product-images'' 
  AND auth.role() = ''authenticated''
  AND EXISTS (
    SELECT 1 FROM public.profiles 
    WHERE id = auth.uid() AND role = ''admin''
  )
);

CREATE POLICY \"Admin delete product images\"
ON storage.objects FOR DELETE
USING (
  bucket_id = ''product-images'' 
  AND auth.role() = ''authenticated''
  AND EXISTS (
    SELECT 1 FROM public.profiles 
    WHERE id = auth.uid() AND role = ''admin''
  )
);
"}', 'product_images_storage_policies', 'ag.gamboa94@gmail.com', NULL, NULL);
INSERT INTO "supabase_migrations"."schema_migrations" ("version", "statements", "name", "created_by", "idempotency_key", "rollback") VALUES ('20260820160512', '{"
-- Safety net: no NULLs expected today (default is false and existing rows
-- have true) but a nullable boolean makes the app-side check awkward
-- (\"false OR null → redirect\"). Tighten to NOT NULL so the check is just
-- `!row.onboarding_complete`.
update public.profiles set onboarding_complete = false where onboarding_complete is null;
alter table public.profiles alter column onboarding_complete set not null;
"}', 'profiles_onboarding_complete_not_null', 'ag.gamboa94@gmail.com', NULL, NULL);
INSERT INTO "supabase_migrations"."schema_migrations" ("version", "statements", "name", "created_by", "idempotency_key", "rollback") VALUES ('20260821051049', '{"
-- 1. handle_new_user() had a mutable search_path — pin it to `public` so a
--    schema-shadowing attack can''t redirect the trigger''s inserts.
alter function public.handle_new_user() set search_path = public;

-- 2. contest_build_part is a SECURITY DEFINER RPC that should only be callable
--    by signed-in users. Revoke anon''s EXECUTE so anonymous browser clients
--    can''t invoke it via /rest/v1/rpc/contest_build_part.
revoke execute on function public.contest_build_part(uuid, integer) from anon;
"}', 'security_fixes_search_path_and_grants', 'ag.gamboa94@gmail.com', NULL, NULL);
INSERT INTO "supabase_migrations"."schema_migrations" ("version", "statements", "name", "created_by", "idempotency_key", "rollback") VALUES ('20260824024247', '{"
-- 1. Drop NOT NULL from builds.user_id so admin can post a build before a
--    user account exists for the builder. The FK to profiles(id) stays,
--    so any non-null value must still resolve to a real profile row.
alter table public.builds
  alter column user_id drop not null;

-- 2. The existing \"Users can create their own builds\" policy has
--    WITH CHECK (auth.uid() = user_id), which rejects inserts with a null
--    user_id (auth.uid() != null in every case). Add a separate admin-only
--    insert policy so admins can create builds with user_id NULL or set to
--    any user''s id (e.g. re-linking a build to a different account).
create policy \"Admins can create any build\"
  on public.builds
  for insert
  to authenticated
  with check (public.is_admin());
"}', 'builds_allow_admin_posted_unlinked_rows', 'ag.gamboa94@gmail.com', NULL, NULL);
