INSERT INTO "supabase_migrations"."schema_migrations" ("version", "statements", "name", "created_by", "idempotency_key", "rollback") VALUES ('20260824070335', '{"
-- The old \"Profiles are publicly readable\" (USING true) exposed every column
-- to anon — including `role`, letting anyone enumerate admin usernames.
--
-- Fix: column-level SELECT grants. RLS controls ROW visibility, not COLUMN
-- visibility, so a two-policy structure with different USING clauses can''t
-- do what we want — protecting the `role` column has to be done via GRANT.
--
-- The spec suggested a second policy gated on (auth.uid() = id OR is_admin()).
-- I did not add that because doing so as the sole authenticated-user policy
-- would prevent signed-in users from reading other users'' usernames (needed
-- everywhere the app shows \"by <author>\") and would break the signup
-- username-availability check. Authenticated users retain their default
-- full-column SELECT grant; the meaningful protection is on the anon side.
drop policy if exists \"Profiles are publicly readable\" on public.profiles;

revoke select on public.profiles from anon;
grant  select (id, username, onboarding_complete) on public.profiles to anon;

create policy \"profiles_public_read\" on public.profiles
  for select to anon, authenticated
  using (true);
"}', 'profiles_hide_role_from_anon', 'ag.gamboa94@gmail.com', NULL, NULL);
INSERT INTO "supabase_migrations"."schema_migrations" ("version", "statements", "name", "created_by", "idempotency_key", "rollback") VALUES ('20260824070345', '{"
-- The old \"partners_public_read\" (USING true) exposed commission_pct,
-- tracking_param, base_url, and notes to any anon caller with the anon key.
-- The frontend only ever reads `name`, so anon''s grant is narrowed to
-- (id, name, slug) — id + slug are stable public identifiers, name is what
-- displays. Authenticated users keep full-column access (unchanged) so
-- admin tooling that needs commission_pct still works.
drop policy if exists \"partners_public_read\" on public.partners;

revoke select on public.partners from anon;
grant  select (id, name, slug) on public.partners to anon;

create policy \"partners_public_read\" on public.partners
  for select to anon, authenticated
  using (true);
"}', 'partners_hide_business_columns_from_anon', 'ag.gamboa94@gmail.com', NULL, NULL);
INSERT INTO "supabase_migrations"."schema_migrations" ("version", "statements", "name", "created_by", "idempotency_key", "rollback") VALUES ('20260824070406', '{"
-- The \"Owners can edit their own unreviewed builds\" policy has WITH CHECK
-- (auth.uid()=user_id AND status IN (''draft'',''pending'')), which allows a
-- draft/pending owner to UPDATE any column — including edit_history. Since
-- edit_history is where admin correction badges get their audit trail, an
-- owner could fake correction entries on their own build before it goes
-- through review.
--
-- RLS is row-level, not column-level: you cannot express \"only these columns
-- may be updated\" in a policy body. The two mechanisms that actually work
-- are column-level UPDATE grants (which would also block admins from
-- writing edit_history and require rewriting doSaveEdit as an RPC) and a
-- BEFORE UPDATE trigger (transparent to admins, no app code changes).
-- Going with the trigger — is_admin() lets admin writes through, everyone
-- else has to leave edit_history unchanged.
create or replace function public.prevent_owner_edit_history_change()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  -- Admins can freely modify edit_history — that''s how corrections get logged.
  if public.is_admin() then
    return new;
  end if;
  -- Anyone else must leave edit_history unchanged. IS DISTINCT FROM is the
  -- null-safe comparison — [] vs [{...}] differs even if either side is null.
  if new.edit_history is distinct from old.edit_history then
    raise exception ''Only admins can modify edit_history''
      using errcode = ''42501'';   -- insufficient_privilege
  end if;
  return new;
end;
$$;

drop trigger if exists trg_prevent_owner_edit_history_change on public.builds;
create trigger trg_prevent_owner_edit_history_change
  before update on public.builds
  for each row execute function public.prevent_owner_edit_history_change();

-- The trigger fires as SECURITY DEFINER; anon/authenticated need no direct
-- grant to execute it (Supabase''s default trigger-function grants apply).
"}', 'builds_only_admins_can_write_edit_history', 'ag.gamboa94@gmail.com', NULL, NULL);
