(''a610b278-80a4-51cc-a666-f2991dacbe43'',''vortex-defender-ccw'',''optic'',''e7c2441d-7df8-5e55-ba2e-877183dab59a'',''Vortex Defender CCW'',''universal'',''https://vortexoptics.com/defender-ccw'',''verified'',NULL,''Shield RMSc footprint. Open emitter.'',NULL,NULL,NULL,0.8,''Lightweight open emitter RMSc micro dot at 0.8 oz.'',''{concealed-carry}'',NULL,NULL,NULL,FALSE),
(''6e32b620-59c4-577f-9f38-194da9ac7c67'',''vortex-venom-enclosed'',''optic'',''e7c2441d-7df8-5e55-ba2e-877183dab59a'',''Vortex Venom Enclosed'',''universal'',''https://vortexoptics.com/venom-enclosed'',''verified'',NULL,''DeltaPoint Pro footprint. Enclosed emitter. Budget enclosed.'',NULL,NULL,NULL,1.2,''An enclosed emitter DPP footprint optic at an entry level price.'',''{range-duty}'',NULL,NULL,NULL,FALSE),
(''9c5bbb99-c0ab-50d2-bf76-76e922fe6fe0'',''leupold-deltapoint-pro'',''optic'',''4f515259-b849-5388-92ce-c3d8bd5efb28'',''Leupold DeltaPoint Pro'',''universal'',''https://www.leupold.com/deltapoint-pro-red-dot'',''verified'',NULL,''DeltaPoint Pro footprint (the original). Open emitter. Made in USA.'',NULL,NULL,NULL,1.95,''The optic that created the DPP footprint, made in Oregon.'',''{duty-competition}'',NULL,NULL,NULL,FALSE),
(''305a5575-64c7-5fc5-86d2-c4191b8748e6'',''eotech-eflx-ce'',''optic'',''481a89b6-5c4e-58c7-8bc8-d8df31939f32'',''EOTech EFLX CE'',''universal'',''https://www.eotechinc.com/products/eotech-eflxce-pistol-optic'',''verified'',NULL,''DeltaPoint Pro AND Shield RMSc footprint — fits both cuts. Enclosed emitter.'',NULL,NULL,NULL,1.46,''EOTech''''s first enclosed pistol optic that fits both DPP and RMSc cuts.'',''{duty}'',NULL,NULL,NULL,FALSE),
(''3b9147f4-3d7b-5899-a63a-71bfa5e8338c'',''eotech-eflx'',''optic'',''481a89b6-5c4e-58c7-8bc8-d8df31939f32'',''EOTech EFLX'',''universal'',''https://www.eotechinc.com/products/eflx-pistol-optic'',''verified'',NULL,''DeltaPoint Pro footprint ONLY. Open emitter.'',NULL,NULL,NULL,1.4,''Open emitter DPP footprint optic with that signature EOTech square window.'',''{duty-competition}'',NULL,NULL,NULL,FALSE),
(''9e5ceddc-f117-514c-b687-dd04901b93a9'',''aimpoint-acro-p2'',''optic'',''0e93d0ca-546a-577e-9314-1de46d1e40a1'',''Aimpoint ACRO P-2'',''universal'',''https://aimpoint.us/acro-p-2-red-dot-reflex-sight-3-5-moa-200691/'',''verified'',NULL,''Aimpoint ACRO proprietary clamping footprint with recoil lug.'',NULL,NULL,NULL,2.19,''The optic that started the enclosed emitter movement.'',''{duty}'',NULL,NULL,NULL,FALSE);"}', 'p365_optics_insert_products', 'ag.gamboa94@gmail.com', NULL, NULL);
