INSERT INTO "supabase_migrations"."schema_migrations" ("version", "statements", "name", "created_by", "idempotency_key", "rollback") VALUES ('20260905053758', '{"INSERT INTO products (slug, category, brand_id, name, family, url, fitment_confidence, fitment_notes, weight_oz, description, best_for, editor_rating, is_discontinued) VALUES
(''osight-x'', ''optic''::product_category, (SELECT id FROM manufacturers WHERE slug=''olight''), ''Osight X'', ''universal'', ''https://www.olight.com/store/osight-x-3-moa-with-charging-cover'', ''unverified''::fitment_confidence, ''RMR/407c/507c footprint. Magnetic charging cover included.'', 1.62, ''Olight''''s biggest window open reflex on the RMR footprint with a selectable multi reticle system and a magnetic rechargeable battery, so you never have to buy cells again. Great pick if you want a full size competition sight that charges like your phone.'', ''{\"competition\"}''::text[], NULL, FALSE),
(''osight-c'', ''optic''::product_category, (SELECT id FROM manufacturers WHERE slug=''olight''), ''Osight C'', ''universal'', ''https://www.olight.com/store/osight-c-open-reflex-replaceable-side-loading-battery'', ''unverified''::fitment_confidence, ''RMR/407c/507c footprint. Side-loading CR1632 battery.'', 1.48, ''Same wide RMR footprint window and multi reticle as the Osight X, but runs on a replaceable CR1632 you can swap in the field. Solid choice if you like the convenience of standard batteries over recharging.'', ''{\"range-duty\"}''::text[], NULL, FALSE),
(''osight-k'', ''optic''::product_category, (SELECT id FROM manufacturers WHERE slug=''olight''), ''Osight K'', ''universal'', ''https://www.olight.com/store/osight-k-open-reflex-replaceable-side-loading-battery'', ''unverified''::fitment_confidence, ''RMSc footprint. Side-loading CR1632 battery.'', 1.02, ''A simple 6 MOA micro dot on the RMSc footprint at just over an ounce, making it one of the lightest open emitter options you can put on a carry gun. If you want a dot that disappears on a micro compact slide, this is it.'', ''{\"concealed-carry\"}''::text[], NULL, FALSE),
(''osight-s'', ''optic''::product_category, (SELECT id FROM manufacturers WHERE slug=''olight''), ''Osight S'', ''universal'', ''https://www.olight.com/store/osight-s-2-moa-with-charging-cover'', ''unverified''::fitment_confidence, ''RMSc footprint. Enclosed emitter. Magnetic charging cover.'', 0.97, ''Enclosed emitter, multi reticle, and under an ounce on the RMSc footprint. Hard to find that combination anywhere else at this price, and the magnetic rechargeable battery keeps it slim and eliminates the battery tray.'', ''{\"concealed-carry\"}''::text[], NULL, FALSE),
(''osight-3moa'', ''optic''::product_category, (SELECT id FROM manufacturers WHERE slug=''olight''), ''Osight 3 MOA'', ''universal'', ''https://www.olight.com/store/osight-3-moa-with-charging-cover'', ''unverified''::fitment_confidence, ''RMR/407c/507c footprint. Magnetic charging cover.'', 1.94, ''A clean single 3 MOA dot on the RMR footprint with a rechargeable magnetic battery. Good starter optic for someone who wants a precise dot without the complexity of multi reticle switching.'', ''{\"range-duty\"}''::text[], NULL, FALSE),
(''osight-xr'', ''optic''::product_category, (SELECT id FROM manufacturers WHERE slug=''olight''), ''Osight XR'', ''universal'', ''https://www.olight.com/store/osight-xr-enclosed-red-dot-sight-rmr'', ''unverified''::fitment_confidence, ''RMR/407c/507c footprint. Enclosed emitter. Magnetic charging cover. Collapsible backup rear sight.'', 1.94, ''Olight''''s flagship with an enclosed emitter, five selectable reticles, and a built in flip up rear sight, all on the RMR footprint. If you want maximum versatility and emitter protection in one package, this checks every box.'', ''{\"duty-competition\"}''::text[], NULL, FALSE),
(''osight-se-rmsc'', ''optic''::product_category, (SELECT id FROM manufacturers WHERE slug=''olight''), ''Osight SE'', ''universal'', ''https://www.olight.com/store/osight-se-enclosed-optic'', ''verified''::fitment_confidence, ''RMSc footprint. Enclosed emitter. Ships with RMR-to-RMSc adapter plate.'', 0.97, ''An enclosed emitter micro optic under an ounce with multi reticle, and it ships with an RMR adapter plate in the box. Exceptional value for anyone who wants sealed protection on a carry gun without spending over $400.'', ''{\"concealed-carry\"}''::text[], NULL, FALSE),
(''osight-xe-amrs'', ''optic''::product_category, (SELECT id FROM manufacturers WHERE slug=''olight''), ''Osight XE AMRS'', ''universal'', ''https://www.olight.com/store/osight-xe-amrs-enclosed-red-dot-sight-rmr'', ''unverified''::fitment_confidence, ''RMR/407c/507c footprint. Enclosed emitter. Side-loading CR1632. Collapsible backup rear sight.'', 1.94, ''Enclosed RMR footprint sight with five reticle options, a replaceable CR1632 good for 105,000 hours, and a built in backup rear sight. Gives you most of what the XR offers but with a field swappable battery instead of rechargeable.'', ''{\"duty-competition\"}''::text[], NULL, FALSE),
(''osight-se-dpp'', ''optic''::product_category, (SELECT id FROM manufacturers WHERE slug=''olight''), ''Osight SE DPP'', ''universal'', ''https://www.olight.com/store/osight-se-enclosed-red-dot-sight-dpp-footprint-optic'', ''unverified''::fitment_confidence, ''DeltaPoint Pro footprint. Enclosed emitter.'', 1.2, ''Enclosed emitter on the DeltaPoint Pro footprint with multi reticle at a very competitive price. If your slide is already cut for DPP and you want sealed protection without paying premium prices, this delivers.'', ''{\"duty-competition\"}''::text[], NULL, FALSE),
(''osight-se-mos'', ''optic''::product_category, (SELECT id FROM manufacturers WHERE slug=''olight''), ''Osight SE MOS'', ''universal'', ''https://www.olight.com/store/osight-se-mos-enclosed-red-dot-sight'', ''unverified''::fitment_confidence, ''Direct Glock MOS footprint — no adapter plate. Fits Gen 5 G17/G19/G47 MOS. NOT for slimline MOS (G43X/G48).'', 1.59, ''The first enclosed emitter optic that bolts directly to a Glock MOS slide with no adapter plate, and the 140,000 hour battery life is a bonus. Purpose built for Glock MOS owners who are tired of stacking plates.'', ''{\"duty\"}''::text[], NULL, FALSE),
(''sig-sauer-romeo-rs-compact'', ''optic''::product_category, (SELECT id FROM manufacturers WHERE slug=''sig-sauer''), ''Sig Sauer Romeo RS Compact'', ''universal'', ''https://www.sigsauer.com/romeo-rs-compact.html'', ''verified''::fitment_confidence, ''Shield RMSc footprint. Steel-reinforced polymer housing.'', 0.95, ''Sig''''s entry level RMSc red dot with a steel reinforced polymer housing starting under $150. MOTAC, shake awake, and proven reliable, making it the best value micro dot if you''''re on a budget.'', ''{\"concealed-carry\"}''::text[], NULL, FALSE),
(''sig-sauer-romeo-rs-pro'', ''optic''::product_category, (SELECT id FROM manufacturers WHERE slug=''sig-sauer''), ''Sig Sauer Romeo RS Pro'', ''universal'', ''https://www.sigsauer.com/romeo-rs-pro.html'', ''unverified''::fitment_confidence, ''DeltaPoint Pro / Sig PRO footprint. Steel-reinforced polymer housing. For P320/P226/P229 PRO cut slides.'', 1.1, ''Full size DPP footprint red dot with a steel chassis inside a polymer shell, keeping weight and price down. A smart pick for a first optic on any DPP cut duty or carry gun.'', ''{\"duty-competition\"}''::text[], NULL, FALSE),
(''sig-sauer-romeo1pro'', ''optic''::product_category, (SELECT id FROM manufacturers WHERE slug=''sig-sauer''), ''Sig Sauer Romeo1Pro'', ''universal'', ''https://www.sigsauer.com/romeo1pro-1x30-mm.html'', ''unverified''::fitment_confidence, ''Sig PRO RX footprint. Fits M17, M18, P320 XFive Legion, P320 XCompact, P320 XFull, all PRO-CUT slides. NOT compatible with standard Romeo1 cut. Shares DPP mounting pattern on most slides.'', 1.6, ''Sig''''s dedicated full size optic on the PRO RX footprint with a 30mm window and protective shroud included. Direct mount to any PRO CUT slide without adapters.'', ''{\"duty-competition\"}''::text[], NULL, FALSE),
(''sig-sauer-romeo3pro'', ''optic''::product_category, (SELECT id FROM manufacturers WHERE slug=''sig-sauer''), ''Sig Sauer Romeo3Pro'', ''universal'', ''https://www.sigsauer.com/romeo3pro-1x31mm.html'', ''unverified''::fitment_confidence, ''Sig PRO footprint. Competition-focused. Mounts to P320 family PRO-cut slides.'', 1.5, ''Competition grade 31mm aspherical lens on the Sig PRO footprint with 15 brightness settings, built for fast splits and wide transitions. The optic competitive pistol shooters reach for on PRO CUT slides.'', ''{\"competition\"}''::text[], NULL, FALSE),
(''sig-sauer-romeo-mdc'', ''optic''::product_category, (SELECT id FROM manufacturers WHERE slug=''sig-sauer''), ''Sig Sauer Romeo MDC'', ''universal'', ''https://www.sigsauer.com/romeo-mdc.html'', ''verified''::fitment_confidence, ''Shield RMSc footprint. Top-loading CR1632 — no re-zero on battery swap.'', 1.03, ''Top loading battery means you never lose zero when you swap cells, and that''''s the whole point of the MDC. A well thought out daily carry dot on the RMSc footprint at a fair price.'', ''{\"concealed-carry\"}''::text[], NULL, FALSE),
(''sig-sauer-romeo-x-compact'', ''optic''::product_category, (SELECT id FROM manufacturers WHERE slug=''sig-sauer''), ''Sig Sauer Romeo X-Compact'', ''universal'', ''https://www.sigsauer.com/romeo-x-compact.html'', ''unverified''::fitment_confidence, ''Shield RMS-C footprint'', 1, ''Sig''''s workhorse RMSc carry optic built from forged 7075 aluminum that sits low enough to co witness with standard height sights. Proven, reliable, and available in multiple reticle options for any RMSc cut micro compact.'', ''{\"concealed-carry\"}''::text[], NULL, FALSE),
(''sig-sauer-romeo-x-sigloc-pro'', ''optic''::product_category, (SELECT id FROM manufacturers WHERE slug=''sig-sauer''), ''Sig Sauer Romeo-X SIG-LOC PRO'', ''universal'', ''https://www.sigsauer.com/romeo-x-sig-loctm-pro.html'', ''verified''::fitment_confidence, ''SIG-LOC PRO bottom-mount footprint. For P320 SIG-LOC-ready slides ONLY. NOT compatible with standard top-mount DPP/RMR cuts. Slides with SIG-LOC cuts also accept traditional top-mount optics.'', 1.24, ''Sig''''s SIG LOC bottom mount gives you five contact points between the optic and slide, and nothing holds zero harder under recoil. Exclusively for P320 slides with the SIG LOC cut.'', ''{\"duty\"}''::text[], NULL, FALSE),
(''sig-sauer-romeo-x-sigloc-compact'', ''optic''::product_category, (SELECT id FROM manufacturers WHERE slug=''sig-sauer''), ''Sig Sauer Romeo-X SIG-LOC Compact'', ''universal'', ''https://www.sigsauer.com/romeo-x-sig-loctm-compact.html'', ''verified''::fitment_confidence, ''SIG-LOC Compact bottom-mount footprint. For P365 SIG-LOC-ready slides ONLY. NOT compatible with standard RMSc top-mount.'', 1.24, ''Same SIG LOC bottom mount technology as the PRO, scaled down for the P365 platform. Exclusively for P365 slides with the SIG LOC cut. This enclosed optic locks in and stays zeroed.'', ''{\"concealed-carry\"}''::text[], NULL, FALSE),
(''sig-sauer-romeo-x-enclosed-compact'', ''optic''::product_category, (SELECT id FROM manufacturers WHERE slug=''sig-sauer''), ''Sig Sauer Romeo-X Enclosed Compact'', ''universal'', ''https://www.sigsauer.com/romeo-x-compact-enclosed.html'', ''verified''::fitment_confidence, ''Shield RMSc footprint. Fully enclosed and sealed. For P365 and all RMSc-cut pistols.'', 1.2, ''Sig''''s enclosed emitter option on the standard RMSc footprint with a fully sealed housing that keeps out moisture, debris, and carbon fouling. The go to if you want Sig quality with enclosed protection on any RMSc cut carry gun.'', ''{\"concealed-carry\"}''::text[], NULL, FALSE),
(''sig-sauer-romeo-x-enclosed-pro'', ''optic''::product_category, (SELECT id FROM manufacturers WHERE slug=''sig-sauer''), ''Sig Sauer Romeo-X Enclosed Pro'', ''universal'', ''https://www.sigsauer.com/romeo-x-pro-enclosed.html'', ''unverified''::fitment_confidence, ''DeltaPoint Pro / Sig PRO footprint. Enclosed. For P320/P226/P229 PRO-cut slides.'', 1.2, ''Enclosed emitter Romeo X on the DPP footprint for full size duty guns with a sealed housing, MOTAC, and 15 brightness settings. Clean choice for any DPP cut slide where you want emitter protection.'', ''{\"duty-competition\"}''::text[], NULL, FALSE),
(''sig-sauer-romeo-x-pro'', ''optic''::product_category, (SELECT id FROM manufacturers WHERE slug=''sig-sauer''), ''Sig Sauer Romeo-X Pro'', ''universal'', ''https://www.sigsauer.com/romeo-x-pro.html'', ''unverified''::fitment_confidence, ''DeltaPoint Pro / Sig PRO footprint. Open emitter. For P320 and all DPP-cut slides.'', 1.3, ''Open emitter DPP footprint optic with a bigger 27mm window and an integrated backup rear sight built into the housing. Gives you more glass to work with than the Compact without going enclosed.'', ''{\"duty-competition\"}''::text[], NULL, FALSE),
(''sig-sauer-romeo2'', ''optic''::product_category, (SELECT id FROM manufacturers WHERE slug=''sig-sauer''), ''Sig Sauer Romeo2'', ''universal'', ''https://www.sigsauer.com/romeo2-1x30-mm-reflex-sight.html'', ''unverified''::fitment_confidence, ''Romeo1Pro / Sig PRO footprint. Open emitter. Includes steel shroud. For P320 PRO-CUT slides.'', 1.8, ''Sig''''s next gen full size optic with a 30mm window and a steel shroud that ships in the box for serious impact protection. Direct mount to any Romeo1Pro footprint slide.'', ''{\"duty-competition\"}''::text[], NULL, FALSE),
(''sig-sauer-romeo2-large-shroud'', ''optic''::product_category, (SELECT id FROM manufacturers WHERE slug=''sig-sauer''), ''Sig Sauer Romeo2 Large Shroud'', ''universal'', ''https://www.sigsauer.com/romeo2-1x30mm-large-shroud.html'', ''unverified''::fitment_confidence, ''Romeo1Pro / Sig PRO footprint. Full-length steel shroud converts it to enclosed. For P320 PRO-CUT slides.'', 2.1, ''Same Romeo2, but the full length steel shroud seals the rear window and turns it into a fully enclosed optic. If you want Romeo2 performance with zero chance of debris reaching the emitter, this is the configuration.'', ''{\"duty\"}''::text[], NULL, FALSE),
(''sig-sauer-romeo-m17'', ''optic''::product_category, (SELECT id FROM manufacturers WHERE slug=''sig-sauer''), ''Sig Sauer Romeo-M17'', ''universal'', ''https://www.sigsauer.com/romeo-m17.html'', ''verified''::fitment_confidence, ''SIG-LOC MHS proprietary bottom-mount. ONLY fits M17/M18 military-issue and commemorative pistols with single optics plate screw. Does NOT fit standard commercial P320 slides.'', 1.5, ''Built to MIL SPEC exclusively for the M17 and M18. Gas purged, submersible to 35 meters, SIG LOC bottom mount. This is a military contract optic and it only fits M17 and M18 pistols.'', ''{\"military-duty\"}''::text[], NULL, FALSE),
(''holosun-eps-core'', ''optic''::product_category, (SELECT id FROM manufacturers WHERE slug=''holosun''), ''Holosun EPS CORE'', ''universal'', ''https://www.holosun.com/products/eps-core-rd-mrs'', ''verified''::fitment_confidence, ''Standard RMSc footprint (NOT Holosun K). Full-size EPS viewing lens in a compact RMSc body. Direct mount to any RMSc-cut slide.'', 1.4, ''Full size EPS window crammed into a standard RMSc body, giving you a bigger sight picture than any other RMSc enclosed optic without changing your slide cut. MRS and single dot variants available in red, green, and gold.'', ''{\"concealed-carry\"}''::text[], NULL, FALSE),
(''holosun-eps-carry'', ''optic''::product_category, (SELECT id FROM manufacturers WHERE slug=''holosun''), ''Holosun EPS Carry'', ''universal'', ''https://www.holosun.com/products/eps-carry-rd-mrs'', ''verified''::fitment_confidence, ''Holosun K footprint (modified RMSc). Direct fit on P365/XL/XMACRO factory cut. Includes RMSc-to-K adapter plate for RMSc slides. Ultra-low deck height.'', 1, ''The go to enclosed carry optic for micro compact pistols. It sits ultra low, weighs an ounce, and mounts directly to any Holosun K cut slide with MRS and Solar Failsafe on MRS variants. An RMSc adapter comes in the box for broader compatibility.'', ''{\"concealed-carry\"}''::text[], NULL, FALSE),
(''holosun-eps'', ''optic''::product_category, (SELECT id FROM manufacturers WHERE slug=''holosun''), ''Holosun EPS'', ''universal'', ''https://www.holosun.com/products/eps-rd-mrs'', ''verified''::fitment_confidence, ''Holosun K footprint (full-size EPS body). Includes RMR-to-K adapter plate. Larger window than EPS Carry. Best on RMR-cut full/compact slides via adapter.'', 1.41, ''Full size enclosed EPS with the largest window in the lineup at 0.91 x 0.63 inches, bringing all the EPS Carry''''s tech into a bigger package for compact and full size guns. Ships with an RMR adapter plate.'', ''{\"duty-competition\"}''::text[], NULL, FALSE),
(''holosun-507k-x2'', ''optic''::product_category, (SELECT id FROM manufacturers WHERE slug=''holosun''), ''Holosun 507K X2'', ''universal'', ''https://www.holosun.com/products/hs507k-x2'', ''verified''::fitment_confidence, ''Holosun K footprint. Open emitter. Direct fit on P365/XL/XMACRO factory cut. Lock Mode. Available in black, FDE, and blackout finishes.'', 1, ''The most popular micro carry optic on the market with MRS multi reticle, Shake Awake, and Lock Mode that mounts directly to any Holosun K cut slide. If someone asks what optic to put on their carry gun, this is usually the answer.'', ''{\"concealed-carry\"}''::text[], NULL, FALSE),
(''holosun-407k-x2'', ''optic''::product_category, (SELECT id FROM manufacturers WHERE slug=''holosun''), ''Holosun 407K X2'', ''universal'', ''https://www.holosun.com/products/hs407k-x2'', ''verified''::fitment_confidence, ''Holosun K footprint. Open emitter. Single 6 MOA dot — budget sibling of the 507K. Same body and fit. Direct P365/XL/XMACRO fit.'', 1, ''Same body and fit as the 507K at a lower price. You get a single 6 MOA dot instead of multi reticle, which is perfect if you know you want a big dot for fast target pickup and don''''t need the circle.'', ''{\"concealed-carry\"}''::text[], NULL, FALSE),
(''holosun-scs-carry-gr'', ''optic''::product_category, (SELECT id FROM manufacturers WHERE slug=''holosun''), ''Holosun SCS Carry GR'', ''universal'', ''https://www.holosun.com/products/scs-carry-gr'', ''verified''::fitment_confidence, ''Holosun K footprint. Solar Charging Sight — internal rechargeable battery, no battery changes needed. Includes RMSc-to-K adapter plate. Designed for P365 platform.'', 1, ''Solar powered and enclosed with an internal battery that has a 20,000 hour reserve, and the solar panel keeps it topped off so it may never need charging. Green reticle only. Set it and forget it on any K footprint micro compact.'', ''{\"concealed-carry\"}''::text[], NULL, FALSE),
(''holosun-507-promax'', ''optic''::product_category, (SELECT id FROM manufacturers WHERE slug=''holosun''), ''Holosun 507 PROMAX'', ''universal'', ''https://www.holosun.com/products/hs507-promax-rd-prs'', ''verified''::fitment_confidence, ''RMR footprint. Open emitter. Enlarged competition window with forward-leaning sunshade. New for 2026 — shipping Q3.'', 1.7, ''The biggest window Holosun has ever put on a pistol optic at 1.18 x 0.98 inches, with a forward sunshade and the Performance Reticle System offering selectable 8, 20, and 32 MOA circles. Built for competition shooters who want every edge.'', ''{\"competition\"}''::text[], NULL, FALSE),
(''holosun-507c-x3'', ''optic''::product_category, (SELECT id FROM manufacturers WHERE slug=''holosun''), ''Holosun 507C X3'', ''universal'', ''https://www.holosun.com/products/hs507c-x3-rd'', ''verified''::fitment_confidence, ''RMR footprint. Open emitter. X3 generation — forward-facing light sensor, improved glass, recessed controls.'', 1.5, ''The new X3 generation puts the light sensor on the front where it reads brightness at your target, not behind you, so the dot brightness actually matches what you''''re looking at. Improved glass and 100,000 hour battery life make this the new standard.'', ''{\"duty-competition\"}''::text[], NULL, FALSE),
(''holosun-407c-x3'', ''optic''::product_category, (SELECT id FROM manufacturers WHERE slug=''holosun''), ''Holosun 407C X3'', ''universal'', ''https://www.holosun.com/products/hs407c-x3-rd'', ''verified''::fitment_confidence, ''RMR footprint. Open emitter. X3 generation. 2 MOA dot only — no MRS. Same body and X3 upgrades as 507C X3.'', 1.5, ''All the X3 upgrades including the forward light sensor, better glass, and 100,000 hour battery with a clean single 2 MOA dot. Great for shooters who want the latest tech without multi reticle complexity.'', ''{\"duty-competition\"}''::text[], NULL, FALSE),
(''holosun-407comp'', ''optic''::product_category, (SELECT id FROM manufacturers WHERE slug=''holosun''), ''Holosun 407COMP'', ''universal'', ''https://www.holosun.com/products/hs407comp-rd-6'', ''verified''::fitment_confidence, ''RMR footprint. Open emitter. Large 1.1x0.87 competition window. Same housing as 507COMP.'', 1.7, ''Oversized 1.1 x 0.87 inch competition window with a big 6 MOA dot, built for fast transitions where you need to find the dot instantly during rapid strings of fire. 100,000 hour battery and less expensive than the 507COMP.'', ''{\"competition\"}''::text[], NULL, FALSE),
(''holosun-507comp'', ''optic''::product_category, (SELECT id FROM manufacturers WHERE slug=''holosun''), ''Holosun 507COMP'', ''universal'', ''https://www.holosun.com/products/hs507comp-rd'', ''verified''::fitment_confidence, ''RMR footprint. Open emitter. Large 1.1x0.87 competition window. Same housing as 407COMP.'', 1.7, ''Same oversized competition window as the 407COMP, but with the Competition Reticle System offering a selectable 2 MOA dot with 8, 20, and 32 MOA circle options. The optic built specifically for action pistol competition.'', ''{\"competition\"}''::text[], NULL, FALSE),
(''holosun-508t-x2'', ''optic''::product_category, (SELECT id FROM manufacturers WHERE slug=''holosun''), ''Holosun 508T X2'', ''universal'', ''https://www.holosun.com/products/he508t-x2-rd'', ''verified''::fitment_confidence, ''RMR footprint. Open emitter. Grade 5 TITANIUM housing — stronger than aluminum. Same footprint/reticle as 507C X2 but in titanium.'', 2, ''Grade 5 titanium housing on the RMR footprint that is stronger than any aluminum optic in Holosun''''s lineup. If you''''re hard on gear or running a duty gun that takes impacts, the titanium body handles what aluminum can''''t.'', ''{\"duty\"}''::text[], NULL, FALSE),
(''holosun-507c-x2'', ''optic''::product_category, (SELECT id FROM manufacturers WHERE slug=''holosun''), ''Holosun 507C X2'', ''universal'', ''https://www.holosun.com/products/hs507c-x2'', ''verified''::fitment_confidence, ''RMR footprint. Open emitter. X2 generation — Lock Mode, redesigned buttons. Previous gen, still widely available.'', 1.5, ''The proven workhorse with MRS, Solar Failsafe, and Shake Awake on the RMR footprint at lower street prices than the newer X3. Still one of the best values in pistol optics and there''''s a reason it''''s everywhere.'', ''{\"duty-competition\"}''::text[], NULL, FALSE),
(''vortex-defender-xl'', ''optic''::product_category, (SELECT id FROM manufacturers WHERE slug=''vortex''), ''Vortex Defender XL'', ''universal'', ''https://vortexoptics.com/defender-xl+vx_optic_color-Black+reticle-5~MOA~Dot'', ''verified''::fitment_confidence, ''DeltaPoint Pro footprint. Open emitter. Oversized competition window. Top-loading CR2032.'', 1.25, ''Vortex''''s oversized competition window on the DPP footprint, available in 3, 5, and 8 MOA dots with Shake Awake and the VIP lifetime warranty behind it. A strong competition optic at a fair price.'', ''{\"competition\"}''::text[], NULL, FALSE),
(''vortex-defender-st'', ''optic''::product_category, (SELECT id FROM manufacturers WHERE slug=''vortex''), ''Vortex Defender ST'', ''universal'', ''https://vortexoptics.com/defender-st+reticle-3~MOA~Dot+vx_optic_color-Black'', ''verified''::fitment_confidence, ''DeltaPoint Pro footprint. Open emitter. Standard-size duty/carry optic.'', 1.1, ''A solid open emitter DPP footprint optic with Shake Awake and Vortex''''s unconditional lifetime warranty. If it ever breaks for any reason, they replace it. Dependable and well supported.'', ''{\"duty-competition\"}''::text[], NULL, FALSE),
(''vortex-defender-st-enclosed'', ''optic''::product_category, (SELECT id FROM manufacturers WHERE slug=''vortex''), ''Vortex Defender ST Enclosed'', ''universal'', ''https://vortexoptics.com/defender-st-enclosed-solar-micro-red-dot+reticle-Multi-Reticle+vx_optic_color-Black'', ''verified''::fitment_confidence, ''DeltaPoint Pro footprint. Enclosed emitter. Solar + CR2032. Fast-rack textured front face.'', 1.4, ''Enclosed emitter with Vortex''''s Solar Unit pushing battery life to 150,000 hours, plus a textured front face for slide racking. The VIP warranty makes this a low risk buy for anyone going enclosed on a DPP cut gun.'', ''{\"duty\"}''::text[], NULL, FALSE),
(''vortex-defender-ccw-enclosed'', ''optic''::product_category, (SELECT id FROM manufacturers WHERE slug=''vortex''), ''Vortex Defender CCW Enclosed'', ''universal'', ''https://vortexoptics.com/defender-ccw-enclosed-solar-micro-red-dot+reticle-Multi-Reticle+vx_optic_color-Black'', ''verified''::fitment_confidence, ''Shield RMSc footprint. Enclosed emitter. Solar + CR1632. Fits P365, G43X/48 MOS, Hellcat OSP. Ships with multiple screw kits.'', 1.1, ''Enclosed emitter micro optic on the RMSc footprint with solar and 125,000 hour battery life, plus Vortex''''s unconditional warranty. Available in dot only and multi reticle. A strong carry optic with the best warranty in the business.'', ''{\"concealed-carry\"}''::text[], NULL, FALSE),
(''vortex-defender-ccw'', ''optic''::product_category, (SELECT id FROM manufacturers WHERE slug=''vortex''), ''Vortex Defender CCW'', ''universal'', ''https://vortexoptics.com/defender-ccw-micro-red-dot+reticle-3~MOA~Dot+vx_optic_color-Black'', ''verified''::fitment_confidence, ''Shield RMSc footprint. Open emitter. Fits P365, G43X/48 MOS, Hellcat OSP. Top-load CR1632.'', 0.8, ''Lightweight open emitter RMSc micro dot at 0.8 oz. Budget friendly entry to the Defender line with Shake Awake and the VIP lifetime warranty. A smart first optic for a carry gun.'', ''{\"concealed-carry\"}''::text[], NULL, FALSE),
(''vortex-venom-enclosed'', ''optic''::product_category, (SELECT id FROM manufacturers WHERE slug=''vortex''), ''Vortex Venom Enclosed'', ''universal'', ''https://vortexoptics.com/venom-enclosed-micro-red-dot+reticle-3~MOA~Dot'', ''verified''::fitment_confidence, ''DeltaPoint Pro footprint. Enclosed emitter. Budget enclosed — no solar, no fast-rack texturing. CR2032.'', 1.2, ''An enclosed emitter DPP footprint optic at an entry level price. No solar, no fancy features, just sealed protection with Shake Awake. If you want enclosed emitter reliability without the premium, this gets you there.'', ''{\"range-duty\"}''::text[], NULL, FALSE),
(''leupold-deltapoint-pro'', ''optic''::product_category, (SELECT id FROM manufacturers WHERE slug=''leupold''), ''Leupold DeltaPoint Pro'', ''universal'', ''https://www.leupold.com/deltapoint-pro-red-dot'', ''verified''::fitment_confidence, ''DeltaPoint Pro footprint (the original — this optic defined the footprint). Open emitter. Top-load CR2032 — no re-zero on battery swap. Made in USA.'', 1.95, ''The optic that created the DPP footprint, made in Oregon with one of the widest windows in the category and a DiamondCoat lens that''''s hard to beat optically. Top loading battery preserves your zero every time you swap cells. Guaranteed for life.'', ''{\"duty-competition\"}''::text[], NULL, FALSE),
(''eotech-eflx-ce'', ''optic''::product_category, (SELECT id FROM manufacturers WHERE slug=''eotech''), ''EOTech EFLX CE'', ''universal'', ''https://www.eotechinc.com/products/eotech-eflxce-pistol-optic'', ''verified''::fitment_confidence, ''DeltaPoint Pro AND Shield RMSc footprint — fits both cuts. Enclosed emitter. Side-load CR2032. Integrated rear backup iron sight. Assembled in USA.'', 1.46, ''EOTech''''s first enclosed pistol optic that fits both DPP and RMSc cuts, running a 42 MOA ring pattern inspired by their holographic sights with an integrated backup rear sight. If you''''re an EOTech shooter, this brings the HWS experience to your pistol.'', ''{\"duty\"}''::text[], NULL, FALSE),
(''eotech-eflx'', ''optic''::product_category, (SELECT id FROM manufacturers WHERE slug=''eotech''), ''EOTech EFLX'', ''universal'', ''https://www.eotechinc.com/products/eflx-pistol-optic'', ''verified''::fitment_confidence, ''DeltaPoint Pro footprint ONLY (not RMSc — that''''s the CE model). Open emitter. Top-load CR2032. Square window shaped like the HWS.'', 1.4, ''Open emitter DPP footprint optic with that signature EOTech square window and 25,000 hour battery life, available in black and FDE. No shake awake on this one, so it stays on until you shut it off. Simple and effective.'', ''{\"duty-competition\"}''::text[], NULL, FALSE),
(''aimpoint-acro-p2'', ''optic''::product_category, (SELECT id FROM manufacturers WHERE slug=''aimpoint''), ''Aimpoint ACRO P-2'', ''universal'', ''https://aimpoint.us/acro-p-2-red-dot-reflex-sight-3-5-moa-200691/'', ''verified''::fitment_confidence, ''Aimpoint ACRO proprietary clamping footprint with recoil lug. Ships with integrated mount. Many aftermarket ACRO-cut slides available, or use ACRO-to-RMR adapter plate from C&H Precision / Forward Controls Design.'', 2.19, ''The optic that started the enclosed emitter movement. The ACRO P 2''''s rear glass design makes the emitter completely untouchable, and the clamping mount with recoil lug holds zero like nothing else. Submersible to 35 meters, made in Sweden. This is the duty standard.'', ''{\"duty\"}''::text[], NULL, FALSE);"}', 'optics_stage1_products', 'ag.gamboa94@gmail.com', NULL, NULL);
