INSERT INTO "supabase_migrations"."schema_migrations" ("version", "statements", "name", "created_by", "idempotency_key", "rollback") VALUES ('20260905054059', '{"
alter table public.partners
  add column awin_merchant_id text;

comment on column public.partners.awin_merchant_id is
  ''AWIN advertiser/merchant ID (awinmid param in AWIN cread.php links). Null for non-AWIN partners.'';

-- backfill from the known merchant IDs confirmed in affiliate_links
update public.partners set awin_merchant_id = ''46059'' where slug = ''awin-optics-planet'';
update public.partners set awin_merchant_id = ''90861'' where slug = ''awin-olight'';

-- one partner per AWIN merchant id
create unique index partners_awin_merchant_id_key
  on public.partners (awin_merchant_id)
  where awin_merchant_id is not null;

alter table public.partners
  add constraint partners_awin_merchant_id_numeric
  check (awin_merchant_id is null or awin_merchant_id ~ ''^[0-9]+$'');
"}', 'add_awin_merchant_id_to_partners', 'ag.gamboa94@gmail.com', NULL, NULL);
