INSERT INTO "supabase_migrations"."schema_migrations" ("version", "statements", "name", "created_by", "idempotency_key", "rollback") VALUES ('20260905063403', '{"INSERT INTO product_internal (product_id, internal_notes) VALUES
((SELECT id FROM products WHERE slug=''osight-se-mos''), ''glock-mos footprint not in shared ref optic_cuts yet — add when Glock category launches.''),
((SELECT id FROM products WHERE slug=''sig-sauer-romeo1pro''), ''romeo1pro footprint not in shared ref optic_cuts — add to footprint_ref. Shares DPP pattern on many slides but Sig notes it may not fit all DPP cuts due to recoil boss variance.''),
((SELECT id FROM products WHERE slug=''sig-sauer-romeo-x-sigloc-pro''), ''sig-loc-pro footprint added to footprint_ref. Not in shared ref optic_cuts — add when SIG-LOC slides enter the DB.''),
((SELECT id FROM products WHERE slug=''sig-sauer-romeo-x-sigloc-compact''), ''sig-loc-compact footprint added to footprint_ref.''),
((SELECT id FROM products WHERE slug=''sig-sauer-romeo-m17''), ''sig-loc-mhs footprint added to footprint_ref. M17/M18 military pistols only — will NOT work on commercial P320.''),
((SELECT id FROM products WHERE slug=''holosun-eps-core''), ''Consolidated from eps-core-rd-mrs, eps-core-rd-3, eps-core-gr-mrs. Reticle/color differences are variant-level.''),
((SELECT id FROM products WHERE slug=''holosun-eps-carry''), ''Consolidated from eps-carry-rd-mrs. Reticle/color handled at variant level. FDE housing available on MRS variants.''),
((SELECT id FROM products WHERE slug=''holosun-eps''), ''Consolidated from eps-rd-mrs. Reticle/color handled at variant level.''),
((SELECT id FROM products WHERE slug=''holosun-507k-x2''), ''Split from k-series consolidation per user request — flagship product deserves its own row.''),
((SELECT id FROM products WHERE slug=''holosun-407k-x2''), ''Split from k-series consolidation per user request — flagship product deserves its own row.''),
((SELECT id FROM products WHERE slug=''holosun-scs-carry-gr''), ''GREEN reticle only — no red variant in SCS Carry line.''),
((SELECT id FROM products WHERE slug=''leupold-deltapoint-pro''), ''Consolidated standard + NV models into one optic row. NV variant adds 2 night vision brightness settings and customizable top-end. MSRP $449–$519.'');"}', 'optics_stage6_product_internal', 'ag.gamboa94@gmail.com', NULL, NULL);
INSERT INTO "supabase_migrations"."schema_migrations" ("version", "statements", "name", "created_by", "idempotency_key", "rollback") VALUES ('20260907045038', '{"INSERT INTO variant_images (variant_id, url, position, alt_text)
SELECT id, primary_image_url, 1, NULL
FROM product_variants
WHERE primary_image_url IS NOT NULL
  AND TRIM(primary_image_url) <> '''';"}', 'backfill_variant_images_from_primary_image_url', 'ag.gamboa94@gmail.com', NULL, NULL);
INSERT INTO "supabase_migrations"."schema_migrations" ("version", "statements", "name", "created_by", "idempotency_key", "rollback") VALUES ('20260907045652', '{"INSERT INTO product_platforms (product_id, platform_id)
SELECT p.id, (SELECT id FROM platforms WHERE slug = ''p365'')
FROM products p
WHERE p.category = ''optic'';"}', 'link_optics_to_p365_platform', 'ag.gamboa94@gmail.com', NULL, NULL);
INSERT INTO "supabase_migrations"."schema_migrations" ("version", "statements", "name", "created_by", "idempotency_key", "rollback") VALUES ('20260907183616', '{"-- Step 1: Fix 2 mis-routed comp SKUs (comp guns already exist, platform_skus was pointing to non-comp base)
UPDATE platform_skus SET gun_id = ''52ce73b1-af25-4445-bb20-5cfb684bd397''
  WHERE gun_db_platform_id = ''sig-p365-fuse-comp'';

UPDATE platform_skus SET gun_id = ''5bbca04c-d997-41c0-bb9c-be80ec7febbf''
  WHERE gun_db_platform_id = ''sig-p365-xmacro-comp'';

-- Step 2: Insert 3 new gun rows for previously-missing sub-models
INSERT INTO guns (slug, name, housing_class, frame_material, slide_length_in, barrel_length_in, oem_capacity, integrated_comp, platform_id, notes) VALUES
  (''p365-xl-rose-comp'', ''P365 XL Rose Comp'', ''p365xl'', ''polymer'', 3.7, 3.1, ''12+1'', TRUE,
    (SELECT id FROM platforms WHERE slug=''p365''),
    ''Integrally compensated slide (internal porting). Same OAL as base XL. Verified from Sig Sauer spec sheet.''),
  (''p365-xf-dh3'', ''P365 XF DH3'', ''xmacro'', ''polymer'', 4.3, 3.7, ''17+1'', TRUE,
    (SELECT id FROM platforms WHERE slug=''p365''),
    ''DH3 barrel + slide-integrated expansion chamber. Coyote polymer XMACRO grip. Same slide/barrel as p365-fuse-comp but XMACRO grip housing.''),
  (''p365-xf-dh3-axg'', ''P365 XF DH3 AXG'', ''xmacro'', ''alloy'', 4.3, 3.7, ''17+1'', TRUE,
    (SELECT id FROM platforms WHERE slug=''p365''),
    ''DH3 barrel + AXG aluminum grip. Same barrel/comp as p365-xf-dh3.'');

-- Step 3: Point the 3 marketing SKUs at their newly-created gun rows
UPDATE platform_skus SET gun_id = (SELECT id FROM guns WHERE slug=''p365-xl-rose-comp'')
  WHERE gun_db_platform_id = ''sig-p365-xl-rose-comp'';

UPDATE platform_skus SET gun_id = (SELECT id FROM guns WHERE slug=''p365-xf-dh3'')
  WHERE gun_db_platform_id = ''sig-p365-xf-dh3'';

UPDATE platform_skus SET gun_id = (SELECT id FROM guns WHERE slug=''p365-xf-dh3-axg'')
  WHERE gun_db_platform_id = ''sig-p365-xf-dh3-axg'';"}', 'split_p365_comp_variants_into_own_gun_classes', 'ag.gamboa94@gmail.com', NULL, NULL);
INSERT INTO "supabase_migrations"."schema_migrations" ("version", "statements", "name", "created_by", "idempotency_key", "rollback") VALUES ('20260907184914', '{"UPDATE guns SET barrel_length_in = 3.1
WHERE slug = ''p365-xmacro-comp'';"}', 'fix_xmacro_comp_barrel_length', 'ag.gamboa94@gmail.com', NULL, NULL);
INSERT INTO "supabase_migrations"."schema_migrations" ("version", "statements", "name", "created_by", "idempotency_key", "rollback") VALUES ('20260907221309', '{"UPDATE products SET name = ''P.ID'', url = ''https://www.holosun.com/products/p-id'', description = ''Holosun''''s flagship weapon light, pushing 1,000 lumens and 23,000 candela from a fully submersible IPX8 housing. The rechargeable 18350 cell charges magnetically, and the interchangeable rail key system lets one light body move between 1913 and proprietary rails as your setup changes.'', material = ''Aluminum'', weight_oz = 5, best_for = ''{\"Duty\",\"Multi-Platform\",\"Home Defense\"}''::text[], fitment_confidence = ''verified'', is_discontinued = FALSE, updated_at = now() WHERE slug = ''holosun-p-id'';
UPDATE products SET name = ''P.ID HC'', url = ''https://www.holosun.com/products/p-id-hc'', description = ''Purpose-built for distance identification, the high-candela P.ID throws 42,000 candela where the standard model tops out at 23,000, nearly doubling effective reach. It shares the same IPX8 submersible, magnetically-charged rechargeable platform, so shooters who need throw over flood get it without switching ecosystems.'', material = ''Aluminum'', weight_oz = 5, best_for = ''{\"Long Range ID\",\"Duty\"}''::text[], fitment_confidence = ''verified'', is_discontinued = FALSE, updated_at = now() WHERE slug = ''holosun-p-id-hc'';
UPDATE products SET name = ''P.ID-K'', url = ''https://www.holosun.com/products/p-id-k'', description = ''Holosun''''s smallest P.ID offering, engineered to fit TLR-7 holsters while still delivering 500 lumens on USB-C rechargeable power. This is the light for shooters who refuse to give up rechargeability but need the footprint small enough for a true subcompact carry setup.'', material = ''Aluminum'', weight_oz = 3.2, best_for = ''{\"Concealed Carry\"}''::text[], fitment_confidence = ''verified'', is_discontinued = FALSE, updated_at = now() WHERE slug = ''holosun-p-id-k'';
UPDATE products SET name = ''P.ID-K Plus'', url = ''https://www.opticsplanet.com/holosun-p-id-k-positive-identification-1000-lumens-led-weapon-light-w-laser.html'', description = ''Packs a green laser alongside 1,000 lumens in the same compact, TLR-7-holster-compatible body as the P.ID-K. The laser gives shooters a visible point-of-aim reference for fast target acquisition in low light, paired with enough flood to positively identify what they are aiming at.'', material = ''Aluminum'', weight_oz = 3.6, best_for = ''{\"Concealed Carry\",\"Low Light Aiming\"}''::text[], fitment_confidence = ''verified'', is_discontinued = FALSE, updated_at = now() WHERE slug = ''holosun-p-id-k-plus'';
UPDATE products SET name = ''P.ID Plus'', url = ''https://www.holosun.com/products/p-id-plus'', description = ''Combines a green laser with the P.ID platform''''s 900 lumens and 20,000 candela in one rechargeable unit. The laser provides a faster aiming reference than sights alone under stress, while the white light handles positive target identification, giving shooters both capabilities from a single rail-mounted package.'', material = ''Aluminum'', weight_oz = 5.1, best_for = ''{\"Duty\",\"Low Light Aiming\"}''::text[], fitment_confidence = ''verified'', is_discontinued = FALSE, updated_at = now() WHERE slug = ''holosun-p-id-plus'';
UPDATE products SET name = ''P.ID Dual'', url = ''https://www.holosun.com/products/p-id-dual'', description = ''The only light in this entire catalog that pairs white illumination with both a visible green laser and an infrared laser in one housing. The green laser handles standard low-light aiming, and the IR laser extends that capability to shooters operating under night vision, all without choosing one role over the other.'', material = ''Aluminum'', weight_oz = 5.1, best_for = ''{\"Night Vision\",\"Low Light Aiming\"}''::text[], fitment_confidence = ''verified'', is_discontinued = FALSE, updated_at = now() WHERE slug = ''holosun-p-id-dual'';
UPDATE products SET name = ''Baldr Mini'', url = ''https://www.olight.com/store/baldr-mini-baldr-rlmini-bk-tactical-light'', description = ''One of the smallest laser/light combos on the market, pairing a green laser with 600 lumens in a body built around Olight''''s sliding rail mount. The combo gives shooters fast laser-aided aiming and positive target identification from a footprint small enough to sit on a subcompact without overhang.'', material = ''Aluminum'', weight_oz = 3.07, best_for = ''{\"Concealed Carry\",\"Low Light Aiming\"}''::text[], fitment_confidence = ''verified'', is_discontinued = FALSE, updated_at = now() WHERE slug = ''olight-baldr-mini'';
UPDATE products SET name = ''Baldr Pro R'', url = ''https://www.olight.com/store/baldr-pro-r-rechargeable-light'', description = ''A full-size rechargeable laser/light combo pushing 1,350 lumens alongside a green laser, with a physical mode-selector ring for switching between light only, laser only, and combined output. The ring is the differentiator here: tactile, deliberate mode selection under stress rather than memorizing click patterns.'', material = ''Aluminum'', weight_oz = 4.44, best_for = ''{\"Duty\",\"Low Light Aiming\",\"Home Defense\"}''::text[], fitment_confidence = ''verified'', is_discontinued = FALSE, updated_at = now() WHERE slug = ''olight-baldr-pro-r'';
UPDATE products SET name = ''Baldr S'', url = ''https://www.olight.com/store/baldr-s'', description = ''Sits between the Mini and Pro R in both size and output, pairing a green laser with white light and adding strobe for shooters who want fast aiming and target identification in a mid-size body without committing to the Pro R''''s full-size footprint.'', material = ''Aluminum'', weight_oz = 3.35, best_for = ''{\"Concealed Carry\",\"Low Light Aiming\"}''::text[], fitment_confidence = ''verified'', is_discontinued = FALSE, updated_at = now() WHERE slug = ''olight-baldr-s'';
UPDATE products SET name = ''PL-3R Valkyrie'', url = ''https://www.olight.com/store/pl-3r-valkyrie-rail-mounted-tactical-light?srsltid=AfmBOooXPtqZBoe0rD3R3ISk4y1wq01Rnnk1F5gllrPt0FHmPIN5yQO0'', description = ''Olight''''s full-size, light-only rechargeable option, pushing 1,500 lumens through swappable rail keys covering both 1913 and Glock-style rails. Charges via magnetic USB, and for shooters who want high output without a laser, this is the cleanest option in the PL lineup.'', material = ''Aluminum'', weight_oz = 3.77, best_for = ''{\"Duty\",\"Home Defense\",\"Multi-Platform\"}''::text[], fitment_confidence = ''verified'', is_discontinued = FALSE, updated_at = now() WHERE slug = ''olight-pl-3r-valkyrie'';
UPDATE products SET name = ''PL-Mini 2 Valkyrie'', url = ''https://www.olight.com/store/pl-mini-2-valkyrie-tactical-light'', description = ''A compact rechargeable light with an adjustable sliding rail, trading the PL-3R''''s raw output for a body that nearly disappears on a subcompact frame. Built for shooters who prioritize a small, light package over peak lumens.'', material = ''Aluminum'', weight_oz = 2.57, best_for = ''{\"Concealed Carry\"}''::text[], fitment_confidence = ''verified'', is_discontinued = FALSE, updated_at = now() WHERE slug = ''olight-pl-mini-2-valkyrie'';
UPDATE products SET name = ''PL-Mini 3 Valkyrie'', url = ''https://illumn.com/olight-pl-mini-3-valkyrie-rechargeable-compact-weapon-light.html?srsltid=AfmBOooeznPcQV-3IVpg-3cC-ZLXIRoE7P6mj4NAKbHVgkn7FfBLNnUQ'', description = ''The updated Mini ships with keys for multiple rail standards out of the box, with additional platform-specific rail adapters available separately. Broader out-of-box compatibility than the Mini 2 without increasing the footprint.'', material = ''Aluminum'', weight_oz = 2.4, best_for = ''{\"Concealed Carry\",\"Multi-Platform\"}''::text[], fitment_confidence = ''verified'', is_discontinued = FALSE, updated_at = now() WHERE slug = ''olight-pl-mini-3-valkyrie'';
UPDATE products SET name = ''PL-Pro Valkyrie'', url = ''https://illumn.com/flashlights/olight/pl-series-weapon-lights/olight-pl-pro-valkyrie-rechargeable-compact-weapon-light-black.html'', description = ''Uses screw-on swappable adapters for GL and 1913 rails rather than a sliding key system, delivering Olight''''s highest-output PL model with a more permanent, wobble-free mount than the tool-less key designs on the rest of the line.'', material = ''Aluminum'', weight_oz = 3.25, best_for = ''{\"Duty\",\"Home Defense\"}''::text[], fitment_confidence = ''verified'', is_discontinued = FALSE, updated_at = now() WHERE slug = ''olight-pl-pro-valkyrie'';
UPDATE products SET name = ''PL Turbo Valkyrie'', url = ''https://illumn.com/olight-pl-turbo-tactical-weapon-light.html'', description = ''Engineered for throw rather than flood, the PL Turbo pushes 66,300 candela on CR123A power, the highest throw figure in Olight''''s entire PL lineup. Built for shooters who need to identify targets at distance, not light up a room.'', material = ''Aluminum'', weight_oz = 4.48, best_for = ''{\"Long Range ID\",\"Duty\"}''::text[], fitment_confidence = ''verified'', is_discontinued = FALSE, updated_at = now() WHERE slug = ''olight-pl-turbo-valkyrie'';
UPDATE products SET name = ''PL-X Dual Beam'', url = ''https://www.olight.com/store/pl-x-dual-beam-rail-weapon-light'', description = ''Combines a dedicated flood emitter and a dedicated spot emitter in one rechargeable body with reversible mounting lugs. Shooters get close-range peripheral illumination and longer-range target identification simultaneously rather than choosing one beam pattern over the other.'', material = ''Aluminum'', weight_oz = 3.07, best_for = ''{\"Duty\",\"Home Defense\"}''::text[], fitment_confidence = ''verified'', is_discontinued = FALSE, updated_at = now() WHERE slug = ''olight-pl-x-dual-beam'';
UPDATE products SET name = ''FOXTROT1X'', url = ''https://www.sigsauer.com/foxtrot1x-weapon-mounted-white-light-450-lumen-rail-mount-black.html'', description = ''A compact rail light shipping with multiple interface plates in the box, running on a front-loading CR123A battery for straightforward compatibility across several rail standards without needing adapters or aftermarket keys.'', material = ''Aluminum'', best_for = ''{\"Concealed Carry\",\"Budget Pick\"}''::text[], fitment_confidence = ''verified'', is_discontinued = FALSE, updated_at = now() WHERE slug = ''sig-sauer-foxtrot1x'';
UPDATE products SET name = ''FOXTROT2R'', url = ''https://www.sigsauer.com/foxtrot2r-weapon-mounted-white-light-700-lumen-rail-mount-black.html'', description = ''Steps up from the FOXTROT1X with rechargeable power, 700 lumens, and two 4-position sliding rail inserts covering both standard and non-standard pistol rails. The rechargeable cell and higher output make this the logical next step for shooters who outgrow the CR123A-only FOXTROT1X.'', material = ''Aluminum'', best_for = ''{\"Concealed Carry\",\"Multi-Platform\"}''::text[], fitment_confidence = ''verified'', is_discontinued = FALSE, updated_at = now() WHERE slug = ''sig-sauer-foxtrot2r'';
UPDATE products SET name = ''TLR-1 HL'', url = ''https://www.streamlight.com/products/detail/tlr-1-hl'', description = ''The industry-standard full-size duty light with 1,000 lumens and an ambidextrous rotating clamp with swappable rail keys. Found on more law enforcement pistols than arguably any other model, built for full-size duty frames.'', material = ''Aluminum'', weight_oz = 4.32, best_for = ''{\"Duty\",\"Home Defense\"}''::text[], build_warning = ''Full-size TLR-1 — does NOT fit the P365. Cross-platform catalog entry.'', fitment_confidence = ''verified'', is_discontinued = FALSE, updated_at = now() WHERE slug = ''streamlight-tlr-1-hl'';
