UPDATE products SET name = ''TLR-7 HL-X Sub USB'', url = ''https://www.streamlight.com/products/detail/tlr-7-hl-x-sub'', description = ''Built around a dedicated, non-interchangeable rail clamp rather than a universal key system. Each variant ships fitted to one specific rail profile, so the light mounts tighter and sits lower than a keyed design, but buyers need to match the clamp to their rail standard at time of purchase.'', material = ''Aluminum'', weight_oz = 2.49, best_for = ''{\"Concealed Carry\"}''::text[], build_warning = ''Clamp is gun-specific: pick the variant matching your rail. Sig-365 clamp does NOT fit the XMACRO (use a 1913-short light).'', fitment_confidence = ''verified'', is_discontinued = FALSE, updated_at = now() WHERE slug = ''streamlight-tlr-7-hl-x-sub-usb'';
