UPDATE products SET name = ''TLR-7 X Contour Remote'', url = ''https://www.streamlight.com/products/detail/tlr-7-x-sub'', description = ''Integrates a contour remote pressure switch directly into the light body, fundamentally changing how the shooter activates the light. This is not an accessory bolted onto a standard TLR-7 X; it is a different product with a different profile and potentially different holster fit.'', material = ''Aluminum'', weight_oz = 2.85, best_for = ''{\"Duty\",\"Concealed Carry\"}''::text[], build_warning = ''Clamp is gun-specific: pick the variant matching your rail. sig-365 clamp does NOT fit the XMACRO.'', fitment_confidence = ''verified'', is_discontinued = FALSE, updated_at = now() WHERE slug = ''streamlight-tlr-7-x-contour-remote'';
UPDATE products SET name = ''TLR-7 X Sub USB'', url = ''https://www.streamlight.com/products/detail/tlr-7-x-sub'', description = ''The USB rechargeable version of the dedicated-clamp TLR-7 X Sub. Same mounting approach: each variant is factory-fitted to one rail profile, so buyers must match the clamp to their rail standard when ordering since it cannot be changed after purchase.'', material = ''Aluminum'', weight_oz = 2.64, best_for = ''{\"Concealed Carry\"}''::text[], build_warning = ''Clamp is gun-specific: pick the variant matching your rail. sig-365 clamp does NOT fit the XMACRO.'', fitment_confidence = ''verified'', is_discontinued = FALSE, updated_at = now() WHERE slug = ''streamlight-tlr-7-x-sub-usb'';
UPDATE products SET name = ''X300T-A (Turbo)'', url = ''https://www.surefire.com/x300t-weaponlight/?sku=X300T-A'', description = ''SureFire''''s long-throw specialist, trading raw lumens for 66,000 candela to identify targets at distances where a standard flood light falls off. The lever-latch mount ships with both universal and 1913 latch options.'', material = ''Aluminum'', weight_oz = 4.4, best_for = ''{\"Long Range ID\",\"Duty\"}''::text[], fitment_confidence = ''verified'', is_discontinued = FALSE, updated_at = now() WHERE slug = ''surefire-x300t-a-turbo'';
UPDATE products SET name = ''X300U-A'', url = ''https://www.surefire.com/x300u-a-weaponlight/'', description = ''The standard-bearer of full-size weapon lights, putting out 1,000 lumens through SureFire''''s proven lever-latch mount. Trusted across military and law enforcement, this is the light the rest of the market benchmarks against.'', material = ''Aluminum'', weight_oz = 4, best_for = ''{\"Duty\",\"Home Defense\"}''::text[], fitment_confidence = ''verified'', is_discontinued = FALSE, updated_at = now() WHERE slug = ''surefire-x300u-a'';
UPDATE products SET name = ''X300U-B'', url = ''https://www.surefire.com/x300u-b-weaponlight/'', description = ''Identical 1,000-lumen output to the X300U-A, mounted via a T-slot screw instead of a lever latch. Built for shooters who want a semi-permanent, tool-installed mount that eliminates any possibility of the light walking off the rail under recoil.'', material = ''Aluminum'', weight_oz = 4.1, best_for = ''{\"Duty\",\"Home Defense\"}''::text[], fitment_confidence = ''verified'', is_discontinued = FALSE, updated_at = now() WHERE slug = ''surefire-x300u-b'';
UPDATE products SET name = ''XC3 (XC3-A)'', url = ''https://www.surefire.com/xc3-weaponlight/'', description = ''SureFire''''s compact carry light, sized down from the full X300 line with a two-crossmember clamp covering both universal and 1913 rails. Brings SureFire build quality to smaller duty and carry guns without the X300''''s full-size overhang.'', material = ''Aluminum'', weight_oz = 2.65, best_for = ''{\"Concealed Carry\"}''::text[], fitment_confidence = ''verified'', is_discontinued = FALSE, updated_at = now() WHERE slug = ''surefire-xc3'';
UPDATE products SET name = ''XC3 Sub'', url = ''https://www.surefire.com/xc3-sub-weaponlight/'', description = ''Ships as one SKU with swappable clamps covering multiple subcompact platforms and short 1913 rails. A single light body that follows a shooter across several different guns rather than locking into one, which is rare at this size and performance level.'', material = ''Aluminum'', weight_oz = 2.65, best_for = ''{\"Concealed Carry\",\"Multi-Platform\"}''::text[], build_warning = ''Clamp is gun-specific: pick the variant matching your rail. sig-365 clamp does NOT fit the XMACRO.'', fitment_confidence = ''verified'', is_discontinued = FALSE, updated_at = now() WHERE slug = ''surefire-xc3-sub'';"}', 'lights_stage1_update_products', 'ag.gamboa94@gmail.com', NULL, NULL);
INSERT INTO "supabase_migrations"."schema_migrations" ("version", "statements", "name", "created_by", "idempotency_key", "rollback") VALUES ('20260909050837', '{"-- Per-user favorites for the parts catalog. Rows are strictly private:
-- users can read/write their own, no public SELECT. FK cascades on user
-- deletion and product removal so we never leak orphaned favorites.
CREATE TABLE public.part_favorites (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
  product_id uuid NOT NULL REFERENCES public.products(id) ON DELETE CASCADE,
  created_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE (user_id, product_id)
);

-- Fast per-user fetch on page load.
CREATE INDEX part_favorites_user_id_idx ON public.part_favorites(user_id);

ALTER TABLE public.part_favorites ENABLE ROW LEVEL SECURITY;

-- Three narrow policies — no policy for anon = anon reads/writes nothing.
CREATE POLICY \"Users read their own part favorites\"
  ON public.part_favorites FOR SELECT
  TO authenticated
  USING (auth.uid() = user_id);

CREATE POLICY \"Users insert their own part favorites\"
  ON public.part_favorites FOR INSERT
  TO authenticated
  WITH CHECK (auth.uid() = user_id);

CREATE POLICY \"Users delete their own part favorites\"
  ON public.part_favorites FOR DELETE
  TO authenticated
  USING (auth.uid() = user_id);"}', 'create_part_favorites_with_rls', 'ag.gamboa94@gmail.com', NULL, NULL);
INSERT INTO "supabase_migrations"."schema_migrations" ("version", "statements", "name", "created_by", "idempotency_key", "rollback") VALUES ('20260909052237', '{"CREATE TABLE public.guides (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  title text NOT NULL,
  category text NOT NULL CHECK (category IN (''home_defense'',''concealed_carry'',''range_competition'',''duty'')),
  platform_id uuid NOT NULL REFERENCES public.platforms(id) ON DELETE RESTRICT,
  description text,
  hero_image_path text,
  parts_snapshot jsonb NOT NULL DEFAULT ''[]''::jsonb,
  created_at timestamptz NOT NULL DEFAULT now(),
  is_published boolean NOT NULL DEFAULT false
);

CREATE INDEX guides_category_idx ON public.guides(category) WHERE is_published;

ALTER TABLE public.guides ENABLE ROW LEVEL SECURITY;

CREATE POLICY \"Public reads published guides\"
  ON public.guides FOR SELECT
  USING (is_published = true);

-- No public INSERT/UPDATE/DELETE — service_role bypasses RLS and is the
-- only writer. Guides are staff-authored editorial content.

WITH plat AS (SELECT id FROM public.platforms WHERE slug=''p365''),
prods AS (
  SELECT p.id, p.category::text AS category, p.name,
         (SELECT name FROM public.manufacturers WHERE id = p.brand_id) AS brand
  FROM public.products p
  JOIN public.product_platforms pp ON pp.product_id = p.id
  WHERE pp.platform_id = (SELECT id FROM plat)
    AND p.id IN (
      ''8c231107-016f-4d2d-bf01-5c3446870677''::uuid,  -- Grey Ghost slide
      ''42db8c43-065a-4a68-8a3b-620763b35900''::uuid,  -- Norsso barrel
      ''cc991e84-7493-5125-ab4e-4b8626c7c25b''::uuid,  -- MCarbo trigger
      ''36341a83-9ebc-4936-9e36-0c2be6657b2a''::uuid,  -- Armory Craft compensator
      ''7455e0f8-b900-4bd4-94eb-e9b08dee9f5b''::uuid,  -- Aimpoint ACRO
      ''d35124c2-1969-5bb2-9c9d-c31647796852''::uuid,  -- Olight Baldr Mini
      ''0a01bfb4-d057-58f0-9706-cf78df89a1bb''::uuid,  -- Align Tactical mag release
      ''90305239-5a83-5f86-aac0-9e3918f7385f''::uuid   -- Herrington Arms magwell
    )
)
INSERT INTO public.guides (title, category, platform_id, description, parts_snapshot, is_published)
SELECT
  g.title, g.category, (SELECT id FROM plat), g.description,
  (SELECT jsonb_agg(jsonb_build_object(
     ''category'', prods.category, ''refId'', prods.id,
     ''brand'', prods.brand, ''name'', prods.name, ''pending'', false
   ))
   FROM prods WHERE prods.category = ANY(g.pick_cats)),
  true
FROM (VALUES
  (''Sig P365 Concealed Carry'', ''concealed_carry'',
   ''A minimalist P365 optimized for daily carry — small footprint, snag-free profile, red dot for fast target acquisition.'',
   ARRAY[''slide'',''barrel'',''trigger'',''optic'']),
  (''Sig P365 Home Defense'', ''home_defense'',
   ''A P365 configured for low-light home defense. Added weapon light and optic for target ID and precision in stressful conditions.'',
   ARRAY[''slide'',''barrel'',''trigger'',''optic'',''light'']),
  (''Sig P365 Range / Competition'', ''range_competition'',
   ''A range-optimized P365 with compensator, magwell, and match trigger for fast splits and reliable reloads on the clock.'',
   ARRAY[''slide'',''barrel'',''compensator'',''trigger'',''optic'',''magwell'']),
  (''Sig P365 Duty'', ''duty'',
   ''A P365 built for duty carry. Extended magazine release and durable slide for high-volume training and reliable operation under pressure.'',
   ARRAY[''slide'',''barrel'',''trigger'',''mag_release''])
) AS g(title, category, description, pick_cats);"}', 'create_guides_with_rls_and_seed', 'ag.gamboa94@gmail.com', NULL, NULL);
INSERT INTO "supabase_migrations"."schema_migrations" ("version", "statements", "name", "created_by", "idempotency_key", "rollback") VALUES ('20260909055611', '{"-- Category-varying key-value attributes. Nullable; kept as jsonb rather than
-- a normalized attribute-value table because the attribute set differs by
-- category and normalization would only hurt readability without giving us
-- anything at this scale.
ALTER TABLE public.products ADD COLUMN specs jsonb;

-- Seed specs across ~30 well-known products. Only attributes derivable from
-- the product name / well-known brand conventions are set; where a value
-- would be a guess, the key is omitted (or specs stays null for the product).

-- ─── Optics ───
UPDATE public.products SET specs = ''{\"footprint\":\"RMR\",\"dot_size_moa\":2,\"emitter\":\"open\",\"battery\":\"CR1632\"}''::jsonb
  WHERE id = ''2e1dfa1b-2705-4b1b-824f-92d775fa015d''; -- Holosun 507C X2
UPDATE public.products SET specs = ''{\"footprint\":\"RMR\",\"dot_size_moa\":2,\"emitter\":\"open\",\"battery\":\"CR1632\"}''::jsonb
  WHERE id = ''72289c20-68a1-4b12-956b-ac91270cfb25''; -- Holosun 507C X3
UPDATE public.products SET specs = ''{\"footprint\":\"RMSc\",\"dot_size_moa\":2,\"emitter\":\"open\",\"battery\":\"CR1632\"}''::jsonb
  WHERE id = ''58565b4c-2f76-42b1-bed0-04898e1c0e30''; -- Holosun 507K X2
UPDATE public.products SET specs = ''{\"footprint\":\"RMSc\",\"dot_size_moa\":6,\"emitter\":\"open\",\"battery\":\"CR1632\"}''::jsonb
  WHERE id = ''b510c062-e80d-4a12-a839-19a904392c8a''; -- Holosun 407K X2
UPDATE public.products SET specs = ''{\"footprint\":\"EPS Carry\",\"dot_size_moa\":2,\"emitter\":\"enclosed\",\"battery\":\"CR1620\"}''::jsonb
  WHERE id = ''361a34ea-6685-4945-89fd-e1404587f4e6''; -- Holosun EPS Carry
UPDATE public.products SET specs = ''{\"footprint\":\"ACRO\",\"dot_size_moa\":3.5,\"emitter\":\"enclosed\",\"battery\":\"CR2032\"}''::jsonb
  WHERE id = ''7455e0f8-b900-4bd4-94eb-e9b08dee9f5b''; -- Aimpoint ACRO P-2
UPDATE public.products SET specs = ''{\"footprint\":\"RMSc\",\"dot_size_moa\":3,\"emitter\":\"open\",\"battery\":\"CR2032\"}''::jsonb
  WHERE id = ''85ffcf29-fa0a-4aa2-94fb-7e51dc6311e5''; -- Vortex Defender CCW
UPDATE public.products SET specs = ''{\"footprint\":\"RMSc\",\"dot_size_moa\":3,\"emitter\":\"enclosed\",\"battery\":\"CR2032\"}''::jsonb
  WHERE id = ''86963873-14f1-4371-8f6c-f9ce80fb1e42''; -- Vortex Defender CCW Enclosed
UPDATE public.products SET specs = ''{\"footprint\":\"RMR\",\"dot_size_moa\":3,\"emitter\":\"enclosed\",\"battery\":\"CR2032\"}''::jsonb
  WHERE id = ''0b4b3152-f0f2-4c19-ba45-9f861944bde1''; -- Vortex Venom Enclosed

-- ─── Slides ───
UPDATE public.products SET specs = ''{\"optic_cut\":\"RMSc\",\"material\":\"stainless steel\",\"finish\":\"DLC black\",\"window_cuts\":true}''::jsonb
  WHERE id = ''8c231107-016f-4d2d-bf01-5c3446870677''; -- Grey Ghost GGP365 V1
UPDATE public.products SET specs = ''{\"optic_cut\":\"RMSc\",\"material\":\"stainless steel\",\"finish\":\"DLC black\",\"window_cuts\":true}''::jsonb
  WHERE id = ''e580b237-2cd8-4997-9e1b-f0201fd68211''; -- Grey Ghost GGP365 V2
UPDATE public.products SET specs = ''{\"optic_cut\":\"RMSc\",\"material\":\"stainless steel\",\"finish\":\"DLC black\",\"window_cuts\":true}''::jsonb
  WHERE id = ''635fa806-3fc4-43f5-8722-db8f00e1f55a''; -- Killer Innovations Velocity V1 P365
UPDATE public.products SET specs = ''{\"optic_cut\":\"RMR\",\"material\":\"stainless steel\",\"finish\":\"DLC black\"}''::jsonb
  WHERE id = ''6608f4b9-40ce-42f3-938a-f68071f503f3''; -- Zaffiri ZPS.2 P365XL
UPDATE public.products SET specs = ''{\"optic_cut\":\"RMR\",\"material\":\"stainless steel\",\"finish\":\"DLC black\",\"ported\":true}''::jsonb
  WHERE id = ''50a9d099-2061-4740-9ddf-27b6cfff4dc9''; -- Zaffiri ZPS.P Ported P365XL
UPDATE public.products SET specs = ''{\"optic_cut\":\"RMSc\",\"material\":\"stainless steel\"}''::jsonb
  WHERE id = ''dfc75d0f-d103-44ae-ba2d-a8bf15e5e0f9''; -- True Precision Axiom P365

-- ─── Barrels ───
UPDATE public.products SET specs = ''{\"length_in\":3.1,\"threaded\":false,\"material\":\"stainless steel\",\"finish\":\"gold TiN\",\"ported\":true}''::jsonb
  WHERE id = ''42db8c43-065a-4a68-8a3b-620763b35900''; -- Norsso N365 3.1\" C Port
UPDATE public.products SET specs = ''{\"length_in\":4.3,\"threaded\":false,\"material\":\"stainless steel\",\"finish\":\"gold TiN\",\"ported\":true}''::jsonb
  WHERE id = ''970202a5-1a39-4d19-8062-d6abb454e449''; -- Norsso N365-FUSE 4.3\" C Port
UPDATE public.products SET specs = ''{\"length_in\":4.3,\"threaded\":false,\"material\":\"stainless steel\",\"finish\":\"gold TiN\",\"ported\":true}''::jsonb
  WHERE id = ''b355ce77-2c49-4a99-8527-e52ae255d2cb''; -- Norsso N365-FUSE 4.3\" E Port
UPDATE public.products SET specs = ''{\"length_in\":3.7,\"threaded\":false,\"material\":\"stainless steel\",\"finish\":\"gold TiN\",\"ported\":true}''::jsonb
  WHERE id = ''f47ea0b5-01fc-4b3a-9964-9a8f806745ca''; -- Norsso N365XL 3.7\" C Port
UPDATE public.products SET specs = ''{\"length_in\":3.1,\"threaded\":false,\"material\":\"stainless steel\"}''::jsonb
  WHERE id = ''377c1752-0a69-429b-b8f5-0a6d076b7b86''; -- Norsso P365 3.1\" LVL1.5 Standard
UPDATE public.products SET specs = ''{\"length_in\":3.1,\"threaded\":true,\"material\":\"stainless steel\"}''::jsonb
  WHERE id = ''05951ceb-f7da-4cfe-90dd-24bbab20fce2''; -- Norsso P365 3.1\" LVL1.5 Threaded
UPDATE public.products SET specs = ''{\"length_in\":3.1,\"threaded\":false,\"material\":\"stainless steel\"}''::jsonb
  WHERE id = ''4a17dd31-7094-4377-8563-8c15700a6370''; -- True Precision P365 3.1\" Non-Threaded
UPDATE public.products SET specs = ''{\"length_in\":3.1,\"threaded\":true,\"material\":\"stainless steel\"}''::jsonb
  WHERE id = ''d99c4043-87fe-449e-80e9-41f34439409b''; -- True Precision P365 3.1\" Threaded
UPDATE public.products SET specs = ''{\"length_in\":3.7,\"threaded\":false,\"material\":\"stainless steel\"}''::jsonb
  WHERE id = ''0657a453-c53a-4c93-81c1-ac04699269d1''; -- True Precision P365 3.7\" Non-Threaded

-- ─── Triggers ───
UPDATE public.products SET specs = ''{\"profile\":\"flat\",\"install\":\"drop-in\"}''::jsonb
  WHERE id = ''cc991e84-7493-5125-ab4e-4b8626c7c25b''; -- MCarbo Short Stroke Flat
UPDATE public.products SET specs = ''{\"profile\":\"curved\",\"install\":\"drop-in\"}''::jsonb
  WHERE id = ''2b160547-c1c8-5970-bdf7-16bfc7d986e0''; -- Sig Sauer Curved P365
UPDATE public.products SET specs = ''{\"profile\":\"flat\",\"install\":\"drop-in\"}''::jsonb
  WHERE id = ''6cfecc5c-080d-5021-99bb-cd0f48f73f0e''; -- Sig Sauer Flat OEM P365
UPDATE public.products SET specs = ''{\"profile\":\"flat\",\"install\":\"drop-in\"}''::jsonb
  WHERE id = ''6c97a18f-18a4-5377-99f1-42c4623a0d76''; -- True Precision Flat P365
UPDATE public.products SET specs = ''{\"profile\":\"flat\",\"install\":\"drop-in\"}''::jsonb
  WHERE id = ''af2121d3-6e19-5e11-bed3-2ef0a74ec58c''; -- Tactical Development Enhanced Dual Flat

-- ─── Lights ───
UPDATE public.products SET specs = ''{\"lumens\":1000,\"laser\":false,\"rail\":\"Picatinny\"}''::jsonb
  WHERE id = ''7c65ae17-4f6f-53c4-8b4b-b49fb71549c2''; -- Streamlight TLR-1 HL
UPDATE public.products SET specs = ''{\"lumens\":1000,\"laser\":false,\"rail\":\"Picatinny\"}''::jsonb
  WHERE id = ''c618c8b6-6041-5a0c-8ff4-269635fe37fa''; -- Streamlight TLR-1 HL-X
