INSERT INTO "supabase_migrations"."schema_migrations" ("version", "statements", "name", "created_by", "idempotency_key", "rollback") VALUES ('20260916035256', '{"
-- Profile page support: adds bio/avatar/social columns on profiles,
-- an avatars storage bucket (public read, 5MB, JPEG-only) with owner-only
-- write/delete, and a saved_builds table (owner-only, composite PK,
-- cascading FKs). part_favorites already exists and is untouched.

alter table public.profiles
  add column if not exists bio text,
  add column if not exists avatar_url text,
  add column if not exists instagram_url text,
  add column if not exists youtube_url text;

insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values (''avatars'', ''avatars'', true, 5242880, array[''image/jpeg'']::text[])
on conflict (id) do nothing;

create policy \"avatars_public_read\"
  on storage.objects for select
  using (bucket_id = ''avatars'');

create policy \"avatars_owner_insert\"
  on storage.objects for insert
  with check (bucket_id = ''avatars'' and (storage.foldername(name))[1] = auth.uid()::text);

create policy \"avatars_owner_delete\"
  on storage.objects for delete
  using (bucket_id = ''avatars'' and (storage.foldername(name))[1] = auth.uid()::text);

create table if not exists public.saved_builds (
  user_id    uuid not null references public.profiles(id) on delete cascade,
  build_id   uuid not null references public.builds(id) on delete cascade,
  created_at timestamptz not null default now(),
  primary key (user_id, build_id)
);
alter table public.saved_builds enable row level security;

create policy \"saved_builds_select_own\" on public.saved_builds
  for select using (auth.uid() = user_id);
create policy \"saved_builds_insert_own\" on public.saved_builds
  for insert with check (auth.uid() = user_id);
create policy \"saved_builds_delete_own\" on public.saved_builds
  for delete using (auth.uid() = user_id);

create index if not exists idx_saved_builds_user_id on public.saved_builds(user_id);
"}', 'profile_page_support', 'ag.gamboa94@gmail.com', NULL, NULL);
INSERT INTO "supabase_migrations"."schema_migrations" ("version", "statements", "name", "created_by", "idempotency_key", "rollback") VALUES ('20260916040352', '{"
-- profiles uses COLUMN-level SELECT grants for anon (see
-- 20260824070335_profiles_hide_role_from_anon, which hides `role` from
-- anonymous readers). Column grants do not extend to columns added later,
-- so the four fields added by 20260916_profile_page_support were
-- unreadable by anon and the public ?u=<username> profile view 401''d.
--
-- Grant SELECT on exactly the columns the PUBLIC profile view renders:
-- avatar, bio, the two social links, and the \"Member since\" date.
-- `role` deliberately stays hidden from anon.
grant select (bio, avatar_url, instagram_url, youtube_url, created_at)
  on public.profiles to anon;
"}', 'profile_page_anon_select_grants', 'ag.gamboa94@gmail.com', NULL, NULL);
INSERT INTO "supabase_migrations"."schema_migrations" ("version", "statements", "name", "created_by", "idempotency_key", "rollback") VALUES ('20260916124613', '{"
-- The original owner-edit policy limited UPDATE to draft/pending, which
-- meant users couldn''t edit their own rejected builds — leaving them stuck
-- with no way to address admin feedback except by starting over. Extend
-- the USING clause (which rows are visible for update) to include
-- ''rejected''; the WITH CHECK stays draft/pending because a resubmit
-- transitions the row to pending — users still can''t reject their own build.

drop policy if exists \"Owners can edit their own unreviewed builds\" on public.builds;

create policy \"Owners can edit their own unreviewed builds\"
on public.builds
for update
to authenticated
using ((auth.uid() = user_id) and status = any (array[''draft''::text, ''pending''::text, ''rejected''::text]))
with check ((auth.uid() = user_id) and status = any (array[''draft''::text, ''pending''::text]));
"}', 'allow_owners_to_edit_rejected_builds', 'ag.gamboa94@gmail.com', NULL, NULL);
INSERT INTO "supabase_migrations"."schema_migrations" ("version", "statements", "name", "created_by", "idempotency_key", "rollback") VALUES ('20260916124626', '{"
-- When an owner resubmits a rejected build (status: rejected -> pending),
-- the existing trigger nulls rejection_reason, reviewed_at, reviewed_by
-- to keep the review-cycle columns clean. That''s the right home for that
-- cleanup, but it means the rejection reason is lost from the row.
--
-- Capture the outgoing review metadata into edit_history BEFORE it''s
-- cleared, so admins re-reviewing a resubmit can see what the previous
-- rejection was for. edit_history is the correct place — it already exists
-- for the \"history of changes to a build\" purpose. Only fire the append
-- when the caller is not an admin, so admin-driven undos (which use the
-- same rejected -> pending transition) stay clean reverts.
--
-- Ordering note: prevent_owner_edit_history_change fires earlier in the
-- BEFORE UPDATE cascade (alphabetical trigger name) and only inspects the
-- client''s payload vs OLD. Our mutation of NEW.edit_history inside this
-- trigger doesn''t re-trigger that check, so appending here is safe.

create or replace function public.stamp_build_review()
returns trigger
language plpgsql
security definer
set search_path to ''public''
as $function$
begin
  if new.status is distinct from old.status and new.status in (''approved'',''rejected'') then
    new.reviewed_by := auth.uid();
    new.reviewed_at := now();
  end if;

  if new.status = ''pending'' and old.status in (''approved'',''rejected'') then
    if old.status = ''rejected'' and not public.is_admin() then
      new.edit_history := coalesce(old.edit_history, ''[]''::jsonb) || jsonb_build_array(
        jsonb_build_object(
          ''kind'', ''resubmit'',
          ''resubmit'', true,
          ''at'', now(),
          ''from_status'', old.status,
          ''previous_rejection_reason'', old.rejection_reason,
          ''previous_reviewed_at'', old.reviewed_at,
          ''previous_reviewed_by'', old.reviewed_by
        )
      );
    end if;
    new.reviewed_by := null;
    new.reviewed_at := null;
    new.rejection_reason := null;
  end if;

  return new;
end;
$function$;
"}', 'stamp_build_review_captures_resubmit', 'ag.gamboa94@gmail.com', NULL, NULL);
INSERT INTO "supabase_migrations"."schema_migrations" ("version", "statements", "name", "created_by", "idempotency_key", "rollback") VALUES ('20260916173007', '{"alter table public.product_variants add column if not exists variant_label text;
comment on column public.product_variants.variant_label is ''Human-readable variant differentiator (e.g. \"2 MOA Red Dot\"). Overrides the computed axis label in the UI when non-empty.'';"}', 'add_product_variants_variant_label', 'ag.gamboa94@gmail.com', NULL, NULL);
INSERT INTO "supabase_migrations"."schema_migrations" ("version", "statements", "name", "created_by", "idempotency_key", "rollback") VALUES ('20261007055811', '{"alter table public.link_clicks
  add column product_id uuid references public.products(id) on delete restrict;

alter table public.link_clicks
