  ''(a partner listing), product_id for /go/part/<product> (the part''''s own ''
  ''products.url — a maker''''s or seller''''s store, unpaid). RLS on, no policies, ''
  ''no grants — private by design, same as price_history. No personal data: ''
  ''target id, timestamp, and the on-site path the click came from.'';"}', 'link_clicks_product_id', 'ag.gamboa94@gmail.com', NULL, NULL);
INSERT INTO "supabase_migrations"."schema_migrations" ("version", "statements", "name", "created_by", "idempotency_key", "rollback") VALUES ('20260917210358', '{"-- 1. Lookup tables: lowercase code is the key, display_name is what the UI shows.
create table if not exists part_classes (
  part_class text primary key,
  display_name text not null,
  sort_order int not null default 0,
  notes text
);
create table if not exists port_styles (
  port_style text primary key, display_name text not null, sort_order int not null default 0, notes text
);
create table if not exists calibers (
  caliber text primary key, display_name text not null, sort_order int not null default 0, notes text
);
create table if not exists basepad_types (
  basepad_type text primary key, display_name text not null, sort_order int not null default 0, notes text
);
create table if not exists mag_types (
  mag_type text primary key, display_name text not null, sort_order int not null default 0, notes text
);
create table if not exists adapter_part_types (
  part_type text primary key, display_name text not null, sort_order int not null default 0, notes text
);
create table if not exists handedness_types (
  handedness text primary key, display_name text not null, sort_order int not null default 0, notes text
);
create table if not exists texture_types (
  texture text primary key, display_name text not null, sort_order int not null default 0, notes text
);

-- 2. Seed from the values already in use (plus the classes the frames already know about).
insert into part_classes values
 (''p365'',''P365'',10,null), (''xl'',''P365 X / XL'',20,null), (''xmacro'',''P365 XMACRO'',30,''No slides or barrels use this yet''),
 (''fuse'',''P365 FUSE'',40,null)
on conflict do nothing;
insert into port_styles values
 (''c-port'',''C-Port'',10,null), (''e-port'',''E-Port'',20,null), (''slide-matched'',''Slide-Matched'',30,''Barrel port matches whatever slide it is fitted to'')
on conflict do nothing;
insert into calibers values (''9mm'',''9mm Luger'',10,null) on conflict do nothing;
insert into basepad_types values
 (''flush-replacement'',''Flush Replacement'',10,null), (''pinky-extension'',''Pinky Extension'',20,null),
 (''extension'',''Extension'',30,null), (''adapter'',''Adapter'',40,null), (''completed-mag'',''Completed Magazine'',50,null)
on conflict do nothing;
insert into mag_types values
 (''10rd'',''10-Round'',10,null), (''15rd'',''15-Round'',20,null), (''17rd-xmacro'',''17-Round XMACRO'',30,null)
on conflict do nothing;
insert into adapter_part_types values
 (''required-adapter'',''Required Adapter'',10,null), (''adapter-included'',''Adapter Included'',15,''Reserved for future use''),
 (''factory-conversion'',''Factory Conversion'',20,null), (''aftermarket-upgrade'',''Aftermarket Upgrade'',30,null),
 (''spare'',''Spare'',40,null)
on conflict do nothing;
insert into handedness_types values
 (''right'',''Right'',10,null), (''left'',''Left'',20,null), (''ambidextrous'',''Ambidextrous'',30,null)
on conflict do nothing;

-- 3. Public read, matching the existing lookup tables.
do $$
declare t text;
begin
  foreach t in array array[''part_classes'',''port_styles'',''calibers'',''basepad_types'',''mag_types'',''adapter_part_types'',''handedness_types'',''texture_types'']
  loop
    execute format(''alter table %I enable row level security'', t);
    execute format(''drop policy if exists %I on %I'', t||''_public_read'', t);
    execute format(''create policy %I on %I for select to anon, authenticated using (true)'', t||''_public_read'', t);
  end loop;
end $$;

-- 4. Foreign keys so a misspelled code is rejected on write instead of vanishing from fitment.
alter table slide_specs  add constraint slide_specs_slide_class_fk  foreign key (slide_class)  references part_classes(part_class);
alter table slide_specs  add constraint slide_specs_port_style_fk   foreign key (port_style)   references port_styles(port_style);
alter table barrel_specs add constraint barrel_specs_barrel_class_fk foreign key (barrel_class) references part_classes(part_class);
alter table barrel_specs add constraint barrel_specs_port_style_fk  foreign key (port_style)   references port_styles(port_style);
alter table barrel_specs add constraint barrel_specs_caliber_fk     foreign key (caliber)     references calibers(caliber);
alter table basepad_specs add constraint basepad_specs_type_fk      foreign key (basepad_type) references basepad_types(basepad_type);
alter table basepad_specs add constraint basepad_specs_mag_type_fk  foreign key (fits_mag_type) references mag_types(mag_type);
alter table adapter_parts add constraint adapter_parts_part_type_fk foreign key (part_type)   references adapter_part_types(part_type);
alter table product_variants add constraint product_variants_handedness_fk foreign key (handedness) references handedness_types(handedness);

-- 5. Lookup tables that already existed but were never enforced.
alter table product_variants add constraint product_variants_optic_cut_fk foreign key (optic_cut) references optic_cuts(optic_cut);
alter table light_compatibility add constraint light_compatibility_rail_type_fk foreign key (rail_type) references rail_types(rail_type);"}', 'add_vocabulary_lookup_tables_and_fks', 'ag.gamboa94@gmail.com', NULL, NULL);
INSERT INTO "supabase_migrations"."schema_migrations" ("version", "statements", "name", "created_by", "idempotency_key", "rollback") VALUES ('20260917210407', '{"drop table if exists texture_types;
alter table rail_bridge add constraint rail_bridge_housing_class_fk foreign key (grip_housing_class) references housing_classes(housing_class);
alter table rail_bridge add constraint rail_bridge_grip_rail_type_fk foreign key (grip_rail_type) references grip_rail_types(grip_rail_type);
alter table rail_bridge add constraint rail_bridge_light_rail_type_fk foreign key (light_rail_type) references rail_types(rail_type);
alter table guns add constraint guns_housing_class_fk foreign key (housing_class) references housing_classes(housing_class);"}', 'rail_bridge_fks_and_cleanup', 'ag.gamboa94@gmail.com', NULL, NULL);
INSERT INTO "supabase_migrations"."schema_migrations" ("version", "statements", "name", "created_by", "idempotency_key", "rollback") VALUES ('20260917225743', '{"-- 1. The notebook: platform + part kind + length -> class
create table if not exists platform_part_lengths (
  platform_id uuid not null references platforms(id) on delete cascade,
  part_kind text not null check (part_kind in (''slide'',''barrel'')),
  length_in numeric(4,2) not null,
  part_class text not null references part_classes(part_class),
  notes text,
  primary key (platform_id, part_kind, length_in)
);
alter table platform_part_lengths enable row level security;
drop policy if exists platform_part_lengths_public_read on platform_part_lengths;
create policy platform_part_lengths_public_read on platform_part_lengths
  for select to anon, authenticated using (true);

-- 2. Seed the rules the generated columns encoded, for P365
insert into platform_part_lengths (platform_id, part_kind, length_in, part_class)
select p.id, k.kind, v.len, v.cls
from platforms p
cross join (values (''slide''),(''barrel'')) k(kind)
cross join (values (3.10,''p365''),(3.70,''xl''),(4.30,''fuse'')) v(len,cls)
where p.slug = ''p365''
on conflict do nothing;

-- 3. Parts need to know their platform
alter table slide_specs  add column if not exists platform_id uuid references platforms(id);
alter table barrel_specs add column if not exists platform_id uuid references platforms(id);
update slide_specs  set platform_id = (select id from platforms where slug=''p365'') where platform_id is null;
update barrel_specs set platform_id = (select id from platforms where slug=''p365'') where platform_id is null;
alter table slide_specs  alter column platform_id set not null;
alter table barrel_specs alter column platform_id set not null;"}', 'platform_length_class_lookup', 'ag.gamboa94@gmail.com', NULL, NULL);
INSERT INTO "supabase_migrations"."schema_migrations" ("version", "statements", "name", "created_by", "idempotency_key", "rollback") VALUES ('20260917225757', '{"-- View depends on slide_class; drop and recreate around the change
drop view if exists v_slide_frame_fit;

-- slide_class: generated -> plain, values preserved
alter table slide_specs add column slide_class_new text;
update slide_specs set slide_class_new = slide_class;
alter table slide_specs drop column slide_class;
alter table slide_specs rename column slide_class_new to slide_class;
alter table slide_specs add constraint slide_specs_slide_class_fk
  foreign key (slide_class) references part_classes(part_class);

-- barrel_class: same
alter table barrel_specs add column barrel_class_new text;
update barrel_specs set barrel_class_new = barrel_class;
alter table barrel_specs drop column barrel_class;
alter table barrel_specs rename column barrel_class_new to barrel_class;
alter table barrel_specs add constraint barrel_specs_barrel_class_fk
  foreign key (barrel_class) references part_classes(part_class);

-- The trigger: look the class up by platform + length, every insert and update
create or replace function set_part_class()
returns trigger
language plpgsql
as $$
declare
  v_len numeric(4,2);
  v_kind text;
  v_class text;
  v_platform text;
begin
  if tg_table_name = ''slide_specs'' then
    v_len := new.slide_length_in; v_kind := ''slide'';
  else
    v_len := new.barrel_length_in; v_kind := ''barrel'';
  end if;

  -- No length yet: nothing to look up, leave the class empty.
  if v_len is null then
    if tg_table_name = ''slide_specs'' then new.slide_class := null;
    else new.barrel_class := null; end if;
    return new;
  end if;

  select ppl.part_class into v_class
  from platform_part_lengths ppl
  where ppl.platform_id = new.platform_id
    and ppl.part_kind = v_kind
    and ppl.length_in = v_len;

  if v_class is null then
    select name into v_platform from platforms where id = new.platform_id;
    raise exception
      ''No % class registered for platform \"%\" at % in. Add a row to platform_part_lengths first (Runbook Step 1).'',
      v_kind, coalesce(v_platform,''unknown''), v_len
      using errcode = ''foreign_key_violation'';
  end if;

  if tg_table_name = ''slide_specs'' then new.slide_class := v_class;
  else new.barrel_class := v_class; end if;
  return new;
end $$;

create trigger slide_specs_set_class
  before insert or update of slide_length_in, platform_id on slide_specs
  for each row execute function set_part_class();

create trigger barrel_specs_set_class
  before insert or update of barrel_length_in, platform_id on barrel_specs
  for each row execute function set_part_class();

-- Recreate the view exactly as it was
create view v_slide_frame_fit as
 select sl.product_id as slide_product_id,
    fr.product_id as frame_product_id,
    sl.slide_length_in,
    sl.slide_class,
    fr.housing_class,
    hc.min_slide_length_in,
    (sl.slide_length_in >= hc.min_slide_length_in) as fits,
    case
      when (sl.slide_length_in < hc.min_slide_length_in) then ''Grip module extends past the slide. Not a usable build.''::text
      when (sl.slide_length_in > hc.min_slide_length_in) then ''Slide overhangs the grip. Intentional and fine.''::text
      else ''Flush fit.''::text
    end as verdict
   from ((slide_specs sl
     cross join frame_specs fr)
     join housing_classes hc on ((hc.housing_class = fr.housing_class)));"}', 'convert_class_columns_and_add_trigger', 'ag.gamboa94@gmail.com', NULL, NULL);
INSERT INTO "supabase_migrations"."schema_migrations" ("version", "statements", "name", "created_by", "idempotency_key", "rollback") VALUES ('20260918024654', '{"-- How the light attaches
create table if not exists clamp_styles (
  clamp_style text primary key,
  display_name text not null,
  sort_order int not null default 0,
  notes text
);
alter table clamp_styles enable row level security;
drop policy if exists clamp_styles_public_read on clamp_styles;
create policy clamp_styles_public_read on clamp_styles for select to anon, authenticated using (true);

insert into clamp_styles values
 (''single-key'',''Single Rail Key'',10,''Ships with one rail key or insert; variant is tied to that rail''),
 (''multi-key'',''Multiple Rail Keys'',20,''Ships with several keys or inserts covering more than one rail''),
 (''multi-plate'',''Multiple Rail Plates'',30,''Ships with interchangeable mounting plates''),
 (''rail-grip'',''Rail-Grip Clamp'',40,''Clamps onto the rail rather than using a key or insert'')
on conflict do nothing;

-- Two columns replacing the one free-text field
alter table product_variants add column if not exists clamp_style text references clamp_styles(clamp_style);
alter table product_variants add column if not exists clamp_rail_type text references rail_types(rail_type);

-- Backfill: rail-specific values
update product_variants set clamp_style=''single-key'', clamp_rail_type=''1913-short''  where clamp=''1913-short'';
update product_variants set clamp_style=''single-key'', clamp_rail_type=''glock-slim''  where clamp=''glock-slim'';
update product_variants set clamp_style=''single-key'', clamp_rail_type=''sa-hellcat''  where clamp=''sa-hellcat'';
update product_variants set clamp_style=''single-key'', clamp_rail_type=''sig-365''     where clamp=''sig-365'';
update product_variants set clamp_style=''single-key'', clamp_rail_type=''1913''        where clamp=''universal (1913)'';
update product_variants set clamp_style=''single-key'', clamp_rail_type=''1913-short''  where clamp=''universal (1913 short)'';

-- Backfill: values that describe the attachment, not one rail
update product_variants set clamp_style=''multi-key''   where clamp in (''universal (1913/GL)'',''universal (keyed)'',''universal (multi-key)'');
update product_variants set clamp_style=''multi-plate'' where clamp=''universal (multi-plate)'';
update product_variants set clamp_style=''rail-grip''   where clamp=''Rail-grip clamp system'';"}', 'split_variant_clamp_into_style_and_rail', 'ag.gamboa94@gmail.com', NULL, NULL);
INSERT INTO "supabase_migrations"."schema_migrations" ("version", "statements", "name", "created_by", "idempotency_key", "rollback") VALUES ('20260918024706', '{"alter table product_variants drop column clamp;"}', 'drop_legacy_variant_clamp_column', 'ag.gamboa94@gmail.com', NULL, NULL);
INSERT INTO "supabase_migrations"."schema_migrations" ("version", "statements", "name", "created_by", "idempotency_key", "rollback") VALUES ('20260918033237', '{"alter table product_variants add column clamp text;

-- Restore the exact original strings, per product
update product_variants v set clamp = v.clamp_rail_type
from products p where p.id = v.product_id
 and v.clamp_style = ''single-key''
 and p.name in (''TLR-7 HL-X Sub USB'',''TLR-7 X Sub USB'',''TLR-7 Sub'');

update product_variants v set clamp = ''universal (1913)''
from products p where p.id = v.product_id
 and v.clamp_style = ''single-key'' and p.name like ''P.ID%'';

update product_variants v set clamp = ''universal (1913 short)''
from products p where p.id = v.product_id
 and v.clamp_style = ''single-key'' and p.name = ''XC3 (XC3-A)'';

update product_variants v set clamp = ''universal (keyed)''
from products p where p.id = v.product_id
 and v.clamp_style = ''multi-key'' and p.name = ''TLR-7 X'';

update product_variants v set clamp = ''universal (multi-key)''
from products p where p.id = v.product_id
 and v.clamp_style = ''multi-key'' and p.name = ''PL-Mini 3 Valkyrie'';

update product_variants set clamp = ''universal (1913/GL)''
 where clamp_style = ''multi-key'' and clamp is null;

update product_variants set clamp = ''universal (multi-plate)'' where clamp_style = ''multi-plate'';
update product_variants set clamp = ''Rail-grip clamp system''  where clamp_style = ''rail-grip'';

comment on column product_variants.clamp is
 ''LEGACY. Superseded by clamp_style + clamp_rail_type. Still selected by gunforma-parts-catalog.html, js/affiliate.js and gunforma-build-detail.html. Do not drop until those are updated.'';"}', 'restore_variant_clamp_column', 'ag.gamboa94@gmail.com', NULL, NULL);
INSERT INTO "supabase_migrations"."schema_migrations" ("version", "statements", "name", "created_by", "idempotency_key", "rollback") VALUES ('20260922031941', '{"
create table public.price_history (
  id           bigint generated always as identity primary key,
  link_id      uuid not null references public.affiliate_links(id) on delete cascade,
  old_price    numeric,
  new_price    numeric,
  old_in_stock boolean,
  new_in_stock boolean,
  changed_at   timestamptz not null default now()
);

comment on table public.price_history is
  ''Append-only log of affiliate_links street_price / in_stock changes. Written only by the trigger below; no direct writers.'';

create index idx_price_history_link_time
  on public.price_history (link_id, changed_at desc);

create index idx_price_history_drops
  on public.price_history (changed_at desc)
  where old_price is not null and new_price is not null and new_price < old_price;

-- Service role only. RLS on with NO policies, plus an explicit REVOKE because
-- Supabase''s default ACL grants anon/authenticated ALL privileges on new
-- public tables. When a product page needs a chart, expose ONE link''s history
-- via a server-rendered page or a narrow SECURITY DEFINER RPC — not a broad
-- SELECT policy, which would make the whole dataset enumerable.
alter table public.price_history enable row level security;

revoke all on public.price_history from anon, authenticated;

create or replace function public.record_price_change()
returns trigger
language plpgsql
security definer
set search_path to ''''
as $$
begin
  if tg_op = ''INSERT'' then
    insert into public.price_history
      (link_id, old_price, new_price, old_in_stock, new_in_stock)
    values
      (new.id, null, new.street_price, null, new.in_stock);

  elsif new.street_price is distinct from old.street_price
     or new.in_stock    is distinct from old.in_stock then
    insert into public.price_history
      (link_id, old_price, new_price, old_in_stock, new_in_stock)
    values
      (old.id, old.street_price, new.street_price, old.in_stock, new.in_stock);
  end if;

  return null;
end;
$$;

create trigger affiliate_links_price_history_ins
  after insert on public.affiliate_links
  for each row execute function public.record_price_change();

create trigger affiliate_links_price_history_upd
  after update on public.affiliate_links
  for each row execute function public.record_price_change();

insert into public.price_history
  (link_id, old_price, new_price, old_in_stock, new_in_stock)
select id, null, street_price, null, in_stock
from public.affiliate_links;
"}', 'price_history', 'ag.gamboa94@gmail.com', NULL, NULL);
INSERT INTO "supabase_migrations"."schema_migrations" ("version", "statements", "name", "created_by", "idempotency_key", "rollback") VALUES ('20260922061220', '{"create table if not exists public.sync_drift_review (
  id                bigint generated always as identity primary key,
  run_at            timestamptz not null,
  partner_id        uuid references public.partners(id) on delete set null,
  link_id           uuid not null,
  kind              text not null check (kind in (''identifier_drift'',''candidate_conflict'')),
  field             text,
  stored_value      text,
  feed_value        text,
  feed_product_name text,
  matched_by        text,
  link_url          text,
  resolved_at       timestamptz,
  resolution_note   text,
  created_at        timestamptz not null default now()
);

comment on table public.sync_drift_review is
  ''Things the nightly affiliate sync refused to write: a feed row contradicting a stored op_* identifier, or several feed rows claiming the same link. Nothing was written for these links on that run. Review, then either correct the link by hand or clear the stored identifier so the next run can refill it.'';

create index if not exists idx_sync_drift_review_open
  on public.sync_drift_review (run_at desc)
  where resolved_at is null;

create index if not exists idx_sync_drift_review_link
  on public.sync_drift_review (link_id, run_at desc);

alter table public.sync_drift_review enable row level security;

revoke all on public.sync_drift_review from anon, authenticated;"}', 'sync_drift_review', 'ag.gamboa94@gmail.com', NULL, NULL);
INSERT INTO "supabase_migrations"."schema_migrations" ("version", "statements", "name", "created_by", "idempotency_key", "rollback") VALUES ('20260922073421', '{"-- #4 partners: authenticated loses the business columns; mirrors anon''s grants.
-- id is included because PostgREST needs it to resolve the
-- affiliate_links.partner_id -> partners.id embed.
revoke select on public.partners from authenticated;
grant  select (id, name, slug) on public.partners to authenticated;

-- #6 trigger functions were never meant to be callable as RPCs.
-- Revoking EXECUTE does not affect trigger firing. service_role keeps its own
-- explicit grant, so the nightly sync is unaffected.
revoke execute on function public.record_price_change()               from public, anon, authenticated;
revoke execute on function public.prevent_owner_edit_history_change() from public, anon, authenticated;

-- #7 view ran as its creator, bypassing RLS. Body untouched; its three source
-- tables are public-read so invoker mode reads identically.
alter view public.v_slide_frame_fit set (security_invoker = true);

-- #9 the last function without a pinned search_path (SECURITY INVOKER).
alter function public.set_part_class() set search_path = public;"}', 'security_audit_4_6_7_9', 'ag.gamboa94@gmail.com', NULL, NULL);
INSERT INTO "supabase_migrations"."schema_migrations" ("version", "statements", "name", "created_by", "idempotency_key", "rollback") VALUES ('20260922170455', '{"-- get_my_profile — the caller''s OWN profile row, including the columns that
-- are about to stop being readable table-wide (audit finding #5).
--
-- Why this exists: column privileges are not row-aware. Revoking SELECT on
-- `role` from `authenticated` stops a user reading their own role, not just
-- other people''s — which breaks sign-in, both admin gates, onboarding, the
-- builder agreement and build submission. This gives each user a narrow,
-- row-scoped way back to their own hidden columns.
--
-- It is hard-scoped to auth.uid() and takes no arguments, so it cannot be
-- pointed at another user. SECURITY DEFINER so it keeps working after the
-- column revoke lands; search_path pinned, per project convention.
--
-- ADDITIVE ONLY. The profiles column grants are NOT revoked here — that is a
-- separate step, after the six rewritten pages are live on production.
create or replace function public.get_my_profile()
returns table (
  id                            uuid,
  username                      text,
  onboarding_complete           boolean,
  role                          text,
  marketing_consent             boolean,
  builder_agreement_accepted    boolean,
  builder_agreement_accepted_at timestamptz,
  builder_agreement_version     text
)
language sql
security definer
stable
set search_path = public
as $$
  select p.id,
         p.username,
         p.onboarding_complete,
         p.role,
         p.marketing_consent,
         p.builder_agreement_accepted,
         p.builder_agreement_accepted_at,
         p.builder_agreement_version
  from public.profiles p
  where p.id = auth.uid();
$$;

comment on function public.get_my_profile() is
  ''Returns the calling user''''s own profile row only, including columns not readable table-wide. Hard-scoped to auth.uid(); takes no arguments so it cannot be aimed at another user.'';

-- Supabase grants EXECUTE to PUBLIC on new functions by default; strip that
-- and hand it only to signed-in users. anon gets nothing: auth.uid() would be
-- null and the function would return zero rows anyway, but an explicit revoke
-- keeps it off the anon API surface entirely.
revoke execute on function public.get_my_profile() from public, anon;
grant  execute on function public.get_my_profile() to authenticated;"}', 'get_my_profile_rpc', 'ag.gamboa94@gmail.com', NULL, NULL);
INSERT INTO "supabase_migrations"."schema_migrations" ("version", "statements", "name", "created_by", "idempotency_key", "rollback") VALUES ('20260922174215', '{"-- Audit finding #5, step 2 of 2. Prerequisite (PR #26) is live: every
-- self-scoped read of these columns now goes through get_my_profile().
--
-- authenticated held a TABLE-level SELECT plus a USING (true) policy, so any
-- signed-up user could read every other user''s role, marketing_consent and
-- builder_agreement_*. Limit it to exactly the 8 columns anon already has.
--
-- The table-level UPDATE grant is NOT touched: the three flows that write
-- hidden columns (complete-profile, claim, builder-agreement) keep working,
-- none of them chains .select(), and trg_prevent_role_self_escalation still
-- blocks self-promotion. anon is not touched in either direction.
revoke select on public.profiles from authenticated;

grant select (
  id,
  username,
  bio,
  avatar_url,
  instagram_url,
  youtube_url,
  created_at,
  onboarding_complete
) on public.profiles to authenticated;"}', 'profiles_revoke_hidden_columns', 'ag.gamboa94@gmail.com', NULL, NULL);
INSERT INTO "supabase_migrations"."schema_migrations" ("version", "statements", "name", "created_by", "idempotency_key", "rollback") VALUES ('20260922195829', '{"-- The guard opened with `if current_user in (''postgres'',''service_role'') then
-- return new; end if;`. This function is SECURITY DEFINER owned by postgres,
-- and inside a SECURITY DEFINER function current_user is the OWNER, not the
-- caller — so that test was always true and neither check below it ever ran.
-- Any signed-in user could set their own role to ''admin''.
--
-- Identify the caller from the request JWT instead. service_role is allowed,
-- as is direct SQL with no request context (migrations, psql, SQL editor).
--
-- The consent rule is widened by exactly one case relative to the original
-- text: the first, forward-only acceptance on your own row. Without it,
-- builder-agreement.html and gunforma-claim.html break, since both write
-- these fields directly as an ordinary user.
create or replace function public.prevent_role_self_escalation()
returns trigger
language plpgsql
security definer
set search_path to ''public''
as $function$
declare
  jwt_role text;
begin
  -- The CALLER''s role. Do NOT use current_user here: in a SECURITY DEFINER
  -- function it is the owner, which is exactly what broke this guard.
  jwt_role := coalesce(
    nullif(current_setting(''request.jwt.claims'', true), '''')::jsonb ->> ''role'',
    ''''
  );

  if jwt_role = ''service_role'' or jwt_role = '''' then
    return new;
  end if;

  if new.role is distinct from old.role and not public.is_admin() then
    raise exception ''Only admins can change role'';
  end if;

  if (new.builder_agreement_accepted    is distinct from old.builder_agreement_accepted
      or new.builder_agreement_version     is distinct from old.builder_agreement_version
      or new.builder_agreement_accepted_at is distinct from old.builder_agreement_accepted_at)
     and not public.is_admin()
     and coalesce(current_setting(''app.bypass_consent_guard'', true), ''false'') <> ''true''
     and not (new.id = auth.uid()
              and old.builder_agreement_accepted = false
              and new.builder_agreement_accepted = true)
  then
    raise exception ''Builder agreement fields can only be set by accepting the agreement or submitting a build'';
  end if;

  return new;
end;
$function$;"}', 'fix_prevent_role_self_escalation', 'ag.gamboa94@gmail.com', NULL, NULL);
INSERT INTO "supabase_migrations"."schema_migrations" ("version", "statements", "name", "created_by", "idempotency_key", "rollback") VALUES ('20260923175255', '{"alter table public.affiliate_links  add column if not exists retired_at timestamptz;
alter table public.product_variants add column if not exists retired_at timestamptz;

comment on column public.affiliate_links.retired_at is
  ''When this listing stopped being offered. Retired links keep their price_history, are skipped by the nightly sync, and are hidden from buy rows. Never hard-delete a link.'';
comment on column public.product_variants.retired_at is
  ''When this variant stopped being sold. Retiring a variant auto-retires its affiliate_links via trg_retire_links_with_variant.'';

alter table public.price_history drop constraint price_history_link_id_fkey;
alter table public.price_history add  constraint price_history_link_id_fkey
  foreign key (link_id) references public.affiliate_links(id) on delete restrict;

alter table public.affiliate_links drop constraint affiliate_links_variant_id_fkey;
alter table public.affiliate_links add  constraint affiliate_links_variant_id_fkey
  foreign key (variant_id) references public.product_variants(id) on delete restrict;

create index if not exists idx_affiliate_links_live
  on public.affiliate_links (variant_id) where retired_at is null;
create index if not exists idx_product_variants_live
  on public.product_variants (product_id) where retired_at is null;

create or replace function public.retire_links_with_variant()
returns trigger
language plpgsql
security definer
set search_path to ''public''
as $function$
begin
  if new.retired_at is not null and old.retired_at is null then
    update public.affiliate_links
       set retired_at = new.retired_at
     where variant_id = new.id
       and retired_at is null;
  end if;
  return null;
end;
$function$;

comment on function public.retire_links_with_variant() is
  ''Retires a variant''''s affiliate_links when the variant is retired. Only ever sets retired_at; never clears it.'';

drop trigger if exists trg_retire_links_with_variant on public.product_variants;
create trigger trg_retire_links_with_variant
  after update of retired_at on public.product_variants
  for each row execute function public.retire_links_with_variant();

revoke execute on function public.retire_links_with_variant() from public, anon, authenticated;"}', 'retired_at_2a_schema_and_sync_filter', 'ag.gamboa94@gmail.com', NULL, NULL);
INSERT INTO "supabase_migrations"."schema_migrations" ("version", "statements", "name", "created_by", "idempotency_key", "rollback") VALUES ('20260924031526', '{"create table if not exists public.affiliate_links_is_primary_archive as
  select id as link_id, now() as archived_at
    from public.affiliate_links
   where is_primary;

alter table public.affiliate_links_is_primary_archive
  add primary key (link_id);

alter table public.affiliate_links_is_primary_archive enable row level security;
revoke all on public.affiliate_links_is_primary_archive from anon, authenticated;

drop index if exists public.affiliate_one_primary_per_variant;

alter table public.affiliate_links drop column is_primary;"}', 'retire_affiliate_links_is_primary', 'ag.gamboa94@gmail.com', NULL, NULL);
INSERT INTO "supabase_migrations"."schema_migrations" ("version", "statements", "name", "created_by", "idempotency_key", "rollback") VALUES ('20260925203335', '{"create table public.build_comments (
  id          uuid primary key default gen_random_uuid(),
  build_id    uuid not null references public.builds(id)   on delete cascade,
  user_id     uuid not null references public.profiles(id) on delete cascade,
  parent_id   uuid references public.build_comments(id) on delete cascade,
  body        text not null,
  created_at  timestamptz not null default now(),
  edited_at   timestamptz,
  deleted_at  timestamptz,
  constraint build_comments_body_len check (char_length(body) between 1 and 2000)
);

comment on table public.build_comments is
  ''Comments on approved builds, one level of replies. Soft-deleted via deleted_at. Read through build_comments_public, never directly.'';

create index idx_build_comments_build   on public.build_comments (build_id, created_at);
create index idx_build_comments_parent  on public.build_comments (parent_id) where parent_id is not null;
create index idx_build_comments_user_time on public.build_comments (user_id, created_at desc);

create table public.build_comment_votes (
  comment_id  uuid not null references public.build_comments(id) on delete cascade,
  user_id     uuid not null references public.profiles(id)       on delete cascade,
  value       smallint not null check (value in (-1, 1)),
  created_at  timestamptz not null default now(),
  primary key (comment_id, user_id)
);

comment on table public.build_comment_votes is
  ''One vote per user per comment, +1 or -1. Who voted is private; only the sum is exposed, via build_comments_public.'';

alter table public.build_comments      enable row level security;
alter table public.build_comment_votes enable row level security;

revoke all on public.build_comments      from anon, authenticated;
revoke all on public.build_comment_votes from anon, authenticated;

grant select, insert, update on public.build_comments to authenticated;
grant delete on public.build_comments to authenticated;

create policy build_comments_select_own_or_admin on public.build_comments
  for select to authenticated
  using (user_id = auth.uid() or public.is_admin());

create policy build_comments_insert_own on public.build_comments
  for insert to authenticated
  with check (user_id = auth.uid());

create policy build_comments_update_own_or_admin on public.build_comments
  for update to authenticated
  using (user_id = auth.uid() or public.is_admin())
  with check (user_id = auth.uid() or public.is_admin());

create policy build_comments_delete_admin on public.build_comments
  for delete to authenticated
  using (public.is_admin());

grant select, insert, update, delete on public.build_comment_votes to authenticated;

create policy build_comment_votes_own on public.build_comment_votes
  for all to authenticated
  using (user_id = auth.uid())
  with check (user_id = auth.uid());

create or replace function public.build_comments_guard_insert()
returns trigger
language plpgsql
security definer
set search_path = ''''
as $$
declare
  v_uid uuid := auth.uid();
  v_recent int;
  v_parent public.build_comments%rowtype;
begin
  if v_uid is null or new.user_id <> v_uid then
    raise exception ''Comment must be posted as yourself'';
  end if;

  if not exists (
    select 1 from public.profiles p
    where p.id = v_uid and p.username is not null and btrim(p.username) <> ''''
  ) then
    raise exception ''Complete your profile before commenting'';
  end if;

  if not exists (
    select 1 from public.builds b where b.id = new.build_id and b.status = ''approved''
  ) then
    raise exception ''Comments are only allowed on approved builds'';
  end if;

  if new.parent_id is not null then
    select * into v_parent from public.build_comments where id = new.parent_id;
    if not found then
      raise exception ''Parent comment not found'';
    end if;
    if v_parent.build_id <> new.build_id then
      raise exception ''Reply must be on the same build as its parent'';
    end if;
    if v_parent.parent_id is not null then
      raise exception ''Replies can only be one level deep'';
    end if;
    if v_parent.deleted_at is not null then
      raise exception ''Cannot reply to a deleted comment'';
    end if;
  end if;

  select count(*) into v_recent
  from public.build_comments c
  where c.user_id = v_uid and c.created_at > now() - interval ''10 minutes'';
  if v_recent >= 10 then
    raise exception ''Slow down — try again in a few minutes'';
  end if;

  new.body       := btrim(new.body);
  new.created_at := now();
  new.edited_at  := null;
  new.deleted_at := null;
  return new;
end;
$$;

create or replace function public.build_comments_guard_update()
returns trigger
language plpgsql
security definer
set search_path = ''''
as $$
declare
  v_uid   uuid    := auth.uid();
  v_owner boolean := (v_uid is not null and v_uid = old.user_id);
  v_admin boolean := public.is_admin();
begin
  if new.id         <> old.id
  or new.build_id   <> old.build_id
  or new.user_id    <> old.user_id
  or new.created_at <> old.created_at
  or new.parent_id is distinct from old.parent_id then
    raise exception ''Cannot move a comment'';
  end if;

  if old.deleted_at is not null then
    raise exception ''Comment is deleted'';
  end if;

  if new.body <> old.body then
    if not v_owner then
      raise exception ''Only the author can edit a comment'';
    end if;
    new.body      := btrim(new.body);
    new.edited_at := now();
  else
    new.edited_at := old.edited_at;
  end if;

  if new.deleted_at is not null then
    if not (v_owner or v_admin) then
      raise exception ''Not allowed to delete this comment'';
    end if;
    new.deleted_at := now();
  end if;

  return new;
end;
$$;

create or replace function public.build_comment_votes_guard()
returns trigger
language plpgsql
security definer
set search_path = ''''
as $$
declare
  v_uid uuid := auth.uid();
  v_c   public.build_comments%rowtype;
begin
  if v_uid is null or new.user_id <> v_uid then
    raise exception ''Vote must be cast as yourself'';
  end if;
  select * into v_c from public.build_comments where id = new.comment_id;
  if not found or v_c.deleted_at is not null then
    raise exception ''Comment not found'';
  end if;
  if v_c.user_id = v_uid then
    raise exception ''You cannot vote on your own comment'';
  end if;
  new.created_at := now();
  return new;
end;
$$;

revoke all on function public.build_comments_guard_insert()  from public;
revoke all on function public.build_comments_guard_update()  from public;
revoke all on function public.build_comment_votes_guard()    from public;

create trigger trg_build_comments_guard_insert
  before insert on public.build_comments
  for each row execute function public.build_comments_guard_insert();

create trigger trg_build_comments_guard_update
  before update on public.build_comments
  for each row execute function public.build_comments_guard_update();

create trigger trg_build_comment_votes_guard
  before insert or update on public.build_comment_votes
  for each row execute function public.build_comment_votes_guard();

create view public.build_comments_public as
select
  c.id,
  c.build_id,
  c.parent_id,
  c.user_id,
  case when c.deleted_at is null then c.body else null end as body,
  c.created_at,
  c.edited_at,
  (c.deleted_at is not null)                              as is_deleted,
  p.username,
  p.avatar_url,
  (select count(*)::int from public.builds b
     where b.user_id = c.user_id and b.status = ''approved'') as author_build_count,
  coalesce((select sum(v.value)::int from public.build_comment_votes v
     where v.comment_id = c.id), 0)                        as score,
  (select v.value from public.build_comment_votes v
     where v.comment_id = c.id and v.user_id = auth.uid()) as my_vote
from public.build_comments c
join public.profiles p on p.id = c.user_id
where exists (select 1 from public.builds b where b.id = c.build_id and b.status = ''approved'');

comment on view public.build_comments_public is
  ''Public read model for build comments. Owner-run on purpose: sums votes without exposing them and enforces approved-builds-only itself.'';

revoke all on public.build_comments_public from anon, authenticated;
grant select on public.build_comments_public to anon, authenticated;"}', 'build_comments', 'ag.gamboa94@gmail.com', NULL, NULL);
INSERT INTO "supabase_migrations"."schema_migrations" ("version", "statements", "name", "created_by", "idempotency_key", "rollback") VALUES ('20260925203352', '{"create table public.notifications (
  id          bigint generated always as identity primary key,
  user_id     uuid not null references public.profiles(id) on delete cascade,
  actor_id    uuid not null references public.profiles(id) on delete cascade,
  kind        text not null check (kind in (''comment'', ''reply'', ''like'')),
  build_id    uuid not null references public.builds(id) on delete cascade,
  comment_id  uuid references public.build_comments(id) on delete cascade,
  preview     text,
  created_at  timestamptz not null default now(),
  read_at     timestamptz
);

comment on table public.notifications is
  ''In-app inbox. Written by triggers on build_comments and build_fires only; recipients read their own rows and set read_at.'';

create index idx_notifications_user_time on public.notifications (user_id, created_at desc);
create index idx_notifications_unread    on public.notifications (user_id) where read_at is null;

create unique index uq_notifications_like on public.notifications (user_id, actor_id, build_id)
  where kind = ''like'';

alter table public.notifications enable row level security;
revoke all on public.notifications from anon, authenticated;

grant select on public.notifications to authenticated;
grant update (read_at) on public.notifications to authenticated;

create policy notifications_select_own on public.notifications
  for select to authenticated
  using (user_id = auth.uid());

create policy notifications_update_own on public.notifications
  for update to authenticated
  using (user_id = auth.uid())
  with check (user_id = auth.uid());

create or replace function public.notifications_guard_update()
returns trigger
language plpgsql
security definer
set search_path = ''''
as $$
begin
  if new.read_at is null and old.read_at is not null then
    raise exception ''Cannot mark a notification unread'';
  end if;
  if new.read_at is not null then
    new.read_at := coalesce(old.read_at, now());
  end if;
  return new;
end;
$$;
revoke all on function public.notifications_guard_update() from public;

create trigger trg_notifications_guard_update
  before update on public.notifications
  for each row execute function public.notifications_guard_update();

create or replace function public.notify_on_comment()
returns trigger
language plpgsql
security definer
set search_path = ''''
as $$
declare
  v_owner  uuid;
  v_parent uuid;
  v_prev   text := left(regexp_replace(new.body, ''\\s+'', '' '', ''g''), 140);
begin
  select user_id into v_owner from public.builds where id = new.build_id and status = ''approved'';
  if v_owner is null then return new; end if;

  if new.parent_id is not null then
    select user_id into v_parent from public.build_comments where id = new.parent_id;
    if v_parent is not null and v_parent <> new.user_id then
      insert into public.notifications (user_id, actor_id, kind, build_id, comment_id, preview)
      values (v_parent, new.user_id, ''reply'', new.build_id, new.id, v_prev);
    end if;
    if v_owner <> new.user_id and v_owner is distinct from v_parent then
      insert into public.notifications (user_id, actor_id, kind, build_id, comment_id, preview)
      values (v_owner, new.user_id, ''comment'', new.build_id, new.id, v_prev);
    end if;
  elsif v_owner <> new.user_id then
    insert into public.notifications (user_id, actor_id, kind, build_id, comment_id, preview)
    values (v_owner, new.user_id, ''comment'', new.build_id, new.id, v_prev);
  end if;
  return new;
end;
$$;

create or replace function public.notify_on_like()
returns trigger
language plpgsql
security definer
set search_path = ''''
as $$
declare
  v_owner uuid;
begin
  if tg_op = ''DELETE'' then
    delete from public.notifications
      where kind = ''like'' and build_id = old.build_id and actor_id = old.user_id and read_at is null;
    return old;
  end if;
  select user_id into v_owner from public.builds where id = new.build_id and status = ''approved'';
  if v_owner is null or v_owner = new.user_id then return new; end if;
  insert into public.notifications (user_id, actor_id, kind, build_id)
  values (v_owner, new.user_id, ''like'', new.build_id)
  on conflict do nothing;
  return new;
end;
$$;

revoke all on function public.notify_on_comment() from public;
revoke all on function public.notify_on_like()    from public;

create trigger trg_notify_on_comment
  after insert on public.build_comments
  for each row execute function public.notify_on_comment();

create trigger trg_notify_on_like
  after insert or delete on public.build_fires
  for each row execute function public.notify_on_like();"}', 'notifications', 'ag.gamboa94@gmail.com', NULL, NULL);
INSERT INTO "supabase_migrations"."schema_migrations" ("version", "statements", "name", "created_by", "idempotency_key", "rollback") VALUES ('20260925210105', '{"-- Trigger functions are called by the table owner when a trigger fires, never
-- by a client, so anon/authenticated need no EXECUTE. Supabase''s default ACL
-- grants it anyway and `revoke ... from public` does not remove a role-specific
-- grant, so it is revoked explicitly here. Matches the posture of the repo''s
-- existing functions.
revoke execute on function
  public.build_comments_guard_insert(),
  public.build_comments_guard_update(),
  public.build_comment_votes_guard(),
  public.notifications_guard_update(),
  public.notify_on_comment(),
  public.notify_on_like()
from anon, authenticated;"}', 'revoke_execute_on_comment_trigger_functions', 'ag.gamboa94@gmail.com', NULL, NULL);
INSERT INTO "supabase_migrations"."schema_migrations" ("version", "statements", "name", "created_by", "idempotency_key", "rollback") VALUES ('20260929230242', '{"-- link_clicks — one row per outbound buy click, written by the /go/ edge
-- function as service_role. No cookie, no user id, no IP: the row says which
-- affiliate link was clicked, when, and which page it was clicked from.
--
-- PRIVATE BY DESIGN, exactly like price_history. RLS on, NO policies and NO
-- grants. CLAUDE.md: Supabase''s default ACL hands anon and authenticated full
-- privileges on every new table in public, so \"protected by RLS alone\" still
-- leaves those grants sitting underneath. The revoke below is the half that
-- actually removes them.
create table public.link_clicks (
  id            bigint generated always as identity primary key,
  -- ON DELETE RESTRICT, matching price_history.link_id. affiliate_links are
  -- never hard-deleted (they carry retired_at); this edge refuses to let a
  -- delete silently take the click history with it.
  link_id       uuid        not null references public.affiliate_links(id) on delete restrict,
  ts            timestamptz not null default now(),
  -- The path the click came FROM, e.g. /b/<slug>-<uuid> or /parts/slides/x.
  -- A path, never a full referrer: no query string, no external origin, so it
  -- cannot carry a search term or a session token.
  referrer_path text
);

-- The comparison query this table exists for is \"clicks per link per day\",
-- which is what gets held against Awin''s click report.
create index idx_link_clicks_link_ts on public.link_clicks (link_id, ts desc);
create index idx_link_clicks_ts      on public.link_clicks (ts desc);

alter table public.link_clicks enable row level security;

-- No policies are added on purpose. service_role bypasses RLS, and nothing
-- else may read or write this.
revoke all on public.link_clicks from anon, authenticated;

comment on table public.link_clicks is
  ''Outbound affiliate click log. Written by the /go/ edge function as service_role. RLS on, no policies, no grants — private by design, same as price_history. No personal data: link id, timestamp, and the on-site path the click came from.'';"}', 'create_link_clicks', 'ag.gamboa94@gmail.com', NULL, NULL);
INSERT INTO "supabase_migrations"."schema_migrations" ("version", "statements", "name", "created_by", "idempotency_key", "rollback") VALUES ('20260930051121', '{"-- Factory optic cut per P365 model, at SKU-group granularity.
-- Verified 2026-09-30 against sigsauer.com live per-SKU spec tables + SIG-LOC FAQ.
-- See project doc claude/optic-cut-findings.md for the verification record.

create table public.gun_optic_cuts (
  gun_id     uuid not null references public.guns(id) on delete restrict,
  optic_cut  text not null,   -- joins optic_cut_footprints.optic_cut; ''none'' = not optic-ready
  applies_to text not null,   -- ''default'' | ''all-current-skus'' | ''sku-sl-rxsl'' | ''sku-rs'' | ''legacy-non-optic-ready''
  confidence text not null default ''verified'' check (confidence in (''verified'',''likely'')),
  source_url text,
  notes      text,
  primary key (gun_id, optic_cut, applies_to)
);

-- CLAUDE.md security convention: RLS on, explicit revoke, re-grant only what the policy needs.
alter table public.gun_optic_cuts enable row level security;
revoke all on public.gun_optic_cuts from anon, authenticated;
grant select on public.gun_optic_cuts to anon, authenticated;
create policy gun_optic_cuts_public_read on public.gun_optic_cuts
  for select using (true);

insert into public.gun_optic_cuts (gun_id, optic_cut, applies_to, confidence, source_url, notes)
select g.id, v.optic_cut, v.applies_to, v.confidence, v.source_url, v.notes
from (values
  (''P365'',''rmsc'',''default'',''verified'',''https://www.sigsauer.com/p365-optic-ready.html'',''Current optic-ready SKUs''),
  (''P365'',''sig-loc-compact'',''sku-sl-rxsl'',''verified'',''https://www.sigsauer.com/p365-optic-ready.html'',''-SL SKUs, e.g. 365-9-BXR3P-MS-SL-CA''),
  (''P365'',''none'',''legacy-non-optic-ready'',''verified'',''https://www.sigsauer.com/p365-optic-ready.html'',''Older non-optic-ready SKUs; slide must be milled or replaced''),
  (''P365 X'',''rmsc'',''default'',''verified'',''https://www.sigsauer.com/p365x.html'',null),
  (''P365 X'',''sig-loc-compact'',''sku-sl-rxsl'',''verified'',''https://www.sigsauer.com/p365x.html'',''365X-9-BXR3-RXSL, -RXSL-10''),
  (''P365 XL'',''rmsc'',''all-current-skus'',''verified'',''https://www.sigsauer.com/p365-xl.html'',''All 6 listed SKUs''),
  (''P365 XL Rose Comp'',''rmsc'',''default'',''verified'',''https://www.sigsauer.com/p365-rose-xl-comp.html'',null),
  (''P365 XL Rose Comp'',''sig-loc-compact'',''sku-sl-rxsl'',''verified'',''https://www.sigsauer.com/p365xl-rose-comp-california.html'',''365XL-9-ROSE-MS-SL-CA''),
  (''P365 XMacro'',''rmsc'',''default'',''verified'',''https://www.sigsauer.com/p365-xmacro-1.html'',''Live per-SKU spec read 2026-09-30''),
  (''P365 XMacro'',''sig-loc-compact'',''sku-sl-rxsl'',''likely'',''https://www.sigsauer.com/p365-xmacro-1.html'',''SIG spec field stale: shows RMSc under factory-mounted ROMEO-X SIG-LOC on -RXSL SKUs; SIG-LOC optics require SIG-LOC cut per sigsauer.com/sig-loc''),
  (''P365 XMacro Comp'',''rmsc'',''default'',''verified'',''https://www.sigsauer.com/p365-xmacro.html'',''Live per-SKU spec read 2026-09-30''),
  (''P365 XMacro Comp'',''sig-loc-compact'',''sku-sl-rxsl'',''likely'',''https://www.sigsauer.com/p365-xmacro.html'',''Same stale spec field as XMacro -RXSL''),
  (''P365 AXG Legion'',''rmsc'',''default'',''verified'',''https://www.sigsauer.com/p365-axg-legion.html'',null),
  (''P365 AXG Legion'',''sig-loc-compact'',''sku-sl-rxsl'',''verified'',''https://www.sigsauer.com/p365-axg-legion.html'',''365AXGCA-9-LEGION-RXSL''),
  (''P365 XF DH3'',''rmsc'',''default'',''verified'',''https://www.sigsauer.com/p365-dh3.html'',''365XF-9-DH3, -10; live per-SKU spec read 2026-09-30''),
  (''P365 XF DH3'',''sig-loc-compact'',''sku-sl-rxsl'',''verified'',''https://www.sigsauer.com/p365-dh3.html'',''365XF-9-DH3-RXSL; live per-SKU spec read 2026-09-30''),
  (''P365 XF DH3 AXG'',''rmsc'',''all-current-skus'',''verified'',''https://www.sigsauer.com/p365-dh3-axg.html'',''Both SKUs; live per-SKU spec read 2026-09-30''),
  (''P365 FUSE'',''sig-loc-compact'',''default'',''verified'',''https://www.sigsauer.com/p365-fuse.html'',''BFO, CFO, -10, -MS, -RXSL; the only model defaulting to SIG-LOC; live read 2026-09-30''),
  (''P365 FUSE'',''rmsc'',''sku-rs'',''verified'',''https://www.sigsauer.com/p365-fuse.html'',''365XF-9-BFO-RS (ROMEO-RS equipped); live read 2026-09-30''),
  (''P365 FUSE Comp'',''rmsc'',''default'',''verified'',''https://www.sigsauer.com/p365-fuse-comp.html'',null),
  (''P365 FUSE Comp'',''sig-loc-compact'',''sku-sl-rxsl'',''verified'',''https://www.sigsauer.com/p365-fuse-comp.html'',''365XF-9-COMP-RXSL'')
) as v(gun_name, optic_cut, applies_to, confidence, source_url, notes)
join public.guns g on g.name = v.gun_name;"}', 'gun_optic_cuts', 'ag.gamboa94@gmail.com', NULL, NULL);
INSERT INTO "supabase_migrations"."schema_migrations" ("version", "statements", "name", "created_by", "idempotency_key", "rollback") VALUES ('20260930051232', '{"-- The sig-loc-compact cut, under SIG''s official name.
-- SIG SIG-LOC FAQ (sigsauer.com/sig-loc, read 2026-09-30): \"Traditional top-mount
-- reflex sights are still compatible with our SIG-LOC slides\", with removable
-- recoil lug pins shipped for alignment. SIG-LOC optics mount directly, no plate.

-- The vocabulary row. ''romeo-x'' was the informal placeholder for the same cut
-- (\"Sig FUSE factory cut. Proprietary.\") with ZERO references anywhere
-- (product_variants, optic_cut_footprints, gun_optic_cuts all checked 2026-09-30),
-- so it is removed rather than left as a duplicate name for one concept.
insert into public.optic_cuts (optic_cut, display_name, mounting, notes)
values (''sig-loc-compact'', ''SIG-LOC Compact'', ''direct'',
        ''SIG''''s factory SIG-LOC cut (FUSE default; -SL/-RXSL SKUs family-wide). Superset of RMSc: also accepts traditional top-mount reflex sights per SIG FAQ.'');

delete from public.optic_cuts where optic_cut = ''romeo-x'';

-- Inherit everything the rmsc cut accepts…
insert into public.optic_cut_footprints (optic_cut, footprint_id, fit, notes)
select ''sig-loc-compact'', ocf.footprint_id, ocf.fit,
       ''Inherited from rmsc cut per SIG SIG-LOC FAQ 2026-09-30: traditional top-mount reflex sights compatible with SIG-LOC slides''
from public.optic_cut_footprints ocf
where ocf.optic_cut = ''rmsc'';

-- …plus the native SIG-LOC footprint.
insert into public.optic_cut_footprints (optic_cut, footprint_id, fit, notes)
select ''sig-loc-compact'', f.id, ''direct'',
       ''Native SIG-LOC mount, no adapter plate (sigsauer.com/sig-loc)''
from public.footprints f
where f.slug = ''sig-loc-compact'';"}', 'sig_loc_compact_cut_footprints', 'ag.gamboa94@gmail.com', NULL, NULL);
INSERT INTO "supabase_migrations"."schema_migrations" ("version", "statements", "name", "created_by", "idempotency_key", "rollback") VALUES ('20260930053438', '{"-- footprints held twin rows for one physical pattern:
--   ''holosun-k''    \"Holosun K-Series / Modified RMSc\"  — held all 5 K-series optics, no cut mapped to it
--   ''holosun-507k'' \"Holosun 507K / EPS Carry\"          — held the cut mappings, zero optics
-- Net effect: the DB claimed the Holosun 507K X2 / 407K X2 / EPS / EPS Carry / SCS Carry
-- fit nothing. Verified 2026-09-30: optic_adapter_footprints references neither twin;
-- the only FK tables into footprints are optic_specs, optic_cut_footprints,
-- optic_adapter_footprints. Approved by AG 2026-09-30.

-- Keep the twin''s common name findable on the surviving row.
update public.footprints
   set also_known_as = case when also_known_as is null or also_known_as = ''''
                            then ''Holosun 507K / EPS Carry''
                            else also_known_as || ''; Holosun 507K / EPS Carry'' end
 where slug = ''holosun-k''
   and (also_known_as is null or position(''507K'' in also_known_as) = 0);

-- Repoint the cut mappings (rmsc, holosun-k, sig-loc-compact) onto the surviving row.
update public.optic_cut_footprints
   set footprint_id = (select id from public.footprints where slug = ''holosun-k''),
       notes = coalesce(notes || '' | '', '''') || ''Repointed from empty twin footprint holosun-507k, 2026-09-30''
 where footprint_id = (select id from public.footprints where slug = ''holosun-507k'');

-- Remove the empty twin. If anything still references it, this raises and the
-- whole migration rolls back — that failure would be the finding, not a nuisance.
delete from public.footprints where slug = ''holosun-507k'';"}', 'merge_holosun_footprint_twins', 'ag.gamboa94@gmail.com', NULL, NULL);
INSERT INTO "supabase_migrations"."schema_migrations" ("version", "statements", "name", "created_by", "idempotency_key", "rollback") VALUES ('20261001193258', '{"-- 001 part 1: backfill + archive. (The DROP COLUMN is run separately.)
update public.optic_specs o
   set dot_size_moa = nullif(trim(p.specs->>''dot_size_moa''), '''')::numeric
  from public.products p
 where p.id = o.product_id
   and o.dot_size_moa is null
   and p.specs ? ''dot_size_moa''
   and trim(p.specs->>''dot_size_moa'') ~ ''^[0-9]+(\\.[0-9]+)?$'';

create table if not exists public._archive_products_specs (
  product_id  uuid primary key references public.products(id) on delete cascade,
  category    text not null,
  specs       jsonb not null,
  archived_at timestamptz not null default now()
);
comment on table public._archive_products_specs is
  ''Archive of the retired products.specs jsonb column (migration 001). Safe to drop after one release cycle.'';
alter table public._archive_products_specs enable row level security;

insert into public._archive_products_specs (product_id, category, specs)
select id, category::text, specs
  from public.products
 where specs is not null and specs <> ''{}''::jsonb
on conflict (product_id) do nothing;"}', 'retire_products_specs_jsonb_part1_backfill_archive', 'ag.gamboa94@gmail.com', NULL, NULL);
INSERT INTO "supabase_migrations"."schema_migrations" ("version", "statements", "name", "created_by", "idempotency_key", "rollback") VALUES ('20261001194356', '{"-- 002 part 1: controlled vocab for color + material. (DROP of frame_specs.frame_material is run separately.)

-- A. COLORS ---------------------------------------------------------------
create table if not exists public.colors (
  color        text primary key,
  color_family text not null,
  sort_order   smallint not null default 100,
  notes        text,
  constraint colors_family_chk check (color_family in (
    ''Black'',''Gray'',''Tan/FDE'',''Green'',''Bronze/Copper'',''Gold'',''Silver/Stainless'',
    ''Blue'',''Red'',''Rose'',''Purple'',''Multi'',''Clear'',''Other''))
);
comment on table public.colors is
  ''Controlled vocabulary for product_variants.color. color_family drives the storefront filter; color is the exact shade shown on the card.'';
alter table public.colors enable row level security;
create policy colors_public_read on public.colors for select to anon, authenticated using (true);

insert into public.colors (color, color_family, sort_order) values
  (''Black'',''Black'',10),(''Black Distressed'',''Black'',12),(''Black/Black'',''Black'',14),
  (''Black/Blue'',''Multi'',80),(''Black/Cherry'',''Multi'',80),(''Black/FDE'',''Multi'',80),(''Black/Gold'',''Multi'',80),
  (''Black/Gray'',''Multi'',80),(''Black/Hogue'',''Multi'',80),(''Black/Red'',''Multi'',80),
  (''Gray'',''Gray'',20),(''Stealth Gray'',''Gray'',21),(''Sniper Gray'',''Gray'',22),(''Gun Metal Gray'',''Gray'',23),
  (''Tiger Stripe Gray'',''Gray'',24),(''Tungsten'',''Gray'',25),(''Gray/Black'',''Multi'',80),
  (''FDE'',''Tan/FDE'',30),(''Tan'',''Tan/FDE'',31),(''Coyote'',''Tan/FDE'',32),
  (''ODG'',''Green'',40),(''Green'',''Green'',41),(''Green/Black'',''Multi'',80),
  (''Copper'',''Bronze/Copper'',50),(''Bronze'',''Bronze/Copper'',51),(''Burnt Bronze'',''Bronze/Copper'',52),
  (''Midnight Bronze'',''Bronze/Copper'',53),(''Coyote Bronze'',''Bronze/Copper'',54),(''Red Bronze'',''Bronze/Copper'',55),
  (''Bronze/Black'',''Multi'',80),
  (''Gold'',''Gold'',60),(''Gold/Black'',''Multi'',80),(''Gold/Blue'',''Multi'',80),(''Gold/Gold'',''Gold'',61),
  (''Gold/Gray'',''Multi'',80),(''Gold/Red'',''Multi'',80),
  (''Silver'',''Silver/Stainless'',70),(''Stainless Steel'',''Silver/Stainless'',71),(''Satin Stainless Steel'',''Silver/Stainless'',72),
  (''Blue'',''Blue'',75),(''Red'',''Red'',76),(''Rose Gold'',''Rose'',77),(''Rose'',''Rose'',78),(''Purple'',''Purple'',79),
  (''Spectrum'',''Multi'',85),(''Rainbow'',''Multi'',86),(''Hyena/Black'',''Multi'',87),(''Clear'',''Clear'',90)
on conflict (color) do nothing;

-- ''FDEB'' is Streamlight''s own \"FDE Brown\" (TLR-1 HL #69267): a real shade, renamed not merged.
insert into public.colors (color, color_family, sort_order, notes) values
  (''FDE Brown'',''Tan/FDE'',33,''Streamlight \"Flat Dark Earth Brown\". Darker than standard FDE.'')
on conflict (color) do nothing;

-- Merge duplicates in place (raw -> canonical).
with map(raw, canonical) as (values
  (''Flat Black'',''Black''),(''Matte Black'',''Black''),(''Coyote Tan'',''Coyote''),(''Desert Tan'',''Tan''),
  (''Matte Rose Gold'',''Rose Gold''),(''FDEB'',''FDE Brown''))
update public.product_variants v set color = m.canonical from map m where v.color = m.raw;

-- Safety net: anything still unmapped becomes a visible ''Other'' row rather than a failed migration.
insert into public.colors (color, color_family, sort_order, notes)
select distinct v.color, ''Other'', 999, ''AUTO-ADDED by migration 002 — classify me''
  from public.product_variants v
 where v.color is not null and not exists (select 1 from public.colors c where c.color = v.color);

alter table public.product_variants add constraint product_variants_color_fkey
  foreign key (color) references public.colors(color) on update cascade;
create index if not exists product_variants_color_idx on public.product_variants (color) where retired_at is null;

-- B. MATERIALS ------------------------------------------------------------
create table if not exists public.materials (
  material_family text primary key,
  sort_order      smallint not null default 100,
  notes           text
);
comment on table public.materials is
  ''Filterable material family. The verbose vendor description lives in products.material.'';
alter table public.materials enable row level security;
create policy materials_public_read on public.materials for select to anon, authenticated using (true);

insert into public.materials (material_family, sort_order) values
  (''Aluminum'',10),(''Stainless Steel'',20),(''Steel'',30),(''Polymer'',40),(''Titanium'',50),(''Mixed'',90),(''Unspecified'',99)
on conflict do nothing;

alter table public.products add column if not exists material_family text;
comment on column public.products.material is
  ''Verbose vendor material description for display only. Filter on material_family.'';

update public.products p set material_family = case
     when material is null or material ilike ''not specified'' then ''Unspecified''
     when material ilike ''%basepad%'' and material ilike ''%steel%'' then ''Mixed''
     when material ilike ''%titanium%'' then ''Titanium''
     when material ilike ''%polymer%'' or material ilike ''%nylon%'' or material ilike ''%elastomer%'' then ''Polymer''
     when material ilike ''%alumin%'' then ''Aluminum''
     when material ilike ''%stainless%'' or material ilike ''%17-4%'' or material ilike ''%416R%'' or material ilike ''%SUS630%''
       or material ilike ''%303 %'' or material ilike ''%300-series%'' then ''Stainless Steel''
     when material ilike ''%steel%'' or material ilike ''%DLC%'' then ''Steel''
     else ''Unspecified'' end
 where material_family is null;

alter table public.products add constraint products_material_family_fkey
  foreign key (material_family) references public.materials(material_family) on update cascade;
create index if not exists products_material_family_idx on public.products (material_family);

-- Guard: frame_specs.frame_material must agree with products.material_family before it is dropped.
do $$
declare bad int;
begin
  select count(*) into bad
    from public.frame_specs f join public.products p on p.id = f.product_id
   where f.frame_material is not null
     and p.material_family is distinct from
         case when f.frame_material ilike ''%alum%'' then ''Aluminum''
              when f.frame_material ilike ''%poly%'' then ''Polymer''
              else f.frame_material end;
  if bad > 0 then
    raise exception ''frame_specs.frame_material disagrees with products.material_family on % rows'', bad;
  end if;
end $$;"}', 'colors_and_materials_lookups_part1', 'ag.gamboa94@gmail.com', NULL, NULL);
INSERT INTO "supabase_migrations"."schema_migrations" ("version", "statements", "name", "created_by", "idempotency_key", "rollback") VALUES ('20261001195045', '{"-- 003: one call to add a color/finish variant, fully wired. Plus two data fixes.

-- A. Optics: products.material_family was ''Unspecified'' for all 47 optics even though
--    optic_specs.housing_material was filled. Sync it up (single source of truth = spec table).
update public.products p
   set material = coalesce(p.material, o.housing_material),
       material_family = case
         when o.housing_material ilike ''%titanium%'' then ''Titanium''
         when o.housing_material ilike ''%polymer%''  then ''Polymer''
         when o.housing_material ilike ''%alumin%''   then ''Aluminum''
         when o.housing_material ilike ''%steel%''    then ''Steel''
         else p.material_family end
  from public.optic_specs o
 where o.product_id = p.id and p.material_family = ''Unspecified'' and o.housing_material is not null;

-- B. slugify helper
create or replace function public.slugify(p_text text)
returns text language sql immutable strict set search_path = '''' as $$
  select trim(both ''-'' from regexp_replace(regexp_replace(lower(p_text), ''[^a-z0-9]+'', ''-'', ''g''), ''-{2,}'', ''-'', ''g''));
$$;

-- C. create_variant: variant + primary image + affiliate link, atomically. Admin-only.
create or replace function public.create_variant(
  p_product_slug   text,
  p_color          text,
  p_finish         text        default null,
  p_sku            text        default null,
  p_upc            text        default null,
  p_msrp           numeric     default null,
  p_image_url      text        default null,
  p_partner_slug   text        default null,
  p_url            text        default null,
  p_affiliate_url  text        default null,
  p_street_price   numeric     default null,
  p_in_stock       boolean     default null,
  p_variant_label  text        default null,
  p_optic_cut      text        default null,
  p_handedness     text        default null,
  p_notes          text        default null,
  p_make_default   boolean     default null   -- null = default only if product has none
)
returns uuid language plpgsql security definer set search_path = '''' as $$
declare
  v_product_id uuid; v_variant_id uuid; v_partner_id uuid;
  v_slug text; v_base_slug text; v_n int := 1; v_is_default boolean;
begin
  if not public.is_admin() then
    raise exception ''create_variant: admin only'' using errcode = ''42501'';
  end if;
  select id into v_product_id from public.products where slug = p_product_slug;
  if v_product_id is null then
    raise exception ''create_variant: no product with slug \"%\"'', p_product_slug using errcode = ''foreign_key_violation'';
  end if;
  if p_color is null or btrim(p_color) = '''' then
    raise exception ''create_variant: color is required'';
  end if;
  if not exists (select 1 from public.colors c where c.color = p_color) then
    raise exception ''create_variant: \"%\" is not in public.colors. Add it there first (with a color_family) so the filter stays clean.'',
      p_color using errcode = ''foreign_key_violation'';
  end if;
  if (p_url is not null) <> (p_partner_slug is not null) then
    raise exception ''create_variant: p_url and p_partner_slug must be supplied together'';
  end if;
  if p_partner_slug is not null then
    select id into v_partner_id from public.partners where slug = p_partner_slug;
    if v_partner_id is null then
      raise exception ''create_variant: no partner with slug \"%\"'', p_partner_slug using errcode = ''foreign_key_violation'';
    end if;
  end if;

  -- slug: <product-slug>-<color>[-<finish>], de-duped with -2, -3 ...
  v_base_slug := public.slugify(p_product_slug || ''-'' || p_color || coalesce(''-'' || p_finish, ''''));
  v_slug := v_base_slug;
  while exists (select 1 from public.product_variants where slug = v_slug) loop
    v_n := v_n + 1; v_slug := v_base_slug || ''-'' || v_n;
  end loop;

  -- first variant of a product becomes the default
  v_is_default := coalesce(p_make_default,
    not exists (select 1 from public.product_variants where product_id = v_product_id and is_default));
  if v_is_default then
    update public.product_variants set is_default = false where product_id = v_product_id and is_default;
  end if;

  insert into public.product_variants
    (slug, product_id, color, finish, sku, upc, msrp, is_default, primary_image_url, variant_label, optic_cut, handedness, notes)
  values
    (v_slug, v_product_id, p_color, p_finish, p_sku, p_upc, p_msrp, v_is_default, p_image_url,
     coalesce(p_variant_label, p_color || coalesce('' · '' || p_finish, '''')), p_optic_cut, p_handedness, p_notes)
  returning id into v_variant_id;

  if p_image_url is not null then
    insert into public.variant_images (variant_id, url, position, alt_text)
    values (v_variant_id, p_image_url, 1,
            (select name from public.products where id = v_product_id) || '' — '' || p_color || coalesce('' '' || p_finish, ''''));
  end if;

  -- price_history row is written by the existing record_price_change trigger
  if p_url is not null then
    insert into public.affiliate_links (variant_id, partner_id, url, affiliate_url, street_price, in_stock, last_checked)
    values (v_variant_id, v_partner_id, p_url, p_affiliate_url, p_street_price, p_in_stock,
            case when p_street_price is not null or p_in_stock is not null then current_date end);
  end if;

  return v_variant_id;
end;
$$;

comment on function public.create_variant is
  ''Admin-only. Creates a product variant + primary image + affiliate link in one atomic call. Enforces colors vocab, slug format, one-default-per-product.'';

revoke all on function public.create_variant from public, anon;
grant execute on function public.create_variant to authenticated, service_role;

-- D. Fill the 644 variants that had no variant_label.
update public.product_variants
   set variant_label = color || coalesce('' · '' || finish, '''')
 where variant_label is null and color is not null;"}', 'create_variant_function_and_label_backfill', 'ag.gamboa94@gmail.com', NULL, NULL);
INSERT INTO "supabase_migrations"."schema_migrations" ("version", "statements", "name", "created_by", "idempotency_key", "rollback") VALUES ('20261002012605', '{"alter table public.magazine_families add column if not exists capacity_note text;"}', 'magazine_families_capacity_note', 'ag.gamboa94@gmail.com', NULL, NULL);
INSERT INTO "supabase_migrations"."schema_migrations" ("version", "statements", "name", "created_by", "idempotency_key", "rollback") VALUES ('20261002060332', '{"-- 004_create_variant_backend_callable.sql
-- Let the backend call create_variant(), so bulk loads stop going around it.
--
-- 003 shipped create_variant() and nothing has ever called it. The reason is
-- the guard: is_admin() reads auth.uid(), which is NULL for the service_role
-- key and for a direct psql session. So every real load -- the only way
-- variants actually get added here -- had to bypass the function and write
-- raw INSERTs through the variant_insert_import staging table, which is
-- exactly the \"adding a colour variant is complicated\" problem 003 existed to
-- end. The validation (colour vocabulary, slug format, one-default-per-
-- product, the image and affiliate rows) was built and then routed around.
--
-- THE current_user TRAP. create_variant() is SECURITY DEFINER, so inside it
-- current_user is the function OWNER (postgres), not the caller. A guard
-- written as `current_user in (''service_role'', ...)` would therefore be TRUE
-- for every caller including anon, silently removing the guard entirely.
-- session_user is NOT rewritten by SECURITY DEFINER, and the PostgREST JWT
-- claim is request-scoped, so both survive correctly. Never reach for
-- current_user in a guard inside a SECURITY DEFINER function.

create or replace function public.is_trusted_backend()
returns boolean
language sql
stable
set search_path = ''''
as $$
  -- PostgREST sets request.jwt.claims per request; the service_role key
  -- carries role=service_role. nullif() because the setting is '''' (not NULL)
  -- when absent, and ''''::jsonb raises.
  select coalesce(
           nullif(current_setting(''request.jwt.claims'', true), '''')::jsonb ->> ''role'',
           ''''
         ) = ''service_role''
      -- A direct superuser session (psql, the Supabase SQL editor, the MCP
      -- connection). session_user, not current_user: see the note above.
      or session_user in (''postgres'', ''supabase_admin'');
$$;

comment on function public.is_trusted_backend is
  ''True for the service_role key or a direct superuser session. Uses session_user and the JWT claim because current_user is rewritten to the owner inside SECURITY DEFINER functions.'';

revoke all on function public.is_trusted_backend() from public, anon;
grant execute on function public.is_trusted_backend() to authenticated, service_role;

-- Recreate create_variant with ONLY the guard changed. Body is otherwise
-- byte-identical to what 003 left in place; verified by diff after applying.
create or replace function public.create_variant(p_product_slug text, p_color text, p_finish text DEFAULT NULL::text, p_sku text DEFAULT NULL::text, p_upc text DEFAULT NULL::text, p_msrp numeric DEFAULT NULL::numeric, p_image_url text DEFAULT NULL::text, p_partner_slug text DEFAULT NULL::text, p_url text DEFAULT NULL::text, p_affiliate_url text DEFAULT NULL::text, p_street_price numeric DEFAULT NULL::numeric, p_in_stock boolean DEFAULT NULL::boolean, p_variant_label text DEFAULT NULL::text, p_optic_cut text DEFAULT NULL::text, p_handedness text DEFAULT NULL::text, p_notes text DEFAULT NULL::text, p_make_default boolean DEFAULT NULL::boolean)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''''
AS $function$
declare
  v_product_id uuid; v_variant_id uuid; v_partner_id uuid;
  v_slug text; v_base_slug text; v_n int := 1; v_is_default boolean;
begin
  if not (public.is_admin() or public.is_trusted_backend()) then
    raise exception ''create_variant: admin or service_role only'' using errcode = ''42501'';
  end if;
  select id into v_product_id from public.products where slug = p_product_slug;
  if v_product_id is null then
    raise exception ''create_variant: no product with slug \"%\"'', p_product_slug using errcode = ''foreign_key_violation'';
  end if;
  if p_color is null or btrim(p_color) = '''' then
    raise exception ''create_variant: color is required'';
  end if;
  if not exists (select 1 from public.colors c where c.color = p_color) then
    raise exception ''create_variant: \"%\" is not in public.colors. Add it there first (with a color_family) so the filter stays clean.'',
      p_color using errcode = ''foreign_key_violation'';
  end if;
  if (p_url is not null) <> (p_partner_slug is not null) then
    raise exception ''create_variant: p_url and p_partner_slug must be supplied together'';
  end if;
  if p_partner_slug is not null then
    select id into v_partner_id from public.partners where slug = p_partner_slug;
    if v_partner_id is null then
      raise exception ''create_variant: no partner with slug \"%\"'', p_partner_slug using errcode = ''foreign_key_violation'';
    end if;
  end if;

  -- slug: <product-slug>-<color>[-<finish>], de-duped with -2, -3 ...
  v_base_slug := public.slugify(p_product_slug || ''-'' || p_color || coalesce(''-'' || p_finish, ''''));
  v_slug := v_base_slug;
  while exists (select 1 from public.product_variants where slug = v_slug) loop
    v_n := v_n + 1; v_slug := v_base_slug || ''-'' || v_n;
  end loop;

  -- first variant of a product becomes the default
  v_is_default := coalesce(p_make_default,
    not exists (select 1 from public.product_variants where product_id = v_product_id and is_default));
  if v_is_default then
    update public.product_variants set is_default = false where product_id = v_product_id and is_default;
  end if;

  insert into public.product_variants
    (slug, product_id, color, finish, sku, upc, msrp, is_default, primary_image_url, variant_label, optic_cut, handedness, notes)
  values
    (v_slug, v_product_id, p_color, p_finish, p_sku, p_upc, p_msrp, v_is_default, p_image_url,
     coalesce(p_variant_label, p_color || coalesce('' · '' || p_finish, '''')), p_optic_cut, p_handedness, p_notes)
  returning id into v_variant_id;

  if p_image_url is not null then
    insert into public.variant_images (variant_id, url, position, alt_text)
    values (v_variant_id, p_image_url, 1,
            (select name from public.products where id = v_product_id) || '' — '' || p_color || coalesce('' '' || p_finish, ''''));
  end if;

  -- price_history row is written by the existing record_price_change trigger
  if p_url is not null then
    insert into public.affiliate_links (variant_id, partner_id, url, affiliate_url, street_price, in_stock, last_checked)
    values (v_variant_id, v_partner_id, p_url, p_affiliate_url, p_street_price, p_in_stock,
            case when p_street_price is not null or p_in_stock is not null then current_date end);
  end if;

  return v_variant_id;
end;
$function$;

revoke all on function public.create_variant from public, anon;
grant execute on function public.create_variant to authenticated, service_role;"}', '004_create_variant_backend_callable', 'ag.gamboa94@gmail.com', NULL, NULL);
INSERT INTO "supabase_migrations"."schema_migrations" ("version", "statements", "name", "created_by", "idempotency_key", "rollback") VALUES ('20261002060430', '{"-- Tighten is_trusted_backend: a PostgREST request is judged ONLY by its JWT
-- role claim, never by session_user.
--
-- The first cut allowed `jwt_role = service_role OR session_user in
-- (postgres, supabase_admin)`. That is correct today only because PostgREST
-- logs in as `authenticator` (anon / authenticated / service_role are NOLOGIN
-- and reached via SET ROLE), so a web request can never present
-- session_user = postgres. That is an assumption about Supabase''s role
-- wiring, and a guard should not rest on one. Branching on whether a request
-- context exists at all makes the superuser branch structurally unreachable
-- from HTTP: PostgREST always sets request.jwt.claims, even for anon.
create or replace function public.is_trusted_backend()
returns boolean
language sql
stable
set search_path = ''''
as $$
  select case
    -- A PostgREST request. Decide only on the role claim.
    when nullif(current_setting(''request.jwt.claims'', true), '''') is not null
      then (nullif(current_setting(''request.jwt.claims'', true), '''')::jsonb ->> ''role'') = ''service_role''
    -- No request context: a direct database session (psql, the SQL editor,
    -- the MCP connection), which is superuser-ish by definition.
    -- session_user, NOT current_user: SECURITY DEFINER rewrites current_user
    -- to the function owner and would make this true for every caller.
    else session_user in (''postgres'', ''supabase_admin'')
  end;
$$;

comment on function public.is_trusted_backend is
  ''True for the service_role key, or a direct superuser database session. A PostgREST request is judged solely by its JWT role claim, so anon/authenticated can never reach the superuser branch. Never use current_user here: SECURITY DEFINER rewrites it to the owner.'';"}', '004b_tighten_is_trusted_backend', 'ag.gamboa94@gmail.com', NULL, NULL);
INSERT INTO "supabase_migrations"."schema_migrations" ("version", "statements", "name", "created_by", "idempotency_key", "rollback") VALUES ('20261003223210', '{"-- spec_field_rules.sql
-- NOT YET APPLIED. Dry-run 2026-10-03 against Gunforma-v2 inside one rolled-back
-- transaction, together with create_product.sql — see that PR for the results.
--
-- WHAT A CATEGORY NEEDS, in one place. Read by create_product() (which spec
-- keys it accepts), by product_data_status() (what makes a part APPROVED),
-- and by PR 2''s add-a-part form (what to ask for, in what order, labelled).
-- Three readers of one table instead of three lists that drift.
--
-- One row per (category, field). `field` is the <category>_specs column,
-- except `platform` and `footprint`, which are entered as slugs and stored as
-- platform_id / footprint_id.
--
--   requirement ''required''  APPROVED needs it filled. A part can still be
--                           saved without it — unapproved, and told so.
--   requirement ''optional''  reported as blank, never blocks approval.
--   only_when_field/values  the rule applies only when that field of the
--                           same spec sheet holds one of these values (as
--                           text: ''true'', ''threaded'', …). When the condition
--                           is false the field is NOT APPLICABLE and appears
--                           in neither list. A required only-when field whose
--                           condition holds must be sent with the spec sheet:
--                           create_product() refuses it otherwise.
--
-- HOW THE SEED WAS CHOSEN — measured over every live product on 2026-10-03,
-- not typed from memory:
--   filled on every product of the category  -> required
--   filled on some                           -> optional
--   filled on none, keys, trigger-owned classes -> no row
-- plus the conditional fields as ruled by Alex. Two deliberate departures
-- from the measurement, both ruled:
--   * compensator.length_in is filled on exactly the 5 compensators sold
--     WITHOUT a barrel. It is optional and only applicable then.
--   * optic.housing_material and mag_release.material are the same fact as
--     products.material. Their rows exist so the keys are accepted, but
--     create_product() fills them from products.material and the form does
--     not ask twice.
-- The ten columns no product has ever filled (barrel ballistic_loss and
-- pairs_with_comp_id, frame palm_swell and finger_grooves, optic mount_height,
-- light beam_type, compensator muzzle_flip_reduction, products pros / cons /
-- editor_rating) have no row, so they cannot be entered.
--
-- DEFAULTS. Several required fields have a database default (caliber ''9mm'',
-- capacity_change 0, drop_in true, is_combo false, …). A spec sheet that omits
-- one passes, holding the default. PR 2''s form must make the admin answer each
-- of these explicitly rather than inherit the default silently.
--
-- RULES ARE ROWS. The 2-product categories (slide_release, safety_selector,
-- takedown_lever) are thin evidence; change a row when the catalog says
-- otherwise. slide_plate has no spec table and therefore no rows.

create table if not exists public.spec_field_rules (
  category         public.product_category not null,
  field            text not null,
  requirement      text not null check (requirement in (''required'', ''optional'')),
  only_when_field  text null,
  only_when_values text[] null,
  label            text not null,
  sort_order       int  not null,
  primary key (category, field),
  constraint spec_field_rules_only_when_pair
    check ((only_when_field is null) = (only_when_values is null))
);

comment on table public.spec_field_rules is
  ''What each category''''s spec sheet needs: required / optional / only-when. Read by create_product(), product_data_status() and the add-a-part form.'';

-- RLS plus the explicit revoke CLAUDE.md requires: Supabase''s default ACL
-- grants anon and authenticated every privilege on a new public table, so
-- RLS alone would leave write grants sitting underneath the read policy.
alter table public.spec_field_rules enable row level security;
revoke all on public.spec_field_rules from anon, authenticated;
grant select on public.spec_field_rules to anon, authenticated;

create policy spec_field_rules_public_read on public.spec_field_rules
  for select to anon, authenticated using (true);

insert into public.spec_field_rules (category, field, requirement, only_when_field, only_when_values, label, sort_order) values
  -- slide (40 products): 10 required + 2 only-when
  (''slide'', ''platform'',               ''required'', null, null, ''Platform'', 10),
  (''slide'', ''slide_length_in'',        ''required'', null, null, ''Slide length (in)'', 20),
  (''slide'', ''barrel_length_in'',       ''required'', null, null, ''Barrel length (in)'', 30),
  (''slide'', ''comes_with_sights'',      ''required'', null, null, ''Comes with sights'', 40),
  (''slide'', ''barrel_included'',        ''required'', null, null, ''Barrel included'', 50),
  (''slide'', ''window_cuts'',            ''required'', null, null, ''Window cuts'', 60),
  (''slide'', ''internally_ported'',      ''required'', null, null, ''Internally ported'', 70),
  (''slide'', ''port_style'',             ''required'', ''internally_ported'', array[''true''], ''Port style'', 80),
  (''slide'', ''port_count'',             ''required'', ''internally_ported'', array[''true''], ''Number of ports'', 90),
  (''slide'', ''integrated_comp'',        ''required'', null, null, ''Integrated compensator'', 100),
  (''slide'', ''threaded_barrel_ok'',     ''required'', null, null, ''Takes a threaded barrel'', 110),
  (''slide'', ''required_spring_weight'', ''required'', null, null, ''Recoil spring weight it needs'', 120),

  -- barrel (20): 5 required + 2 only-when + 1 optional
  (''barrel'', ''platform'',            ''required'', null, null, ''Platform'', 10),
  (''barrel'', ''barrel_length_in'',    ''required'', null, null, ''Barrel length (in)'', 20),
  (''barrel'', ''barrel_type'',         ''required'', null, null, ''Barrel type'', 30),
  (''barrel'', ''thread_pitch'',        ''required'', ''barrel_type'', array[''threaded'',''threaded-and-ported''], ''Thread pitch'', 40),
  (''barrel'', ''port_style'',          ''required'', ''barrel_type'', array[''ported'',''threaded-and-ported''], ''Port style'', 50),
  (''barrel'', ''caliber'',             ''required'', null, null, ''Caliber'', 60),
  (''barrel'', ''is_lci'',              ''required'', null, null, ''Loaded-chamber indicator'', 70),
  (''barrel'', ''requires_slide_text'', ''optional'', null, null, ''Slide it requires'', 80),

  -- frame (51): 3 required + 1 only-when + 7 optional
  (''frame'', ''housing_class'',          ''required'', null, null, ''Grip housing class'', 10),
  (''frame'', ''has_rail'',               ''required'', null, null, ''Has an accessory rail'', 20),
  (''frame'', ''grip_rail_type'',         ''required'', ''has_rail'', array[''true''], ''Rail type'', 30),
  (''frame'', ''grip_texture'',           ''required'', null, null, ''Grip texture'', 40),
  (''frame'', ''magwell_type'',           ''optional'', null, null, ''Magwell type'', 50),
  (''frame'', ''has_beaver_tail'',        ''optional'', null, null, ''Beavertail'', 60),
  (''frame'', ''undercut_trigger_guard'', ''optional'', null, null, ''Undercut trigger guard'', 70),
  (''frame'', ''thumb_rest'',             ''optional'', null, null, ''Thumb rest'', 80),
  (''frame'', ''thumb_stippling'',        ''optional'', null, null, ''Thumb stippling'', 90),
  (''frame'', ''includes_hardware'',      ''optional'', null, null, ''Includes hardware'', 100),
  (''frame'', ''hardware_notes'',         ''optional'', null, null, ''Hardware notes'', 110),

  -- optic (47): 19 required + 1 optional
  (''optic'', ''footprint'',            ''required'', null, null, ''Footprint'', 10),
  (''optic'', ''optic_type'',           ''required'', null, null, ''Optic type'', 20),
  (''optic'', ''reticle'',              ''required'', null, null, ''Reticle'', 30),
  (''optic'', ''reticle_type'',         ''required'', null, null, ''Reticle type'', 40),
  (''optic'', ''selectable_reticle'',   ''required'', null, null, ''Selectable reticle'', 50),
  (''optic'', ''dot_size_moa'',         ''optional'', null, null, ''Dot size (MOA)'', 60),
  (''optic'', ''magnification'',        ''required'', null, null, ''Magnification'', 70),
  (''optic'', ''window_size'',          ''required'', null, null, ''Window size'', 80),
  (''optic'', ''emitter'',              ''required'', null, null, ''Emitter'', 90),
  (''optic'', ''enclosed_emitter'',     ''required'', null, null, ''Enclosed emitter'', 100),
  (''optic'', ''brightness_settings'',  ''required'', null, null, ''Brightness settings'', 110),
  (''optic'', ''auto_on_off'',          ''required'', null, null, ''Auto on/off'', 120),
  (''optic'', ''shake_awake'',          ''required'', null, null, ''Shake awake'', 130),
  (''optic'', ''adjustment_per_click'', ''required'', null, null, ''Adjustment per click'', 140),
  (''optic'', ''battery_type'',         ''required'', null, null, ''Battery type'', 150),
  (''optic'', ''battery_location'',     ''required'', null, null, ''Battery location'', 160),
  (''optic'', ''removable_battery'',    ''required'', null, null, ''Removable battery'', 170),
  (''optic'', ''battery_life'',         ''required'', null, null, ''Battery life'', 180),
  (''optic'', ''solar_power'',          ''required'', null, null, ''Solar power'', 190),
  (''optic'', ''housing_material'',     ''required'', null, null, ''Housing material (filled from the product''''s material)'', 200),

  -- light (33): 13 required + 1 only-when
  (''light'', ''series'',                  ''required'', null, null, ''Series'', 10),
  (''light'', ''config_note'',             ''required'', null, null, ''Configuration'', 20),
  (''light'', ''mount_system'',            ''required'', null, null, ''Mount system'', 30),
  (''light'', ''lumens_max'',              ''required'', null, null, ''Lumens (max)'', 40),
  (''light'', ''candela_max'',             ''required'', null, null, ''Candela (max)'', 50),
  (''light'', ''battery_type'',            ''required'', null, null, ''Battery type'', 60),
  (''light'', ''rechargeable'',            ''required'', null, null, ''Rechargeable'', 70),
  (''light'', ''length_in'',               ''required'', null, null, ''Length (in)'', 80),
  (''light'', ''ipx_rating'',              ''required'', null, null, ''IPX rating'', 90),
  (''light'', ''multiple_light_settings'', ''required'', null, null, ''Multiple light settings'', 100),
  (''light'', ''has_strobe'',              ''required'', null, null, ''Strobe'', 110),
  (''light'', ''has_infrared'',            ''required'', null, null, ''Infrared'', 120),
  (''light'', ''has_laser'',               ''required'', null, null, ''Laser'', 130),
  (''light'', ''laser_color'',             ''required'', ''has_laser'', array[''true''], ''Laser color'', 140),

  -- compensator (12): 6 required + 2 only-when + 1 optional only-when
  (''compensator'', ''caliber'',                  ''required'', null, null, ''Caliber'', 10),
  (''compensator'', ''mounting_type'',            ''required'', null, null, ''Mounting type'', 20),
  (''compensator'', ''requires_threaded_barrel'', ''required'', null, null, ''Needs a threaded barrel'', 30),
  (''compensator'', ''thread_pitch'',             ''required'', null, null, ''Thread pitch'', 40),
  (''compensator'', ''port_design'',              ''required'', null, null, ''Port design'', 50),
  (''compensator'', ''comes_with_barrel'',        ''required'', null, null, ''Comes with a barrel'', 60),
  (''compensator'', ''included_barrel'',          ''required'', ''comes_with_barrel'', array[''true''], ''Included barrel'', 70),
  (''compensator'', ''barrel_length_in'',         ''required'', ''comes_with_barrel'', array[''true''], ''Included barrel length (in)'', 80),
  (''compensator'', ''length_in'',                ''optional'', ''comes_with_barrel'', array[''false''], ''Compensator length (in)'', 90),

  -- trigger (8): 5 required + 2 optional
  (''trigger'', ''profile'',          ''required'', null, null, ''Profile'', 10),
  (''trigger'', ''adjustable'',       ''required'', null, null, ''Adjustable'', 20),
  (''trigger'', ''adjustment_type'',  ''required'', null, null, ''Adjustment type'', 30),
  (''trigger'', ''safety_type'',      ''required'', null, null, ''Safety type'', 40),
  (''trigger'', ''drop_in'',          ''required'', null, null, ''Drop-in'', 50),
  (''trigger'', ''pull_weight_lb'',   ''optional'', null, null, ''Pull weight (lb)'', 60),
  (''trigger'', ''pull_weight_text'', ''optional'', null, null, ''Pull weight (as stated)'', 70),

  -- mag_release (8): 3 required + 3 optional
  (''mag_release'', ''caliber'',              ''required'', null, null, ''Caliber'', 10),
  (''mag_release'', ''style'',                ''required'', null, null, ''Style'', 20),
  (''mag_release'', ''texture'',              ''required'', null, null, ''Texture'', 30),
  (''mag_release'', ''material'',             ''optional'', null, null, ''Material (filled from the product''''s material)'', 40),
  (''mag_release'', ''length_added_in'',      ''optional'', null, null, ''Length added (in)'', 50),
  (''mag_release'', ''includes_spring_stop'', ''optional'', null, null, ''Includes spring stop'', 60),

  -- magwell (6): 3 required
  (''magwell'', ''attachment_method'', ''required'', null, null, ''Attachment method'', 10),
  (''magwell'', ''is_combo'',          ''required'', null, null, ''Combo (magwell + grip)'', 20),
  (''magwell'', ''includes_hardware'', ''required'', null, null, ''Includes hardware'', 30),

  -- basepad (8): 3 required
  (''basepad'', ''basepad_type'',    ''required'', null, null, ''Base pad type'', 10),
  (''basepad'', ''fits_mag_type'',   ''required'', null, null, ''Fits magazine'', 20),
  (''basepad'', ''capacity_change'', ''required'', null, null, ''Capacity change (rounds)'', 30),

  -- slide_release (2): 2 required
  (''slide_release'', ''texture'',         ''required'', null, null, ''Texture'', 10),
  (''slide_release'', ''uses_oem_spring'', ''required'', null, null, ''Uses the OEM spring'', 20),

  -- safety_selector (2): 3 required
  (''safety_selector'', ''is_ambidextrous'',        ''required'', null, null, ''Ambidextrous'', 10),
  (''safety_selector'', ''includes_detent_spring'', ''required'', null, null, ''Includes detent spring'', 20),
  (''safety_selector'', ''kit_contents'',           ''required'', null, null, ''Kit contents'', 30),

  -- takedown_lever (2): 2 required + 1 optional
  (''takedown_lever'', ''takedown_type'',             ''required'', null, null, ''Takedown type'', 10),
  (''takedown_lever'', ''has_thumb_rest'',            ''required'', null, null, ''Thumb rest'', 20),
  (''takedown_lever'', ''optic_compatibility_notes'', ''optional'', null, null, ''Optic compatibility notes'', 30);
"}', 'spec_field_rules', 'ag.gamboa94@gmail.com', NULL, NULL);
INSERT INTO "supabase_migrations"."schema_migrations" ("version", "statements", "name", "created_by", "idempotency_key", "rollback") VALUES ('20261003223355', '{"-- create_product.sql
-- NOT YET APPLIED. Dry-run 2026-10-03 against Gunforma-v2 inside one
-- transaction that was rolled back (a DO block ending in RAISE EXCEPTION);
-- the results are in the PR. Apply spec_field_rules.sql FIRST: every function
-- here reads that table.
--
-- WHY. There was no way to add ONE product. Every product arrived in a bulk
-- load, create_variant() only adds to a product that already exists, and the
-- catalog tables carry SELECT policies only, so a signed-in admin cannot
-- write them from the site.
--
-- WHAT. One atomic call that writes everything an admin enters for a part:
--   p_product   brand (find-or-create), name, category, platforms[], slug, url,
--               description, family, material, material_family, fitment_notes,
--               build_warning, build_notes, weight_oz, fitment_confidence,
--               internal_notes
--   p_variants  one object per variant: colour/finish/sku/upc/msrp/label/notes,
--               every option column, image_url + gallery[], and links[]
--               (zero or more retailers; partner_slug + url on the variant
--               itself is shorthand for one)
--   p_specs     the category''s <category>_specs row. Accepted keys are exactly
--               the category''s spec_field_rules fields; `platform` and
--               `footprint` take slugs.
--   p_fits      light: light_compatibility[] · optic: adapter_footprints[] ·
--               barrel: slides[] · slide: barrels[] · magwell: frames[] ·
--               frame: magwells[]
--   p_build_id + p_part_index  swap a build''s pending custom part for this
--               product (the variant flagged use_in_build, else the default)
--   p_dry_run   do everything, then raise P0DRY with the result in DETAIL so
--               nothing is written. The form''s \"Check\" button uses it, and it
--               is the only safe way to try a part against production:
--               affiliate_links and price_history are ON DELETE RESTRICT, so a
--               real test product that got a link can never be deleted.
--
-- SAVING needs only: brand, name, category, at least one platform, the source
-- URL (the product page the data came from — a reference, rendered nowhere),
-- one variant, and a photo and MSRP on the default variant. Retailer links
-- are optional. A part can be saved unapproved; it cannot be saved silently
-- unapproved — the result always carries product_data_status().
--
-- APPROVED (product_data_status): description, material and material_family;
-- every required spec_field_rules field for the category (only-when fields
-- where their condition holds); a photo and an MSRP on every live variant;
-- at least one platform; and for a light, at least one light_compatibility
-- row. A retailer link is reported but never blocks approval.
-- fitment_confidence other than ''unverified'' is refused unless approved.
--
-- PLATFORM IS EXPLICIT. Nothing defaults to P365. A slide or barrel belongs to
-- exactly one platform, and its spec row''s platform is that one. A not-yet-
-- live platform is accepted (parts go in ahead of launch) with a warning.
--
-- NEVER ENTERED: the sync''s columns (street_price, in_stock, last_checked,
-- op_last_matched_by), trigger-owned slide_class / barrel_class, any spec
-- column with no spec_field_rules row (including the ten no product has ever
-- filled), and products.pros / cons / editor_rating / installation_difficulty
-- / best_for. Existing values in those columns are untouched.
--
-- TRACKED LINKS ARE BUILT, NOT TYPED, for partners with an awin_merchant_id.
-- A supplied Awin link whose merchant id disagrees with the partner is
-- refused: 17 of 25 live Olight links carry OpticsPlanet''s id.
--
-- WARNINGS, not errors: a new slide that is not added to the barrels that
-- carry a slide whitelist, and a new frame not added to the whitelisted
-- magwells, will show as NOT fitting them. The result names them.
--
-- The spec vocabulary and the variant vocabulary are different on purpose
-- (optic_specs.reticle \"2 MOA Dot & 32 MOA Circle (MRS)\" vs variant \"MRS\";
-- light_specs.battery_type vs variant \"Rechargeable\"), so nothing is copied
-- between them. Material IS one fact: products.material fills
-- optic_specs.housing_material / mag_release_specs.material, and the reverse
-- when only the spec side is given. A disagreement is refused.
--
-- Never use current_user in the guard: SECURITY DEFINER rewrites it to the
-- owner. See create_variant_backend_callable.sql.

create or replace function public.url_encode(p text) returns text
language sql immutable strict set search_path = '''' as $ue$
  select coalesce(string_agg(
    case when ch ~ ''^[A-Za-z0-9_.~-]$'' then ch
         else upper(regexp_replace(encode(convert_to(ch, ''UTF8''), ''hex''), ''(..)'', ''%\\1'', ''g'')) end,
    '''' order by ord), '''')
  from regexp_split_to_table(p, '''') with ordinality as t(ch, ord);
$ue$;

-- A form sends \"\" (or null, or []) for an untouched field. Treat it as absent.
create or replace function public.jsonb_strip_blank(j jsonb) returns jsonb
language sql immutable set search_path = '''' as $sb$
  select coalesce((select jsonb_object_agg(e.key, e.value) from jsonb_each(j) e
                    where e.value not in (''\"\"''::jsonb, ''null''::jsonb, ''[]''::jsonb)), ''{}''::jsonb);
$sb$;

-- ── how complete a product is ───────────────────────────────────────────────
-- { approved, missing[], optional_blank[], platforms[] }. Reads only catalog
-- data, as the caller. A field whose only-when condition is false is not
-- applicable and appears in neither list. Spec fields are reported as
-- \"spec.<field>\"; the form maps them to spec_field_rules.label.
create or replace function public.product_data_status(p_product_id uuid) returns jsonb
language plpgsql stable set search_path = '''' as $ds$
declare
  pr record; j jsonb; v_tbl regclass; r record; v_col text; v_val text;
  v_missing text[] := ''{}''; v_opt text[] := ''{}''; v_platforms text[];
begin
  select p.id, p.category, p.description, p.material, p.material_family::text as material_family,
         p.url, p.weight_oz, p.fitment_notes
    into pr from public.products p where p.id = p_product_id;
  if not found then return null; end if;

  if coalesce(btrim(pr.description), '''') = ''''     then v_missing := v_missing || ''description''::text; end if;
  if coalesce(btrim(pr.material), '''') = ''''        then v_missing := v_missing || ''material''::text; end if;
  if coalesce(btrim(pr.material_family), '''') = '''' then v_missing := v_missing || ''material_family''::text; end if;

  v_platforms := array(select pl.slug from public.product_platforms pp join public.platforms pl on pl.id = pp.platform_id
                        where pp.product_id = p_product_id order by pl.slug);
  if cardinality(v_platforms) = 0 then v_missing := v_missing || ''platform''::text; end if;

  v_tbl := to_regclass(''public.'' || quote_ident(pr.category::text || ''_specs''));
  if v_tbl is not null then
    execute format(''select to_jsonb(s) from %s s where s.product_id = $1'', v_tbl) into j using p_product_id;
  end if;
  j := coalesce(j, ''{}''::jsonb);   -- no spec row: every applicable required field is missing
  for r in select f.field, f.requirement, f.only_when_field, f.only_when_values
             from public.spec_field_rules f where f.category = pr.category order by f.sort_order loop
    if r.only_when_field is not null and not coalesce((j ->> r.only_when_field) = any (r.only_when_values), false) then
      continue;   -- not applicable
    end if;
    v_col := case r.field when ''platform'' then ''platform_id'' when ''footprint'' then ''footprint_id'' else r.field end;
    v_val := j ->> v_col;
    if coalesce(btrim(v_val), '''') = '''' then
      if r.requirement = ''required'' then v_missing := v_missing || (''spec.'' || r.field);
      else v_opt := v_opt || (''spec.'' || r.field); end if;
    end if;
  end loop;

  if not exists (select 1 from public.product_variants pv where pv.product_id = p_product_id and pv.retired_at is null) then
    v_missing := v_missing || ''variant''::text;
  end if;
  v_missing := v_missing || array(select ''variant '' || pv.slug || '': photo'' from public.product_variants pv
                                   where pv.product_id = p_product_id and pv.retired_at is null and pv.primary_image_url is null order by pv.slug);
  v_missing := v_missing || array(select ''variant '' || pv.slug || '': msrp'' from public.product_variants pv
                                   where pv.product_id = p_product_id and pv.retired_at is null and pv.msrp is null order by pv.slug);

  if pr.category = ''light'' and not exists (select 1 from public.light_compatibility lc where lc.light_product_id = p_product_id) then
    v_missing := v_missing || ''light compatibility''::text;
  end if;

  if not exists (select 1 from public.affiliate_links al join public.product_variants pv on pv.id = al.variant_id
                  where pv.product_id = p_product_id and pv.retired_at is null and al.retired_at is null) then
    v_opt := v_opt || ''retailer link''::text;
  end if;
  if coalesce(btrim(pr.url), '''') = ''''           then v_opt := v_opt || ''url''::text; end if;
  if pr.weight_oz is null                       then v_opt := v_opt || ''weight_oz''::text; end if;
  if coalesce(btrim(pr.fitment_notes), '''') = '''' then v_opt := v_opt || ''fitment_notes''::text; end if;

  return jsonb_build_object(''approved'', cardinality(v_missing) = 0, ''missing'', to_jsonb(v_missing),
                            ''optional_blank'', to_jsonb(v_opt), ''platforms'', to_jsonb(v_platforms));
end;
$ds$;

revoke all on function public.product_data_status(uuid) from public, anon;
grant execute on function public.product_data_status(uuid) to authenticated, service_role;

create or replace function public.create_product(
  p_product jsonb, p_variants jsonb, p_specs jsonb default null, p_fits jsonb default null,
  p_build_id uuid default null, p_part_index integer default null, p_dry_run boolean default false)
returns jsonb
language plpgsql security definer set search_path = ''''
as $fn$
declare
  c_awin_affid   constant text   := ''2959345'';   -- Gunforma''s Awin publisher id; public, it is in every live link
  c_product_keys constant text[] := array[''brand'',''name'',''category'',''platforms'',''slug'',''url'',''description'',''family'',''material'',''material_family'',''fitment_notes'',''build_warning'',''build_notes'',''weight_oz'',''fitment_confidence'',''internal_notes''];
  c_variant_keys constant text[] := array[''color'',''finish'',''sku'',''upc'',''msrp'',''image_url'',''gallery'',''variant_label'',''optic_cut'',''handedness'',''notes'',''is_default'',''manual_safety_variant'',''reticle'',''reticle_color'',''battery_type'',''mount_system'',''bundle'',''clamp_style'',''clamp_rail_type'',''clamp'',''partner_slug'',''url'',''affiliate_url'',''links'',''use_in_build''];
  c_link_keys    constant text[] := array[''partner_slug'',''url'',''affiliate_url'',''op_mpn'',''op_gtin'',''op_merchant_product_id'',''notes''];
  p jsonb; s jsonb; f jsonb; v jsonb; l jsonb; r jsonb; v_result jsonb; v_status jsonb;
  v_category public.product_category; v_want public.product_category; v_platforms text[];
  v_platform_id uuid; v_platform_name text; v_kind text; v_len numeric; v_lengths text;
  v_brand_id uuid; v_brand_name text; v_brand_created boolean := false;
  v_product_id uuid; v_slug text; v_name text; v_confidence public.fitment_confidence;
  v_i int := 0; v_bad text; v_n int; v_key text;
  v_variant_id uuid; v_build_variant uuid; v_links jsonb; v_partner_id uuid; v_other_id uuid;
  v_mid text; v_aff text; v_aff_mid text;
  v_axes text; v_vslug text; v_vbase text; v_part jsonb;
  v_tbl regclass; v_rule_fields text[]; v_collist text; v_has_specs boolean := false;
  v_warn text[] := ''{}'';
begin
  if not (public.is_admin() or public.is_trusted_backend()) then
    raise exception ''create_product: admin or service_role only'' using errcode = ''42501'';
  end if;
  if p_product is null or jsonb_typeof(p_product) <> ''object'' then
    raise exception ''create_product: p_product must be an object'';
  end if;
  p := public.jsonb_strip_blank(p_product);
  if p ? ''installation_difficulty'' or p ? ''best_for'' then
    raise exception ''create_product: installation_difficulty and best_for are no longer entered. Existing values stay where they are; leave these out.'';
  end if;
  select string_agg(k, '', '') into v_bad from jsonb_object_keys(p) k where k <> all (c_product_keys);
  if v_bad is not null then raise exception ''create_product: unknown product field(s): %'', v_bad; end if;
  v_name := btrim(coalesce(p->>''name'', ''''));
  if btrim(coalesce(p->>''brand'', '''')) = '''' or v_name = '''' then
    raise exception ''create_product: brand and name are required'';
  end if;
  if p->>''category'' is null then raise exception ''create_product: category is required''; end if;
  v_category := (p->>''category'')::public.product_category;
  v_confidence := coalesce((p->>''fitment_confidence'')::public.fitment_confidence, ''unverified'');

  -- ── platform: explicit, never defaulted ───────────────────────────────────
  if jsonb_typeof(p->''platforms'') is distinct from ''array'' or jsonb_array_length(p->''platforms'') = 0 then
    raise exception ''create_product: send at least one platform (e.g. \"platforms\": [\"p365\"]). Nothing defaults: without one the part never appears in the builder.'';
  end if;
  v_platforms := array(select distinct x from jsonb_array_elements_text(p->''platforms'') x order by x);
  select string_agg(x, '', '') into v_bad from unnest(v_platforms) x where not exists (select 1 from public.platforms pl where pl.slug = x);
  if v_bad is not null then
    raise exception ''create_product: unknown platform(s): %. Known: %'', v_bad,
      (select string_agg(slug, '', '' order by slug) from public.platforms) using errcode = ''foreign_key_violation'';
  end if;
  if v_category in (''slide'', ''barrel'') and cardinality(v_platforms) <> 1 then
    raise exception ''create_product: a % belongs to exactly one platform; this one names %: %. Send one.'',
      v_category, cardinality(v_platforms), array_to_string(v_platforms, '', '');
  end if;
  select string_agg(pl.name, '', '' order by pl.name) into v_bad from public.platforms pl
   where pl.slug = any (v_platforms) and not pl.is_live;
  if v_bad is not null then
    v_warn := v_warn || (''Not live yet: '' || v_bad || ''. The part is saved and appears when the platform launches.'');
  end if;

  if p->>''url'' is null then
    raise exception ''create_product: the source URL (the product page the data came from) is required'';
  end if;
  if p_variants is null or jsonb_typeof(p_variants) <> ''array'' or jsonb_array_length(p_variants) = 0 then
    raise exception ''create_product: at least one variant is required'';
  end if;
  if (p_build_id is null) <> (p_part_index is null) or p_part_index < 0 then
    raise exception ''create_product: p_build_id and p_part_index must be supplied together'';
  end if;

  select m.id, m.name into v_brand_id, v_brand_name from public.manufacturers m
   where lower(m.name) = lower(btrim(p->>''brand'')) or m.slug = public.slugify(p->>''brand'')
   order by m.created_at limit 1;
  if v_brand_id is null then
    insert into public.manufacturers (slug, name) values (public.slugify(p->>''brand''), btrim(p->>''brand''))
    returning id, name into v_brand_id, v_brand_name;
    v_brand_created := true;
  end if;

  -- The slug is the product''s URL for good. Brand is prefixed unless the name
  -- already starts with it. Pass \"slug\" to choose it by hand.
  v_slug := coalesce(nullif(btrim(p->>''slug''), ''''),
    public.slugify(case when left(lower(v_name), length(v_brand_name)) = lower(v_brand_name)
                        then v_name else v_brand_name || '' '' || v_name end));
  if exists (select 1 from public.products where slug = v_slug) then
    raise exception ''create_product: a product with slug \"%\" already exists. To add a colour or option to it, use create_variant.'', v_slug using errcode = ''unique_violation'';
  end if;
  if exists (select 1 from public.products where brand_id = v_brand_id and lower(name) = lower(v_name)) then
    raise exception ''create_product: % already has a product named \"%\". To add a colour or option to it, use create_variant.'', v_brand_name, v_name using errcode = ''unique_violation'';
  end if;

  insert into public.products (slug, category, brand_id, name, family, url, description, material, material_family,
                               fitment_notes, build_warning, build_notes, weight_oz, fitment_confidence)
  values (v_slug, v_category, v_brand_id, v_name, p->>''family'', p->>''url'', p->>''description'', p->>''material'', p->>''material_family'',
          p->>''fitment_notes'', p->>''build_warning'', p->>''build_notes'', (p->>''weight_oz'')::numeric, ''unverified'')
  returning id into v_product_id;
  -- fitment_confidence is set at the end, once the part is known to be approved

  if p ? ''internal_notes'' then
    insert into public.product_internal (product_id, internal_notes) values (v_product_id, p->>''internal_notes'');
  end if;

  insert into public.product_platforms (product_id, platform_id)
  select v_product_id, pl.id from public.platforms pl where pl.slug = any (v_platforms);

  -- ── spec sheet ────────────────────────────────────────────────────────────
  -- Accepted keys are the category''s spec_field_rules fields and nothing else.
  -- Only supplied keys are named in the INSERT, so column defaults survive.
  s := public.jsonb_strip_blank(p_specs);
  v_tbl := to_regclass(''public.'' || quote_ident(v_category::text || ''_specs''));
  v_rule_fields := array(select fr.field from public.spec_field_rules fr where fr.category = v_category order by fr.sort_order);
  if s <> ''{}''::jsonb then
    if v_tbl is null then raise exception ''create_product: a % has no spec sheet; leave p_specs out'', v_category; end if;
    select string_agg(k, '', '') into v_bad from jsonb_object_keys(s) k where k <> all (v_rule_fields);
    if v_bad is not null then
      raise exception ''create_product: spec sheet: no rule for field(s): %. Fields for a %: %'', v_bad, v_category, array_to_string(v_rule_fields, '', '');
    end if;

    -- platform: the product''s one platform. A disagreeing key is refused.
    if ''platform'' = any (v_rule_fields) then
      if s ? ''platform'' and s->>''platform'' <> v_platforms[1] then
        raise exception ''create_product: spec sheet platform \"%\" disagrees with the product''''s platform \"%\"'', s->>''platform'', v_platforms[1];
      end if;
      select pl.id, pl.name into v_platform_id, v_platform_name from public.platforms pl where pl.slug = v_platforms[1];
      s := (s - ''platform'') || jsonb_build_object(''platform_id'', v_platform_id);
    end if;
    if s ? ''footprint'' then
      select fp.id into v_other_id from public.footprints fp where fp.slug = s->>''footprint'';
      if v_other_id is null then
        raise exception ''create_product: spec sheet: no footprint \"%\". Known: %'', s->>''footprint'',
          (select string_agg(slug, '', '' order by slug) from public.footprints);
      end if;
      s := (s - ''footprint'') || jsonb_build_object(''footprint_id'', v_other_id);
    end if;

    -- material is one fact held in two places
    foreach v_key in array array[''housing_material'', ''material''] loop
      if v_key = any (v_rule_fields) then
        if s ? v_key and p ? ''material'' and lower(btrim(s->>v_key)) <> lower(btrim(p->>''material'')) then
          raise exception ''create_product: material is one fact: the product says \"%\" but the spec sheet''''s % says \"%\"'', p->>''material'', v_key, s->>v_key;
        elsif not s ? v_key and p ? ''material'' then
          s := s || jsonb_build_object(v_key, p->>''material'');
        elsif s ? v_key and not p ? ''material'' then
          update public.products set material = s->>v_key where id = v_product_id;
        end if;
      end if;
    end loop;

    -- only-when fields whose condition holds must come with the sheet
    select string_agg(fr.field, '', '' order by fr.sort_order) into v_bad from public.spec_field_rules fr
     where fr.category = v_category and fr.requirement = ''required'' and fr.only_when_field is not null
       and (s ->> fr.only_when_field) = any (fr.only_when_values)
       and coalesce(btrim(s ->> fr.field), '''') = '''';
    if v_bad is not null then
      raise exception ''create_product: the % spec sheet needs % (it applies here because of %)'', v_category, v_bad,
        (select string_agg(distinct fr.only_when_field || '' = '' || (s ->> fr.only_when_field), '', '') from public.spec_field_rules fr
          where fr.category = v_category and fr.only_when_field is not null and fr.field = any (string_to_array(v_bad, '', '')));
    end if;

    -- slide / barrel length must be registered for that platform. Checked
    -- here so an admin reads a sentence, not the class trigger''s raw text.
    if v_category in (''slide'', ''barrel'') then
      v_kind := v_category::text;
      v_len  := (s ->> (v_kind || ''_length_in''))::numeric;
      if v_len is not null then
        if not exists (select 1 from public.platform_part_lengths ppl where ppl.platform_id = v_platform_id and ppl.part_kind = v_kind) then
          raise exception ''create_product: % % lengths are not registered yet. Add them to platform_part_lengths before adding a % for it.'',
            v_platform_name, v_kind, v_kind;
        end if;
        if not exists (select 1 from public.platform_part_lengths ppl
                        where ppl.platform_id = v_platform_id and ppl.part_kind = v_kind and ppl.length_in = v_len) then
          select string_agg(ppl.length_in::text, '', '' order by ppl.length_in) into v_lengths from public.platform_part_lengths ppl
           where ppl.platform_id = v_platform_id and ppl.part_kind = v_kind;
          raise exception ''create_product: no % % is registered at % in. Registered % lengths: %.'', v_platform_name, v_kind, v_len, v_kind, v_lengths;
        end if;
      end if;
    end if;

    -- columns the table itself declares NOT NULL without a default
    select string_agg(a.attname::text, '', '') into v_bad from pg_catalog.pg_attribute a
     where a.attrelid = v_tbl and a.attnum > 0 and not a.attisdropped and a.attnotnull and not a.atthasdef
       and a.attname::text not in (''product_id'', ''category'') and not s ? (a.attname::text);
    if v_bad is not null then
      raise exception ''create_product: the % spec sheet needs: %'', v_category, replace(replace(v_bad, ''footprint_id'', ''footprint''), ''platform_id'', ''platform'');
    end if;

    s := s || jsonb_build_object(''product_id'', v_product_id, ''category'', v_category);
    select string_agg(quote_ident(k), '', '') into v_collist from jsonb_object_keys(s) k;
    execute format(''insert into %s (%s) select %s from jsonb_populate_record(null::%s, $1)'', v_tbl, v_collist, v_collist, v_tbl) using s;
    v_has_specs := true;
  end if;

  -- ── variants ──────────────────────────────────────────────────────────────
  for v in select value from jsonb_array_elements(p_variants) loop
    v_i := v_i + 1;
    if jsonb_typeof(v) <> ''object'' then raise exception ''create_product: variant % is not an object'', v_i; end if;
    v := public.jsonb_strip_blank(v);
    select string_agg(k, '', '') into v_bad from jsonb_object_keys(v) k where k <> all (c_variant_keys);
    if v_bad is not null then
      raise exception ''create_product: variant %: unknown field(s): %'', v_i, v_bad;
    end if;

    -- colour vocabulary, slug, default flag and the position-1 image row are
    -- create_variant''s rules; they are not restated here.
    v_variant_id := public.create_variant(
      p_product_slug => v_slug, p_color => v->>''color'', p_finish => v->>''finish'', p_sku => v->>''sku'', p_upc => v->>''upc'',
      p_msrp => (v->>''msrp'')::numeric, p_image_url => v->>''image_url'', p_variant_label => v->>''variant_label'',
      p_optic_cut => v->>''optic_cut'', p_handedness => v->>''handedness'', p_notes => v->>''notes'',
      p_make_default => case when (v->>''is_default'')::boolean then true end);

    -- the options create_variant does not carry; when present they also go into the slug
    v_axes := concat_ws(''-'', nullif(v->>''optic_cut'',''none''), v->>''reticle_color'', v->>''reticle'', v->>''clamp'', v->>''bundle'',
                        case when (v->>''manual_safety_variant'')::boolean then ''ms'' end,
                        case when v->>''handedness'' in (''left'',''right'') then v->>''handedness'' end);
    v_vslug := null;
    if v_axes <> '''' then
      v_vbase := public.slugify(v_slug || ''-'' || v_axes || ''-'' || (v->>''color'') || coalesce(''-'' || (v->>''finish''), ''''));
      v_vslug := v_vbase; v_n := 1;
      while exists (select 1 from public.product_variants where slug = v_vslug and id <> v_variant_id) loop
        v_n := v_n + 1; v_vslug := v_vbase || ''-'' || v_n;
      end loop;
    end if;
    update public.product_variants set
      slug = coalesce(v_vslug, slug),
      manual_safety_variant = (v->>''manual_safety_variant'')::boolean,
      reticle = v->>''reticle'', reticle_color = v->>''reticle_color'', battery_type = v->>''battery_type'',
      mount_system = v->>''mount_system'', bundle = v->>''bundle'', clamp_style = v->>''clamp_style'',
      clamp_rail_type = v->>''clamp_rail_type'', clamp = v->>''clamp''
    where id = v_variant_id;

    if v ? ''gallery'' then
      if v->>''image_url'' is null then
        raise exception ''create_product: variant %: gallery photos need a main photo first'', v_i;
      end if;
      insert into public.variant_images (variant_id, url, position)
      select v_variant_id, g.url, (g.ord + 1)::smallint
        from jsonb_array_elements_text(v->''gallery'') with ordinality g(url, ord);
    end if;

    -- retailer links: zero or more per variant. street_price / in_stock /
    -- last_checked / op_last_matched_by are never set — the sync owns them.
    v_links := coalesce(v->''links'', ''[]''::jsonb);
    if jsonb_typeof(v_links) <> ''array'' then raise exception ''create_product: variant %: links must be a list'', v_i; end if;
    if v ? ''url'' or v ? ''partner_slug'' or v ? ''affiliate_url'' then
      v_links := v_links || jsonb_build_array(jsonb_build_object(''partner_slug'', v->>''partner_slug'', ''url'', v->>''url'', ''affiliate_url'', v->>''affiliate_url''));
    end if;
    for l in select value from jsonb_array_elements(v_links) loop
      l := public.jsonb_strip_blank(l);
      select string_agg(k, '', '') into v_bad from jsonb_object_keys(l) k where k <> all (c_link_keys);
      if v_bad is not null then raise exception ''create_product: variant %: retailer link: unknown field(s): %'', v_i, v_bad; end if;
      if l->>''partner_slug'' is null or l->>''url'' is null then
        raise exception ''create_product: variant %: each retailer link needs a retailer and a URL'', v_i;
      end if;
      select pa.id, pa.awin_merchant_id into v_partner_id, v_mid from public.partners pa where pa.slug = l->>''partner_slug'';
      if v_partner_id is null then
        raise exception ''create_product: variant %: no partner with slug \"%\"'', v_i, l->>''partner_slug'' using errcode = ''foreign_key_violation'';
      end if;
      v_aff := l->>''affiliate_url'';
      if v_mid is not null then
        if v_aff is null then
          v_aff := ''https://www.awin1.com/cread.php?awinmid='' || v_mid || ''&awinaffid='' || c_awin_affid
                || ''&clickref='' || public.url_encode(''build-detail_'' || v_slug)
                || ''&ued='' || public.url_encode(l->>''url'');
        elsif v_aff ~ ''awin1\\.com'' then
          v_aff_mid := coalesce(substring(v_aff from ''[?&]awinmid=(\\d+)''), substring(v_aff from ''[?&]m=(\\d+)''));
          if v_aff_mid is distinct from v_mid then
            raise exception ''create_product: variant %: the tracked link carries Awin merchant % but partner \"%\" is merchant %'', v_i, coalesce(v_aff_mid,''(none)''), l->>''partner_slug'', v_mid;
          end if;
        end if;
      end if;
      insert into public.affiliate_links (variant_id, partner_id, url, affiliate_url, notes, op_mpn, op_gtin, op_merchant_product_id)
      values (v_variant_id, v_partner_id, l->>''url'', v_aff, l->>''notes'', l->>''op_mpn'', l->>''op_gtin'', l->>''op_merchant_product_id'');
    end loop;

    if (v->>''use_in_build'')::boolean then v_build_variant := v_variant_id; end if;
  end loop;

  if exists (select 1 from public.product_variants where product_id = v_product_id
             group by color, finish, optic_cut, handedness, manual_safety_variant, reticle, reticle_color,
                      battery_type, mount_system, bundle, clamp, clamp_style, clamp_rail_type
             having count(*) > 1) then
    raise exception ''create_product: two variants are identical on every option. Each one must differ by colour, finish or another option.'';
  end if;
  if exists (select 1 from public.product_variants pv where pv.product_id = v_product_id and pv.is_default
               and (pv.primary_image_url is null or pv.msrp is null)) then
    raise exception ''create_product: the default variant needs a photo and an MSRP'';
  end if;

  -- ── fits-with rules ───────────────────────────────────────────────────────
  f := public.jsonb_strip_blank(p_fits);
  for v_key, r in select e.key, e.value from jsonb_each(f) e loop
    if not ((v_category = ''light''   and v_key = ''light_compatibility'')
         or (v_category = ''optic''   and v_key = ''adapter_footprints'')
         or (v_category = ''barrel''  and v_key = ''slides'')
         or (v_category = ''slide''   and v_key = ''barrels'')
         or (v_category = ''magwell'' and v_key = ''frames'')
         or (v_category = ''frame''   and v_key = ''magwells'')) then
      raise exception ''create_product: fits-with rule \"%\" does not apply to a %. (light: light_compatibility; optic: adapter_footprints; barrel: slides; slide: barrels; magwell: frames; frame: magwells)'', v_key, v_category;
    end if;
    if jsonb_typeof(r) <> ''array'' then raise exception ''create_product: fits-with rule \"%\" must be a list'', v_key; end if;
    -- these four reference the <category>_specs row, not products
    if v_key in (''light_compatibility'',''adapter_footprints'',''slides'',''barrels'') and not v_has_specs then
      raise exception ''create_product: fits-with rules for a % need its spec sheet filled in first'', v_category;
    end if;
    for l in select value from jsonb_array_elements(r) loop
      if jsonb_typeof(l) = ''string'' then l := jsonb_build_object(''product'', l #>> ''{}''); end if;
      l := public.jsonb_strip_blank(l);
      if v_key = ''light_compatibility'' then
        select string_agg(k, '', '') into v_bad from jsonb_object_keys(l) k
         where k <> all (array[''rail_type'',''fitment_type'',''key_or_adapter'',''gun_make'',''gun'',''gun_model_text'',''confirmed'',''notes'']);
        if v_bad is not null then raise exception ''create_product: light_compatibility: unknown field(s): %'', v_bad; end if;
        v_other_id := null;
        if l ? ''gun'' then
          select g.id into v_other_id from public.guns g where g.slug = l->>''gun'';
          if v_other_id is null then raise exception ''create_product: light_compatibility: no gun \"%\"'', l->>''gun''; end if;
        end if;
        insert into public.light_compatibility (light_product_id, rail_type, fitment_type, key_or_adapter, gun_make, gun_id, gun_model_text, confirmed, notes)
        values (v_product_id, l->>''rail_type'', (l->>''fitment_type'')::public.light_fitment_type, l->>''key_or_adapter'', l->>''gun_make'',
                v_other_id, l->>''gun_model_text'', coalesce((l->>''confirmed'')::boolean, false), l->>''notes'');
      elsif v_key = ''adapter_footprints'' then
        select string_agg(k, '', '') into v_bad from jsonb_object_keys(l) k where k <> all (array[''footprint'',''plate_included'',''notes'']);
        if v_bad is not null then raise exception ''create_product: adapter_footprints: unknown field(s): %'', v_bad; end if;
        if not l ? ''plate_included'' then raise exception ''create_product: adapter_footprints: say whether the plate is included''; end if;
        select fp.id into v_other_id from public.footprints fp where fp.slug = l->>''footprint'';
        if v_other_id is null then raise exception ''create_product: adapter_footprints: no footprint \"%\"'', l->>''footprint''; end if;
        insert into public.optic_adapter_footprints (optic_product_id, footprint_id, plate_included, notes)
        values (v_product_id, v_other_id, (l->>''plate_included'')::boolean, l->>''notes'');
      else
        select string_agg(k, '', '') into v_bad from jsonb_object_keys(l) k where k <> all (array[''product'',''source'',''compatibility_note'']);
        if v_bad is not null then raise exception ''create_product: %: unknown field(s): %'', v_key, v_bad; end if;
        v_want := case v_key when ''slides'' then ''slide'' when ''barrels'' then ''barrel'' when ''frames'' then ''frame'' else ''magwell'' end;
        select pr.id into v_other_id from public.products pr where pr.slug = l->>''product'' and pr.category = v_want;
        if v_other_id is null then
          raise exception ''create_product: %: there is no % with slug \"%\"'', v_key, v_want, l->>''product'';
        end if;
        if v_key in (''slides'',''barrels'') then
          insert into public.barrel_slide_requirements (barrel_product_id, slide_product_id, source, compatibility_note)
          values (case when v_key = ''slides'' then v_product_id else v_other_id end,
                  case when v_key = ''slides'' then v_other_id else v_product_id end,
                  l->>''source'', l->>''compatibility_note'');
        elsif l ? ''source'' then
          insert into public.magwell_frame_requirements (magwell_product_id, frame_product_id, source, compatibility_note)
          values (case when v_key = ''frames'' then v_product_id else v_other_id end,
                  case when v_key = ''frames'' then v_other_id else v_product_id end,
                  l->>''source'', l->>''compatibility_note'');
        else
          insert into public.magwell_frame_requirements (magwell_product_id, frame_product_id, compatibility_note)
          values (case when v_key = ''frames'' then v_product_id else v_other_id end,
                  case when v_key = ''frames'' then v_other_id else v_product_id end,
                  l->>''compatibility_note'');
        end if;
      end if;
    end loop;
  end loop;

  -- ── things the admin should know, but that do not block ───────────────────
  if v_category = ''slide'' and not f ? ''barrels'' then
    select string_agg(distinct pr.slug, '', '') into v_bad
      from public.barrel_slide_requirements b join public.products pr on pr.id = b.barrel_product_id;
    if v_bad is not null then
      v_warn := v_warn || (''These barrels only fit the slides listed for them, so they will show as NOT fitting this slide: '' || v_bad);
    end if;
  end if;
  if v_category = ''frame'' and not f ? ''magwells'' then
    select string_agg(distinct pr.slug, '', '') into v_bad
      from public.magwell_frame_requirements b join public.products pr on pr.id = b.magwell_product_id;
    if v_bad is not null then
      v_warn := v_warn || (''These magwells only fit the frames listed for them, so they will show as NOT fitting this frame: '' || v_bad);
    end if;
  end if;

  -- ── swap the build''s pending custom part for this product ─────────────────
  -- variantSpecs is not written into the snapshot here: its formula lives in
  -- js/variant-label.js and _variant-label.mjs, and a third copy in SQL would
  -- drift. The build page reads the spec line from the live variant.
  if p_build_id is not null then
    select b.parts_snapshot -> p_part_index into v_part from public.builds b where b.id = p_build_id for update;
    if not found then raise exception ''create_product: no build %'', p_build_id; end if;
    if v_part is null then raise exception ''create_product: build has no part at index %'', p_part_index; end if;
    if (v_part->>''pending'')::boolean is not true or v_part->>''refId'' is not null then
      raise exception ''create_product: part % (\"%\") on that build is not a pending custom part'', p_part_index, v_part->>''name'';
    end if;
    if v_build_variant is null then
      select pv.id into v_build_variant from public.product_variants pv where pv.product_id = v_product_id and pv.is_default;
    end if;
    update public.builds b set parts_snapshot = jsonb_set(b.parts_snapshot, array[p_part_index::text],
        v_part
        || jsonb_strip_nulls(jsonb_build_object(''name'', v_name, ''brand'', v_brand_name, ''refId'', v_product_id,
             ''imageUrl'', pv.primary_image_url, ''variantId'', pv.id, ''variantColor'', pv.color,
             ''variantLabel'', pv.variant_label, ''variantFinish'', pv.finish))
        || jsonb_build_object(''pending'', false))
    from public.product_variants pv
    where b.id = p_build_id and pv.id = v_build_variant;
  end if;

  -- ── completeness, and the confidence it allows ────────────────────────────
  v_status := public.product_data_status(v_product_id);
  if v_confidence <> ''unverified'' then
    if not (v_status->>''approved'')::boolean then
      raise exception ''create_product: fitment confidence \"%\" needs an approved part. Still missing: %'',
        v_confidence, (select string_agg(x, '', '') from jsonb_array_elements_text(v_status->''missing'') x);
    end if;
    update public.products set fitment_confidence = v_confidence where id = v_product_id;
  end if;

  v_result := jsonb_build_object(
    ''product_id'', v_product_id, ''slug'', v_slug, ''category'', v_category,
    ''brand'', v_brand_name, ''brand_created'', v_brand_created, ''build_relinked'', p_build_id is not null,
    ''has_spec_sheet'', v_has_specs, ''fitment_confidence'', v_confidence, ''warnings'', to_jsonb(v_warn),
    ''variants'', (select jsonb_agg(jsonb_build_object(''id'', pv.id, ''slug'', pv.slug, ''label'', pv.variant_label, ''default'', pv.is_default,
                    ''photos'', (select count(*) from public.variant_images vi where vi.variant_id = pv.id),
                    ''links'', (select count(*) from public.affiliate_links al where al.variant_id = pv.id))
                  order by pv.is_default desc, pv.slug)
                 from public.product_variants pv where pv.product_id = v_product_id))
    || v_status;

  if p_dry_run then
    raise exception ''create_product: dry run, nothing was written'' using errcode = ''P0DRY'', detail = v_result::text;
  end if;
  return v_result;
end;
$fn$;

comment on function public.create_product(jsonb, jsonb, jsonb, jsonb, uuid, integer, boolean) is
  ''Admin / service_role only. Creates a product with its brand, platforms, spec sheet, every variant (photos + retailer links) and fits-with rules in one transaction, optionally re-links a build''''s pending custom part, and returns product_data_status. p_dry_run raises P0DRY with the result instead of writing.'';

-- CREATE re-grants EXECUTE to anon through default privileges; take it back.
revoke all on function public.create_product(jsonb, jsonb, jsonb, jsonb, uuid, integer, boolean) from public, anon;
grant execute on function public.create_product(jsonb, jsonb, jsonb, jsonb, uuid, integer, boolean) to authenticated, service_role;

-- ── the needs-data list (PR 3) ──────────────────────────────────────────────
-- Unapproved products and what each is missing. Admins (and the service role)
-- see rows; everyone else sees none. security_invoker so it reads as the
-- caller, and the filter is in the view itself.
create or replace view public.products_needing_data with (security_invoker = true) as
select p.id as product_id, p.slug, p.name, m.name as brand, p.category,
       array(select jsonb_array_elements_text(st.s -> ''platforms'')) as platforms,
       array(select jsonb_array_elements_text(st.s -> ''missing''))   as missing
  from public.products p
  join public.manufacturers m on m.id = p.brand_id
  cross join lateral (select public.product_data_status(p.id) as s) st
 where (public.is_admin() or public.is_trusted_backend())
   and not (st.s ->> ''approved'')::boolean;

revoke all on public.products_needing_data from public, anon, authenticated;
grant select on public.products_needing_data to authenticated, service_role;
"}', 'create_product', 'ag.gamboa94@gmail.com', NULL, NULL);
INSERT INTO "supabase_migrations"."schema_migrations" ("version", "statements", "name", "created_by", "idempotency_key", "rollback") VALUES ('20261003225703', '{"-- fix_product_data_status_url.sql
-- NOT YET APPLIED. Dry-run 2026-10-03 against Gunforma-v2 inside one
-- rolled-back transaction; results in the PR.
--
-- A missing source URL is MISSING, not optional.
--
-- create_product() refuses a product without products.url: it is the page
-- the data came from, and without it nothing on the product can be checked
-- again. product_data_status() as applied in create_product.sql reported a
-- blank url under optional_blank, so a product with no source could still
-- read as approved, and the status disagreed with the rule the function that
-- creates products enforces. This moves it to missing[].
--
-- Only product_data_status() changes. create_product() never produces a
-- blank url, so its results are unaffected; the one live product affected is
-- streamlight-tlr-7-sub, which was already unapproved (no MSRP on one
-- variant) and now also reports url.
--
-- create or replace keeps the grants; they are restated so this file says
-- the whole of what is live.

create or replace function public.product_data_status(p_product_id uuid) returns jsonb
language plpgsql stable set search_path = '''' as $ds$
declare
  pr record; j jsonb; v_tbl regclass; r record; v_col text; v_val text;
  v_missing text[] := ''{}''; v_opt text[] := ''{}''; v_platforms text[];
begin
  select p.id, p.category, p.description, p.material, p.material_family::text as material_family,
         p.url, p.weight_oz, p.fitment_notes
    into pr from public.products p where p.id = p_product_id;
  if not found then return null; end if;

  if coalesce(btrim(pr.description), '''') = ''''     then v_missing := v_missing || ''description''::text; end if;
  if coalesce(btrim(pr.material), '''') = ''''        then v_missing := v_missing || ''material''::text; end if;
  if coalesce(btrim(pr.material_family), '''') = '''' then v_missing := v_missing || ''material_family''::text; end if;
  -- the source page the data came from: create_product() requires it, so a
  -- product without one did not come through it and is not approved
  if coalesce(btrim(pr.url), '''') = ''''             then v_missing := v_missing || ''url''::text; end if;

  v_platforms := array(select pl.slug from public.product_platforms pp join public.platforms pl on pl.id = pp.platform_id
                        where pp.product_id = p_product_id order by pl.slug);
  if cardinality(v_platforms) = 0 then v_missing := v_missing || ''platform''::text; end if;

  v_tbl := to_regclass(''public.'' || quote_ident(pr.category::text || ''_specs''));
  if v_tbl is not null then
    execute format(''select to_jsonb(s) from %s s where s.product_id = $1'', v_tbl) into j using p_product_id;
  end if;
  j := coalesce(j, ''{}''::jsonb);   -- no spec row: every applicable required field is missing
  for r in select f.field, f.requirement, f.only_when_field, f.only_when_values
             from public.spec_field_rules f where f.category = pr.category order by f.sort_order loop
    if r.only_when_field is not null and not coalesce((j ->> r.only_when_field) = any (r.only_when_values), false) then
      continue;   -- not applicable
    end if;
    v_col := case r.field when ''platform'' then ''platform_id'' when ''footprint'' then ''footprint_id'' else r.field end;
    v_val := j ->> v_col;
    if coalesce(btrim(v_val), '''') = '''' then
      if r.requirement = ''required'' then v_missing := v_missing || (''spec.'' || r.field);
      else v_opt := v_opt || (''spec.'' || r.field); end if;
    end if;
  end loop;

  if not exists (select 1 from public.product_variants pv where pv.product_id = p_product_id and pv.retired_at is null) then
    v_missing := v_missing || ''variant''::text;
  end if;
  v_missing := v_missing || array(select ''variant '' || pv.slug || '': photo'' from public.product_variants pv
                                   where pv.product_id = p_product_id and pv.retired_at is null and pv.primary_image_url is null order by pv.slug);
  v_missing := v_missing || array(select ''variant '' || pv.slug || '': msrp'' from public.product_variants pv
                                   where pv.product_id = p_product_id and pv.retired_at is null and pv.msrp is null order by pv.slug);

  if pr.category = ''light'' and not exists (select 1 from public.light_compatibility lc where lc.light_product_id = p_product_id) then
    v_missing := v_missing || ''light compatibility''::text;
  end if;

  if not exists (select 1 from public.affiliate_links al join public.product_variants pv on pv.id = al.variant_id
                  where pv.product_id = p_product_id and pv.retired_at is null and al.retired_at is null) then
    v_opt := v_opt || ''retailer link''::text;
  end if;
  if pr.weight_oz is null                       then v_opt := v_opt || ''weight_oz''::text; end if;
  if coalesce(btrim(pr.fitment_notes), '''') = '''' then v_opt := v_opt || ''fitment_notes''::text; end if;

  return jsonb_build_object(''approved'', cardinality(v_missing) = 0, ''missing'', to_jsonb(v_missing),
                            ''optional_blank'', to_jsonb(v_opt), ''platforms'', to_jsonb(v_platforms));
end;
$ds$;

revoke all on function public.product_data_status(uuid) from public, anon;
grant execute on function public.product_data_status(uuid) to authenticated, service_role;
"}', 'fix_product_data_status_url', 'ag.gamboa94@gmail.com', NULL, NULL);
INSERT INTO "supabase_migrations"."schema_migrations" ("version", "statements", "name", "created_by", "idempotency_key", "rollback") VALUES ('20261004032655', '{"-- colors_admin_insert.sql
-- NOT YET APPLIED. Apply AFTER gunforma-admin-part.html is merged and live:
-- the page reports a refusal cleanly without this, so it ships first.
--
-- Lets an admin add a colour from the add-a-part page. create_variant()
-- refuses any colour not in public.colors (\"Add it there first (with a
-- color_family)\"), and until now the only way to add one was SQL: the table
-- carries one policy, colors_public_read, and nothing that admits a write.
--
-- INSERT only. The page never edits or removes a colour, so no UPDATE or
-- DELETE policy is added.
--
-- is_admin(), never an inline read of profiles: a policy''s table reads are
-- permission-checked at plan time for every statement on the table, so an
-- inline `exists (select 1 from profiles …)` would break INSERTs for anyone
-- without SELECT on profiles, whatever the predicate says. See CLAUDE.md,
-- \"A policy''s table reads are checked even when the policy doesn''t apply\".
-- is_admin() is SECURITY DEFINER with a pinned search_path.
--
-- GRANTS, logged and deliberately NOT changed here: authenticated holds
-- INSERT, SELECT, UPDATE, DELETE, TRUNCATE, REFERENCES and TRIGGER on
-- public.colors. INSERT is the one this policy needs. UPDATE, DELETE and
-- TRUNCATE have no policy behind them (RLS refuses the first two; TRUNCATE
-- is not subject to RLS at all) and belong to the grants audit, not here.

create policy colors_admin_insert on public.colors
  for insert to authenticated
  with check (public.is_admin());
"}', 'colors_admin_insert', 'ag.gamboa94@gmail.com', NULL, NULL);
INSERT INTO "supabase_migrations"."schema_migrations" ("version", "statements", "name", "created_by", "idempotency_key", "rollback") VALUES ('20261004032834', '{"-- fix_strip_blank_and_link_result.sql
-- NOT YET APPLIED. Dry-run 2026-10-04 against Gunforma-v2 inside one
-- rolled-back transaction; results in #133. Apply after #133 is merged,
-- alongside colors_admin_insert.sql. gunforma-admin-part.html reads both
-- result shapes, so the order page-then-migration holds.
--
-- Two changes, both create or replace, nothing else touched:
--
-- 1. jsonb_strip_blank() treats any non-object as empty. It raised \"cannot
--    call jsonb_each on a non-object\" on JSON null, and create_product()
--    runs it over p_product, every variant, every link, p_specs and p_fits —
--    so a caller sending \"p_fits\": null as the jsonb value ''null'' (not SQL
--    NULL) had its whole call refused. Found replaying the add-a-part page''s
--    first payload; the page also leaves empty sections out.
--
-- 2. create_product()''s result says, per retailer link, whether a tracked
--    link was built: variants[].retailers[] = {partner, partner_name, url,
--    tracked_url}. tracked_url is null for a partner with no
--    awin_merchant_id, which earns no commission — and partners such as
--    `optics-planet` (no Awin id) sit beside `awin-optics-planet` in the
--    retailer list, so picking the wrong one is easy and was silent.
--    The variants[] keys that already existed are unchanged. This is the
--    whole function restated from create_product.sql with only the
--    ''variants'' expression changed; diff the two to see it.

create or replace function public.jsonb_strip_blank(j jsonb) returns jsonb
language sql immutable set search_path = '''' as $sb$
  -- Anything that is not an object — SQL NULL, JSON null, an array, a string —
  -- is an empty section. jsonb_each() raises on a non-object, and a form or a
  -- PostgREST caller can send JSON null for a section it left out.
  select case when jsonb_typeof(j) = ''object''
              then coalesce((select jsonb_object_agg(e.key, e.value) from jsonb_each(j) e
                              where e.value not in (''\"\"''::jsonb, ''null''::jsonb, ''[]''::jsonb)), ''{}''::jsonb)
              else ''{}''::jsonb end;
$sb$;

create or replace function public.create_product(
  p_product jsonb, p_variants jsonb, p_specs jsonb default null, p_fits jsonb default null,
  p_build_id uuid default null, p_part_index integer default null, p_dry_run boolean default false)
returns jsonb
language plpgsql security definer set search_path = ''''
as $fn$
declare
  c_awin_affid   constant text   := ''2959345'';   -- Gunforma''s Awin publisher id; public, it is in every live link
  c_product_keys constant text[] := array[''brand'',''name'',''category'',''platforms'',''slug'',''url'',''description'',''family'',''material'',''material_family'',''fitment_notes'',''build_warning'',''build_notes'',''weight_oz'',''fitment_confidence'',''internal_notes''];
  c_variant_keys constant text[] := array[''color'',''finish'',''sku'',''upc'',''msrp'',''image_url'',''gallery'',''variant_label'',''optic_cut'',''handedness'',''notes'',''is_default'',''manual_safety_variant'',''reticle'',''reticle_color'',''battery_type'',''mount_system'',''bundle'',''clamp_style'',''clamp_rail_type'',''clamp'',''partner_slug'',''url'',''affiliate_url'',''links'',''use_in_build''];
  c_link_keys    constant text[] := array[''partner_slug'',''url'',''affiliate_url'',''op_mpn'',''op_gtin'',''op_merchant_product_id'',''notes''];
  p jsonb; s jsonb; f jsonb; v jsonb; l jsonb; r jsonb; v_result jsonb; v_status jsonb;
  v_category public.product_category; v_want public.product_category; v_platforms text[];
  v_platform_id uuid; v_platform_name text; v_kind text; v_len numeric; v_lengths text;
  v_brand_id uuid; v_brand_name text; v_brand_created boolean := false;
  v_product_id uuid; v_slug text; v_name text; v_confidence public.fitment_confidence;
  v_i int := 0; v_bad text; v_n int; v_key text;
  v_variant_id uuid; v_build_variant uuid; v_links jsonb; v_partner_id uuid; v_other_id uuid;
  v_mid text; v_aff text; v_aff_mid text;
  v_axes text; v_vslug text; v_vbase text; v_part jsonb;
  v_tbl regclass; v_rule_fields text[]; v_collist text; v_has_specs boolean := false;
  v_warn text[] := ''{}'';
begin
  if not (public.is_admin() or public.is_trusted_backend()) then
    raise exception ''create_product: admin or service_role only'' using errcode = ''42501'';
  end if;
  if p_product is null or jsonb_typeof(p_product) <> ''object'' then
    raise exception ''create_product: p_product must be an object'';
  end if;
  p := public.jsonb_strip_blank(p_product);
  if p ? ''installation_difficulty'' or p ? ''best_for'' then
    raise exception ''create_product: installation_difficulty and best_for are no longer entered. Existing values stay where they are; leave these out.'';
  end if;
  select string_agg(k, '', '') into v_bad from jsonb_object_keys(p) k where k <> all (c_product_keys);
  if v_bad is not null then raise exception ''create_product: unknown product field(s): %'', v_bad; end if;
  v_name := btrim(coalesce(p->>''name'', ''''));
  if btrim(coalesce(p->>''brand'', '''')) = '''' or v_name = '''' then
    raise exception ''create_product: brand and name are required'';
  end if;
  if p->>''category'' is null then raise exception ''create_product: category is required''; end if;
  v_category := (p->>''category'')::public.product_category;
  v_confidence := coalesce((p->>''fitment_confidence'')::public.fitment_confidence, ''unverified'');

  -- ── platform: explicit, never defaulted ───────────────────────────────────
  if jsonb_typeof(p->''platforms'') is distinct from ''array'' or jsonb_array_length(p->''platforms'') = 0 then
    raise exception ''create_product: send at least one platform (e.g. \"platforms\": [\"p365\"]). Nothing defaults: without one the part never appears in the builder.'';
  end if;
  v_platforms := array(select distinct x from jsonb_array_elements_text(p->''platforms'') x order by x);
  select string_agg(x, '', '') into v_bad from unnest(v_platforms) x where not exists (select 1 from public.platforms pl where pl.slug = x);
  if v_bad is not null then
    raise exception ''create_product: unknown platform(s): %. Known: %'', v_bad,
      (select string_agg(slug, '', '' order by slug) from public.platforms) using errcode = ''foreign_key_violation'';
  end if;
  if v_category in (''slide'', ''barrel'') and cardinality(v_platforms) <> 1 then
    raise exception ''create_product: a % belongs to exactly one platform; this one names %: %. Send one.'',
      v_category, cardinality(v_platforms), array_to_string(v_platforms, '', '');
  end if;
  select string_agg(pl.name, '', '' order by pl.name) into v_bad from public.platforms pl
   where pl.slug = any (v_platforms) and not pl.is_live;
  if v_bad is not null then
    v_warn := v_warn || (''Not live yet: '' || v_bad || ''. The part is saved and appears when the platform launches.'');
  end if;

  if p->>''url'' is null then
    raise exception ''create_product: the source URL (the product page the data came from) is required'';
  end if;
  if p_variants is null or jsonb_typeof(p_variants) <> ''array'' or jsonb_array_length(p_variants) = 0 then
    raise exception ''create_product: at least one variant is required'';
  end if;
  if (p_build_id is null) <> (p_part_index is null) or p_part_index < 0 then
    raise exception ''create_product: p_build_id and p_part_index must be supplied together'';
  end if;

  select m.id, m.name into v_brand_id, v_brand_name from public.manufacturers m
   where lower(m.name) = lower(btrim(p->>''brand'')) or m.slug = public.slugify(p->>''brand'')
   order by m.created_at limit 1;
  if v_brand_id is null then
    insert into public.manufacturers (slug, name) values (public.slugify(p->>''brand''), btrim(p->>''brand''))
    returning id, name into v_brand_id, v_brand_name;
    v_brand_created := true;
  end if;

  -- The slug is the product''s URL for good. Brand is prefixed unless the name
  -- already starts with it. Pass \"slug\" to choose it by hand.
  v_slug := coalesce(nullif(btrim(p->>''slug''), ''''),
    public.slugify(case when left(lower(v_name), length(v_brand_name)) = lower(v_brand_name)
                        then v_name else v_brand_name || '' '' || v_name end));
  if exists (select 1 from public.products where slug = v_slug) then
    raise exception ''create_product: a product with slug \"%\" already exists. To add a colour or option to it, use create_variant.'', v_slug using errcode = ''unique_violation'';
  end if;
  if exists (select 1 from public.products where brand_id = v_brand_id and lower(name) = lower(v_name)) then
    raise exception ''create_product: % already has a product named \"%\". To add a colour or option to it, use create_variant.'', v_brand_name, v_name using errcode = ''unique_violation'';
  end if;

  insert into public.products (slug, category, brand_id, name, family, url, description, material, material_family,
                               fitment_notes, build_warning, build_notes, weight_oz, fitment_confidence)
  values (v_slug, v_category, v_brand_id, v_name, p->>''family'', p->>''url'', p->>''description'', p->>''material'', p->>''material_family'',
          p->>''fitment_notes'', p->>''build_warning'', p->>''build_notes'', (p->>''weight_oz'')::numeric, ''unverified'')
  returning id into v_product_id;
  -- fitment_confidence is set at the end, once the part is known to be approved

  if p ? ''internal_notes'' then
    insert into public.product_internal (product_id, internal_notes) values (v_product_id, p->>''internal_notes'');
  end if;

  insert into public.product_platforms (product_id, platform_id)
  select v_product_id, pl.id from public.platforms pl where pl.slug = any (v_platforms);

  -- ── spec sheet ────────────────────────────────────────────────────────────
  -- Accepted keys are the category''s spec_field_rules fields and nothing else.
  -- Only supplied keys are named in the INSERT, so column defaults survive.
  s := public.jsonb_strip_blank(p_specs);
  v_tbl := to_regclass(''public.'' || quote_ident(v_category::text || ''_specs''));
  v_rule_fields := array(select fr.field from public.spec_field_rules fr where fr.category = v_category order by fr.sort_order);
  if s <> ''{}''::jsonb then
    if v_tbl is null then raise exception ''create_product: a % has no spec sheet; leave p_specs out'', v_category; end if;
    select string_agg(k, '', '') into v_bad from jsonb_object_keys(s) k where k <> all (v_rule_fields);
    if v_bad is not null then
      raise exception ''create_product: spec sheet: no rule for field(s): %. Fields for a %: %'', v_bad, v_category, array_to_string(v_rule_fields, '', '');
    end if;

    -- platform: the product''s one platform. A disagreeing key is refused.
    if ''platform'' = any (v_rule_fields) then
      if s ? ''platform'' and s->>''platform'' <> v_platforms[1] then
        raise exception ''create_product: spec sheet platform \"%\" disagrees with the product''''s platform \"%\"'', s->>''platform'', v_platforms[1];
      end if;
      select pl.id, pl.name into v_platform_id, v_platform_name from public.platforms pl where pl.slug = v_platforms[1];
      s := (s - ''platform'') || jsonb_build_object(''platform_id'', v_platform_id);
    end if;
    if s ? ''footprint'' then
      select fp.id into v_other_id from public.footprints fp where fp.slug = s->>''footprint'';
      if v_other_id is null then
        raise exception ''create_product: spec sheet: no footprint \"%\". Known: %'', s->>''footprint'',
          (select string_agg(slug, '', '' order by slug) from public.footprints);
      end if;
      s := (s - ''footprint'') || jsonb_build_object(''footprint_id'', v_other_id);
    end if;

    -- material is one fact held in two places
    foreach v_key in array array[''housing_material'', ''material''] loop
      if v_key = any (v_rule_fields) then
        if s ? v_key and p ? ''material'' and lower(btrim(s->>v_key)) <> lower(btrim(p->>''material'')) then
          raise exception ''create_product: material is one fact: the product says \"%\" but the spec sheet''''s % says \"%\"'', p->>''material'', v_key, s->>v_key;
        elsif not s ? v_key and p ? ''material'' then
          s := s || jsonb_build_object(v_key, p->>''material'');
        elsif s ? v_key and not p ? ''material'' then
          update public.products set material = s->>v_key where id = v_product_id;
        end if;
      end if;
    end loop;

    -- only-when fields whose condition holds must come with the sheet
    select string_agg(fr.field, '', '' order by fr.sort_order) into v_bad from public.spec_field_rules fr
     where fr.category = v_category and fr.requirement = ''required'' and fr.only_when_field is not null
       and (s ->> fr.only_when_field) = any (fr.only_when_values)
       and coalesce(btrim(s ->> fr.field), '''') = '''';
    if v_bad is not null then
      raise exception ''create_product: the % spec sheet needs % (it applies here because of %)'', v_category, v_bad,
        (select string_agg(distinct fr.only_when_field || '' = '' || (s ->> fr.only_when_field), '', '') from public.spec_field_rules fr
          where fr.category = v_category and fr.only_when_field is not null and fr.field = any (string_to_array(v_bad, '', '')));
    end if;

    -- slide / barrel length must be registered for that platform. Checked
    -- here so an admin reads a sentence, not the class trigger''s raw text.
    if v_category in (''slide'', ''barrel'') then
      v_kind := v_category::text;
      v_len  := (s ->> (v_kind || ''_length_in''))::numeric;
      if v_len is not null then
        if not exists (select 1 from public.platform_part_lengths ppl where ppl.platform_id = v_platform_id and ppl.part_kind = v_kind) then
          raise exception ''create_product: % % lengths are not registered yet. Add them to platform_part_lengths before adding a % for it.'',
            v_platform_name, v_kind, v_kind;
        end if;
        if not exists (select 1 from public.platform_part_lengths ppl
                        where ppl.platform_id = v_platform_id and ppl.part_kind = v_kind and ppl.length_in = v_len) then
          select string_agg(ppl.length_in::text, '', '' order by ppl.length_in) into v_lengths from public.platform_part_lengths ppl
           where ppl.platform_id = v_platform_id and ppl.part_kind = v_kind;
          raise exception ''create_product: no % % is registered at % in. Registered % lengths: %.'', v_platform_name, v_kind, v_len, v_kind, v_lengths;
        end if;
      end if;
    end if;

    -- columns the table itself declares NOT NULL without a default
    select string_agg(a.attname::text, '', '') into v_bad from pg_catalog.pg_attribute a
     where a.attrelid = v_tbl and a.attnum > 0 and not a.attisdropped and a.attnotnull and not a.atthasdef
       and a.attname::text not in (''product_id'', ''category'') and not s ? (a.attname::text);
    if v_bad is not null then
      raise exception ''create_product: the % spec sheet needs: %'', v_category, replace(replace(v_bad, ''footprint_id'', ''footprint''), ''platform_id'', ''platform'');
    end if;

    s := s || jsonb_build_object(''product_id'', v_product_id, ''category'', v_category);
    select string_agg(quote_ident(k), '', '') into v_collist from jsonb_object_keys(s) k;
    execute format(''insert into %s (%s) select %s from jsonb_populate_record(null::%s, $1)'', v_tbl, v_collist, v_collist, v_tbl) using s;
    v_has_specs := true;
  end if;

  -- ── variants ──────────────────────────────────────────────────────────────
  for v in select value from jsonb_array_elements(p_variants) loop
    v_i := v_i + 1;
    if jsonb_typeof(v) <> ''object'' then raise exception ''create_product: variant % is not an object'', v_i; end if;
    v := public.jsonb_strip_blank(v);
    select string_agg(k, '', '') into v_bad from jsonb_object_keys(v) k where k <> all (c_variant_keys);
    if v_bad is not null then
      raise exception ''create_product: variant %: unknown field(s): %'', v_i, v_bad;
    end if;

    -- colour vocabulary, slug, default flag and the position-1 image row are
    -- create_variant''s rules; they are not restated here.
    v_variant_id := public.create_variant(
      p_product_slug => v_slug, p_color => v->>''color'', p_finish => v->>''finish'', p_sku => v->>''sku'', p_upc => v->>''upc'',
      p_msrp => (v->>''msrp'')::numeric, p_image_url => v->>''image_url'', p_variant_label => v->>''variant_label'',
      p_optic_cut => v->>''optic_cut'', p_handedness => v->>''handedness'', p_notes => v->>''notes'',
      p_make_default => case when (v->>''is_default'')::boolean then true end);

    -- the options create_variant does not carry; when present they also go into the slug
    v_axes := concat_ws(''-'', nullif(v->>''optic_cut'',''none''), v->>''reticle_color'', v->>''reticle'', v->>''clamp'', v->>''bundle'',
                        case when (v->>''manual_safety_variant'')::boolean then ''ms'' end,
                        case when v->>''handedness'' in (''left'',''right'') then v->>''handedness'' end);
    v_vslug := null;
    if v_axes <> '''' then
      v_vbase := public.slugify(v_slug || ''-'' || v_axes || ''-'' || (v->>''color'') || coalesce(''-'' || (v->>''finish''), ''''));
      v_vslug := v_vbase; v_n := 1;
      while exists (select 1 from public.product_variants where slug = v_vslug and id <> v_variant_id) loop
        v_n := v_n + 1; v_vslug := v_vbase || ''-'' || v_n;
      end loop;
    end if;
    update public.product_variants set
      slug = coalesce(v_vslug, slug),
      manual_safety_variant = (v->>''manual_safety_variant'')::boolean,
      reticle = v->>''reticle'', reticle_color = v->>''reticle_color'', battery_type = v->>''battery_type'',
      mount_system = v->>''mount_system'', bundle = v->>''bundle'', clamp_style = v->>''clamp_style'',
      clamp_rail_type = v->>''clamp_rail_type'', clamp = v->>''clamp''
    where id = v_variant_id;

    if v ? ''gallery'' then
      if v->>''image_url'' is null then
        raise exception ''create_product: variant %: gallery photos need a main photo first'', v_i;
      end if;
      insert into public.variant_images (variant_id, url, position)
      select v_variant_id, g.url, (g.ord + 1)::smallint
        from jsonb_array_elements_text(v->''gallery'') with ordinality g(url, ord);
    end if;

    -- retailer links: zero or more per variant. street_price / in_stock /
    -- last_checked / op_last_matched_by are never set — the sync owns them.
    v_links := coalesce(v->''links'', ''[]''::jsonb);
    if jsonb_typeof(v_links) <> ''array'' then raise exception ''create_product: variant %: links must be a list'', v_i; end if;
    if v ? ''url'' or v ? ''partner_slug'' or v ? ''affiliate_url'' then
      v_links := v_links || jsonb_build_array(jsonb_build_object(''partner_slug'', v->>''partner_slug'', ''url'', v->>''url'', ''affiliate_url'', v->>''affiliate_url''));
    end if;
    for l in select value from jsonb_array_elements(v_links) loop
      l := public.jsonb_strip_blank(l);
      select string_agg(k, '', '') into v_bad from jsonb_object_keys(l) k where k <> all (c_link_keys);
      if v_bad is not null then raise exception ''create_product: variant %: retailer link: unknown field(s): %'', v_i, v_bad; end if;
      if l->>''partner_slug'' is null or l->>''url'' is null then
        raise exception ''create_product: variant %: each retailer link needs a retailer and a URL'', v_i;
      end if;
      select pa.id, pa.awin_merchant_id into v_partner_id, v_mid from public.partners pa where pa.slug = l->>''partner_slug'';
      if v_partner_id is null then
        raise exception ''create_product: variant %: no partner with slug \"%\"'', v_i, l->>''partner_slug'' using errcode = ''foreign_key_violation'';
      end if;
      v_aff := l->>''affiliate_url'';
      if v_mid is not null then
        if v_aff is null then
          v_aff := ''https://www.awin1.com/cread.php?awinmid='' || v_mid || ''&awinaffid='' || c_awin_affid
                || ''&clickref='' || public.url_encode(''build-detail_'' || v_slug)
                || ''&ued='' || public.url_encode(l->>''url'');
        elsif v_aff ~ ''awin1\\.com'' then
          v_aff_mid := coalesce(substring(v_aff from ''[?&]awinmid=(\\d+)''), substring(v_aff from ''[?&]m=(\\d+)''));
          if v_aff_mid is distinct from v_mid then
            raise exception ''create_product: variant %: the tracked link carries Awin merchant % but partner \"%\" is merchant %'', v_i, coalesce(v_aff_mid,''(none)''), l->>''partner_slug'', v_mid;
          end if;
        end if;
      end if;
      insert into public.affiliate_links (variant_id, partner_id, url, affiliate_url, notes, op_mpn, op_gtin, op_merchant_product_id)
      values (v_variant_id, v_partner_id, l->>''url'', v_aff, l->>''notes'', l->>''op_mpn'', l->>''op_gtin'', l->>''op_merchant_product_id'');
    end loop;

    if (v->>''use_in_build'')::boolean then v_build_variant := v_variant_id; end if;
  end loop;

  if exists (select 1 from public.product_variants where product_id = v_product_id
             group by color, finish, optic_cut, handedness, manual_safety_variant, reticle, reticle_color,
                      battery_type, mount_system, bundle, clamp, clamp_style, clamp_rail_type
             having count(*) > 1) then
    raise exception ''create_product: two variants are identical on every option. Each one must differ by colour, finish or another option.'';
  end if;
  if exists (select 1 from public.product_variants pv where pv.product_id = v_product_id and pv.is_default
               and (pv.primary_image_url is null or pv.msrp is null)) then
    raise exception ''create_product: the default variant needs a photo and an MSRP'';
  end if;

  -- ── fits-with rules ───────────────────────────────────────────────────────
  f := public.jsonb_strip_blank(p_fits);
  for v_key, r in select e.key, e.value from jsonb_each(f) e loop
    if not ((v_category = ''light''   and v_key = ''light_compatibility'')
         or (v_category = ''optic''   and v_key = ''adapter_footprints'')
         or (v_category = ''barrel''  and v_key = ''slides'')
         or (v_category = ''slide''   and v_key = ''barrels'')
         or (v_category = ''magwell'' and v_key = ''frames'')
         or (v_category = ''frame''   and v_key = ''magwells'')) then
      raise exception ''create_product: fits-with rule \"%\" does not apply to a %. (light: light_compatibility; optic: adapter_footprints; barrel: slides; slide: barrels; magwell: frames; frame: magwells)'', v_key, v_category;
    end if;
    if jsonb_typeof(r) <> ''array'' then raise exception ''create_product: fits-with rule \"%\" must be a list'', v_key; end if;
    -- these four reference the <category>_specs row, not products
    if v_key in (''light_compatibility'',''adapter_footprints'',''slides'',''barrels'') and not v_has_specs then
      raise exception ''create_product: fits-with rules for a % need its spec sheet filled in first'', v_category;
    end if;
    for l in select value from jsonb_array_elements(r) loop
      if jsonb_typeof(l) = ''string'' then l := jsonb_build_object(''product'', l #>> ''{}''); end if;
      l := public.jsonb_strip_blank(l);
      if v_key = ''light_compatibility'' then
        select string_agg(k, '', '') into v_bad from jsonb_object_keys(l) k
         where k <> all (array[''rail_type'',''fitment_type'',''key_or_adapter'',''gun_make'',''gun'',''gun_model_text'',''confirmed'',''notes'']);
        if v_bad is not null then raise exception ''create_product: light_compatibility: unknown field(s): %'', v_bad; end if;
        v_other_id := null;
        if l ? ''gun'' then
          select g.id into v_other_id from public.guns g where g.slug = l->>''gun'';
          if v_other_id is null then raise exception ''create_product: light_compatibility: no gun \"%\"'', l->>''gun''; end if;
        end if;
        insert into public.light_compatibility (light_product_id, rail_type, fitment_type, key_or_adapter, gun_make, gun_id, gun_model_text, confirmed, notes)
        values (v_product_id, l->>''rail_type'', (l->>''fitment_type'')::public.light_fitment_type, l->>''key_or_adapter'', l->>''gun_make'',
                v_other_id, l->>''gun_model_text'', coalesce((l->>''confirmed'')::boolean, false), l->>''notes'');
      elsif v_key = ''adapter_footprints'' then
        select string_agg(k, '', '') into v_bad from jsonb_object_keys(l) k where k <> all (array[''footprint'',''plate_included'',''notes'']);
        if v_bad is not null then raise exception ''create_product: adapter_footprints: unknown field(s): %'', v_bad; end if;
        if not l ? ''plate_included'' then raise exception ''create_product: adapter_footprints: say whether the plate is included''; end if;
        select fp.id into v_other_id from public.footprints fp where fp.slug = l->>''footprint'';
        if v_other_id is null then raise exception ''create_product: adapter_footprints: no footprint \"%\"'', l->>''footprint''; end if;
        insert into public.optic_adapter_footprints (optic_product_id, footprint_id, plate_included, notes)
        values (v_product_id, v_other_id, (l->>''plate_included'')::boolean, l->>''notes'');
      else
        select string_agg(k, '', '') into v_bad from jsonb_object_keys(l) k where k <> all (array[''product'',''source'',''compatibility_note'']);
        if v_bad is not null then raise exception ''create_product: %: unknown field(s): %'', v_key, v_bad; end if;
        v_want := case v_key when ''slides'' then ''slide'' when ''barrels'' then ''barrel'' when ''frames'' then ''frame'' else ''magwell'' end;
        select pr.id into v_other_id from public.products pr where pr.slug = l->>''product'' and pr.category = v_want;
        if v_other_id is null then
          raise exception ''create_product: %: there is no % with slug \"%\"'', v_key, v_want, l->>''product'';
        end if;
        if v_key in (''slides'',''barrels'') then
          insert into public.barrel_slide_requirements (barrel_product_id, slide_product_id, source, compatibility_note)
          values (case when v_key = ''slides'' then v_product_id else v_other_id end,
                  case when v_key = ''slides'' then v_other_id else v_product_id end,
                  l->>''source'', l->>''compatibility_note'');
        elsif l ? ''source'' then
          insert into public.magwell_frame_requirements (magwell_product_id, frame_product_id, source, compatibility_note)
          values (case when v_key = ''frames'' then v_product_id else v_other_id end,
                  case when v_key = ''frames'' then v_other_id else v_product_id end,
                  l->>''source'', l->>''compatibility_note'');
        else
          insert into public.magwell_frame_requirements (magwell_product_id, frame_product_id, compatibility_note)
          values (case when v_key = ''frames'' then v_product_id else v_other_id end,
                  case when v_key = ''frames'' then v_other_id else v_product_id end,
                  l->>''compatibility_note'');
        end if;
      end if;
    end loop;
  end loop;

  -- ── things the admin should know, but that do not block ───────────────────
  if v_category = ''slide'' and not f ? ''barrels'' then
    select string_agg(distinct pr.slug, '', '') into v_bad
      from public.barrel_slide_requirements b join public.products pr on pr.id = b.barrel_product_id;
    if v_bad is not null then
      v_warn := v_warn || (''These barrels only fit the slides listed for them, so they will show as NOT fitting this slide: '' || v_bad);
    end if;
  end if;
  if v_category = ''frame'' and not f ? ''magwells'' then
    select string_agg(distinct pr.slug, '', '') into v_bad
      from public.magwell_frame_requirements b join public.products pr on pr.id = b.magwell_product_id;
    if v_bad is not null then
      v_warn := v_warn || (''These magwells only fit the frames listed for them, so they will show as NOT fitting this frame: '' || v_bad);
    end if;
  end if;

  -- ── swap the build''s pending custom part for this product ─────────────────
  -- variantSpecs is not written into the snapshot here: its formula lives in
  -- js/variant-label.js and _variant-label.mjs, and a third copy in SQL would
  -- drift. The build page reads the spec line from the live variant.
  if p_build_id is not null then
    select b.parts_snapshot -> p_part_index into v_part from public.builds b where b.id = p_build_id for update;
    if not found then raise exception ''create_product: no build %'', p_build_id; end if;
    if v_part is null then raise exception ''create_product: build has no part at index %'', p_part_index; end if;
    if (v_part->>''pending'')::boolean is not true or v_part->>''refId'' is not null then
      raise exception ''create_product: part % (\"%\") on that build is not a pending custom part'', p_part_index, v_part->>''name'';
    end if;
    if v_build_variant is null then
      select pv.id into v_build_variant from public.product_variants pv where pv.product_id = v_product_id and pv.is_default;
    end if;
    update public.builds b set parts_snapshot = jsonb_set(b.parts_snapshot, array[p_part_index::text],
        v_part
        || jsonb_strip_nulls(jsonb_build_object(''name'', v_name, ''brand'', v_brand_name, ''refId'', v_product_id,
             ''imageUrl'', pv.primary_image_url, ''variantId'', pv.id, ''variantColor'', pv.color,
             ''variantLabel'', pv.variant_label, ''variantFinish'', pv.finish))
        || jsonb_build_object(''pending'', false))
    from public.product_variants pv
    where b.id = p_build_id and pv.id = v_build_variant;
  end if;

  -- ── completeness, and the confidence it allows ────────────────────────────
  v_status := public.product_data_status(v_product_id);
  if v_confidence <> ''unverified'' then
    if not (v_status->>''approved'')::boolean then
      raise exception ''create_product: fitment confidence \"%\" needs an approved part. Still missing: %'',
        v_confidence, (select string_agg(x, '', '') from jsonb_array_elements_text(v_status->''missing'') x);
    end if;
    update public.products set fitment_confidence = v_confidence where id = v_product_id;
  end if;

  v_result := jsonb_build_object(
    ''product_id'', v_product_id, ''slug'', v_slug, ''category'', v_category,
    ''brand'', v_brand_name, ''brand_created'', v_brand_created, ''build_relinked'', p_build_id is not null,
    ''has_spec_sheet'', v_has_specs, ''fitment_confidence'', v_confidence, ''warnings'', to_jsonb(v_warn),
    ''variants'', (select jsonb_agg(jsonb_build_object(''id'', pv.id, ''slug'', pv.slug, ''label'', pv.variant_label, ''default'', pv.is_default,
                    ''photos'', (select count(*) from public.variant_images vi where vi.variant_id = pv.id),
                    ''links'', (select count(*) from public.affiliate_links al where al.variant_id = pv.id),
                    -- one entry per retailer link: tracked_url is the link the buy
                    -- button will use, null when none was built (no commission)
                    ''retailers'', coalesce((select jsonb_agg(jsonb_build_object(''partner'', pa.slug, ''partner_name'', pa.name,
                                     ''url'', al.url, ''tracked_url'', al.affiliate_url) order by pa.slug, al.url)
                                   from public.affiliate_links al join public.partners pa on pa.id = al.partner_id
                                  where al.variant_id = pv.id), ''[]''::jsonb))
                  order by pv.is_default desc, pv.slug)
                 from public.product_variants pv where pv.product_id = v_product_id))
    || v_status;

  if p_dry_run then
    raise exception ''create_product: dry run, nothing was written'' using errcode = ''P0DRY'', detail = v_result::text;
  end if;
  return v_result;
end;
$fn$;

comment on function public.create_product(jsonb, jsonb, jsonb, jsonb, uuid, integer, boolean) is
  ''Admin / service_role only. Creates a product with its brand, platforms, spec sheet, every variant (photos + retailer links) and fits-with rules in one transaction, optionally re-links a build''''s pending custom part, and returns product_data_status. p_dry_run raises P0DRY with the result instead of writing.'';

-- create or replace keeps the grants; restated so this file says the whole
-- of what is live.
revoke all on function public.create_product(jsonb, jsonb, jsonb, jsonb, uuid, integer, boolean) from public, anon;
grant execute on function public.create_product(jsonb, jsonb, jsonb, jsonb, uuid, integer, boolean) to authenticated, service_role;
"}', 'fix_strip_blank_and_link_result', 'ag.gamboa94@gmail.com', NULL, NULL);
INSERT INTO "supabase_migrations"."schema_migrations" ("version", "statements", "name", "created_by", "idempotency_key", "rollback") VALUES ('20261004032852', '{"-- material_optional.sql
-- NOT YET APPLIED. Dry-run 2026-10-04 against Gunforma-v2 inside one
-- rolled-back transaction; results in #133. Apply after #133 is merged,
-- alongside colors_admin_insert.sql and fix_strip_blank_and_link_result.sql.
--
-- The material rule, as ruled:
--   * material_family stays REQUIRED for approval. ''Unspecified'' (a row in
--     public.materials) is a valid answer. When it is the answer,
--     optional_blank carries \"material family unspecified\" so those parts can
--     be found later. It does not block approval.
--   * material, the exact wording, becomes OPTIONAL: a blank one moves from
--     missing[] to optional_blank[].
--
-- Only product_data_status() changes. create_product() still fills
-- optic_specs.housing_material and mag_release_specs.material from the
-- product''s material when one is given, and leaves them alone when it is
-- blank, exactly as before.
--
-- ONE CONSEQUENCE, deliberately left as it is: the optic rule row
-- housing_material is ''required'' in spec_field_rules. An optic with no
-- material therefore still reads missing \"spec.housing_material\" — blank
-- material stops blocking approval for every category except optics. Making
-- that row optional would be a one-row change to spec_field_rules; it is not
-- made here.
--
-- Restated from fix_product_data_status_url.sql (applied), with only the two
-- material lines changed; diff the two to see it.

create or replace function public.product_data_status(p_product_id uuid) returns jsonb
language plpgsql stable set search_path = '''' as $ds$
declare
  pr record; j jsonb; v_tbl regclass; r record; v_col text; v_val text;
  v_missing text[] := ''{}''; v_opt text[] := ''{}''; v_platforms text[];
begin
  select p.id, p.category, p.description, p.material, p.material_family::text as material_family,
         p.url, p.weight_oz, p.fitment_notes
    into pr from public.products p where p.id = p_product_id;
  if not found then return null; end if;

  if coalesce(btrim(pr.description), '''') = ''''     then v_missing := v_missing || ''description''::text; end if;
  if coalesce(btrim(pr.material_family), '''') = '''' then v_missing := v_missing || ''material_family''::text; end if;
  -- the source page the data came from: create_product() requires it, so a
  -- product without one did not come through it and is not approved
  if coalesce(btrim(pr.url), '''') = ''''             then v_missing := v_missing || ''url''::text; end if;

  v_platforms := array(select pl.slug from public.product_platforms pp join public.platforms pl on pl.id = pp.platform_id
                        where pp.product_id = p_product_id order by pl.slug);
  if cardinality(v_platforms) = 0 then v_missing := v_missing || ''platform''::text; end if;

  v_tbl := to_regclass(''public.'' || quote_ident(pr.category::text || ''_specs''));
  if v_tbl is not null then
    execute format(''select to_jsonb(s) from %s s where s.product_id = $1'', v_tbl) into j using p_product_id;
  end if;
  j := coalesce(j, ''{}''::jsonb);   -- no spec row: every applicable required field is missing
  for r in select f.field, f.requirement, f.only_when_field, f.only_when_values
             from public.spec_field_rules f where f.category = pr.category order by f.sort_order loop
    if r.only_when_field is not null and not coalesce((j ->> r.only_when_field) = any (r.only_when_values), false) then
      continue;   -- not applicable
    end if;
    v_col := case r.field when ''platform'' then ''platform_id'' when ''footprint'' then ''footprint_id'' else r.field end;
    v_val := j ->> v_col;
    if coalesce(btrim(v_val), '''') = '''' then
      if r.requirement = ''required'' then v_missing := v_missing || (''spec.'' || r.field);
      else v_opt := v_opt || (''spec.'' || r.field); end if;
    end if;
  end loop;

  if not exists (select 1 from public.product_variants pv where pv.product_id = p_product_id and pv.retired_at is null) then
    v_missing := v_missing || ''variant''::text;
  end if;
  v_missing := v_missing || array(select ''variant '' || pv.slug || '': photo'' from public.product_variants pv
                                   where pv.product_id = p_product_id and pv.retired_at is null and pv.primary_image_url is null order by pv.slug);
  v_missing := v_missing || array(select ''variant '' || pv.slug || '': msrp'' from public.product_variants pv
                                   where pv.product_id = p_product_id and pv.retired_at is null and pv.msrp is null order by pv.slug);

  if pr.category = ''light'' and not exists (select 1 from public.light_compatibility lc where lc.light_product_id = p_product_id) then
    v_missing := v_missing || ''light compatibility''::text;
  end if;

  if not exists (select 1 from public.affiliate_links al join public.product_variants pv on pv.id = al.variant_id
                  where pv.product_id = p_product_id and pv.retired_at is null and al.retired_at is null) then
    v_opt := v_opt || ''retailer link''::text;
  end if;
  -- material (the exact wording) is optional; material_family stays required
  -- above, and ''Unspecified'' answers it — reported here so those parts can be
  -- found later
  if coalesce(btrim(pr.material), '''') = ''''      then v_opt := v_opt || ''material''::text; end if;
  if pr.material_family = ''Unspecified''         then v_opt := v_opt || ''material family unspecified''::text; end if;
  if pr.weight_oz is null                       then v_opt := v_opt || ''weight_oz''::text; end if;
  if coalesce(btrim(pr.fitment_notes), '''') = '''' then v_opt := v_opt || ''fitment_notes''::text; end if;

  return jsonb_build_object(''approved'', cardinality(v_missing) = 0, ''missing'', to_jsonb(v_missing),
                            ''optional_blank'', to_jsonb(v_opt), ''platforms'', to_jsonb(v_platforms));
end;
$ds$;

revoke all on function public.product_data_status(uuid) from public, anon;
grant execute on function public.product_data_status(uuid) to authenticated, service_role;
"}', 'material_optional', 'ag.gamboa94@gmail.com', NULL, NULL);
INSERT INTO "supabase_migrations"."schema_migrations" ("version", "statements", "name", "created_by", "idempotency_key", "rollback") VALUES ('20261004224459', '{"-- relink_build_part.sql
-- NOT YET APPLIED. Dry-run 2026-10-04 against Gunforma-v2 inside one
-- rolled-back transaction; results in the PR. Apply AFTER the queue page
-- that calls it is merged and live: the page reports a missing function
-- cleanly, so it ships first.
--
-- Swaps a build''s pending custom part for a product that is ALREADY in the
-- catalog — the \"Link to existing part\" action on gunforma-admin-queue.html.
--
-- WHY. create_product() can re-link a pending part, but only while creating
-- the product. The first real part (Springer Precision''s +3 X-Macro base
-- plate) was saved from the add-a-part page without the build parameters, so
-- \"P365 Complete Build\" still shows it as pending and create_product() would
-- now refuse it as a duplicate. The same happens whenever a builder types a
-- part that already exists under another name.
--
-- WHAT IT WRITES: exactly what create_product()''s re-link step writes — name
-- and brand from the product; imageUrl, variantId, variantColor, variantLabel
-- and variantFinish from the chosen variant; pending false; every other key
-- of the entry (its category above all) left as it was — PLUS variantSpecs,
-- the spec line, when the caller sends a non-empty one. The queue page
-- computes it with js/variant-label.js, so the formula stays in one place
-- and a linked part reads the same as one picked in the builder.
--
-- REFUSES, each with a sentence an admin can act on:
--   * a caller who is not an admin (or the service role)       42501
--   * no such build, or no part at that index
--   * a part that is not a pending custom part — the same refusal as
--     create_product()''s re-link
--   * a part with corrections in builds.edit_history: the build page lays
--     those over the entry, so a linked part would read as the correction,
--     not the catalog part. It says how many there are.
--   * a product that does not exist; a variant that is not that product''s,
--     or is retired
-- It does NOT check that the product''s category suits the part''s section:
-- the queue page offers only products in that section, and the taxonomy
-- lives in js/build-categories.js. A copy here would be a third one.
--
-- p_part_index is the part''s ORIGINAL index in parts_snapshot (CLAUDE.md,
-- \"renderPartCard takes a part''s ORIGINAL index\").
--
-- The guard is is_admin() or is_trusted_backend(), never current_user:
-- SECURITY DEFINER rewrites current_user to the owner. The update passes
-- restrict_owner_edits_on_approved_build because the caller is an admin.

create or replace function public.relink_build_part(
  p_build_id uuid, p_part_index integer, p_product_id uuid, p_variant_id uuid,
  p_variant_specs text default null)
returns jsonb
language plpgsql security definer set search_path = ''''
as $rl$
declare
  v_part jsonb; v_history jsonb; v_corrections int; v_entry jsonb;
  pr record; pv record;
begin
  if not (public.is_admin() or public.is_trusted_backend()) then
    raise exception ''relink_build_part: admin or service_role only'' using errcode = ''42501'';
  end if;
  if p_build_id is null or p_part_index is null or p_product_id is null or p_variant_id is null then
    raise exception ''relink_build_part: build, part index, product and variant are all required'';
  end if;
  if p_part_index < 0 then
    raise exception ''relink_build_part: part index must be 0 or more'';   -- jsonb -> -1 would read from the end
  end if;

  select b.parts_snapshot -> p_part_index, coalesce(b.edit_history, ''[]''::jsonb)
    into v_part, v_history
    from public.builds b where b.id = p_build_id for update;
  if not found then raise exception ''relink_build_part: no build %'', p_build_id; end if;
  if v_part is null then raise exception ''relink_build_part: that build has no part at index %'', p_part_index; end if;
  if (v_part->>''pending'')::boolean is not true or v_part->>''refId'' is not null then
    raise exception ''relink_build_part: part % (\"%\") on that build is not a pending custom part'', p_part_index, v_part->>''name'';
  end if;

  select count(*) into v_corrections from jsonb_array_elements(v_history) e
   where (e->>''part_index'') ~ ''^[0-9]+$'' and (e->>''part_index'')::int = p_part_index;
  if v_corrections > 0 then
    raise exception ''relink_build_part: part % (\"%\") has % correction% in the review queue. The build page shows those over the part, so a linked part would read as the correction. Not linked.'',
      p_part_index, v_part->>''name'', v_corrections, case when v_corrections = 1 then '''' else ''s'' end;
  end if;

  select p.id, p.name, m.name as brand into pr
    from public.products p join public.manufacturers m on m.id = p.brand_id
   where p.id = p_product_id;
  if not found then raise exception ''relink_build_part: no product %'', p_product_id; end if;

  select v.id, v.product_id, v.retired_at, v.primary_image_url, v.color, v.variant_label, v.finish into pv
    from public.product_variants v where v.id = p_variant_id;
  if not found or pv.product_id is distinct from p_product_id then
    raise exception ''relink_build_part: that variant is not one of \"%\"''''s variants'', pr.name;
  end if;
  if pv.retired_at is not null then
    raise exception ''relink_build_part: that variant of \"%\" is retired. Pick a live one.'', pr.name;
  end if;

  v_entry := v_part
    || jsonb_strip_nulls(jsonb_build_object(''name'', pr.name, ''brand'', pr.brand, ''refId'', pr.id,
         ''imageUrl'', pv.primary_image_url, ''variantId'', pv.id, ''variantColor'', pv.color,
         ''variantLabel'', pv.variant_label, ''variantFinish'', pv.finish,
         ''variantSpecs'', nullif(btrim(coalesce(p_variant_specs, '''')), '''')))
    || jsonb_build_object(''pending'', false);

  update public.builds b set parts_snapshot = jsonb_set(b.parts_snapshot, array[p_part_index::text], v_entry)
   where b.id = p_build_id;

  return jsonb_build_object(''build_id'', p_build_id, ''part_index'', p_part_index, ''entry'', v_entry);
end;
$rl$;

comment on function public.relink_build_part(uuid, integer, uuid, uuid, text) is
  ''Admin / service_role only. Swaps a build''''s pending custom part (by its original index) for an existing catalog product and variant, as create_product()''''s re-link does, plus variantSpecs when given. Refuses a part that is not pending or carries corrections.'';

revoke all on function public.relink_build_part(uuid, integer, uuid, uuid, text) from public, anon;
grant execute on function public.relink_build_part(uuid, integer, uuid, uuid, text) to authenticated, service_role;
"}', 'relink_build_part', 'ag.gamboa94@gmail.com', NULL, NULL);
INSERT INTO "supabase_migrations"."schema_migrations" ("version", "statements", "name", "created_by", "idempotency_key", "rollback") VALUES ('20261005005427', '{"-- add_variants.sql
-- NOT YET APPLIED. Dry-run 2026-10-04 against Gunforma-v2 inside one
-- rolled-back transaction; results, and the A/B comparison of
-- create_product() before and after, in the PR. Apply AFTER the page that
-- calls add_variants() is merged and live.
--
-- WHY. gunforma-admin-part.html only creates new parts and create_product()
-- refuses an existing one. create_variant() exists but cannot set the option
-- columns (reticle, dot colour, battery, mount, bundle, clamp, manual
-- safety), builds no tracked link and has no page. 161 of 243 parts have
-- more than one variant, and a builder''s colour is often the one we lack.
--
-- WHAT.
--   variant_identity()            what makes two variants the same, normalised
--   create_variants_for_product() THE ONE COPY of \"a variant object becomes a
--                                 variant\", moved out of create_product()
--   create_product()              restated from fix_strip_blank_and_link_result.sql
--                                 with its variant loop replaced by one call;
--                                 nothing else in it changes
--   add_variants()                new variants on an existing part
--
-- create_product() BEHAVES AS BEFORE, with two intended differences that come
-- from the shared duplicate rule (ruled): identical variants are now caught
-- trimmed and case-insensitively, and the refusal names the match instead of
-- \"two variants are identical on every option\". The PR''s A/B table runs every
-- PR 1 case through the old and new function in one transaction and compares
-- the returned JSON and the rows written per table.

-- ── what makes two variants the same ────────────────────────────────────────
-- Every column that tells two variants of one part apart, normalised:
-- trimmed, case-folded, blank = null. optic_cut ''none'' = no cut, and a
-- missing manual-safety flag = false (bulk-loaded rows say false, rows from
-- create_product() leave it null; both mean \"no manual safety\").
-- \"anodized\" and \"Anodized \" are the same finish.
create or replace function public.variant_identity(
  p_color text, p_finish text, p_optic_cut text, p_handedness text, p_manual_safety boolean,
  p_reticle text, p_reticle_color text, p_battery_type text, p_mount_system text, p_bundle text,
  p_clamp text, p_clamp_style text, p_clamp_rail_type text)
returns text language sql immutable set search_path = '''' as $vi$
  select concat_ws(chr(31),
    coalesce(nullif(lower(btrim(p_color)), ''''), ''∅''),
    coalesce(nullif(lower(btrim(p_finish)), ''''), ''∅''),
    coalesce(nullif(nullif(lower(btrim(p_optic_cut)), ''''), ''none''), ''∅''),
    coalesce(nullif(lower(btrim(p_handedness)), ''''), ''∅''),
    coalesce(p_manual_safety, false)::text,
    coalesce(nullif(lower(btrim(p_reticle)), ''''), ''∅''),
    coalesce(nullif(lower(btrim(p_reticle_color)), ''''), ''∅''),
    coalesce(nullif(lower(btrim(p_battery_type)), ''''), ''∅''),
    coalesce(nullif(lower(btrim(p_mount_system)), ''''), ''∅''),
    coalesce(nullif(lower(btrim(p_bundle)), ''''), ''∅''),
    coalesce(nullif(lower(btrim(p_clamp)), ''''), ''∅''),
    coalesce(nullif(lower(btrim(p_clamp_style)), ''''), ''∅''),
    coalesce(nullif(lower(btrim(p_clamp_rail_type)), ''''), ''∅''));
$vi$;

-- ── one copy of \"a variant object becomes a variant\" ────────────────────────
-- Shared by create_product() and add_variants(). Unknown keys refused;
-- colour vocabulary, slug, default flag and the first photo are
-- create_variant()''s rules; the option columns it cannot carry are written
-- here and folded into the slug; gallery photos; retailer links with the Awin
-- link built and a wrong merchant id refused.
--
-- Checked BEFORE anything is written: unknown keys, and that no new variant
-- is identical on every option (variant_identity) to a live variant of the
-- part — discontinued ones included — or to another new one. The refusal
-- names the match.
--
-- Not callable from the API: SECURITY INVOKER with EXECUTE revoked from
-- everyone but the owner, so only the two SECURITY DEFINER callers reach it.
-- It repeats their guard anyway. p_caller only prefixes messages, so each
-- caller''s refusals read as its own.
create or replace function public.create_variants_for_product(
  p_product_id uuid, p_product_slug text, p_variants jsonb, p_caller text)
returns jsonb
language plpgsql set search_path = ''''
as $cv$
declare
  c_awin_affid   constant text   := ''2959345'';   -- Gunforma''s Awin publisher id; public, it is in every live link
  c_variant_keys constant text[] := array[''color'',''finish'',''sku'',''upc'',''msrp'',''image_url'',''gallery'',''variant_label'',''optic_cut'',''handedness'',''notes'',''is_default'',''manual_safety_variant'',''reticle'',''reticle_color'',''battery_type'',''mount_system'',''bundle'',''clamp_style'',''clamp_rail_type'',''clamp'',''partner_slug'',''url'',''affiliate_url'',''links'',''use_in_build''];
  c_link_keys    constant text[] := array[''partner_slug'',''url'',''affiliate_url'',''op_mpn'',''op_gtin'',''op_merchant_product_id'',''notes''];
  v jsonb; l jsonb; v_i int := 0; v_j int; v_bad text;
  v_variant_id uuid; v_build_variant uuid; v_links jsonb; v_partner_id uuid;
  v_mid text; v_aff text; v_aff_mid text;
  v_axes text; v_vslug text; v_vbase text; v_n int;
  v_ids uuid[] := ''{}''; v_new text[] := ''{}''; v_ident text; v_match record;
begin
  if not (public.is_admin() or public.is_trusted_backend()) then
    raise exception ''%: admin or service_role only'', p_caller using errcode = ''42501'';
  end if;

  -- pass 1: refuse before writing anything
  for v in select value from jsonb_array_elements(p_variants) loop
    v_i := v_i + 1;
    if jsonb_typeof(v) <> ''object'' then raise exception ''%: variant % is not an object'', p_caller, v_i; end if;
    v := public.jsonb_strip_blank(v);
    select string_agg(k, '', '') into v_bad from jsonb_object_keys(v) k where k <> all (c_variant_keys);
    if v_bad is not null then
      raise exception ''%: variant %: unknown field(s): %'', p_caller, v_i, v_bad;
    end if;
    v_ident := public.variant_identity(v->>''color'', v->>''finish'', v->>''optic_cut'', v->>''handedness'', (v->>''manual_safety_variant'')::boolean,
                 v->>''reticle'', v->>''reticle_color'', v->>''battery_type'', v->>''mount_system'', v->>''bundle'',
                 v->>''clamp'', v->>''clamp_style'', v->>''clamp_rail_type'');
    select pv.slug, pv.variant_label into v_match from public.product_variants pv
     where pv.product_id = p_product_id and pv.retired_at is null
       and public.variant_identity(pv.color, pv.finish, pv.optic_cut, pv.handedness, pv.manual_safety_variant,
             pv.reticle, pv.reticle_color, pv.battery_type, pv.mount_system, pv.bundle,
             pv.clamp, pv.clamp_style, pv.clamp_rail_type) = v_ident
     order by pv.slug limit 1;
    if found then
      raise exception ''%: variant % is identical on every option to the existing variant \"%\" (%). Change its colour, finish or an option, or edit that variant instead.'',
        p_caller, v_i, coalesce(v_match.variant_label, v_match.slug), v_match.slug;
    end if;
    v_j := array_position(v_new, v_ident);
    if v_j is not null then
      raise exception ''%: variants % and % are identical on every option. Each one must differ by colour, finish or another option.'', p_caller, v_j, v_i;
    end if;
    v_new := v_new || v_ident;
  end loop;

  -- pass 2: write
  v_i := 0;
  for v in select value from jsonb_array_elements(p_variants) loop
    v_i := v_i + 1;
    v := public.jsonb_strip_blank(v);

    v_variant_id := public.create_variant(
      p_product_slug => p_product_slug, p_color => v->>''color'', p_finish => v->>''finish'', p_sku => v->>''sku'', p_upc => v->>''upc'',
      p_msrp => (v->>''msrp'')::numeric, p_image_url => v->>''image_url'', p_variant_label => v->>''variant_label'',
      p_optic_cut => v->>''optic_cut'', p_handedness => v->>''handedness'', p_notes => v->>''notes'',
      p_make_default => case when (v->>''is_default'')::boolean then true end);

    -- the options create_variant does not carry; when present they also go into the slug
    v_axes := concat_ws(''-'', nullif(v->>''optic_cut'',''none''), v->>''reticle_color'', v->>''reticle'', v->>''clamp'', v->>''bundle'',
                        case when (v->>''manual_safety_variant'')::boolean then ''ms'' end,
                        case when v->>''handedness'' in (''left'',''right'') then v->>''handedness'' end);
    v_vslug := null;
    if v_axes <> '''' then
      v_vbase := public.slugify(p_product_slug || ''-'' || v_axes || ''-'' || (v->>''color'') || coalesce(''-'' || (v->>''finish''), ''''));
      v_vslug := v_vbase; v_n := 1;
      while exists (select 1 from public.product_variants where slug = v_vslug and id <> v_variant_id) loop
        v_n := v_n + 1; v_vslug := v_vbase || ''-'' || v_n;
      end loop;
    end if;
    update public.product_variants set
      slug = coalesce(v_vslug, slug),
      manual_safety_variant = (v->>''manual_safety_variant'')::boolean,
      reticle = v->>''reticle'', reticle_color = v->>''reticle_color'', battery_type = v->>''battery_type'',
      mount_system = v->>''mount_system'', bundle = v->>''bundle'', clamp_style = v->>''clamp_style'',
      clamp_rail_type = v->>''clamp_rail_type'', clamp = v->>''clamp''
    where id = v_variant_id;

    if v ? ''gallery'' then
      if v->>''image_url'' is null then
        raise exception ''%: variant %: gallery photos need a main photo first'', p_caller, v_i;
      end if;
      insert into public.variant_images (variant_id, url, position)
      select v_variant_id, g.url, (g.ord + 1)::smallint
        from jsonb_array_elements_text(v->''gallery'') with ordinality g(url, ord);
    end if;

    -- retailer links: zero or more per variant. street_price / in_stock /
    -- last_checked / op_last_matched_by are never set — the sync owns them.
    v_links := coalesce(v->''links'', ''[]''::jsonb);
    if jsonb_typeof(v_links) <> ''array'' then raise exception ''%: variant %: links must be a list'', p_caller, v_i; end if;
    if v ? ''url'' or v ? ''partner_slug'' or v ? ''affiliate_url'' then
      v_links := v_links || jsonb_build_array(jsonb_build_object(''partner_slug'', v->>''partner_slug'', ''url'', v->>''url'', ''affiliate_url'', v->>''affiliate_url''));
    end if;
    for l in select value from jsonb_array_elements(v_links) loop
      l := public.jsonb_strip_blank(l);
      select string_agg(k, '', '') into v_bad from jsonb_object_keys(l) k where k <> all (c_link_keys);
      if v_bad is not null then raise exception ''%: variant %: retailer link: unknown field(s): %'', p_caller, v_i, v_bad; end if;
      if l->>''partner_slug'' is null or l->>''url'' is null then
        raise exception ''%: variant %: each retailer link needs a retailer and a URL'', p_caller, v_i;
      end if;
      select pa.id, pa.awin_merchant_id into v_partner_id, v_mid from public.partners pa where pa.slug = l->>''partner_slug'';
      if v_partner_id is null then
        raise exception ''%: variant %: no partner with slug \"%\"'', p_caller, v_i, l->>''partner_slug'' using errcode = ''foreign_key_violation'';
      end if;
      v_aff := l->>''affiliate_url'';
      if v_mid is not null then
        if v_aff is null then
          v_aff := ''https://www.awin1.com/cread.php?awinmid='' || v_mid || ''&awinaffid='' || c_awin_affid
                || ''&clickref='' || public.url_encode(''build-detail_'' || p_product_slug)
                || ''&ued='' || public.url_encode(l->>''url'');
        elsif v_aff ~ ''awin1\\.com'' then
          v_aff_mid := coalesce(substring(v_aff from ''[?&]awinmid=(\\d+)''), substring(v_aff from ''[?&]m=(\\d+)''));
          if v_aff_mid is distinct from v_mid then
            raise exception ''%: variant %: the tracked link carries Awin merchant % but partner \"%\" is merchant %'', p_caller, v_i, coalesce(v_aff_mid,''(none)''), l->>''partner_slug'', v_mid;
          end if;
        end if;
      end if;
      insert into public.affiliate_links (variant_id, partner_id, url, affiliate_url, notes, op_mpn, op_gtin, op_merchant_product_id)
      values (v_variant_id, v_partner_id, l->>''url'', v_aff, l->>''notes'', l->>''op_mpn'', l->>''op_gtin'', l->>''op_merchant_product_id'');
    end loop;

    v_ids := v_ids || v_variant_id;
    if (v->>''use_in_build'')::boolean then v_build_variant := v_variant_id; end if;
  end loop;

  return jsonb_build_object(''variant_ids'', to_jsonb(v_ids), ''build_variant'', v_build_variant);
end;
$cv$;

create or replace function public.create_product(
  p_product jsonb, p_variants jsonb, p_specs jsonb default null, p_fits jsonb default null,
  p_build_id uuid default null, p_part_index integer default null, p_dry_run boolean default false)
returns jsonb
language plpgsql security definer set search_path = ''''
as $fn$
declare
  c_awin_affid   constant text   := ''2959345'';   -- Gunforma''s Awin publisher id; public, it is in every live link
  c_product_keys constant text[] := array[''brand'',''name'',''category'',''platforms'',''slug'',''url'',''description'',''family'',''material'',''material_family'',''fitment_notes'',''build_warning'',''build_notes'',''weight_oz'',''fitment_confidence'',''internal_notes''];
  c_variant_keys constant text[] := array[''color'',''finish'',''sku'',''upc'',''msrp'',''image_url'',''gallery'',''variant_label'',''optic_cut'',''handedness'',''notes'',''is_default'',''manual_safety_variant'',''reticle'',''reticle_color'',''battery_type'',''mount_system'',''bundle'',''clamp_style'',''clamp_rail_type'',''clamp'',''partner_slug'',''url'',''affiliate_url'',''links'',''use_in_build''];
  c_link_keys    constant text[] := array[''partner_slug'',''url'',''affiliate_url'',''op_mpn'',''op_gtin'',''op_merchant_product_id'',''notes''];
  p jsonb; s jsonb; f jsonb; v jsonb; l jsonb; r jsonb; v_result jsonb; v_status jsonb;
  v_category public.product_category; v_want public.product_category; v_platforms text[];
  v_platform_id uuid; v_platform_name text; v_kind text; v_len numeric; v_lengths text;
  v_brand_id uuid; v_brand_name text; v_brand_created boolean := false;
  v_product_id uuid; v_slug text; v_name text; v_confidence public.fitment_confidence;
  v_i int := 0; v_bad text; v_n int; v_key text;
  v_variant_id uuid; v_build_variant uuid; v_links jsonb; v_partner_id uuid; v_other_id uuid;
  v_mid text; v_aff text; v_aff_mid text;
  v_axes text; v_vslug text; v_vbase text; v_part jsonb;
  v_tbl regclass; v_rule_fields text[]; v_collist text; v_has_specs boolean := false;
  v_warn text[] := ''{}'';
  v_vr jsonb;
begin
  if not (public.is_admin() or public.is_trusted_backend()) then
    raise exception ''create_product: admin or service_role only'' using errcode = ''42501'';
  end if;
  if p_product is null or jsonb_typeof(p_product) <> ''object'' then
    raise exception ''create_product: p_product must be an object'';
  end if;
  p := public.jsonb_strip_blank(p_product);
  if p ? ''installation_difficulty'' or p ? ''best_for'' then
    raise exception ''create_product: installation_difficulty and best_for are no longer entered. Existing values stay where they are; leave these out.'';
  end if;
  select string_agg(k, '', '') into v_bad from jsonb_object_keys(p) k where k <> all (c_product_keys);
  if v_bad is not null then raise exception ''create_product: unknown product field(s): %'', v_bad; end if;
  v_name := btrim(coalesce(p->>''name'', ''''));
  if btrim(coalesce(p->>''brand'', '''')) = '''' or v_name = '''' then
    raise exception ''create_product: brand and name are required'';
  end if;
  if p->>''category'' is null then raise exception ''create_product: category is required''; end if;
  v_category := (p->>''category'')::public.product_category;
  v_confidence := coalesce((p->>''fitment_confidence'')::public.fitment_confidence, ''unverified'');

  -- ── platform: explicit, never defaulted ───────────────────────────────────
  if jsonb_typeof(p->''platforms'') is distinct from ''array'' or jsonb_array_length(p->''platforms'') = 0 then
    raise exception ''create_product: send at least one platform (e.g. \"platforms\": [\"p365\"]). Nothing defaults: without one the part never appears in the builder.'';
  end if;
  v_platforms := array(select distinct x from jsonb_array_elements_text(p->''platforms'') x order by x);
  select string_agg(x, '', '') into v_bad from unnest(v_platforms) x where not exists (select 1 from public.platforms pl where pl.slug = x);
  if v_bad is not null then
    raise exception ''create_product: unknown platform(s): %. Known: %'', v_bad,
      (select string_agg(slug, '', '' order by slug) from public.platforms) using errcode = ''foreign_key_violation'';
  end if;
  if v_category in (''slide'', ''barrel'') and cardinality(v_platforms) <> 1 then
    raise exception ''create_product: a % belongs to exactly one platform; this one names %: %. Send one.'',
      v_category, cardinality(v_platforms), array_to_string(v_platforms, '', '');
  end if;
  select string_agg(pl.name, '', '' order by pl.name) into v_bad from public.platforms pl
   where pl.slug = any (v_platforms) and not pl.is_live;
  if v_bad is not null then
    v_warn := v_warn || (''Not live yet: '' || v_bad || ''. The part is saved and appears when the platform launches.'');
  end if;

  if p->>''url'' is null then
    raise exception ''create_product: the source URL (the product page the data came from) is required'';
  end if;
  if p_variants is null or jsonb_typeof(p_variants) <> ''array'' or jsonb_array_length(p_variants) = 0 then
    raise exception ''create_product: at least one variant is required'';
  end if;
  if (p_build_id is null) <> (p_part_index is null) or p_part_index < 0 then
    raise exception ''create_product: p_build_id and p_part_index must be supplied together'';
  end if;

  select m.id, m.name into v_brand_id, v_brand_name from public.manufacturers m
   where lower(m.name) = lower(btrim(p->>''brand'')) or m.slug = public.slugify(p->>''brand'')
   order by m.created_at limit 1;
  if v_brand_id is null then
    insert into public.manufacturers (slug, name) values (public.slugify(p->>''brand''), btrim(p->>''brand''))
    returning id, name into v_brand_id, v_brand_name;
    v_brand_created := true;
  end if;

  -- The slug is the product''s URL for good. Brand is prefixed unless the name
  -- already starts with it. Pass \"slug\" to choose it by hand.
  v_slug := coalesce(nullif(btrim(p->>''slug''), ''''),
    public.slugify(case when left(lower(v_name), length(v_brand_name)) = lower(v_brand_name)
                        then v_name else v_brand_name || '' '' || v_name end));
  if exists (select 1 from public.products where slug = v_slug) then
    raise exception ''create_product: a product with slug \"%\" already exists. To add a colour or option to it, use create_variant.'', v_slug using errcode = ''unique_violation'';
  end if;
  if exists (select 1 from public.products where brand_id = v_brand_id and lower(name) = lower(v_name)) then
    raise exception ''create_product: % already has a product named \"%\". To add a colour or option to it, use create_variant.'', v_brand_name, v_name using errcode = ''unique_violation'';
  end if;

  insert into public.products (slug, category, brand_id, name, family, url, description, material, material_family,
                               fitment_notes, build_warning, build_notes, weight_oz, fitment_confidence)
  values (v_slug, v_category, v_brand_id, v_name, p->>''family'', p->>''url'', p->>''description'', p->>''material'', p->>''material_family'',
          p->>''fitment_notes'', p->>''build_warning'', p->>''build_notes'', (p->>''weight_oz'')::numeric, ''unverified'')
  returning id into v_product_id;
  -- fitment_confidence is set at the end, once the part is known to be approved

  if p ? ''internal_notes'' then
    insert into public.product_internal (product_id, internal_notes) values (v_product_id, p->>''internal_notes'');
  end if;

  insert into public.product_platforms (product_id, platform_id)
  select v_product_id, pl.id from public.platforms pl where pl.slug = any (v_platforms);

  -- ── spec sheet ────────────────────────────────────────────────────────────
  -- Accepted keys are the category''s spec_field_rules fields and nothing else.
  -- Only supplied keys are named in the INSERT, so column defaults survive.
  s := public.jsonb_strip_blank(p_specs);
  v_tbl := to_regclass(''public.'' || quote_ident(v_category::text || ''_specs''));
  v_rule_fields := array(select fr.field from public.spec_field_rules fr where fr.category = v_category order by fr.sort_order);
  if s <> ''{}''::jsonb then
    if v_tbl is null then raise exception ''create_product: a % has no spec sheet; leave p_specs out'', v_category; end if;
    select string_agg(k, '', '') into v_bad from jsonb_object_keys(s) k where k <> all (v_rule_fields);
    if v_bad is not null then
      raise exception ''create_product: spec sheet: no rule for field(s): %. Fields for a %: %'', v_bad, v_category, array_to_string(v_rule_fields, '', '');
    end if;

    -- platform: the product''s one platform. A disagreeing key is refused.
    if ''platform'' = any (v_rule_fields) then
      if s ? ''platform'' and s->>''platform'' <> v_platforms[1] then
        raise exception ''create_product: spec sheet platform \"%\" disagrees with the product''''s platform \"%\"'', s->>''platform'', v_platforms[1];
      end if;
      select pl.id, pl.name into v_platform_id, v_platform_name from public.platforms pl where pl.slug = v_platforms[1];
      s := (s - ''platform'') || jsonb_build_object(''platform_id'', v_platform_id);
    end if;
    if s ? ''footprint'' then
      select fp.id into v_other_id from public.footprints fp where fp.slug = s->>''footprint'';
      if v_other_id is null then
        raise exception ''create_product: spec sheet: no footprint \"%\". Known: %'', s->>''footprint'',
          (select string_agg(slug, '', '' order by slug) from public.footprints);
      end if;
      s := (s - ''footprint'') || jsonb_build_object(''footprint_id'', v_other_id);
    end if;

    -- material is one fact held in two places
    foreach v_key in array array[''housing_material'', ''material''] loop
      if v_key = any (v_rule_fields) then
        if s ? v_key and p ? ''material'' and lower(btrim(s->>v_key)) <> lower(btrim(p->>''material'')) then
          raise exception ''create_product: material is one fact: the product says \"%\" but the spec sheet''''s % says \"%\"'', p->>''material'', v_key, s->>v_key;
        elsif not s ? v_key and p ? ''material'' then
          s := s || jsonb_build_object(v_key, p->>''material'');
        elsif s ? v_key and not p ? ''material'' then
          update public.products set material = s->>v_key where id = v_product_id;
        end if;
      end if;
    end loop;

    -- only-when fields whose condition holds must come with the sheet
    select string_agg(fr.field, '', '' order by fr.sort_order) into v_bad from public.spec_field_rules fr
     where fr.category = v_category and fr.requirement = ''required'' and fr.only_when_field is not null
       and (s ->> fr.only_when_field) = any (fr.only_when_values)
       and coalesce(btrim(s ->> fr.field), '''') = '''';
    if v_bad is not null then
      raise exception ''create_product: the % spec sheet needs % (it applies here because of %)'', v_category, v_bad,
        (select string_agg(distinct fr.only_when_field || '' = '' || (s ->> fr.only_when_field), '', '') from public.spec_field_rules fr
          where fr.category = v_category and fr.only_when_field is not null and fr.field = any (string_to_array(v_bad, '', '')));
    end if;

    -- slide / barrel length must be registered for that platform. Checked
    -- here so an admin reads a sentence, not the class trigger''s raw text.
    if v_category in (''slide'', ''barrel'') then
      v_kind := v_category::text;
      v_len  := (s ->> (v_kind || ''_length_in''))::numeric;
      if v_len is not null then
        if not exists (select 1 from public.platform_part_lengths ppl where ppl.platform_id = v_platform_id and ppl.part_kind = v_kind) then
          raise exception ''create_product: % % lengths are not registered yet. Add them to platform_part_lengths before adding a % for it.'',
            v_platform_name, v_kind, v_kind;
        end if;
        if not exists (select 1 from public.platform_part_lengths ppl
                        where ppl.platform_id = v_platform_id and ppl.part_kind = v_kind and ppl.length_in = v_len) then
          select string_agg(ppl.length_in::text, '', '' order by ppl.length_in) into v_lengths from public.platform_part_lengths ppl
           where ppl.platform_id = v_platform_id and ppl.part_kind = v_kind;
          raise exception ''create_product: no % % is registered at % in. Registered % lengths: %.'', v_platform_name, v_kind, v_len, v_kind, v_lengths;
        end if;
      end if;
    end if;

    -- columns the table itself declares NOT NULL without a default
    select string_agg(a.attname::text, '', '') into v_bad from pg_catalog.pg_attribute a
     where a.attrelid = v_tbl and a.attnum > 0 and not a.attisdropped and a.attnotnull and not a.atthasdef
       and a.attname::text not in (''product_id'', ''category'') and not s ? (a.attname::text);
    if v_bad is not null then
      raise exception ''create_product: the % spec sheet needs: %'', v_category, replace(replace(v_bad, ''footprint_id'', ''footprint''), ''platform_id'', ''platform'');
    end if;

    s := s || jsonb_build_object(''product_id'', v_product_id, ''category'', v_category);
    select string_agg(quote_ident(k), '', '') into v_collist from jsonb_object_keys(s) k;
    execute format(''insert into %s (%s) select %s from jsonb_populate_record(null::%s, $1)'', v_tbl, v_collist, v_collist, v_tbl) using s;
    v_has_specs := true;
  end if;

  -- ── variants ──────────────────────────────────────────────────────────────
  -- The loop lives in create_variants_for_product(), shared with
  -- add_variants(): one copy of how a variant object becomes a variant.
  v_vr := public.create_variants_for_product(v_product_id, v_slug, p_variants, ''create_product'');
  v_build_variant := (v_vr->>''build_variant'')::uuid;

  if exists (select 1 from public.product_variants pv where pv.product_id = v_product_id and pv.is_default
               and (pv.primary_image_url is null or pv.msrp is null)) then
    raise exception ''create_product: the default variant needs a photo and an MSRP'';
  end if;

  -- ── fits-with rules ───────────────────────────────────────────────────────
  f := public.jsonb_strip_blank(p_fits);
  for v_key, r in select e.key, e.value from jsonb_each(f) e loop
    if not ((v_category = ''light''   and v_key = ''light_compatibility'')
         or (v_category = ''optic''   and v_key = ''adapter_footprints'')
         or (v_category = ''barrel''  and v_key = ''slides'')
         or (v_category = ''slide''   and v_key = ''barrels'')
         or (v_category = ''magwell'' and v_key = ''frames'')
         or (v_category = ''frame''   and v_key = ''magwells'')) then
      raise exception ''create_product: fits-with rule \"%\" does not apply to a %. (light: light_compatibility; optic: adapter_footprints; barrel: slides; slide: barrels; magwell: frames; frame: magwells)'', v_key, v_category;
    end if;
    if jsonb_typeof(r) <> ''array'' then raise exception ''create_product: fits-with rule \"%\" must be a list'', v_key; end if;
    -- these four reference the <category>_specs row, not products
    if v_key in (''light_compatibility'',''adapter_footprints'',''slides'',''barrels'') and not v_has_specs then
      raise exception ''create_product: fits-with rules for a % need its spec sheet filled in first'', v_category;
    end if;
    for l in select value from jsonb_array_elements(r) loop
      if jsonb_typeof(l) = ''string'' then l := jsonb_build_object(''product'', l #>> ''{}''); end if;
      l := public.jsonb_strip_blank(l);
      if v_key = ''light_compatibility'' then
        select string_agg(k, '', '') into v_bad from jsonb_object_keys(l) k
         where k <> all (array[''rail_type'',''fitment_type'',''key_or_adapter'',''gun_make'',''gun'',''gun_model_text'',''confirmed'',''notes'']);
        if v_bad is not null then raise exception ''create_product: light_compatibility: unknown field(s): %'', v_bad; end if;
        v_other_id := null;
        if l ? ''gun'' then
          select g.id into v_other_id from public.guns g where g.slug = l->>''gun'';
          if v_other_id is null then raise exception ''create_product: light_compatibility: no gun \"%\"'', l->>''gun''; end if;
        end if;
        insert into public.light_compatibility (light_product_id, rail_type, fitment_type, key_or_adapter, gun_make, gun_id, gun_model_text, confirmed, notes)
        values (v_product_id, l->>''rail_type'', (l->>''fitment_type'')::public.light_fitment_type, l->>''key_or_adapter'', l->>''gun_make'',
                v_other_id, l->>''gun_model_text'', coalesce((l->>''confirmed'')::boolean, false), l->>''notes'');
      elsif v_key = ''adapter_footprints'' then
        select string_agg(k, '', '') into v_bad from jsonb_object_keys(l) k where k <> all (array[''footprint'',''plate_included'',''notes'']);
        if v_bad is not null then raise exception ''create_product: adapter_footprints: unknown field(s): %'', v_bad; end if;
        if not l ? ''plate_included'' then raise exception ''create_product: adapter_footprints: say whether the plate is included''; end if;
        select fp.id into v_other_id from public.footprints fp where fp.slug = l->>''footprint'';
        if v_other_id is null then raise exception ''create_product: adapter_footprints: no footprint \"%\"'', l->>''footprint''; end if;
        insert into public.optic_adapter_footprints (optic_product_id, footprint_id, plate_included, notes)
        values (v_product_id, v_other_id, (l->>''plate_included'')::boolean, l->>''notes'');
      else
        select string_agg(k, '', '') into v_bad from jsonb_object_keys(l) k where k <> all (array[''product'',''source'',''compatibility_note'']);
        if v_bad is not null then raise exception ''create_product: %: unknown field(s): %'', v_key, v_bad; end if;
        v_want := case v_key when ''slides'' then ''slide'' when ''barrels'' then ''barrel'' when ''frames'' then ''frame'' else ''magwell'' end;
        select pr.id into v_other_id from public.products pr where pr.slug = l->>''product'' and pr.category = v_want;
        if v_other_id is null then
          raise exception ''create_product: %: there is no % with slug \"%\"'', v_key, v_want, l->>''product'';
        end if;
        if v_key in (''slides'',''barrels'') then
          insert into public.barrel_slide_requirements (barrel_product_id, slide_product_id, source, compatibility_note)
          values (case when v_key = ''slides'' then v_product_id else v_other_id end,
                  case when v_key = ''slides'' then v_other_id else v_product_id end,
                  l->>''source'', l->>''compatibility_note'');
        elsif l ? ''source'' then
          insert into public.magwell_frame_requirements (magwell_product_id, frame_product_id, source, compatibility_note)
          values (case when v_key = ''frames'' then v_product_id else v_other_id end,
                  case when v_key = ''frames'' then v_other_id else v_product_id end,
                  l->>''source'', l->>''compatibility_note'');
        else
          insert into public.magwell_frame_requirements (magwell_product_id, frame_product_id, compatibility_note)
          values (case when v_key = ''frames'' then v_product_id else v_other_id end,
                  case when v_key = ''frames'' then v_other_id else v_product_id end,
                  l->>''compatibility_note'');
        end if;
      end if;
    end loop;
  end loop;

  -- ── things the admin should know, but that do not block ───────────────────
  if v_category = ''slide'' and not f ? ''barrels'' then
    select string_agg(distinct pr.slug, '', '') into v_bad
      from public.barrel_slide_requirements b join public.products pr on pr.id = b.barrel_product_id;
    if v_bad is not null then
      v_warn := v_warn || (''These barrels only fit the slides listed for them, so they will show as NOT fitting this slide: '' || v_bad);
    end if;
  end if;
  if v_category = ''frame'' and not f ? ''magwells'' then
    select string_agg(distinct pr.slug, '', '') into v_bad
      from public.magwell_frame_requirements b join public.products pr on pr.id = b.magwell_product_id;
    if v_bad is not null then
      v_warn := v_warn || (''These magwells only fit the frames listed for them, so they will show as NOT fitting this frame: '' || v_bad);
    end if;
  end if;

  -- ── swap the build''s pending custom part for this product ─────────────────
  -- variantSpecs is not written into the snapshot here: its formula lives in
  -- js/variant-label.js and _variant-label.mjs, and a third copy in SQL would
  -- drift. The build page reads the spec line from the live variant.
  if p_build_id is not null then
    select b.parts_snapshot -> p_part_index into v_part from public.builds b where b.id = p_build_id for update;
    if not found then raise exception ''create_product: no build %'', p_build_id; end if;
    if v_part is null then raise exception ''create_product: build has no part at index %'', p_part_index; end if;
    if (v_part->>''pending'')::boolean is not true or v_part->>''refId'' is not null then
      raise exception ''create_product: part % (\"%\") on that build is not a pending custom part'', p_part_index, v_part->>''name'';
    end if;
    if v_build_variant is null then
      select pv.id into v_build_variant from public.product_variants pv where pv.product_id = v_product_id and pv.is_default;
    end if;
    update public.builds b set parts_snapshot = jsonb_set(b.parts_snapshot, array[p_part_index::text],
        v_part
        || jsonb_strip_nulls(jsonb_build_object(''name'', v_name, ''brand'', v_brand_name, ''refId'', v_product_id,
             ''imageUrl'', pv.primary_image_url, ''variantId'', pv.id, ''variantColor'', pv.color,
             ''variantLabel'', pv.variant_label, ''variantFinish'', pv.finish))
        || jsonb_build_object(''pending'', false))
    from public.product_variants pv
    where b.id = p_build_id and pv.id = v_build_variant;
  end if;

  -- ── completeness, and the confidence it allows ────────────────────────────
  v_status := public.product_data_status(v_product_id);
  if v_confidence <> ''unverified'' then
    if not (v_status->>''approved'')::boolean then
      raise exception ''create_product: fitment confidence \"%\" needs an approved part. Still missing: %'',
        v_confidence, (select string_agg(x, '', '') from jsonb_array_elements_text(v_status->''missing'') x);
    end if;
    update public.products set fitment_confidence = v_confidence where id = v_product_id;
  end if;

  v_result := jsonb_build_object(
    ''product_id'', v_product_id, ''slug'', v_slug, ''category'', v_category,
    ''brand'', v_brand_name, ''brand_created'', v_brand_created, ''build_relinked'', p_build_id is not null,
    ''has_spec_sheet'', v_has_specs, ''fitment_confidence'', v_confidence, ''warnings'', to_jsonb(v_warn),
    ''variants'', (select jsonb_agg(jsonb_build_object(''id'', pv.id, ''slug'', pv.slug, ''label'', pv.variant_label, ''default'', pv.is_default,
                    ''photos'', (select count(*) from public.variant_images vi where vi.variant_id = pv.id),
                    ''links'', (select count(*) from public.affiliate_links al where al.variant_id = pv.id),
                    -- one entry per retailer link: tracked_url is the link the buy
                    -- button will use, null when none was built (no commission)
                    ''retailers'', coalesce((select jsonb_agg(jsonb_build_object(''partner'', pa.slug, ''partner_name'', pa.name,
                                     ''url'', al.url, ''tracked_url'', al.affiliate_url) order by pa.slug, al.url)
                                   from public.affiliate_links al join public.partners pa on pa.id = al.partner_id
                                  where al.variant_id = pv.id), ''[]''::jsonb))
                  order by pv.is_default desc, pv.slug)
                 from public.product_variants pv where pv.product_id = v_product_id))
    || v_status;

  if p_dry_run then
    raise exception ''create_product: dry run, nothing was written'' using errcode = ''P0DRY'', detail = v_result::text;
  end if;
  return v_result;
end;
$fn$;

comment on function public.create_product(jsonb, jsonb, jsonb, jsonb, uuid, integer, boolean) is
  ''Admin / service_role only. Creates a product with its brand, platforms, spec sheet, every variant (photos + retailer links) and fits-with rules in one transaction, optionally re-links a build''''s pending custom part, and returns product_data_status. p_dry_run raises P0DRY with the result instead of writing.'';

-- ── add_variants(): new variants on a part that already exists ──────────────
-- Same variant object, same rules and same dry run as create_product(), plus:
--   * every new variant needs a photo and an MSRP — adding a variant must
--     never unapprove a part (refused here, not only on the page)
--   * at most one new variant may say is_default. When one does, the old
--     default is unset in the same transaction (create_variant() does it,
--     and variants_one_default_per_product enforces it); otherwise the
--     current default stays the default
--   * existing variants are never changed
--   * an unknown or discontinued part is refused
-- Returns the new variants (with each retailer link''s tracked URL) plus
-- product_data_status. p_dry_run raises P0DRY with that result in DETAIL.
create or replace function public.add_variants(
  p_product_slug text, p_variants jsonb, p_dry_run boolean default false)
returns jsonb
language plpgsql security definer set search_path = ''''
as $av$
declare
  pr record; v jsonb; v_i int := 0; v_defaults int := 0; v_vr jsonb; v_result jsonb;
begin
  if not (public.is_admin() or public.is_trusted_backend()) then
    raise exception ''add_variants: admin or service_role only'' using errcode = ''42501'';
  end if;
  select p.id, p.slug, p.category, p.is_discontinued into pr from public.products p where p.slug = btrim(coalesce(p_product_slug, ''''));
  if not found then
    raise exception ''add_variants: no product with slug \"%\"'', p_product_slug using errcode = ''foreign_key_violation'';
  end if;
  if pr.is_discontinued then
    raise exception ''add_variants: \"%\" is discontinued. New variants are not added to a discontinued part.'', pr.slug;
  end if;
  if p_variants is null or jsonb_typeof(p_variants) <> ''array'' or jsonb_array_length(p_variants) = 0 then
    raise exception ''add_variants: at least one variant is required'';
  end if;
  for v in select value from jsonb_array_elements(p_variants) loop
    v_i := v_i + 1;
    if jsonb_typeof(v) <> ''object'' then raise exception ''add_variants: variant % is not an object'', v_i; end if;
    v := public.jsonb_strip_blank(v);
    if v->>''image_url'' is null or v->>''msrp'' is null then
      raise exception ''add_variants: variant % needs a photo and an MSRP. A new variant without them would leave the part unapproved.'', v_i;
    end if;
    if (v->>''is_default'')::boolean then v_defaults := v_defaults + 1; end if;
  end loop;
  if v_defaults > 1 then
    raise exception ''add_variants: % new variants say is_default. A part has one default; mark at most one.'', v_defaults;
  end if;

  v_vr := public.create_variants_for_product(pr.id, pr.slug, p_variants, ''add_variants'');

  v_result := jsonb_build_object(
    ''product_id'', pr.id, ''slug'', pr.slug, ''category'', pr.category, ''warnings'', ''[]''::jsonb,
    ''defaults'', (select count(*) from public.product_variants pv where pv.product_id = pr.id and pv.is_default and pv.retired_at is null),
    ''variants'', (select jsonb_agg(jsonb_build_object(''id'', pv.id, ''slug'', pv.slug, ''label'', pv.variant_label, ''default'', pv.is_default,
                    ''photos'', (select count(*) from public.variant_images vi where vi.variant_id = pv.id),
                    ''links'', (select count(*) from public.affiliate_links al where al.variant_id = pv.id),
                    ''retailers'', coalesce((select jsonb_agg(jsonb_build_object(''partner'', pa.slug, ''partner_name'', pa.name,
                                     ''url'', al.url, ''tracked_url'', al.affiliate_url) order by pa.slug, al.url)
                                   from public.affiliate_links al join public.partners pa on pa.id = al.partner_id
                                  where al.variant_id = pv.id), ''[]''::jsonb))
                  order by pv.is_default desc, pv.slug)
                 from public.product_variants pv
                where pv.id in (select (x #>> ''{}'')::uuid from jsonb_array_elements(v_vr->''variant_ids'') x)))
    || public.product_data_status(pr.id);

  if p_dry_run then
    raise exception ''add_variants: dry run, nothing was written'' using errcode = ''P0DRY'', detail = v_result::text;
  end if;
  return v_result;
end;
$av$;

-- grants: create or replace keeps them; restated so this file says the whole
-- of what is live. The helper and the identity function are not callable
-- from the API at all.
revoke all on function public.variant_identity(text, text, text, text, boolean, text, text, text, text, text, text, text, text) from public, anon, authenticated;
revoke all on function public.create_variants_for_product(uuid, text, jsonb, text) from public, anon, authenticated;
revoke all on function public.create_product(jsonb, jsonb, jsonb, jsonb, uuid, integer, boolean) from public, anon;
grant execute on function public.create_product(jsonb, jsonb, jsonb, jsonb, uuid, integer, boolean) to authenticated, service_role;
revoke all on function public.add_variants(text, jsonb, boolean) from public, anon;
grant execute on function public.add_variants(text, jsonb, boolean) to authenticated, service_role;
"}', 'add_variants', 'ag.gamboa94@gmail.com', NULL, NULL);
INSERT INTO "supabase_migrations"."schema_migrations" ("version", "statements", "name", "created_by", "idempotency_key", "rollback") VALUES ('20261005020804', '{"-- add_categories_enum.sql
-- Three new products.category values: recoil springs, sights, and Other
-- Parts (catalog parts that fit no other category). Values only: nothing
-- here touches a row, and no page reads them until a product has one.
--
-- Its own file, applied on its own and BEFORE add_categories.sql: Postgres
-- refuses to USE an enum value in the transaction that added it, so the
-- spec tables, rules and functions that name these values cannot run (or be
-- dry-run) until this is committed.
--
-- `other` is a products.category value. It is NOT the legacy parts_snapshot
-- section key `other_parts` (retired in #114), and neither is ever used as
-- the other; see js/build-categories.js.
--
-- Appended in this order, so the enum order (which _category-meta.mjs and
-- js/category-map.js follow) ends: … slide_plate, recoil_spring, sight, other.

alter type public.product_category add value if not exists ''recoil_spring'';
alter type public.product_category add value if not exists ''sight'';
alter type public.product_category add value if not exists ''other'';"}', 'add_categories_enum', 'ag.gamboa94@gmail.com', NULL, NULL);
INSERT INTO "supabase_migrations"."schema_migrations" ("version", "statements", "name", "created_by", "idempotency_key", "rollback") VALUES ('20261005024538', '{"-- add_categories.sql
-- NOT YET APPLIED. Needs add_categories_enum.sql (applied 2026-10-05,
-- 20261005020804) first: Postgres refuses to use an enum value in the
-- transaction that added it. Dry-run 2026-10-05 against Gunforma-v2 inside
-- one rolled-back transaction; results, and the A/B comparison of
-- create_product() and relink_build_part() before and after, in the PR.
--
-- WHAT.
--   recoil_spring_specs, sight_specs   the two new spec sheets
--   spec_field_rules                   their rules (approved field lists)
--   products.part_type                 an Other Part''s one extra fact
--   create_product()                   part_type; recoil-spring slide length;
--                                      guide rod material is the material;
--                                      a misc part re-linked takes the
--                                      product''s category
--   relink_build_part()                the same misc rule
--
-- product_data_status() does not change: it finds a spec sheet by name
-- (<category>_specs) and its rules in spec_field_rules, and an Other Part
-- cannot exist without a part type (the table rule below).
--
-- Both spec tables follow frame_specs/optic_specs: a category column held to
-- its one value, and the (product_id, category) FK into products, so a spec
-- row can only ever belong to a product of that category. Unlike the older
-- spec tables they arrive with grants revoked: SELECT only, to anon and
-- authenticated, behind a read policy (CLAUDE.md, \"every new public table
-- needs RLS and an explicit revoke\"). The older tables'' broad grants are
-- logged, not fixed here.

-- ── recoil springs ──────────────────────────────────────────────────────────
-- A different spring weight or slide length is a different PRODUCT, not a
-- variant: neither is one of the option columns variant_identity() compares,
-- so two weights as variants would be refused as identical.
create table public.recoil_spring_specs (
  product_id         uuid primary key,
  category           public.product_category not null default ''recoil_spring'',
  slide_length_in    numeric(3,2),   -- the slide length it fits; registered in platform_part_lengths
  spring_weight      text,           -- as the maker writes it: \"13 lb\", \"Reduced (Soft)\"
  captured           boolean,
  spring_type        text,           -- flat-wire, round-wire, dual
  guide_rod_material text,           -- filled from products.material (\"material is one fact\")
  constraint recoil_spring_specs_category check (category = ''recoil_spring''),
  constraint recoil_spring_specs_product_fkey foreign key (product_id, category)
    references public.products (id, category) on delete cascade
);

-- ── sights ──────────────────────────────────────────────────────────────────
-- The front dot colour is a VARIANT option (product_variants.reticle_color,
-- labelled \"Front dot colour\" for sights), so green and orange fronts are
-- variants of one product.
create table public.sight_specs (
  product_id     uuid primary key,
  category       public.product_category not null default ''sight'',
  sight_position text,   -- front | rear | set
  height         text,   -- standard | suppressor (makers'' \"co-witness\")
  sight_type     text,   -- night (tritium) | fiber | night-fiber | plain
  dovetail       text,   -- the slide cut, as makers write it; optional
  rear_notch     text,   -- U-notch, square, …; optional
  constraint sight_specs_category check (category = ''sight''),
  constraint sight_specs_sight_position check (sight_position in (''front'', ''rear'', ''set'')),
  constraint sight_specs_height check (height in (''standard'', ''suppressor'')),
  constraint sight_specs_sight_type check (sight_type in (''night'', ''fiber'', ''night-fiber'', ''plain'')),
  constraint sight_specs_product_fkey foreign key (product_id, category)
    references public.products (id, category) on delete cascade
);

alter table public.recoil_spring_specs enable row level security;
alter table public.sight_specs enable row level security;
revoke all on public.recoil_spring_specs, public.sight_specs from public, anon, authenticated;
grant select on public.recoil_spring_specs, public.sight_specs to anon, authenticated;
create policy recoil_spring_specs_public_read on public.recoil_spring_specs for select to anon, authenticated using (true);
create policy sight_specs_public_read on public.sight_specs for select to anon, authenticated using (true);

-- ── rules (the approved field lists) ────────────────────────────────────────
insert into public.spec_field_rules (category, field, requirement, only_when_field, only_when_values, label, sort_order) values
  (''recoil_spring'', ''slide_length_in'',    ''required'', null, null, ''Slide length (in)'',    10),
  (''recoil_spring'', ''spring_weight'',      ''required'', null, null, ''Spring weight'',        20),
  (''recoil_spring'', ''captured'',           ''required'', null, null, ''Captured'',             30),
  (''recoil_spring'', ''spring_type'',        ''optional'', null, null, ''Spring type'',          40),
  (''recoil_spring'', ''guide_rod_material'', ''optional'', null, null, ''Guide rod material'',   50),
  (''sight'',         ''sight_position'',     ''required'', null, null, ''Front, rear or set'',   10),
  (''sight'',         ''height'',             ''required'', null, null, ''Height'',               20),
  (''sight'',         ''sight_type'',         ''required'', null, null, ''Sight type'',           30),
  (''sight'',         ''dovetail'',           ''optional'', null, null, ''Dovetail / slide cut'', 40),
  (''sight'',         ''rear_notch'',         ''optional'', null, null, ''Rear notch'',           50);

-- ── Other Parts: part_type ──────────────────────────────────────────────────
-- Two or three words saying what the part is (\"thumb ledge\"). An Other Part
-- must have one and no other category may: the rule compares the category as
-- TEXT, so it does not depend on the enum value at plan time. anon reads
-- products through column grants, so the new column is granted explicitly.
alter table public.products add column part_type text;
alter table public.products add constraint products_part_type_other
  check ((category::text = ''other'') = (coalesce(btrim(part_type), '''') <> ''''));
grant select (part_type) on public.products to anon, authenticated;
comment on column public.products.part_type is
  ''Other Parts only: what the part is, in two or three words (\"thumb ledge\"). Required there, absent everywhere else (products_part_type_other).'';

-- ── create_product(): restated from add_variants.sql (applied) ──────────────
-- Changes, and nothing else: part_type accepted, required for and only for
-- Other Parts; a recoil spring''s slide length must be registered for one of
-- its platforms; guide_rod_material is filled from the material, like an
-- optic''s housing_material; a re-linked part stored under misc takes the
-- product''s category.
create or replace function public.create_product(
  p_product jsonb, p_variants jsonb, p_specs jsonb default null, p_fits jsonb default null,
  p_build_id uuid default null, p_part_index integer default null, p_dry_run boolean default false)
returns jsonb
language plpgsql security definer set search_path = ''''
as $fn$
declare
  c_awin_affid   constant text   := ''2959345'';   -- Gunforma''s Awin publisher id; public, it is in every live link
  c_product_keys constant text[] := array[''brand'',''name'',''category'',''platforms'',''slug'',''url'',''description'',''family'',''material'',''material_family'',''fitment_notes'',''build_warning'',''build_notes'',''weight_oz'',''fitment_confidence'',''internal_notes'',''part_type''];
  c_variant_keys constant text[] := array[''color'',''finish'',''sku'',''upc'',''msrp'',''image_url'',''gallery'',''variant_label'',''optic_cut'',''handedness'',''notes'',''is_default'',''manual_safety_variant'',''reticle'',''reticle_color'',''battery_type'',''mount_system'',''bundle'',''clamp_style'',''clamp_rail_type'',''clamp'',''partner_slug'',''url'',''affiliate_url'',''links'',''use_in_build''];
  c_link_keys    constant text[] := array[''partner_slug'',''url'',''affiliate_url'',''op_mpn'',''op_gtin'',''op_merchant_product_id'',''notes''];
  p jsonb; s jsonb; f jsonb; v jsonb; l jsonb; r jsonb; v_result jsonb; v_status jsonb;
  v_category public.product_category; v_want public.product_category; v_platforms text[];
  v_platform_id uuid; v_platform_name text; v_kind text; v_len numeric; v_lengths text;
  v_brand_id uuid; v_brand_name text; v_brand_created boolean := false;
  v_product_id uuid; v_slug text; v_name text; v_confidence public.fitment_confidence;
  v_i int := 0; v_bad text; v_n int; v_key text;
  v_variant_id uuid; v_build_variant uuid; v_links jsonb; v_partner_id uuid; v_other_id uuid;
  v_mid text; v_aff text; v_aff_mid text;
  v_axes text; v_vslug text; v_vbase text; v_part jsonb;
  v_tbl regclass; v_rule_fields text[]; v_collist text; v_has_specs boolean := false;
  v_warn text[] := ''{}'';
  v_vr jsonb;
begin
  if not (public.is_admin() or public.is_trusted_backend()) then
    raise exception ''create_product: admin or service_role only'' using errcode = ''42501'';
  end if;
  if p_product is null or jsonb_typeof(p_product) <> ''object'' then
    raise exception ''create_product: p_product must be an object'';
  end if;
  p := public.jsonb_strip_blank(p_product);
  if p ? ''installation_difficulty'' or p ? ''best_for'' then
    raise exception ''create_product: installation_difficulty and best_for are no longer entered. Existing values stay where they are; leave these out.'';
  end if;
  select string_agg(k, '', '') into v_bad from jsonb_object_keys(p) k where k <> all (c_product_keys);
  if v_bad is not null then raise exception ''create_product: unknown product field(s): %'', v_bad; end if;
  v_name := btrim(coalesce(p->>''name'', ''''));
  if btrim(coalesce(p->>''brand'', '''')) = '''' or v_name = '''' then
    raise exception ''create_product: brand and name are required'';
  end if;
  if p->>''category'' is null then raise exception ''create_product: category is required''; end if;
  v_category := (p->>''category'')::public.product_category;
  v_confidence := coalesce((p->>''fitment_confidence'')::public.fitment_confidence, ''unverified'');

  -- Other Parts: what the part is, in two or three words, is its one extra
  -- fact (products.part_type). Only that category carries one; the table
  -- rule products_part_type_other says the same, and this says it in words.
  if v_category::text = ''other'' and coalesce(btrim(p->>''part_type''), '''') = '''' then
    raise exception ''create_product: an Other Part needs a part type: two or three words saying what it is (e.g. \"thumb ledge\")'';
  elsif v_category::text <> ''other'' and p ? ''part_type'' then
    raise exception ''create_product: a part type is only for Other Parts; a % is its own category'', v_category;
  end if;

  -- ── platform: explicit, never defaulted ───────────────────────────────────
  if jsonb_typeof(p->''platforms'') is distinct from ''array'' or jsonb_array_length(p->''platforms'') = 0 then
    raise exception ''create_product: send at least one platform (e.g. \"platforms\": [\"p365\"]). Nothing defaults: without one the part never appears in the builder.'';
  end if;
  v_platforms := array(select distinct x from jsonb_array_elements_text(p->''platforms'') x order by x);
  select string_agg(x, '', '') into v_bad from unnest(v_platforms) x where not exists (select 1 from public.platforms pl where pl.slug = x);
  if v_bad is not null then
    raise exception ''create_product: unknown platform(s): %. Known: %'', v_bad,
      (select string_agg(slug, '', '' order by slug) from public.platforms) using errcode = ''foreign_key_violation'';
  end if;
  if v_category in (''slide'', ''barrel'') and cardinality(v_platforms) <> 1 then
    raise exception ''create_product: a % belongs to exactly one platform; this one names %: %. Send one.'',
      v_category, cardinality(v_platforms), array_to_string(v_platforms, '', '');
  end if;
  select string_agg(pl.name, '', '' order by pl.name) into v_bad from public.platforms pl
   where pl.slug = any (v_platforms) and not pl.is_live;
  if v_bad is not null then
    v_warn := v_warn || (''Not live yet: '' || v_bad || ''. The part is saved and appears when the platform launches.'');
  end if;

  if p->>''url'' is null then
    raise exception ''create_product: the source URL (the product page the data came from) is required'';
  end if;
  if p_variants is null or jsonb_typeof(p_variants) <> ''array'' or jsonb_array_length(p_variants) = 0 then
    raise exception ''create_product: at least one variant is required'';
  end if;
  if (p_build_id is null) <> (p_part_index is null) or p_part_index < 0 then
    raise exception ''create_product: p_build_id and p_part_index must be supplied together'';
  end if;

  select m.id, m.name into v_brand_id, v_brand_name from public.manufacturers m
   where lower(m.name) = lower(btrim(p->>''brand'')) or m.slug = public.slugify(p->>''brand'')
   order by m.created_at limit 1;
  if v_brand_id is null then
    insert into public.manufacturers (slug, name) values (public.slugify(p->>''brand''), btrim(p->>''brand''))
    returning id, name into v_brand_id, v_brand_name;
    v_brand_created := true;
  end if;

  -- The slug is the product''s URL for good. Brand is prefixed unless the name
  -- already starts with it. Pass \"slug\" to choose it by hand.
  v_slug := coalesce(nullif(btrim(p->>''slug''), ''''),
    public.slugify(case when left(lower(v_name), length(v_brand_name)) = lower(v_brand_name)
                        then v_name else v_brand_name || '' '' || v_name end));
  if exists (select 1 from public.products where slug = v_slug) then
    raise exception ''create_product: a product with slug \"%\" already exists. To add a colour or option to it, use create_variant.'', v_slug using errcode = ''unique_violation'';
  end if;
  if exists (select 1 from public.products where brand_id = v_brand_id and lower(name) = lower(v_name)) then
    raise exception ''create_product: % already has a product named \"%\". To add a colour or option to it, use create_variant.'', v_brand_name, v_name using errcode = ''unique_violation'';
  end if;

  insert into public.products (slug, category, brand_id, name, family, url, description, material, material_family,
                               fitment_notes, build_warning, build_notes, weight_oz, fitment_confidence, part_type)
  values (v_slug, v_category, v_brand_id, v_name, p->>''family'', p->>''url'', p->>''description'', p->>''material'', p->>''material_family'',
          p->>''fitment_notes'', p->>''build_warning'', p->>''build_notes'', (p->>''weight_oz'')::numeric, ''unverified'', btrim(p->>''part_type''))
  returning id into v_product_id;
  -- fitment_confidence is set at the end, once the part is known to be approved

  if p ? ''internal_notes'' then
    insert into public.product_internal (product_id, internal_notes) values (v_product_id, p->>''internal_notes'');
  end if;

  insert into public.product_platforms (product_id, platform_id)
  select v_product_id, pl.id from public.platforms pl where pl.slug = any (v_platforms);

  -- ── spec sheet ────────────────────────────────────────────────────────────
  -- Accepted keys are the category''s spec_field_rules fields and nothing else.
  -- Only supplied keys are named in the INSERT, so column defaults survive.
  s := public.jsonb_strip_blank(p_specs);
  v_tbl := to_regclass(''public.'' || quote_ident(v_category::text || ''_specs''));
  v_rule_fields := array(select fr.field from public.spec_field_rules fr where fr.category = v_category order by fr.sort_order);
  if s <> ''{}''::jsonb then
    if v_tbl is null then raise exception ''create_product: a % has no spec sheet; leave p_specs out'', v_category; end if;
    select string_agg(k, '', '') into v_bad from jsonb_object_keys(s) k where k <> all (v_rule_fields);
    if v_bad is not null then
      raise exception ''create_product: spec sheet: no rule for field(s): %. Fields for a %: %'', v_bad, v_category, array_to_string(v_rule_fields, '', '');
    end if;

    -- platform: the product''s one platform. A disagreeing key is refused.
    if ''platform'' = any (v_rule_fields) then
      if s ? ''platform'' and s->>''platform'' <> v_platforms[1] then
        raise exception ''create_product: spec sheet platform \"%\" disagrees with the product''''s platform \"%\"'', s->>''platform'', v_platforms[1];
      end if;
      select pl.id, pl.name into v_platform_id, v_platform_name from public.platforms pl where pl.slug = v_platforms[1];
      s := (s - ''platform'') || jsonb_build_object(''platform_id'', v_platform_id);
    end if;
    if s ? ''footprint'' then
      select fp.id into v_other_id from public.footprints fp where fp.slug = s->>''footprint'';
      if v_other_id is null then
        raise exception ''create_product: spec sheet: no footprint \"%\". Known: %'', s->>''footprint'',
          (select string_agg(slug, '', '' order by slug) from public.footprints);
      end if;
      s := (s - ''footprint'') || jsonb_build_object(''footprint_id'', v_other_id);
    end if;

    -- material is one fact held in two places
    foreach v_key in array array[''housing_material'', ''material'', ''guide_rod_material''] loop
      if v_key = any (v_rule_fields) then
        if s ? v_key and p ? ''material'' and lower(btrim(s->>v_key)) <> lower(btrim(p->>''material'')) then
          raise exception ''create_product: material is one fact: the product says \"%\" but the spec sheet''''s % says \"%\"'', p->>''material'', v_key, s->>v_key;
        elsif not s ? v_key and p ? ''material'' then
          s := s || jsonb_build_object(v_key, p->>''material'');
        elsif s ? v_key and not p ? ''material'' then
          update public.products set material = s->>v_key where id = v_product_id;
        end if;
      end if;
    end loop;

    -- only-when fields whose condition holds must come with the sheet
    select string_agg(fr.field, '', '' order by fr.sort_order) into v_bad from public.spec_field_rules fr
     where fr.category = v_category and fr.requirement = ''required'' and fr.only_when_field is not null
       and (s ->> fr.only_when_field) = any (fr.only_when_values)
       and coalesce(btrim(s ->> fr.field), '''') = '''';
    if v_bad is not null then
      raise exception ''create_product: the % spec sheet needs % (it applies here because of %)'', v_category, v_bad,
        (select string_agg(distinct fr.only_when_field || '' = '' || (s ->> fr.only_when_field), '', '') from public.spec_field_rules fr
          where fr.category = v_category and fr.only_when_field is not null and fr.field = any (string_to_array(v_bad, '', '')));
    end if;

    -- slide / barrel length must be registered for that platform. Checked
    -- here so an admin reads a sentence, not the class trigger''s raw text.
    if v_category in (''slide'', ''barrel'') then
      v_kind := v_category::text;
      v_len  := (s ->> (v_kind || ''_length_in''))::numeric;
      if v_len is not null then
        if not exists (select 1 from public.platform_part_lengths ppl where ppl.platform_id = v_platform_id and ppl.part_kind = v_kind) then
          raise exception ''create_product: % % lengths are not registered yet. Add them to platform_part_lengths before adding a % for it.'',
            v_platform_name, v_kind, v_kind;
        end if;
        if not exists (select 1 from public.platform_part_lengths ppl
                        where ppl.platform_id = v_platform_id and ppl.part_kind = v_kind and ppl.length_in = v_len) then
          select string_agg(ppl.length_in::text, '', '' order by ppl.length_in) into v_lengths from public.platform_part_lengths ppl
           where ppl.platform_id = v_platform_id and ppl.part_kind = v_kind;
          raise exception ''create_product: no % % is registered at % in. Registered % lengths: %.'', v_platform_name, v_kind, v_len, v_kind, v_lengths;
        end if;
      end if;
    end if;

    -- a recoil spring fits one slide length. It has no platform rule of its
    -- own, so the length must be registered for one of the part''s platforms.
    if v_category::text = ''recoil_spring'' and s ? ''slide_length_in'' then
      v_len := (s ->> ''slide_length_in'')::numeric;
      if not exists (select 1 from public.platform_part_lengths ppl join public.platforms pl on pl.id = ppl.platform_id
                      where pl.slug = any (v_platforms) and ppl.part_kind = ''slide'' and ppl.length_in = v_len) then
        select string_agg(distinct ppl.length_in::text, '', '' order by ppl.length_in::text) into v_lengths
          from public.platform_part_lengths ppl join public.platforms pl on pl.id = ppl.platform_id
         where pl.slug = any (v_platforms) and ppl.part_kind = ''slide'';
        raise exception ''create_product: no slide length of % in is registered for %. Registered slide lengths: %.'',
          v_len, array_to_string(v_platforms, '', ''), coalesce(v_lengths, ''none'');
      end if;
    end if;

    -- columns the table itself declares NOT NULL without a default
    select string_agg(a.attname::text, '', '') into v_bad from pg_catalog.pg_attribute a
     where a.attrelid = v_tbl and a.attnum > 0 and not a.attisdropped and a.attnotnull and not a.atthasdef
       and a.attname::text not in (''product_id'', ''category'') and not s ? (a.attname::text);
    if v_bad is not null then
      raise exception ''create_product: the % spec sheet needs: %'', v_category, replace(replace(v_bad, ''footprint_id'', ''footprint''), ''platform_id'', ''platform'');
    end if;

    s := s || jsonb_build_object(''product_id'', v_product_id, ''category'', v_category);
    select string_agg(quote_ident(k), '', '') into v_collist from jsonb_object_keys(s) k;
    execute format(''insert into %s (%s) select %s from jsonb_populate_record(null::%s, $1)'', v_tbl, v_collist, v_collist, v_tbl) using s;
    v_has_specs := true;
  end if;

  -- ── variants ──────────────────────────────────────────────────────────────
  -- The loop lives in create_variants_for_product(), shared with
  -- add_variants(): one copy of how a variant object becomes a variant.
  v_vr := public.create_variants_for_product(v_product_id, v_slug, p_variants, ''create_product'');
  v_build_variant := (v_vr->>''build_variant'')::uuid;

  if exists (select 1 from public.product_variants pv where pv.product_id = v_product_id and pv.is_default
               and (pv.primary_image_url is null or pv.msrp is null)) then
    raise exception ''create_product: the default variant needs a photo and an MSRP'';
  end if;

  -- ── fits-with rules ───────────────────────────────────────────────────────
  f := public.jsonb_strip_blank(p_fits);
  for v_key, r in select e.key, e.value from jsonb_each(f) e loop
    if not ((v_category = ''light''   and v_key = ''light_compatibility'')
         or (v_category = ''optic''   and v_key = ''adapter_footprints'')
         or (v_category = ''barrel''  and v_key = ''slides'')
         or (v_category = ''slide''   and v_key = ''barrels'')
         or (v_category = ''magwell'' and v_key = ''frames'')
         or (v_category = ''frame''   and v_key = ''magwells'')) then
      raise exception ''create_product: fits-with rule \"%\" does not apply to a %. (light: light_compatibility; optic: adapter_footprints; barrel: slides; slide: barrels; magwell: frames; frame: magwells)'', v_key, v_category;
    end if;
    if jsonb_typeof(r) <> ''array'' then raise exception ''create_product: fits-with rule \"%\" must be a list'', v_key; end if;
    -- these four reference the <category>_specs row, not products
    if v_key in (''light_compatibility'',''adapter_footprints'',''slides'',''barrels'') and not v_has_specs then
      raise exception ''create_product: fits-with rules for a % need its spec sheet filled in first'', v_category;
    end if;
    for l in select value from jsonb_array_elements(r) loop
      if jsonb_typeof(l) = ''string'' then l := jsonb_build_object(''product'', l #>> ''{}''); end if;
      l := public.jsonb_strip_blank(l);
      if v_key = ''light_compatibility'' then
        select string_agg(k, '', '') into v_bad from jsonb_object_keys(l) k
         where k <> all (array[''rail_type'',''fitment_type'',''key_or_adapter'',''gun_make'',''gun'',''gun_model_text'',''confirmed'',''notes'']);
        if v_bad is not null then raise exception ''create_product: light_compatibility: unknown field(s): %'', v_bad; end if;
        v_other_id := null;
        if l ? ''gun'' then
          select g.id into v_other_id from public.guns g where g.slug = l->>''gun'';
          if v_other_id is null then raise exception ''create_product: light_compatibility: no gun \"%\"'', l->>''gun''; end if;
        end if;
        insert into public.light_compatibility (light_product_id, rail_type, fitment_type, key_or_adapter, gun_make, gun_id, gun_model_text, confirmed, notes)
        values (v_product_id, l->>''rail_type'', (l->>''fitment_type'')::public.light_fitment_type, l->>''key_or_adapter'', l->>''gun_make'',
                v_other_id, l->>''gun_model_text'', coalesce((l->>''confirmed'')::boolean, false), l->>''notes'');
      elsif v_key = ''adapter_footprints'' then
        select string_agg(k, '', '') into v_bad from jsonb_object_keys(l) k where k <> all (array[''footprint'',''plate_included'',''notes'']);
        if v_bad is not null then raise exception ''create_product: adapter_footprints: unknown field(s): %'', v_bad; end if;
        if not l ? ''plate_included'' then raise exception ''create_product: adapter_footprints: say whether the plate is included''; end if;
        select fp.id into v_other_id from public.footprints fp where fp.slug = l->>''footprint'';
        if v_other_id is null then raise exception ''create_product: adapter_footprints: no footprint \"%\"'', l->>''footprint''; end if;
        insert into public.optic_adapter_footprints (optic_product_id, footprint_id, plate_included, notes)
        values (v_product_id, v_other_id, (l->>''plate_included'')::boolean, l->>''notes'');
      else
        select string_agg(k, '', '') into v_bad from jsonb_object_keys(l) k where k <> all (array[''product'',''source'',''compatibility_note'']);
        if v_bad is not null then raise exception ''create_product: %: unknown field(s): %'', v_key, v_bad; end if;
        v_want := case v_key when ''slides'' then ''slide'' when ''barrels'' then ''barrel'' when ''frames'' then ''frame'' else ''magwell'' end;
        select pr.id into v_other_id from public.products pr where pr.slug = l->>''product'' and pr.category = v_want;
        if v_other_id is null then
          raise exception ''create_product: %: there is no % with slug \"%\"'', v_key, v_want, l->>''product'';
        end if;
        if v_key in (''slides'',''barrels'') then
          insert into public.barrel_slide_requirements (barrel_product_id, slide_product_id, source, compatibility_note)
          values (case when v_key = ''slides'' then v_product_id else v_other_id end,
                  case when v_key = ''slides'' then v_other_id else v_product_id end,
                  l->>''source'', l->>''compatibility_note'');
        elsif l ? ''source'' then
          insert into public.magwell_frame_requirements (magwell_product_id, frame_product_id, source, compatibility_note)
          values (case when v_key = ''frames'' then v_product_id else v_other_id end,
                  case when v_key = ''frames'' then v_other_id else v_product_id end,
                  l->>''source'', l->>''compatibility_note'');
        else
          insert into public.magwell_frame_requirements (magwell_product_id, frame_product_id, compatibility_note)
          values (case when v_key = ''frames'' then v_product_id else v_other_id end,
                  case when v_key = ''frames'' then v_other_id else v_product_id end,
                  l->>''compatibility_note'');
        end if;
      end if;
    end loop;
  end loop;

  -- ── things the admin should know, but that do not block ───────────────────
  if v_category = ''slide'' and not f ? ''barrels'' then
    select string_agg(distinct pr.slug, '', '') into v_bad
      from public.barrel_slide_requirements b join public.products pr on pr.id = b.barrel_product_id;
    if v_bad is not null then
      v_warn := v_warn || (''These barrels only fit the slides listed for them, so they will show as NOT fitting this slide: '' || v_bad);
    end if;
  end if;
  if v_category = ''frame'' and not f ? ''magwells'' then
    select string_agg(distinct pr.slug, '', '') into v_bad
      from public.magwell_frame_requirements b join public.products pr on pr.id = b.magwell_product_id;
    if v_bad is not null then
      v_warn := v_warn || (''These magwells only fit the frames listed for them, so they will show as NOT fitting this frame: '' || v_bad);
    end if;
  end if;

  -- ── swap the build''s pending custom part for this product ─────────────────
  -- variantSpecs is not written into the snapshot here: its formula lives in
  -- js/variant-label.js and _variant-label.mjs, and a third copy in SQL would
  -- drift. The build page reads the spec line from the live variant.
  if p_build_id is not null then
    select b.parts_snapshot -> p_part_index into v_part from public.builds b where b.id = p_build_id for update;
    if not found then raise exception ''create_product: no build %'', p_build_id; end if;
    if v_part is null then raise exception ''create_product: build has no part at index %'', p_part_index; end if;
    if (v_part->>''pending'')::boolean is not true or v_part->>''refId'' is not null then
      raise exception ''create_product: part % (\"%\") on that build is not a pending custom part'', p_part_index, v_part->>''name'';
    end if;
    if v_build_variant is null then
      select pv.id into v_build_variant from public.product_variants pv where pv.product_id = v_product_id and pv.is_default;
    end if;
    update public.builds b set parts_snapshot = jsonb_set(b.parts_snapshot, array[p_part_index::text],
        v_part
        || jsonb_strip_nulls(jsonb_build_object(''name'', v_name, ''brand'', v_brand_name, ''refId'', v_product_id,
             ''imageUrl'', pv.primary_image_url, ''variantId'', pv.id, ''variantColor'', pv.color,
             ''variantLabel'', pv.variant_label, ''variantFinish'', pv.finish))
        || jsonb_build_object(''pending'', false)
        -- Other Parts (stored as `misc`) is the catch-all: a part typed there
        -- takes the product''s own category, so it renders in its real section
        -- (the DMP recoil spring under Recoil Springs). Every other section
        -- keeps the category it was saved under.
        || case when v_part->>''category'' = ''misc'' then jsonb_build_object(''category'', v_category::text) else ''{}''::jsonb end)
    from public.product_variants pv
    where b.id = p_build_id and pv.id = v_build_variant;
  end if;

  -- ── completeness, and the confidence it allows ────────────────────────────
  v_status := public.product_data_status(v_product_id);
  if v_confidence <> ''unverified'' then
    if not (v_status->>''approved'')::boolean then
      raise exception ''create_product: fitment confidence \"%\" needs an approved part. Still missing: %'',
        v_confidence, (select string_agg(x, '', '') from jsonb_array_elements_text(v_status->''missing'') x);
    end if;
    update public.products set fitment_confidence = v_confidence where id = v_product_id;
  end if;

  v_result := jsonb_build_object(
    ''product_id'', v_product_id, ''slug'', v_slug, ''category'', v_category,
    ''brand'', v_brand_name, ''brand_created'', v_brand_created, ''build_relinked'', p_build_id is not null,
    ''has_spec_sheet'', v_has_specs, ''fitment_confidence'', v_confidence, ''warnings'', to_jsonb(v_warn),
    ''variants'', (select jsonb_agg(jsonb_build_object(''id'', pv.id, ''slug'', pv.slug, ''label'', pv.variant_label, ''default'', pv.is_default,
                    ''photos'', (select count(*) from public.variant_images vi where vi.variant_id = pv.id),
                    ''links'', (select count(*) from public.affiliate_links al where al.variant_id = pv.id),
                    -- one entry per retailer link: tracked_url is the link the buy
                    -- button will use, null when none was built (no commission)
                    ''retailers'', coalesce((select jsonb_agg(jsonb_build_object(''partner'', pa.slug, ''partner_name'', pa.name,
                                     ''url'', al.url, ''tracked_url'', al.affiliate_url) order by pa.slug, al.url)
                                   from public.affiliate_links al join public.partners pa on pa.id = al.partner_id
                                  where al.variant_id = pv.id), ''[]''::jsonb))
                  order by pv.is_default desc, pv.slug)
                 from public.product_variants pv where pv.product_id = v_product_id))
    || v_status;

  if p_dry_run then
    raise exception ''create_product: dry run, nothing was written'' using errcode = ''P0DRY'', detail = v_result::text;
  end if;
  return v_result;
end;
$fn$;

comment on function public.create_product(jsonb, jsonb, jsonb, jsonb, uuid, integer, boolean) is
  ''Admin / service_role only. Creates a product with its brand, platforms, spec sheet, every variant (photos + retailer links) and fits-with rules in one transaction, optionally re-links a build''''s pending custom part, and returns product_data_status. p_dry_run raises P0DRY with the result instead of writing.'';

-- ── relink_build_part(): restated from relink_build_part.sql (applied) ──────
-- One change: a part stored under misc (Other Parts, the catch-all) takes the
-- product''s own category. Every other section keeps its category.
create or replace function public.relink_build_part(
  p_build_id uuid, p_part_index integer, p_product_id uuid, p_variant_id uuid,
  p_variant_specs text default null)
returns jsonb
language plpgsql security definer set search_path = ''''
as $rl$
declare
  v_part jsonb; v_history jsonb; v_corrections int; v_entry jsonb;
  pr record; pv record;
begin
  if not (public.is_admin() or public.is_trusted_backend()) then
    raise exception ''relink_build_part: admin or service_role only'' using errcode = ''42501'';
  end if;
  if p_build_id is null or p_part_index is null or p_product_id is null or p_variant_id is null then
    raise exception ''relink_build_part: build, part index, product and variant are all required'';
  end if;
  if p_part_index < 0 then
    raise exception ''relink_build_part: part index must be 0 or more'';   -- jsonb -> -1 would read from the end
  end if;

  select b.parts_snapshot -> p_part_index, coalesce(b.edit_history, ''[]''::jsonb)
    into v_part, v_history
    from public.builds b where b.id = p_build_id for update;
  if not found then raise exception ''relink_build_part: no build %'', p_build_id; end if;
  if v_part is null then raise exception ''relink_build_part: that build has no part at index %'', p_part_index; end if;
  if (v_part->>''pending'')::boolean is not true or v_part->>''refId'' is not null then
    raise exception ''relink_build_part: part % (\"%\") on that build is not a pending custom part'', p_part_index, v_part->>''name'';
  end if;

  select count(*) into v_corrections from jsonb_array_elements(v_history) e
   where (e->>''part_index'') ~ ''^[0-9]+$'' and (e->>''part_index'')::int = p_part_index;
  if v_corrections > 0 then
    raise exception ''relink_build_part: part % (\"%\") has % correction% in the review queue. The build page shows those over the part, so a linked part would read as the correction. Not linked.'',
      p_part_index, v_part->>''name'', v_corrections, case when v_corrections = 1 then '''' else ''s'' end;
  end if;

  select p.id, p.name, p.category, m.name as brand into pr
    from public.products p join public.manufacturers m on m.id = p.brand_id
   where p.id = p_product_id;
  if not found then raise exception ''relink_build_part: no product %'', p_product_id; end if;

  select v.id, v.product_id, v.retired_at, v.primary_image_url, v.color, v.variant_label, v.finish into pv
    from public.product_variants v where v.id = p_variant_id;
  if not found or pv.product_id is distinct from p_product_id then
    raise exception ''relink_build_part: that variant is not one of \"%\"''''s variants'', pr.name;
  end if;
  if pv.retired_at is not null then
    raise exception ''relink_build_part: that variant of \"%\" is retired. Pick a live one.'', pr.name;
  end if;

  v_entry := v_part
    || jsonb_strip_nulls(jsonb_build_object(''name'', pr.name, ''brand'', pr.brand, ''refId'', pr.id,
         ''imageUrl'', pv.primary_image_url, ''variantId'', pv.id, ''variantColor'', pv.color,
         ''variantLabel'', pv.variant_label, ''variantFinish'', pv.finish,
         ''variantSpecs'', nullif(btrim(coalesce(p_variant_specs, '''')), '''')))
    || jsonb_build_object(''pending'', false)
    -- Other Parts (stored as `misc`) is the catch-all: a linked part takes the
    -- product''s own category and renders in its real section. Every other
    -- section keeps the category it was saved under.
    || case when v_part->>''category'' = ''misc'' then jsonb_build_object(''category'', pr.category::text) else ''{}''::jsonb end;

  update public.builds b set parts_snapshot = jsonb_set(b.parts_snapshot, array[p_part_index::text], v_entry)
   where b.id = p_build_id;

  return jsonb_build_object(''build_id'', p_build_id, ''part_index'', p_part_index, ''entry'', v_entry);
end;
$rl$;

comment on function public.relink_build_part(uuid, integer, uuid, uuid, text) is
  ''Admin / service_role only. Swaps a build''''s pending custom part (by its original index) for an existing catalog product and variant, as create_product()''''s re-link does, plus variantSpecs when given. A part stored under misc (Other Parts) takes the product''''s category. Refuses a part that is not pending or carries corrections.'';

revoke all on function public.relink_build_part(uuid, integer, uuid, uuid, text) from public, anon;
grant execute on function public.relink_build_part(uuid, integer, uuid, uuid, text) to authenticated, service_role;

-- grants: create or replace keeps them; restated so this file says the whole
-- of what is live.
revoke all on function public.create_product(jsonb, jsonb, jsonb, jsonb, uuid, integer, boolean) from public, anon;
grant execute on function public.create_product(jsonb, jsonb, jsonb, jsonb, uuid, integer, boolean) to authenticated, service_role;
"}', 'add_categories', 'ag.gamboa94@gmail.com', NULL, NULL);
INSERT INTO "supabase_migrations"."schema_migrations" ("version", "statements", "name", "created_by", "idempotency_key", "rollback") VALUES ('20261005033214', '{"-- sight_values_in_words.sql
-- NOT YET APPLIED. Dry-run 2026-10-05 against Gunforma-v2 inside one
-- rolled-back transaction; the A/B comparison of create_product() before and
-- after is in the PR.
--
-- One change to create_product(): a sight''s position, height or type outside
-- its list is refused in words that name the allowed values, before the
-- insert. It used to reach the admin as the raw CHECK violation
-- (\"new row for relation \"sight_specs\" violates check constraint
-- \"sight_specs_sight_position\"\"). The CHECKs stay; this only says the same
-- thing first, in a sentence.
--
-- Restated from add_categories.sql (applied 2026-10-05, 20261005024538);
-- nothing else in it changes.

create or replace function public.create_product(
  p_product jsonb, p_variants jsonb, p_specs jsonb default null, p_fits jsonb default null,
  p_build_id uuid default null, p_part_index integer default null, p_dry_run boolean default false)
returns jsonb
language plpgsql security definer set search_path = ''''
as $fn$
declare
  c_awin_affid   constant text   := ''2959345'';   -- Gunforma''s Awin publisher id; public, it is in every live link
  c_product_keys constant text[] := array[''brand'',''name'',''category'',''platforms'',''slug'',''url'',''description'',''family'',''material'',''material_family'',''fitment_notes'',''build_warning'',''build_notes'',''weight_oz'',''fitment_confidence'',''internal_notes'',''part_type''];
  c_variant_keys constant text[] := array[''color'',''finish'',''sku'',''upc'',''msrp'',''image_url'',''gallery'',''variant_label'',''optic_cut'',''handedness'',''notes'',''is_default'',''manual_safety_variant'',''reticle'',''reticle_color'',''battery_type'',''mount_system'',''bundle'',''clamp_style'',''clamp_rail_type'',''clamp'',''partner_slug'',''url'',''affiliate_url'',''links'',''use_in_build''];
  c_link_keys    constant text[] := array[''partner_slug'',''url'',''affiliate_url'',''op_mpn'',''op_gtin'',''op_merchant_product_id'',''notes''];
  p jsonb; s jsonb; f jsonb; v jsonb; l jsonb; r jsonb; v_result jsonb; v_status jsonb;
  v_category public.product_category; v_want public.product_category; v_platforms text[];
  v_platform_id uuid; v_platform_name text; v_kind text; v_len numeric; v_lengths text;
  v_brand_id uuid; v_brand_name text; v_brand_created boolean := false;
  v_product_id uuid; v_slug text; v_name text; v_confidence public.fitment_confidence;
  v_i int := 0; v_bad text; v_n int; v_key text;
  v_variant_id uuid; v_build_variant uuid; v_links jsonb; v_partner_id uuid; v_other_id uuid;
  v_mid text; v_aff text; v_aff_mid text;
  v_axes text; v_vslug text; v_vbase text; v_part jsonb;
  v_tbl regclass; v_rule_fields text[]; v_collist text; v_has_specs boolean := false;
  v_warn text[] := ''{}'';
  v_vr jsonb;
  v_allowed text;
begin
  if not (public.is_admin() or public.is_trusted_backend()) then
    raise exception ''create_product: admin or service_role only'' using errcode = ''42501'';
  end if;
  if p_product is null or jsonb_typeof(p_product) <> ''object'' then
    raise exception ''create_product: p_product must be an object'';
  end if;
  p := public.jsonb_strip_blank(p_product);
  if p ? ''installation_difficulty'' or p ? ''best_for'' then
    raise exception ''create_product: installation_difficulty and best_for are no longer entered. Existing values stay where they are; leave these out.'';
  end if;
  select string_agg(k, '', '') into v_bad from jsonb_object_keys(p) k where k <> all (c_product_keys);
  if v_bad is not null then raise exception ''create_product: unknown product field(s): %'', v_bad; end if;
  v_name := btrim(coalesce(p->>''name'', ''''));
  if btrim(coalesce(p->>''brand'', '''')) = '''' or v_name = '''' then
    raise exception ''create_product: brand and name are required'';
  end if;
  if p->>''category'' is null then raise exception ''create_product: category is required''; end if;
  v_category := (p->>''category'')::public.product_category;
  v_confidence := coalesce((p->>''fitment_confidence'')::public.fitment_confidence, ''unverified'');

  -- Other Parts: what the part is, in two or three words, is its one extra
  -- fact (products.part_type). Only that category carries one; the table
  -- rule products_part_type_other says the same, and this says it in words.
  if v_category::text = ''other'' and coalesce(btrim(p->>''part_type''), '''') = '''' then
    raise exception ''create_product: an Other Part needs a part type: two or three words saying what it is (e.g. \"thumb ledge\")'';
  elsif v_category::text <> ''other'' and p ? ''part_type'' then
    raise exception ''create_product: a part type is only for Other Parts; a % is its own category'', v_category;
  end if;

  -- ── platform: explicit, never defaulted ───────────────────────────────────
  if jsonb_typeof(p->''platforms'') is distinct from ''array'' or jsonb_array_length(p->''platforms'') = 0 then
    raise exception ''create_product: send at least one platform (e.g. \"platforms\": [\"p365\"]). Nothing defaults: without one the part never appears in the builder.'';
  end if;
  v_platforms := array(select distinct x from jsonb_array_elements_text(p->''platforms'') x order by x);
  select string_agg(x, '', '') into v_bad from unnest(v_platforms) x where not exists (select 1 from public.platforms pl where pl.slug = x);
  if v_bad is not null then
    raise exception ''create_product: unknown platform(s): %. Known: %'', v_bad,
      (select string_agg(slug, '', '' order by slug) from public.platforms) using errcode = ''foreign_key_violation'';
  end if;
  if v_category in (''slide'', ''barrel'') and cardinality(v_platforms) <> 1 then
    raise exception ''create_product: a % belongs to exactly one platform; this one names %: %. Send one.'',
      v_category, cardinality(v_platforms), array_to_string(v_platforms, '', '');
  end if;
  select string_agg(pl.name, '', '' order by pl.name) into v_bad from public.platforms pl
   where pl.slug = any (v_platforms) and not pl.is_live;
  if v_bad is not null then
    v_warn := v_warn || (''Not live yet: '' || v_bad || ''. The part is saved and appears when the platform launches.'');
  end if;

  if p->>''url'' is null then
    raise exception ''create_product: the source URL (the product page the data came from) is required'';
  end if;
  if p_variants is null or jsonb_typeof(p_variants) <> ''array'' or jsonb_array_length(p_variants) = 0 then
    raise exception ''create_product: at least one variant is required'';
  end if;
  if (p_build_id is null) <> (p_part_index is null) or p_part_index < 0 then
    raise exception ''create_product: p_build_id and p_part_index must be supplied together'';
  end if;

  select m.id, m.name into v_brand_id, v_brand_name from public.manufacturers m
   where lower(m.name) = lower(btrim(p->>''brand'')) or m.slug = public.slugify(p->>''brand'')
   order by m.created_at limit 1;
  if v_brand_id is null then
    insert into public.manufacturers (slug, name) values (public.slugify(p->>''brand''), btrim(p->>''brand''))
    returning id, name into v_brand_id, v_brand_name;
    v_brand_created := true;
  end if;

  -- The slug is the product''s URL for good. Brand is prefixed unless the name
  -- already starts with it. Pass \"slug\" to choose it by hand.
  v_slug := coalesce(nullif(btrim(p->>''slug''), ''''),
    public.slugify(case when left(lower(v_name), length(v_brand_name)) = lower(v_brand_name)
                        then v_name else v_brand_name || '' '' || v_name end));
  if exists (select 1 from public.products where slug = v_slug) then
    raise exception ''create_product: a product with slug \"%\" already exists. To add a colour or option to it, use create_variant.'', v_slug using errcode = ''unique_violation'';
  end if;
  if exists (select 1 from public.products where brand_id = v_brand_id and lower(name) = lower(v_name)) then
    raise exception ''create_product: % already has a product named \"%\". To add a colour or option to it, use create_variant.'', v_brand_name, v_name using errcode = ''unique_violation'';
  end if;

  insert into public.products (slug, category, brand_id, name, family, url, description, material, material_family,
                               fitment_notes, build_warning, build_notes, weight_oz, fitment_confidence, part_type)
  values (v_slug, v_category, v_brand_id, v_name, p->>''family'', p->>''url'', p->>''description'', p->>''material'', p->>''material_family'',
          p->>''fitment_notes'', p->>''build_warning'', p->>''build_notes'', (p->>''weight_oz'')::numeric, ''unverified'', btrim(p->>''part_type''))
  returning id into v_product_id;
  -- fitment_confidence is set at the end, once the part is known to be approved

  if p ? ''internal_notes'' then
    insert into public.product_internal (product_id, internal_notes) values (v_product_id, p->>''internal_notes'');
  end if;

  insert into public.product_platforms (product_id, platform_id)
  select v_product_id, pl.id from public.platforms pl where pl.slug = any (v_platforms);

  -- ── spec sheet ────────────────────────────────────────────────────────────
  -- Accepted keys are the category''s spec_field_rules fields and nothing else.
  -- Only supplied keys are named in the INSERT, so column defaults survive.
  s := public.jsonb_strip_blank(p_specs);
  v_tbl := to_regclass(''public.'' || quote_ident(v_category::text || ''_specs''));
  v_rule_fields := array(select fr.field from public.spec_field_rules fr where fr.category = v_category order by fr.sort_order);
  if s <> ''{}''::jsonb then
    if v_tbl is null then raise exception ''create_product: a % has no spec sheet; leave p_specs out'', v_category; end if;
    select string_agg(k, '', '') into v_bad from jsonb_object_keys(s) k where k <> all (v_rule_fields);
    if v_bad is not null then
      raise exception ''create_product: spec sheet: no rule for field(s): %. Fields for a %: %'', v_bad, v_category, array_to_string(v_rule_fields, '', '');
    end if;

    -- a sight''s three fixed lists. Checked here so an admin reads the
    -- allowed values, not the name of a sight_specs CHECK constraint. The
    -- same lists are those CHECKs (supabase/add_categories.sql) and
    -- SIGHT_CHOICES in gunforma-admin-part.html; change all three together.
    if v_category::text = ''sight'' then
      foreach v_key in array array[''sight_position'', ''height'', ''sight_type''] loop
        v_allowed := case v_key when ''sight_position'' then ''front, rear, set''
                                when ''height''         then ''standard, suppressor''
                                else                       ''night, fiber, night-fiber, plain'' end;
        if s ? v_key and not (s->>v_key = any (string_to_array(v_allowed, '', ''))) then
          raise exception ''create_product: a sight''''s % must be one of: %. \"%\" is not one of them.'',
            case v_key when ''sight_position'' then ''position'' when ''height'' then ''height'' else ''type'' end,
            v_allowed, s->>v_key;
        end if;
      end loop;
    end if;

    -- platform: the product''s one platform. A disagreeing key is refused.
    if ''platform'' = any (v_rule_fields) then
      if s ? ''platform'' and s->>''platform'' <> v_platforms[1] then
        raise exception ''create_product: spec sheet platform \"%\" disagrees with the product''''s platform \"%\"'', s->>''platform'', v_platforms[1];
      end if;
      select pl.id, pl.name into v_platform_id, v_platform_name from public.platforms pl where pl.slug = v_platforms[1];
      s := (s - ''platform'') || jsonb_build_object(''platform_id'', v_platform_id);
    end if;
    if s ? ''footprint'' then
      select fp.id into v_other_id from public.footprints fp where fp.slug = s->>''footprint'';
      if v_other_id is null then
        raise exception ''create_product: spec sheet: no footprint \"%\". Known: %'', s->>''footprint'',
          (select string_agg(slug, '', '' order by slug) from public.footprints);
      end if;
      s := (s - ''footprint'') || jsonb_build_object(''footprint_id'', v_other_id);
    end if;

    -- material is one fact held in two places
    foreach v_key in array array[''housing_material'', ''material'', ''guide_rod_material''] loop
      if v_key = any (v_rule_fields) then
        if s ? v_key and p ? ''material'' and lower(btrim(s->>v_key)) <> lower(btrim(p->>''material'')) then
          raise exception ''create_product: material is one fact: the product says \"%\" but the spec sheet''''s % says \"%\"'', p->>''material'', v_key, s->>v_key;
        elsif not s ? v_key and p ? ''material'' then
          s := s || jsonb_build_object(v_key, p->>''material'');
        elsif s ? v_key and not p ? ''material'' then
          update public.products set material = s->>v_key where id = v_product_id;
        end if;
      end if;
    end loop;

    -- only-when fields whose condition holds must come with the sheet
    select string_agg(fr.field, '', '' order by fr.sort_order) into v_bad from public.spec_field_rules fr
     where fr.category = v_category and fr.requirement = ''required'' and fr.only_when_field is not null
       and (s ->> fr.only_when_field) = any (fr.only_when_values)
       and coalesce(btrim(s ->> fr.field), '''') = '''';
    if v_bad is not null then
      raise exception ''create_product: the % spec sheet needs % (it applies here because of %)'', v_category, v_bad,
        (select string_agg(distinct fr.only_when_field || '' = '' || (s ->> fr.only_when_field), '', '') from public.spec_field_rules fr
          where fr.category = v_category and fr.only_when_field is not null and fr.field = any (string_to_array(v_bad, '', '')));
    end if;

    -- slide / barrel length must be registered for that platform. Checked
    -- here so an admin reads a sentence, not the class trigger''s raw text.
    if v_category in (''slide'', ''barrel'') then
      v_kind := v_category::text;
      v_len  := (s ->> (v_kind || ''_length_in''))::numeric;
      if v_len is not null then
        if not exists (select 1 from public.platform_part_lengths ppl where ppl.platform_id = v_platform_id and ppl.part_kind = v_kind) then
          raise exception ''create_product: % % lengths are not registered yet. Add them to platform_part_lengths before adding a % for it.'',
            v_platform_name, v_kind, v_kind;
        end if;
        if not exists (select 1 from public.platform_part_lengths ppl
                        where ppl.platform_id = v_platform_id and ppl.part_kind = v_kind and ppl.length_in = v_len) then
          select string_agg(ppl.length_in::text, '', '' order by ppl.length_in) into v_lengths from public.platform_part_lengths ppl
           where ppl.platform_id = v_platform_id and ppl.part_kind = v_kind;
          raise exception ''create_product: no % % is registered at % in. Registered % lengths: %.'', v_platform_name, v_kind, v_len, v_kind, v_lengths;
        end if;
      end if;
    end if;

    -- a recoil spring fits one slide length. It has no platform rule of its
    -- own, so the length must be registered for one of the part''s platforms.
    if v_category::text = ''recoil_spring'' and s ? ''slide_length_in'' then
      v_len := (s ->> ''slide_length_in'')::numeric;
      if not exists (select 1 from public.platform_part_lengths ppl join public.platforms pl on pl.id = ppl.platform_id
                      where pl.slug = any (v_platforms) and ppl.part_kind = ''slide'' and ppl.length_in = v_len) then
        select string_agg(distinct ppl.length_in::text, '', '' order by ppl.length_in::text) into v_lengths
          from public.platform_part_lengths ppl join public.platforms pl on pl.id = ppl.platform_id
         where pl.slug = any (v_platforms) and ppl.part_kind = ''slide'';
        raise exception ''create_product: no slide length of % in is registered for %. Registered slide lengths: %.'',
          v_len, array_to_string(v_platforms, '', ''), coalesce(v_lengths, ''none'');
      end if;
    end if;

    -- columns the table itself declares NOT NULL without a default
    select string_agg(a.attname::text, '', '') into v_bad from pg_catalog.pg_attribute a
     where a.attrelid = v_tbl and a.attnum > 0 and not a.attisdropped and a.attnotnull and not a.atthasdef
       and a.attname::text not in (''product_id'', ''category'') and not s ? (a.attname::text);
    if v_bad is not null then
      raise exception ''create_product: the % spec sheet needs: %'', v_category, replace(replace(v_bad, ''footprint_id'', ''footprint''), ''platform_id'', ''platform'');
    end if;

    s := s || jsonb_build_object(''product_id'', v_product_id, ''category'', v_category);
    select string_agg(quote_ident(k), '', '') into v_collist from jsonb_object_keys(s) k;
    execute format(''insert into %s (%s) select %s from jsonb_populate_record(null::%s, $1)'', v_tbl, v_collist, v_collist, v_tbl) using s;
    v_has_specs := true;
  end if;

  -- ── variants ──────────────────────────────────────────────────────────────
  -- The loop lives in create_variants_for_product(), shared with
  -- add_variants(): one copy of how a variant object becomes a variant.
  v_vr := public.create_variants_for_product(v_product_id, v_slug, p_variants, ''create_product'');
  v_build_variant := (v_vr->>''build_variant'')::uuid;

  if exists (select 1 from public.product_variants pv where pv.product_id = v_product_id and pv.is_default
               and (pv.primary_image_url is null or pv.msrp is null)) then
    raise exception ''create_product: the default variant needs a photo and an MSRP'';
  end if;

  -- ── fits-with rules ───────────────────────────────────────────────────────
  f := public.jsonb_strip_blank(p_fits);
  for v_key, r in select e.key, e.value from jsonb_each(f) e loop
    if not ((v_category = ''light''   and v_key = ''light_compatibility'')
         or (v_category = ''optic''   and v_key = ''adapter_footprints'')
         or (v_category = ''barrel''  and v_key = ''slides'')
         or (v_category = ''slide''   and v_key = ''barrels'')
         or (v_category = ''magwell'' and v_key = ''frames'')
         or (v_category = ''frame''   and v_key = ''magwells'')) then
      raise exception ''create_product: fits-with rule \"%\" does not apply to a %. (light: light_compatibility; optic: adapter_footprints; barrel: slides; slide: barrels; magwell: frames; frame: magwells)'', v_key, v_category;
    end if;
    if jsonb_typeof(r) <> ''array'' then raise exception ''create_product: fits-with rule \"%\" must be a list'', v_key; end if;
    -- these four reference the <category>_specs row, not products
    if v_key in (''light_compatibility'',''adapter_footprints'',''slides'',''barrels'') and not v_has_specs then
      raise exception ''create_product: fits-with rules for a % need its spec sheet filled in first'', v_category;
    end if;
    for l in select value from jsonb_array_elements(r) loop
      if jsonb_typeof(l) = ''string'' then l := jsonb_build_object(''product'', l #>> ''{}''); end if;
      l := public.jsonb_strip_blank(l);
      if v_key = ''light_compatibility'' then
        select string_agg(k, '', '') into v_bad from jsonb_object_keys(l) k
         where k <> all (array[''rail_type'',''fitment_type'',''key_or_adapter'',''gun_make'',''gun'',''gun_model_text'',''confirmed'',''notes'']);
        if v_bad is not null then raise exception ''create_product: light_compatibility: unknown field(s): %'', v_bad; end if;
        v_other_id := null;
        if l ? ''gun'' then
          select g.id into v_other_id from public.guns g where g.slug = l->>''gun'';
          if v_other_id is null then raise exception ''create_product: light_compatibility: no gun \"%\"'', l->>''gun''; end if;
        end if;
        insert into public.light_compatibility (light_product_id, rail_type, fitment_type, key_or_adapter, gun_make, gun_id, gun_model_text, confirmed, notes)
        values (v_product_id, l->>''rail_type'', (l->>''fitment_type'')::public.light_fitment_type, l->>''key_or_adapter'', l->>''gun_make'',
                v_other_id, l->>''gun_model_text'', coalesce((l->>''confirmed'')::boolean, false), l->>''notes'');
      elsif v_key = ''adapter_footprints'' then
        select string_agg(k, '', '') into v_bad from jsonb_object_keys(l) k where k <> all (array[''footprint'',''plate_included'',''notes'']);
        if v_bad is not null then raise exception ''create_product: adapter_footprints: unknown field(s): %'', v_bad; end if;
        if not l ? ''plate_included'' then raise exception ''create_product: adapter_footprints: say whether the plate is included''; end if;
        select fp.id into v_other_id from public.footprints fp where fp.slug = l->>''footprint'';
        if v_other_id is null then raise exception ''create_product: adapter_footprints: no footprint \"%\"'', l->>''footprint''; end if;
        insert into public.optic_adapter_footprints (optic_product_id, footprint_id, plate_included, notes)
        values (v_product_id, v_other_id, (l->>''plate_included'')::boolean, l->>''notes'');
      else
        select string_agg(k, '', '') into v_bad from jsonb_object_keys(l) k where k <> all (array[''product'',''source'',''compatibility_note'']);
        if v_bad is not null then raise exception ''create_product: %: unknown field(s): %'', v_key, v_bad; end if;
        v_want := case v_key when ''slides'' then ''slide'' when ''barrels'' then ''barrel'' when ''frames'' then ''frame'' else ''magwell'' end;
        select pr.id into v_other_id from public.products pr where pr.slug = l->>''product'' and pr.category = v_want;
        if v_other_id is null then
          raise exception ''create_product: %: there is no % with slug \"%\"'', v_key, v_want, l->>''product'';
        end if;
        if v_key in (''slides'',''barrels'') then
          insert into public.barrel_slide_requirements (barrel_product_id, slide_product_id, source, compatibility_note)
          values (case when v_key = ''slides'' then v_product_id else v_other_id end,
                  case when v_key = ''slides'' then v_other_id else v_product_id end,
                  l->>''source'', l->>''compatibility_note'');
        elsif l ? ''source'' then
          insert into public.magwell_frame_requirements (magwell_product_id, frame_product_id, source, compatibility_note)
          values (case when v_key = ''frames'' then v_product_id else v_other_id end,
                  case when v_key = ''frames'' then v_other_id else v_product_id end,
                  l->>''source'', l->>''compatibility_note'');
        else
          insert into public.magwell_frame_requirements (magwell_product_id, frame_product_id, compatibility_note)
          values (case when v_key = ''frames'' then v_product_id else v_other_id end,
                  case when v_key = ''frames'' then v_other_id else v_product_id end,
                  l->>''compatibility_note'');
        end if;
      end if;
    end loop;
  end loop;

  -- ── things the admin should know, but that do not block ───────────────────
  if v_category = ''slide'' and not f ? ''barrels'' then
    select string_agg(distinct pr.slug, '', '') into v_bad
      from public.barrel_slide_requirements b join public.products pr on pr.id = b.barrel_product_id;
    if v_bad is not null then
      v_warn := v_warn || (''These barrels only fit the slides listed for them, so they will show as NOT fitting this slide: '' || v_bad);
    end if;
  end if;
  if v_category = ''frame'' and not f ? ''magwells'' then
    select string_agg(distinct pr.slug, '', '') into v_bad
      from public.magwell_frame_requirements b join public.products pr on pr.id = b.magwell_product_id;
    if v_bad is not null then
      v_warn := v_warn || (''These magwells only fit the frames listed for them, so they will show as NOT fitting this frame: '' || v_bad);
    end if;
  end if;

  -- ── swap the build''s pending custom part for this product ─────────────────
  -- variantSpecs is not written into the snapshot here: its formula lives in
  -- js/variant-label.js and _variant-label.mjs, and a third copy in SQL would
  -- drift. The build page reads the spec line from the live variant.
  if p_build_id is not null then
    select b.parts_snapshot -> p_part_index into v_part from public.builds b where b.id = p_build_id for update;
    if not found then raise exception ''create_product: no build %'', p_build_id; end if;
    if v_part is null then raise exception ''create_product: build has no part at index %'', p_part_index; end if;
    if (v_part->>''pending'')::boolean is not true or v_part->>''refId'' is not null then
      raise exception ''create_product: part % (\"%\") on that build is not a pending custom part'', p_part_index, v_part->>''name'';
    end if;
    if v_build_variant is null then
      select pv.id into v_build_variant from public.product_variants pv where pv.product_id = v_product_id and pv.is_default;
    end if;
    update public.builds b set parts_snapshot = jsonb_set(b.parts_snapshot, array[p_part_index::text],
        v_part
        || jsonb_strip_nulls(jsonb_build_object(''name'', v_name, ''brand'', v_brand_name, ''refId'', v_product_id,
             ''imageUrl'', pv.primary_image_url, ''variantId'', pv.id, ''variantColor'', pv.color,
             ''variantLabel'', pv.variant_label, ''variantFinish'', pv.finish))
        || jsonb_build_object(''pending'', false)
        -- Other Parts (stored as `misc`) is the catch-all: a part typed there
        -- takes the product''s own category, so it renders in its real section
        -- (the DMP recoil spring under Recoil Springs). Every other section
        -- keeps the category it was saved under.
        || case when v_part->>''category'' = ''misc'' then jsonb_build_object(''category'', v_category::text) else ''{}''::jsonb end)
    from public.product_variants pv
    where b.id = p_build_id and pv.id = v_build_variant;
  end if;

  -- ── completeness, and the confidence it allows ────────────────────────────
  v_status := public.product_data_status(v_product_id);
  if v_confidence <> ''unverified'' then
    if not (v_status->>''approved'')::boolean then
      raise exception ''create_product: fitment confidence \"%\" needs an approved part. Still missing: %'',
        v_confidence, (select string_agg(x, '', '') from jsonb_array_elements_text(v_status->''missing'') x);
    end if;
    update public.products set fitment_confidence = v_confidence where id = v_product_id;
  end if;

  v_result := jsonb_build_object(
    ''product_id'', v_product_id, ''slug'', v_slug, ''category'', v_category,
    ''brand'', v_brand_name, ''brand_created'', v_brand_created, ''build_relinked'', p_build_id is not null,
    ''has_spec_sheet'', v_has_specs, ''fitment_confidence'', v_confidence, ''warnings'', to_jsonb(v_warn),
    ''variants'', (select jsonb_agg(jsonb_build_object(''id'', pv.id, ''slug'', pv.slug, ''label'', pv.variant_label, ''default'', pv.is_default,
                    ''photos'', (select count(*) from public.variant_images vi where vi.variant_id = pv.id),
                    ''links'', (select count(*) from public.affiliate_links al where al.variant_id = pv.id),
                    -- one entry per retailer link: tracked_url is the link the buy
                    -- button will use, null when none was built (no commission)
                    ''retailers'', coalesce((select jsonb_agg(jsonb_build_object(''partner'', pa.slug, ''partner_name'', pa.name,
                                     ''url'', al.url, ''tracked_url'', al.affiliate_url) order by pa.slug, al.url)
                                   from public.affiliate_links al join public.partners pa on pa.id = al.partner_id
                                  where al.variant_id = pv.id), ''[]''::jsonb))
                  order by pv.is_default desc, pv.slug)
                 from public.product_variants pv where pv.product_id = v_product_id))
    || v_status;

  if p_dry_run then
    raise exception ''create_product: dry run, nothing was written'' using errcode = ''P0DRY'', detail = v_result::text;
  end if;
  return v_result;
end;
$fn$;

comment on function public.create_product(jsonb, jsonb, jsonb, jsonb, uuid, integer, boolean) is
  ''Admin / service_role only. Creates a product with its brand, platforms, spec sheet, every variant (photos + retailer links) and fits-with rules in one transaction, optionally re-links a build''''s pending custom part, and returns product_data_status. p_dry_run raises P0DRY with the result instead of writing.'';

revoke all on function public.create_product(jsonb, jsonb, jsonb, jsonb, uuid, integer, boolean) from public, anon;
grant execute on function public.create_product(jsonb, jsonb, jsonb, jsonb, uuid, integer, boolean) to authenticated, service_role;
"}', 'sight_values_in_words', 'ag.gamboa94@gmail.com', NULL, NULL);
INSERT INTO "supabase_migrations"."schema_migrations" ("version", "statements", "name", "created_by", "idempotency_key", "rollback") VALUES ('20261006160738', '{"revoke truncate on all tables in schema public from anon, authenticated;
alter default privileges for role postgres in schema public
  revoke truncate on tables from anon, authenticated;"}', 'revoke_truncate_grants', 'ag.gamboa94@gmail.com', NULL, NULL);
INSERT INTO "supabase_migrations"."schema_migrations" ("version", "statements", "name", "created_by", "idempotency_key", "rollback") VALUES ('20261006235015', '{"create or replace function public.restrict_build_status_to_reviewers()
returns trigger
language plpgsql
security definer
set search_path to ''public''
as $function$
begin
  if public.is_trusted_backend() or public.is_admin() then
    return new;
  end if;

  -- IS DISTINCT FROM, not NOT IN: status is NOT NULL today, but `x not in
  -- (...)` is NULL for a NULL x and an IF treats NULL as false, which would
  -- make a guard that passes exactly the value nobody thought about.
  if tg_op = ''INSERT'' then
    if new.status is distinct from ''draft'' and new.status is distinct from ''pending'' then
      raise exception ''A new build starts as a draft or goes into review. Only a reviewer can approve or reject it.''
        using errcode = ''42501'';   -- insufficient_privilege -> HTTP 403
    end if;
  elsif new.status is distinct from old.status
        and new.status is distinct from ''draft''
        and new.status is distinct from ''pending'' then
    raise exception ''Only a reviewer can approve or reject a build.''
      using errcode = ''42501'';
  end if;

  return new;
end;
$function$;

-- A trigger function is never called directly, and firing a trigger does
-- not check EXECUTE on it. Same ACL as the other build guards
-- (postgres, service_role).
revoke execute on function public.restrict_build_status_to_reviewers() from public, anon, authenticated;

drop trigger if exists trg_restrict_build_status on public.builds;
create trigger trg_restrict_build_status
  before insert or update on public.builds
  for each row execute function public.restrict_build_status_to_reviewers();"}', 'restrict_build_status_to_reviewers', 'ag.gamboa94@gmail.com', NULL, NULL);
INSERT INTO "supabase_migrations"."schema_migrations" ("version", "statements", "name", "created_by", "idempotency_key", "rollback") VALUES ('20261009053247', '{"-- ============================================================
-- Gunforma-v2 — every build part has its own id, and corrections use it
-- Applied from supabase/part_ids.sql as merged in #152 (origin/main 7c599ec).
-- Rollback: part_ids_rollback.sql
-- ============================================================

begin;

-- ── the rule, as a function: assign ids, keep every valid one ──────────────
create or replace function public.with_part_ids(p_new jsonb, p_old jsonb)
returns jsonb
language plpgsql
volatile
set search_path to ''''
as $function$
declare
  v_out      jsonb  := ''[]''::jsonb;
  v_reserved text[] := ''{}'';   -- valid ids NEW already carries (first use of each)
  v_used     text[] := ''{}'';   -- ids handed out so far, in this call
  v_el jsonb; v_old jsonb; v_id text; i int; j int;
begin
  if p_new is null or jsonb_typeof(p_new) <> ''array'' then
    return p_new;
  end if;

  -- First pass: the ids NEW already has. A part that brought its own id must
  -- keep it, so no other part may be given it in the second pass.
  for i in 0 .. jsonb_array_length(p_new) - 1 loop
    v_id := p_new -> i ->> ''partId'';
    if jsonb_typeof(p_new -> i) = ''object'' and v_id ~ ''^[0-9a-f]{12}$'' and not v_id = any (v_reserved) then
      v_reserved := v_reserved || v_id;
    end if;
  end loop;

  for i in 0 .. jsonb_array_length(p_new) - 1 loop
    v_el := p_new -> i;
    if jsonb_typeof(v_el) <> ''object'' then
      v_out := v_out || jsonb_build_array(v_el);
      continue;
    end if;

    v_id := v_el ->> ''partId'';
    -- Its own valid id, first time it is seen: kept.
    if v_id ~ ''^[0-9a-f]{12}$'' and not v_id = any (v_used) then
      v_used := v_used || v_id;
      v_out  := v_out || jsonb_build_array(v_el);
      continue;
    end if;

    -- No id (or an invalid or duplicate one). An identical part on OLD gives
    -- it that part''s id, if nothing else here has it.
    v_id := null;
    if jsonb_typeof(p_old) = ''array'' then
      for j in 0 .. jsonb_array_length(p_old) - 1 loop
        v_old := p_old -> j;
        if jsonb_typeof(v_old) = ''object''
           and (v_old ->> ''partId'') ~ ''^[0-9a-f]{12}$''
           and not (v_old ->> ''partId'') = any (v_reserved)
           and not (v_old ->> ''partId'') = any (v_used)
           and (v_old - ''partId'') = (v_el - ''partId'') then
          v_id := v_old ->> ''partId'';
          exit;
        end if;
      end loop;
    end if;

    -- Otherwise a new one.
    while v_id is null or v_id = any (v_reserved) or v_id = any (v_used) loop
      v_id := substr(replace(gen_random_uuid()::text, ''-'', ''''), 1, 12);
    end loop;

    v_used := v_used || v_id;
    v_out  := v_out || jsonb_build_array(v_el || jsonb_build_object(''partId'', v_id));
  end loop;

  return v_out;
end;
$function$;

-- Called by the trigger as whoever is writing the row, so authenticated
-- needs it. It reads nothing and writes nothing; anon cannot write builds.
revoke execute on function public.with_part_ids(jsonb, jsonb) from public, anon;
grant  execute on function public.with_part_ids(jsonb, jsonb) to authenticated, service_role;

create or replace function public.assign_part_ids()
returns trigger
language plpgsql
set search_path to ''''
as $function$
begin
  if tg_op = ''UPDATE'' and new.parts_snapshot is not distinct from old.parts_snapshot then
    return new;
  end if;
  new.parts_snapshot := public.with_part_ids(
    new.parts_snapshot,
    case when tg_op = ''UPDATE'' then old.parts_snapshot end);
  return new;
end;
$function$;

revoke execute on function public.assign_part_ids() from public, anon, authenticated;

drop trigger if exists trg_assign_part_ids on public.builds;
create trigger trg_assign_part_ids
  before insert or update of parts_snapshot on public.builds
  for each row execute function public.assign_part_ids();

-- ── the builds that exist today ────────────────────────────────────────────
-- Five on 2026-10-08, all approved, none with a correction. This bumps their
-- updated_at (builds_updated_at), so an editor tab left open on one will be
-- told the build changed on its next save — which is true.
update public.builds
   set parts_snapshot = public.with_part_ids(parts_snapshot, null)
 where exists (select 1 from jsonb_array_elements(parts_snapshot) p
                where jsonb_typeof(p) = ''object''
                  and not coalesce(p ->> ''partId'', '''') ~ ''^[0-9a-f]{12}$'');

-- ── flags remember which part, not just where it was ───────────────────────
alter table public.build_part_flags add column if not exists part_id text;

-- ── the edit_history guard: let a flag through, and the service role ──────
-- Found by the dry run of this file (Claude Code, #152): the visitor''s flag
-- has NEVER worked. contest_build_part() is SECURITY DEFINER, but this
-- trigger identifies the caller with is_admin() (auth.uid()), and the caller
-- is still the visitor — so its final UPDATE was refused with \"Only admins
-- can modify edit_history\", the page said \"Something went wrong\", and the
-- database holds zero contested entries and zero flag rows. Same shape as
-- CLAUDE.md''s \"service_role bypasses RLS. It does not bypass triggers\", and
-- that half was logged too: the service role and a direct session were
-- refused here as well.
--
-- The rule now, for anyone who is not an admin or a trusted backend: the ONE
-- change allowed to edit_history is marking existing corrections
-- ''contested'' on a build that is live and stays live — same entries, same
-- order, every key equal except `status`, which may only become
-- ''contested''. That is exactly what contest_build_part() writes, and all it
-- can write. Adding, removing, rewriting or un-contesting an entry is still
-- refused, as before. An owner can do the same thing by a direct UPDATE of
-- their own live build; that is the same act any signed-in visitor can do
-- through the function, so it opens nothing.
create or replace function public.prevent_owner_edit_history_change()
 returns trigger
 language plpgsql
 security definer
 set search_path to ''public''
as $function$
begin
  -- Admins log corrections; the service role and a direct session (the SQL
  -- editor, a migration) are trusted. See is_trusted_backend().
  if public.is_admin() or public.is_trusted_backend() then
    return new;
  end if;
  if new.edit_history is not distinct from old.edit_history then
    return new;
  end if;
  -- A flag: only statuses changed, only to ''contested'', on a live build.
  if old.status = ''approved'' and new.status = ''approved''
     and jsonb_typeof(old.edit_history) = ''array'' and jsonb_typeof(new.edit_history) = ''array''
     and jsonb_array_length(old.edit_history) = jsonb_array_length(new.edit_history)
     and not exists (
       select 1
         from jsonb_array_elements(old.edit_history) with ordinality as o(oe, oi)
         join jsonb_array_elements(new.edit_history) with ordinality as n(ne, ni) on ni = oi
        where not (
          ne = oe
          or (jsonb_typeof(ne) = ''object'' and jsonb_typeof(oe) = ''object''
              and (ne - ''status'') = (oe - ''status'')
              and ne ->> ''status'' = ''contested'')
        ))
  then
    return new;
  end if;
  raise exception ''Only admins can modify edit_history''
    using errcode = ''42501'';   -- insufficient_privilege
end;
$function$;

-- ── contest_build_part: the flagged correction is the PART''s ───────────────
-- Same signature, so the page''s call and the grants are unchanged. The page
-- still sends the position it rendered; the function reads the id of the
-- part at that position and finds the correction by it. An entry written
-- before ids (part_index only) is still found by position.
create or replace function public.contest_build_part(p_build_id uuid, p_part_index integer)
 returns void
 language plpgsql
 security definer
 set search_path to ''public''
as $function$
declare
  target_idx int;
  uid uuid := auth.uid();
  v_pid text;
begin
  if uid is null then
    raise exception ''must be signed in to flag'';
  end if;
  if p_part_index is null or p_part_index < 0 then
    raise exception ''contest_build_part: part index must be 0 or more'';   -- jsonb -> -1 reads from the end
  end if;

  select b.parts_snapshot -> p_part_index ->> ''partId'' into v_pid
    from public.builds b where b.id = p_build_id;

  insert into public.build_part_flags (build_id, part_index, part_id, user_id)
  values (p_build_id, p_part_index, v_pid, uid)
  on conflict (build_id, part_index, user_id) do nothing;

  select (ord - 1) into target_idx
  from public.builds b, jsonb_array_elements(b.edit_history) with ordinality as e(elem, ord)
  where b.id = p_build_id
    and b.status = ''approved''
    and case when (e.elem ->> ''part_id'') ~ ''^[0-9a-f]{12}$''
             then (e.elem ->> ''part_id'') = v_pid
             else (e.elem ->> ''part_index'') ~ ''^[0-9]+$'' and (e.elem ->> ''part_index'')::int = p_part_index
        end
  order by ord desc
  limit 1;

  if target_idx is null then
    return;
  end if;

  update public.builds
  set edit_history = jsonb_set(edit_history, array[target_idx::text, ''status''], ''\"contested\"''::jsonb)
  where id = p_build_id and status = ''approved'';
end;
$function$;

-- ── relink_build_part: \"has corrections\" means THIS part''s ─────────────────
-- The live body, unchanged except for the count of corrections (marked).
create or replace function public.relink_build_part(p_build_id uuid, p_part_index integer, p_product_id uuid, p_variant_id uuid, p_variant_specs text default null::text)
 returns jsonb
 language plpgsql
 security definer
 set search_path to ''''
as $function$
declare
  v_part jsonb; v_history jsonb; v_corrections int; v_entry jsonb;
  pr record; pv record;
begin
  if not (public.is_admin() or public.is_trusted_backend()) then
    raise exception ''relink_build_part: admin or service_role only'' using errcode = ''42501'';
  end if;
  if p_build_id is null or p_part_index is null or p_product_id is null or p_variant_id is null then
    raise exception ''relink_build_part: build, part index, product and variant are all required'';
  end if;
  if p_part_index < 0 then
    raise exception ''relink_build_part: part index must be 0 or more'';   -- jsonb -> -1 would read from the end
  end if;

  select b.parts_snapshot -> p_part_index, coalesce(b.edit_history, ''[]''::jsonb)
    into v_part, v_history
    from public.builds b where b.id = p_build_id for update;
  if not found then raise exception ''relink_build_part: no build %'', p_build_id; end if;
  if v_part is null then raise exception ''relink_build_part: that build has no part at index %'', p_part_index; end if;
  if (v_part->>''pending'')::boolean is not true or v_part->>''refId'' is not null then
    raise exception ''relink_build_part: part % (\"%\") on that build is not a pending custom part'', p_part_index, v_part->>''name'';
  end if;

  -- CHANGED (part_ids.sql): by the part''s own id when the entry has one,
  -- else by position, as every entry used to be.
  select count(*) into v_corrections from jsonb_array_elements(v_history) e
   where case when (e->>''part_id'') ~ ''^[0-9a-f]{12}$''
              then (e->>''part_id'') = (v_part->>''partId'')
              else (e->>''part_index'') ~ ''^[0-9]+$'' and (e->>''part_index'')::int = p_part_index
         end;
  if v_corrections > 0 then
    raise exception ''relink_build_part: part % (\"%\") has % correction% in the review queue. The build page shows those over the part, so a linked part would read as the correction. Not linked.'',
      p_part_index, v_part->>''name'', v_corrections, case when v_corrections = 1 then '''' else ''s'' end;
  end if;

  select p.id, p.name, p.category, m.name as brand into pr
    from public.products p join public.manufacturers m on m.id = p.brand_id
   where p.id = p_product_id;
  if not found then raise exception ''relink_build_part: no product %'', p_product_id; end if;

  select v.id, v.product_id, v.retired_at, v.primary_image_url, v.color, v.variant_label, v.finish into pv
    from public.product_variants v where v.id = p_variant_id;
  if not found or pv.product_id is distinct from p_product_id then
    raise exception ''relink_build_part: that variant is not one of \"%\"''''s variants'', pr.name;
  end if;
  if pv.retired_at is not null then
    raise exception ''relink_build_part: that variant of \"%\" is retired. Pick a live one.'', pr.name;
  end if;

  v_entry := v_part
    || jsonb_strip_nulls(jsonb_build_object(''name'', pr.name, ''brand'', pr.brand, ''refId'', pr.id,
         ''imageUrl'', pv.primary_image_url, ''variantId'', pv.id, ''variantColor'', pv.color,
         ''variantLabel'', pv.variant_label, ''variantFinish'', pv.finish,
         ''variantSpecs'', nullif(btrim(coalesce(p_variant_specs, '''')), '''')))
    || jsonb_build_object(''pending'', false)
    -- Other Parts (stored as `misc`) is the catch-all: a linked part takes the
    -- product''s own category and renders in its real section. Every other
    -- section keeps the category it was saved under.
    || case when v_part->>''category'' = ''misc'' then jsonb_build_object(''category'', pr.category::text) else ''{}''::jsonb end;

  update public.builds b set parts_snapshot = jsonb_set(b.parts_snapshot, array[p_part_index::text], v_entry)
   where b.id = p_build_id;

  return jsonb_build_object(''build_id'', p_build_id, ''part_index'', p_part_index, ''entry'', v_entry);
end;
$function$;

commit;"}', 'part_ids', 'ag.gamboa94@gmail.com', NULL, NULL);
INSERT INTO "supabase_migrations"."schema_migrations" ("version", "statements", "name", "created_by", "idempotency_key", "rollback") VALUES ('20261010213545', '{"alter table public.guns
  add constraint guns_id_platform_key unique (id, platform_id);

alter table public.builds
  add column gun_id uuid,
  add column fcu_only boolean not null default false;

alter table public.builds
  add constraint builds_fcu_xor_gun check (not (fcu_only and gun_id is not null));

alter table public.builds
  add constraint builds_gun_fkey
  foreign key (gun_id, platform_id)
  references public.guns (id, platform_id)
  on delete set null (gun_id);

create index builds_gun_id_idx on public.builds (gun_id) where gun_id is not null;

grant insert (gun_id, fcu_only), update (gun_id, fcu_only) on public.builds to authenticated;

comment on column public.builds.gun_id is
  ''Which factory model this build is (guns.id). NULL = not asked, not listed, or an FCU build (see fcu_only). Must belong to platform_id — builds_gun_fkey is composite.'';
comment on column public.builds.fcu_only is
  ''TRUE = built from a bare fire control unit: no factory slide, barrel or grip module to assume. Never true together with a gun_id (builds_fcu_xor_gun).'';

-- The deployed body, read back with pg_get_functiondef on 2026-10-10, plus
-- two lines: gun_id and fcu_only. Nothing else is changed.
create or replace function public.restrict_owner_edits_on_approved_build()
returns trigger
language plpgsql
security definer
set search_path to ''public''
as $function$
declare claims text; jwt_role text;
begin
  claims := current_setting(''request.jwt.claims'', true);
  -- NULL on a direct SQL connection, which already requires credentials
  -- nobody but the owner holds. This guard is for API callers.
  if claims is null then return new; end if;
  begin jwt_role := coalesce(claims::jsonb ->> ''role'',''''); exception when others then jwt_role := ''''; end;

  if old.status = ''approved'' and jwt_role <> ''service_role'' and not public.is_admin() then
    if new.platform_id is distinct from old.platform_id
       or new.gun_id is distinct from old.gun_id
       or new.fcu_only is distinct from old.fcu_only
       or new.parts_snapshot is distinct from old.parts_snapshot
       or new.status is distinct from old.status
       or new.tier is distinct from old.tier
       or new.user_id is distinct from old.user_id
       or new.legal_confirmed is distinct from old.legal_confirmed
       or new.content_license_confirmed is distinct from old.content_license_confirmed
       or new.builder_agreement_version is distinct from old.builder_agreement_version
       or new.confirmed_at is distinct from old.confirmed_at
       or new.reviewed_by is distinct from old.reviewed_by
       or new.reviewed_at is distinct from old.reviewed_at
       or new.rejection_reason is distinct from old.rejection_reason
       or new.created_at is distinct from old.created_at
    then
      raise exception ''On a live build you can change the name, description and activity. To change the gun itself, delete this build and post the new one.'';
    end if;
  end if;
  return new;
end; $function$;"}', 'builds_gun_id', 'ag.gamboa94@gmail.com', NULL, NULL);
INSERT INTO "supabase_migrations"."schema_migrations" ("version", "statements", "name", "created_by", "idempotency_key", "rollback") VALUES ('20261013033628', '{"-- 1. ''changes'' ----------------------------------------------------------
alter table public.notifications drop constraint notifications_kind_check;
alter table public.notifications add constraint notifications_kind_check
  check (kind in (''comment'', ''reply'', ''like'', ''approved'', ''changes''));

alter table public.notifications drop constraint notifications_actor_required;
alter table public.notifications add constraint notifications_actor_required
  check (kind in (''approved'', ''changes'') or actor_id is not null);

-- 2. the counter --------------------------------------------------------
alter table public.builds
  add column if not exists changes_notified_count integer not null default 0;

-- 3. old corrections into parts_snapshot --------------------------------
-- Same matching rule as js/part-ids.js: by part_id when the entry has one
-- (and then only by it), by part_index when it has only that.
do $$
declare
  r record; v_parts jsonb; v_e jsonb; v_i int; v_n int := 0;
begin
  for r in
    select id, parts_snapshot, edit_history from public.builds
     where jsonb_typeof(edit_history) = ''array'' and jsonb_array_length(edit_history) > 0
       and jsonb_typeof(parts_snapshot) = ''array''
  loop
    v_parts := r.parts_snapshot;
    for v_e in select e from jsonb_array_elements(r.edit_history) as t(e) loop
      continue when jsonb_typeof(v_e) <> ''object''
                 or coalesce(v_e ->> ''field'', '''') not in (''category'', ''brand'', ''name'', ''variant'');
      v_i := null;
      if (v_e ->> ''part_id'') ~ ''^[0-9a-f]{12}$'' then
        select (ord - 1)::int into v_i
          from jsonb_array_elements(v_parts) with ordinality as p(part, ord)
         where p.part ->> ''partId'' = v_e ->> ''part_id''
         limit 1;
      elsif (v_e ->> ''part_index'') ~ ''^[0-9]+$'' then
        v_i := (v_e ->> ''part_index'')::int;
      end if;
      continue when v_i is null or v_parts -> v_i is null;
      -- Only over the value the reviewer corrected. Anything else means the
      -- part changed since (or the new queue already wrote it in).
      continue when coalesce(v_parts -> v_i ->> (v_e ->> ''field''), '''') is distinct from coalesce(v_e ->> ''from_value'', '''');
      continue when v_e ->> ''field'' in (''brand'', ''name'') and coalesce(v_parts -> v_i ->> ''refId'', '''') <> '''';
      if v_e ->> ''field'' = ''variant'' and coalesce(v_e ->> ''to_value'', '''') = '''' then
        v_parts := jsonb_set(v_parts, array[v_i::text], (v_parts -> v_i) - ''variant'');
      else
        v_parts := jsonb_set(v_parts, array[v_i::text, v_e ->> ''field''], to_jsonb(coalesce(v_e ->> ''to_value'', '''')));
      end if;
    end loop;
    if v_parts is distinct from r.parts_snapshot then
      update public.builds set parts_snapshot = v_parts where id = r.id;
      v_n := v_n + 1;
    end if;
  end loop;
  raise notice ''corrections written into parts_snapshot on % build(s)'', v_n;
end $$;

-- 4. backfill -----------------------------------------------------------
update public.builds
   set changes_notified_count = jsonb_array_length(edit_history)
 where jsonb_typeof(edit_history) = ''array''
   and (status = ''approved'' or user_id is null);

-- 5. the trigger --------------------------------------------------------
-- Which entries are a reviewer''s changes: the same rule as
-- PartIds.changes() in js/part-ids.js — an added or removed part, or a
-- correction (a field, and a part_id or part_index). Change both together.
create or replace function public.notify_build_changes()
returns trigger
language plpgsql
security definer
set search_path to ''public''
as $function$
declare
  v_hist jsonb := coalesce(new.edit_history, ''[]''::jsonb);
  v_len int;
  v_from int;
  v_e jsonb;
  v_lines text[] := ''{}'';
  v_text text;
  v_preview text;
begin
  if tg_op = ''INSERT'' then
    if not public.is_trusted_backend() then
      new.changes_notified_count := 0;
    end if;
    return new;
  end if;
  if jsonb_typeof(v_hist) <> ''array'' then
    new.changes_notified_count := old.changes_notified_count;
    return new;
  end if;
  v_len := jsonb_array_length(v_hist);

  -- Only a reviewer or the backend moves the counter.
  if not (public.is_admin() or public.is_trusted_backend()) then
    new.changes_notified_count := old.changes_notified_count;
    return new;
  end if;

  -- Nobody to tell. Moving the counter means a build claimed later does
  -- not announce changes made before its builder had it.
  if new.user_id is null then
    new.changes_notified_count := v_len;
    return new;
  end if;

  -- Held until the build is live: the builder hears once, with the
  -- approval, not once per correction during review.
  if new.status is distinct from ''approved'' then
    new.changes_notified_count := least(greatest(coalesce(old.changes_notified_count, 0), 0), v_len);
    return new;
  end if;

  v_from := least(greatest(coalesce(old.changes_notified_count, 0), 0), v_len);
  new.changes_notified_count := v_len;
  if v_from >= v_len then
    return new;
  end if;

  for v_e in
    select e from jsonb_array_elements(v_hist) with ordinality as t(e, ord)
     where ord > v_from order by ord
  loop
    continue when jsonb_typeof(v_e) <> ''object'';
    if v_e ->> ''kind'' in (''part_added'', ''part_removed'') then
      v_text := case when v_e ->> ''kind'' = ''part_added'' then ''Added '' else ''Removed '' end
        || coalesce(nullif(btrim(concat_ws('' '', v_e -> ''part'' ->> ''brand'', v_e -> ''part'' ->> ''name'')), ''''), ''a part'');
    elsif v_e ? ''field'' and (v_e ? ''part_id'' or v_e ? ''part_index'') then
      v_text := ''Corrected the ''
        || case v_e ->> ''field'' when ''variant'' then ''variant note'' when ''category'' then ''section'' else v_e ->> ''field'' end
        || case when coalesce(v_e ->> ''to_value'', '''') = '''' then '''' else '' to “'' || (v_e ->> ''to_value'') || ''”'' end;
    else
      continue;   -- the ''resubmit'' marker, a contested flag, anything else
    end if;
    v_lines := v_lines || v_text;
  end loop;

  if coalesce(array_length(v_lines, 1), 0) = 0 then
    return new;
  end if;
  -- A reviewer changing their own build has nothing to be told.
  if auth.uid() is not distinct from new.user_id then
    return new;
  end if;

  v_preview := array_to_string(v_lines, '' · '');
  if length(v_preview) > 280 then
    v_preview := left(v_preview, 279) || ''…'';
  end if;

  insert into public.notifications (user_id, actor_id, kind, build_id, preview, email_sent_at)
  values (new.user_id, null, ''changes'', new.id, v_preview, now());   -- see EMAIL above
  return new;
end;
$function$;

-- Not an API endpoint. Postgres grants EXECUTE to PUBLIC on every new
-- function; see CLAUDE.md on default privileges re-granting.
revoke execute on function public.notify_build_changes() from public, anon, authenticated;

drop trigger if exists trg_zz_notify_build_changes on public.builds;
create trigger trg_zz_notify_build_changes
  before insert or update on public.builds
  for each row
  execute function public.notify_build_changes();"}', 'admin_part_changes', 'ag.gamboa94@gmail.com', NULL, NULL);
INSERT INTO "supabase_migrations"."schema_migrations" ("version", "statements", "name", "created_by", "idempotency_key", "rollback") VALUES ('20261013223126', '{"-- magazine_category_enum.sql (PR #167). One new products.category value,
-- ordered right after magwell. Its own migration: Postgres refuses to use an
-- enum value in the transaction that added it.
alter type public.product_category add value if not exists ''magazine'' after ''magwell'';"}', 'magazine_category_enum', 'ag.gamboa94@gmail.com', NULL, NULL);
INSERT INTO "supabase_migrations"."schema_migrations" ("version", "statements", "name", "created_by", "idempotency_key", "rollback") VALUES ('20261013223718', '{"-- magazine_category.sql (PR #167), applied after magazine_category_enum
-- (20261013223126), with the TTI spec sheet filled in the same transaction
-- (values from Taran Tactical''s product page, supplied by Alex 2026-10-13).
--
-- WHAT.
--   magazine_specs                  the magazine spec sheet
--   magazine_frame_requirements     which frames a magazine fits (p_fits:
--                                   \"frames\", the same shape as a magwell''s)
--   spec_field_rules                the magazine''s approved field list
--   products.restricted_states      states a part cannot ship to — a product
--                                   field, not a magazine one
--   create_product()                restricted_states accepted and checked;
--                                   a magazine''s style and capacity refused
--                                   in words; magazine: frames fits rule
--   the TTI part                    tti-xmacro-completed-mag-w-basepad moves
--                                   from basepad to magazine

-- ── magazines ───────────────────────────────────────────────────────────────
create table public.magazine_specs (
  product_id          uuid primary key,
  category            public.product_category not null default ''magazine'',
  capacity            integer,   -- rounds, as the maker states it
  caliber             text,      -- as the maker writes it: \"9mm Luger\", \".380 ACP\"
  mag_style           text,      -- Flush | Finger Extension | Extended
  fits_models         text,      -- the models the maker says it fits, in the maker''s words
  not_compatible_with text,      -- models the maker explicitly rules out
  body_material       text,      -- \"Steel\"; deliberately NOT tied to products.material,
                                 -- which may describe the basepad as well
  witness_holes       text,      -- as the maker states it: \"Yes\", \"5, 10, 15\"
  included_extras     text,      -- \"Extra X-Series baseplate\"
  constraint magazine_specs_category check (category = ''magazine''),
  constraint magazine_specs_capacity check (capacity is null or capacity > 0),
  constraint magazine_specs_mag_style check (mag_style is null or mag_style in (''Flush'', ''Finger Extension'', ''Extended'')),
  constraint magazine_specs_product_fkey foreign key (product_id, category)
    references public.products (id, category) on delete cascade
);

-- Which frames a magazine fits — the fits-with rule a magazine may send to
-- create_product() as \"frames\", written here exactly as a magwell''s goes to
-- magwell_frame_requirements. Zero rows means no claim, not \"fits none\"; a
-- \"which mag fits my P365\" tool is what this is for, and it is not built yet.
create table public.magazine_frame_requirements (
  magazine_product_id uuid not null references public.products (id) on delete cascade,
  frame_product_id    uuid not null references public.products (id) on delete cascade,
  source              text default ''manufacturer'',
  compatibility_note  text,
  primary key (magazine_product_id, frame_product_id)
);
create index magazine_frame_requirements_frame_idx on public.magazine_frame_requirements (frame_product_id);

alter table public.magazine_specs enable row level security;
alter table public.magazine_frame_requirements enable row level security;
revoke all on public.magazine_specs, public.magazine_frame_requirements from public, anon, authenticated;
grant select on public.magazine_specs, public.magazine_frame_requirements to anon, authenticated;
create policy magazine_specs_public_read on public.magazine_specs for select to anon, authenticated using (true);
create policy magazine_frame_requirements_public_read on public.magazine_frame_requirements for select to anon, authenticated using (true);

-- ── rules (the approved field list) ─────────────────────────────────────────
insert into public.spec_field_rules (category, field, requirement, only_when_field, only_when_values, label, sort_order) values
  (''magazine'', ''capacity'',            ''required'', null, null, ''Capacity (rounds)'',   10),
  (''magazine'', ''caliber'',             ''required'', null, null, ''Caliber'',             20),
  (''magazine'', ''mag_style'',           ''required'', null, null, ''Style'',               30),
  (''magazine'', ''fits_models'',         ''required'', null, null, ''Fits models'',         40),
  (''magazine'', ''not_compatible_with'', ''optional'', null, null, ''Not compatible with'', 50),
  (''magazine'', ''body_material'',       ''optional'', null, null, ''Body material'',       60),
  (''magazine'', ''witness_holes'',       ''optional'', null, null, ''Witness holes'',       70),
  (''magazine'', ''included_extras'',     ''optional'', null, null, ''Included extras'',     80);

-- ── products.restricted_states ──────────────────────────────────────────────
-- The states a part cannot be shipped to, as two-letter postal codes. A
-- product field: a magazine today, anything tomorrow. NULL is \"no
-- restriction\"; the CHECK refuses an empty list, a NULL element and anything
-- outside the 50 states and DC. create_product() refuses the same in words,
-- before the row. anon reads products through column grants, so the new
-- column is granted explicitly (as part_type was).
alter table public.products add column restricted_states text[];
alter table public.products add constraint products_restricted_states_codes check (
  restricted_states is null or (
    cardinality(restricted_states) > 0
    and array_position(restricted_states, null) is null
    and restricted_states <@ array[''AL'',''AK'',''AZ'',''AR'',''CA'',''CO'',''CT'',''DE'',''DC'',''FL'',''GA'',''HI'',''ID'',''IL'',''IN'',''IA'',''KS'',''KY'',''LA'',''ME'',''MD'',''MA'',''MI'',''MN'',''MS'',''MO'',''MT'',''NE'',''NV'',''NH'',''NJ'',''NM'',''NY'',''NC'',''ND'',''OH'',''OK'',''OR'',''PA'',''RI'',''SC'',''SD'',''TN'',''TX'',''UT'',''VT'',''VA'',''WA'',''WV'',''WI'',''WY'']::text[]
  ));
grant select (restricted_states) on public.products to anon, authenticated;
comment on column public.products.restricted_states is
  ''Two-letter codes of the US states (or DC) this part cannot be shipped to. NULL = no restriction. The part page prints \"Not available in: …\" above the buy button.'';

-- ── create_product(): restated from sight_values_in_words.sql (applied) ──────
-- Changes, and nothing else: restricted_states accepted, normalised and
-- checked; a magazine''s mag_style and capacity refused in words; the
-- magazine: frames fits-with rule, written to magazine_frame_requirements;
-- restricted_states in the result (so a dry run shows it).
create or replace function public.create_product(
  p_product jsonb, p_variants jsonb, p_specs jsonb default null, p_fits jsonb default null,
  p_build_id uuid default null, p_part_index integer default null, p_dry_run boolean default false)
returns jsonb
language plpgsql security definer set search_path = ''''
as $fn$
declare
  c_awin_affid   constant text   := ''2959345'';   -- Gunforma''s Awin publisher id; public, it is in every live link
  c_product_keys constant text[] := array[''brand'',''name'',''category'',''platforms'',''slug'',''url'',''description'',''family'',''material'',''material_family'',''fitment_notes'',''build_warning'',''build_notes'',''weight_oz'',''fitment_confidence'',''internal_notes'',''part_type'',''restricted_states''];
  c_variant_keys constant text[] := array[''color'',''finish'',''sku'',''upc'',''msrp'',''image_url'',''gallery'',''variant_label'',''optic_cut'',''handedness'',''notes'',''is_default'',''manual_safety_variant'',''reticle'',''reticle_color'',''battery_type'',''mount_system'',''bundle'',''clamp_style'',''clamp_rail_type'',''clamp'',''partner_slug'',''url'',''affiliate_url'',''links'',''use_in_build''];
  c_link_keys    constant text[] := array[''partner_slug'',''url'',''affiliate_url'',''op_mpn'',''op_gtin'',''op_merchant_product_id'',''notes''];
  -- the 50 states and DC, as USPS writes them: what products.restricted_states
  -- may hold (the table''s products_restricted_states_codes CHECK is the same list)
  c_state_codes  constant text[] := array[''AL'',''AK'',''AZ'',''AR'',''CA'',''CO'',''CT'',''DE'',''DC'',''FL'',''GA'',''HI'',''ID'',''IL'',''IN'',''IA'',''KS'',''KY'',''LA'',''ME'',''MD'',''MA'',''MI'',''MN'',''MS'',''MO'',''MT'',''NE'',''NV'',''NH'',''NJ'',''NM'',''NY'',''NC'',''ND'',''OH'',''OK'',''OR'',''PA'',''RI'',''SC'',''SD'',''TN'',''TX'',''UT'',''VT'',''VA'',''WA'',''WV'',''WI'',''WY''];
  p jsonb; s jsonb; f jsonb; v jsonb; l jsonb; r jsonb; v_result jsonb; v_status jsonb;
  v_category public.product_category; v_want public.product_category; v_platforms text[];
  v_platform_id uuid; v_platform_name text; v_kind text; v_len numeric; v_lengths text;
  v_brand_id uuid; v_brand_name text; v_brand_created boolean := false;
  v_product_id uuid; v_slug text; v_name text; v_confidence public.fitment_confidence;
  v_i int := 0; v_bad text; v_n int; v_key text;
  v_variant_id uuid; v_build_variant uuid; v_links jsonb; v_partner_id uuid; v_other_id uuid;
  v_mid text; v_aff text; v_aff_mid text;
  v_axes text; v_vslug text; v_vbase text; v_part jsonb;
  v_tbl regclass; v_rule_fields text[]; v_collist text; v_has_specs boolean := false;
  v_warn text[] := ''{}'';
  v_vr jsonb;
  v_allowed text;
  v_states text[];
begin
  if not (public.is_admin() or public.is_trusted_backend()) then
    raise exception ''create_product: admin or service_role only'' using errcode = ''42501'';
  end if;
  if p_product is null or jsonb_typeof(p_product) <> ''object'' then
    raise exception ''create_product: p_product must be an object'';
  end if;
  p := public.jsonb_strip_blank(p_product);
  if p ? ''installation_difficulty'' or p ? ''best_for'' then
    raise exception ''create_product: installation_difficulty and best_for are no longer entered. Existing values stay where they are; leave these out.'';
  end if;
  select string_agg(k, '', '') into v_bad from jsonb_object_keys(p) k where k <> all (c_product_keys);
  if v_bad is not null then raise exception ''create_product: unknown product field(s): %'', v_bad; end if;
  v_name := btrim(coalesce(p->>''name'', ''''));
  if btrim(coalesce(p->>''brand'', '''')) = '''' or v_name = '''' then
    raise exception ''create_product: brand and name are required'';
  end if;
  if p->>''category'' is null then raise exception ''create_product: category is required''; end if;
  v_category := (p->>''category'')::public.product_category;
  v_confidence := coalesce((p->>''fitment_confidence'')::public.fitment_confidence, ''unverified'');

  -- Other Parts: what the part is, in two or three words, is its one extra
  -- fact (products.part_type). Only that category carries one; the table
  -- rule products_part_type_other says the same, and this says it in words.
  if v_category::text = ''other'' and coalesce(btrim(p->>''part_type''), '''') = '''' then
    raise exception ''create_product: an Other Part needs a part type: two or three words saying what it is (e.g. \"thumb ledge\")'';
  elsif v_category::text <> ''other'' and p ? ''part_type'' then
    raise exception ''create_product: a part type is only for Other Parts; a % is its own category'', v_category;
  end if;

  -- Capacity-restricted states: the two-letter codes of states this part
  -- cannot ship to, on any category (a 20-round magazine today). Upper-cased
  -- and de-duplicated; anything that is not one of the 50 states or DC is
  -- refused by name. An empty list is no restriction at all (NULL).
  if p ? ''restricted_states'' then
    if jsonb_typeof(p->''restricted_states'') <> ''array'' then
      raise exception ''create_product: restricted_states must be a list of two-letter US state codes, e.g. [\"CA\", \"NY\"]'';
    end if;
    v_states := array(select distinct upper(btrim(x)) from jsonb_array_elements_text(p->''restricted_states'') x
                       where btrim(x) <> '''' order by 1);
    select string_agg(x, '', '' order by x) into v_bad from unnest(v_states) x where x <> all (c_state_codes);
    if v_bad is not null then
      raise exception ''create_product: restricted_states: % is not a US state. Use the two-letter postal codes (CA, NY, …), or DC.'', v_bad;
    end if;
    if cardinality(v_states) = 0 then v_states := null; end if;
  end if;

  -- ── platform: explicit, never defaulted ───────────────────────────────────
  if jsonb_typeof(p->''platforms'') is distinct from ''array'' or jsonb_array_length(p->''platforms'') = 0 then
    raise exception ''create_product: send at least one platform (e.g. \"platforms\": [\"p365\"]). Nothing defaults: without one the part never appears in the builder.'';
  end if;
  v_platforms := array(select distinct x from jsonb_array_elements_text(p->''platforms'') x order by x);
  select string_agg(x, '', '') into v_bad from unnest(v_platforms) x where not exists (select 1 from public.platforms pl where pl.slug = x);
  if v_bad is not null then
    raise exception ''create_product: unknown platform(s): %. Known: %'', v_bad,
      (select string_agg(slug, '', '' order by slug) from public.platforms) using errcode = ''foreign_key_violation'';
  end if;
  if v_category in (''slide'', ''barrel'') and cardinality(v_platforms) <> 1 then
    raise exception ''create_product: a % belongs to exactly one platform; this one names %: %. Send one.'',
      v_category, cardinality(v_platforms), array_to_string(v_platforms, '', '');
  end if;
  select string_agg(pl.name, '', '' order by pl.name) into v_bad from public.platforms pl
   where pl.slug = any (v_platforms) and not pl.is_live;
  if v_bad is not null then
    v_warn := v_warn || (''Not live yet: '' || v_bad || ''. The part is saved and appears when the platform launches.'');
  end if;

  if p->>''url'' is null then
    raise exception ''create_product: the source URL (the product page the data came from) is required'';
  end if;
  if p_variants is null or jsonb_typeof(p_variants) <> ''array'' or jsonb_array_length(p_variants) = 0 then
    raise exception ''create_product: at least one variant is required'';
  end if;
  if (p_build_id is null) <> (p_part_index is null) or p_part_index < 0 then
    raise exception ''create_product: p_build_id and p_part_index must be supplied together'';
  end if;

  select m.id, m.name into v_brand_id, v_brand_name from public.manufacturers m
   where lower(m.name) = lower(btrim(p->>''brand'')) or m.slug = public.slugify(p->>''brand'')
   order by m.created_at limit 1;
  if v_brand_id is null then
    insert into public.manufacturers (slug, name) values (public.slugify(p->>''brand''), btrim(p->>''brand''))
    returning id, name into v_brand_id, v_brand_name;
    v_brand_created := true;
  end if;

  -- The slug is the product''s URL for good. Brand is prefixed unless the name
  -- already starts with it. Pass \"slug\" to choose it by hand.
  v_slug := coalesce(nullif(btrim(p->>''slug''), ''''),
    public.slugify(case when left(lower(v_name), length(v_brand_name)) = lower(v_brand_name)
                        then v_name else v_brand_name || '' '' || v_name end));
  if exists (select 1 from public.products where slug = v_slug) then
    raise exception ''create_product: a product with slug \"%\" already exists. To add a colour or option to it, use create_variant.'', v_slug using errcode = ''unique_violation'';
  end if;
  if exists (select 1 from public.products where brand_id = v_brand_id and lower(name) = lower(v_name)) then
    raise exception ''create_product: % already has a product named \"%\". To add a colour or option to it, use create_variant.'', v_brand_name, v_name using errcode = ''unique_violation'';
  end if;

  insert into public.products (slug, category, brand_id, name, family, url, description, material, material_family,
                               fitment_notes, build_warning, build_notes, weight_oz, fitment_confidence, part_type, restricted_states)
  values (v_slug, v_category, v_brand_id, v_name, p->>''family'', p->>''url'', p->>''description'', p->>''material'', p->>''material_family'',
          p->>''fitment_notes'', p->>''build_warning'', p->>''build_notes'', (p->>''weight_oz'')::numeric, ''unverified'', btrim(p->>''part_type''), v_states)
  returning id into v_product_id;
  -- fitment_confidence is set at the end, once the part is known to be approved

  if p ? ''internal_notes'' then
    insert into public.product_internal (product_id, internal_notes) values (v_product_id, p->>''internal_notes'');
  end if;

  insert into public.product_platforms (product_id, platform_id)
  select v_product_id, pl.id from public.platforms pl where pl.slug = any (v_platforms);

  -- ── spec sheet ────────────────────────────────────────────────────────────
  -- Accepted keys are the category''s spec_field_rules fields and nothing else.
  -- Only supplied keys are named in the INSERT, so column defaults survive.
  s := public.jsonb_strip_blank(p_specs);
  v_tbl := to_regclass(''public.'' || quote_ident(v_category::text || ''_specs''));
  v_rule_fields := array(select fr.field from public.spec_field_rules fr where fr.category = v_category order by fr.sort_order);
  if s <> ''{}''::jsonb then
    if v_tbl is null then raise exception ''create_product: a % has no spec sheet; leave p_specs out'', v_category; end if;
    select string_agg(k, '', '') into v_bad from jsonb_object_keys(s) k where k <> all (v_rule_fields);
    if v_bad is not null then
      raise exception ''create_product: spec sheet: no rule for field(s): %. Fields for a %: %'', v_bad, v_category, array_to_string(v_rule_fields, '', '');
    end if;

    -- a sight''s three fixed lists. Checked here so an admin reads the
    -- allowed values, not the name of a sight_specs CHECK constraint. The
    -- same lists are those CHECKs (supabase/add_categories.sql) and
    -- SIGHT_CHOICES in gunforma-admin-part.html; change all three together.
    if v_category::text = ''sight'' then
      foreach v_key in array array[''sight_position'', ''height'', ''sight_type''] loop
        v_allowed := case v_key when ''sight_position'' then ''front, rear, set''
                                when ''height''         then ''standard, suppressor''
                                else                       ''night, fiber, night-fiber, plain'' end;
        if s ? v_key and not (s->>v_key = any (string_to_array(v_allowed, '', ''))) then
          raise exception ''create_product: a sight''''s % must be one of: %. \"%\" is not one of them.'',
            case v_key when ''sight_position'' then ''position'' when ''height'' then ''height'' else ''type'' end,
            v_allowed, s->>v_key;
        end if;
      end loop;
    end if;

    -- a magazine''s style is one of three, and its capacity is a count of
    -- rounds. Both refused here in words; the style list is also
    -- magazine_specs'' CHECK and MAG_CHOICES in gunforma-admin-part.html.
    -- Compared as text so nothing here casts ''magazine'' to the enum.
    if v_category::text = ''magazine'' then
      if s ? ''mag_style'' and not (s->>''mag_style'' = any (array[''Flush'', ''Finger Extension'', ''Extended''])) then
        raise exception ''create_product: a magazine''''s style must be one of: Flush, Finger Extension, Extended. \"%\" is not one of them.'', s->>''mag_style'';
      end if;
      if s ? ''capacity'' and not ((s->>''capacity'') ~ ''^[1-9][0-9]*$'') then
        raise exception ''create_product: a magazine''''s capacity is a whole number of rounds, as the maker states it (\"17\"). \"%\" is not one.'', s->>''capacity'';
      end if;
    end if;

    -- platform: the product''s one platform. A disagreeing key is refused.
    if ''platform'' = any (v_rule_fields) then
      if s ? ''platform'' and s->>''platform'' <> v_platforms[1] then
        raise exception ''create_product: spec sheet platform \"%\" disagrees with the product''''s platform \"%\"'', s->>''platform'', v_platforms[1];
      end if;
      select pl.id, pl.name into v_platform_id, v_platform_name from public.platforms pl where pl.slug = v_platforms[1];
      s := (s - ''platform'') || jsonb_build_object(''platform_id'', v_platform_id);
    end if;
    if s ? ''footprint'' then
      select fp.id into v_other_id from public.footprints fp where fp.slug = s->>''footprint'';
      if v_other_id is null then
        raise exception ''create_product: spec sheet: no footprint \"%\". Known: %'', s->>''footprint'',
          (select string_agg(slug, '', '' order by slug) from public.footprints);
      end if;
      s := (s - ''footprint'') || jsonb_build_object(''footprint_id'', v_other_id);
    end if;

    -- material is one fact held in two places
    foreach v_key in array array[''housing_material'', ''material'', ''guide_rod_material''] loop
      if v_key = any (v_rule_fields) then
        if s ? v_key and p ? ''material'' and lower(btrim(s->>v_key)) <> lower(btrim(p->>''material'')) then
          raise exception ''create_product: material is one fact: the product says \"%\" but the spec sheet''''s % says \"%\"'', p->>''material'', v_key, s->>v_key;
        elsif not s ? v_key and p ? ''material'' then
          s := s || jsonb_build_object(v_key, p->>''material'');
        elsif s ? v_key and not p ? ''material'' then
          update public.products set material = s->>v_key where id = v_product_id;
        end if;
      end if;
    end loop;

    -- only-when fields whose condition holds must come with the sheet
    select string_agg(fr.field, '', '' order by fr.sort_order) into v_bad from public.spec_field_rules fr
     where fr.category = v_category and fr.requirement = ''required'' and fr.only_when_field is not null
       and (s ->> fr.only_when_field) = any (fr.only_when_values)
       and coalesce(btrim(s ->> fr.field), '''') = '''';
    if v_bad is not null then
      raise exception ''create_product: the % spec sheet needs % (it applies here because of %)'', v_category, v_bad,
        (select string_agg(distinct fr.only_when_field || '' = '' || (s ->> fr.only_when_field), '', '') from public.spec_field_rules fr
          where fr.category = v_category and fr.only_when_field is not null and fr.field = any (string_to_array(v_bad, '', '')));
    end if;

    -- slide / barrel length must be registered for that platform. Checked
    -- here so an admin reads a sentence, not the class trigger''s raw text.
    if v_category in (''slide'', ''barrel'') then
      v_kind := v_category::text;
      v_len  := (s ->> (v_kind || ''_length_in''))::numeric;
      if v_len is not null then
        if not exists (select 1 from public.platform_part_lengths ppl where ppl.platform_id = v_platform_id and ppl.part_kind = v_kind) then
          raise exception ''create_product: % % lengths are not registered yet. Add them to platform_part_lengths before adding a % for it.'',
            v_platform_name, v_kind, v_kind;
        end if;
        if not exists (select 1 from public.platform_part_lengths ppl
                        where ppl.platform_id = v_platform_id and ppl.part_kind = v_kind and ppl.length_in = v_len) then
          select string_agg(ppl.length_in::text, '', '' order by ppl.length_in) into v_lengths from public.platform_part_lengths ppl
           where ppl.platform_id = v_platform_id and ppl.part_kind = v_kind;
          raise exception ''create_product: no % % is registered at % in. Registered % lengths: %.'', v_platform_name, v_kind, v_len, v_kind, v_lengths;
        end if;
      end if;
    end if;

    -- a recoil spring fits one slide length. It has no platform rule of its
    -- own, so the length must be registered for one of the part''s platforms.
    if v_category::text = ''recoil_spring'' and s ? ''slide_length_in'' then
      v_len := (s ->> ''slide_length_in'')::numeric;
      if not exists (select 1 from public.platform_part_lengths ppl join public.platforms pl on pl.id = ppl.platform_id
                      where pl.slug = any (v_platforms) and ppl.part_kind = ''slide'' and ppl.length_in = v_len) then
        select string_agg(distinct ppl.length_in::text, '', '' order by ppl.length_in::text) into v_lengths
          from public.platform_part_lengths ppl join public.platforms pl on pl.id = ppl.platform_id
         where pl.slug = any (v_platforms) and ppl.part_kind = ''slide'';
        raise exception ''create_product: no slide length of % in is registered for %. Registered slide lengths: %.'',
          v_len, array_to_string(v_platforms, '', ''), coalesce(v_lengths, ''none'');
      end if;
    end if;

    -- columns the table itself declares NOT NULL without a default
    select string_agg(a.attname::text, '', '') into v_bad from pg_catalog.pg_attribute a
     where a.attrelid = v_tbl and a.attnum > 0 and not a.attisdropped and a.attnotnull and not a.atthasdef
       and a.attname::text not in (''product_id'', ''category'') and not s ? (a.attname::text);
    if v_bad is not null then
      raise exception ''create_product: the % spec sheet needs: %'', v_category, replace(replace(v_bad, ''footprint_id'', ''footprint''), ''platform_id'', ''platform'');
    end if;

    s := s || jsonb_build_object(''product_id'', v_product_id, ''category'', v_category);
    select string_agg(quote_ident(k), '', '') into v_collist from jsonb_object_keys(s) k;
    execute format(''insert into %s (%s) select %s from jsonb_populate_record(null::%s, $1)'', v_tbl, v_collist, v_collist, v_tbl) using s;
    v_has_specs := true;
  end if;

  -- ── variants ──────────────────────────────────────────────────────────────
  -- The loop lives in create_variants_for_product(), shared with
  -- add_variants(): one copy of how a variant object becomes a variant.
  v_vr := public.create_variants_for_product(v_product_id, v_slug, p_variants, ''create_product'');
  v_build_variant := (v_vr->>''build_variant'')::uuid;

  if exists (select 1 from public.product_variants pv where pv.product_id = v_product_id and pv.is_default
               and (pv.primary_image_url is null or pv.msrp is null)) then
    raise exception ''create_product: the default variant needs a photo and an MSRP'';
  end if;

  -- ── fits-with rules ───────────────────────────────────────────────────────
  f := public.jsonb_strip_blank(p_fits);
  for v_key, r in select e.key, e.value from jsonb_each(f) e loop
    if not ((v_category = ''light''   and v_key = ''light_compatibility'')
         or (v_category = ''optic''   and v_key = ''adapter_footprints'')
         or (v_category = ''barrel''  and v_key = ''slides'')
         or (v_category = ''slide''   and v_key = ''barrels'')
         or (v_category = ''magwell'' and v_key = ''frames'')
         or (v_category::text = ''magazine'' and v_key = ''frames'')
         or (v_category = ''frame''   and v_key = ''magwells'')) then
      raise exception ''create_product: fits-with rule \"%\" does not apply to a %. (light: light_compatibility; optic: adapter_footprints; barrel: slides; slide: barrels; magwell: frames; magazine: frames; frame: magwells)'', v_key, v_category;
    end if;
    if jsonb_typeof(r) <> ''array'' then raise exception ''create_product: fits-with rule \"%\" must be a list'', v_key; end if;
    -- these four reference the <category>_specs row, not products
    if v_key in (''light_compatibility'',''adapter_footprints'',''slides'',''barrels'') and not v_has_specs then
      raise exception ''create_product: fits-with rules for a % need its spec sheet filled in first'', v_category;
    end if;
    for l in select value from jsonb_array_elements(r) loop
      if jsonb_typeof(l) = ''string'' then l := jsonb_build_object(''product'', l #>> ''{}''); end if;
      l := public.jsonb_strip_blank(l);
      if v_key = ''light_compatibility'' then
        select string_agg(k, '', '') into v_bad from jsonb_object_keys(l) k
         where k <> all (array[''rail_type'',''fitment_type'',''key_or_adapter'',''gun_make'',''gun'',''gun_model_text'',''confirmed'',''notes'']);
        if v_bad is not null then raise exception ''create_product: light_compatibility: unknown field(s): %'', v_bad; end if;
        v_other_id := null;
        if l ? ''gun'' then
          select g.id into v_other_id from public.guns g where g.slug = l->>''gun'';
          if v_other_id is null then raise exception ''create_product: light_compatibility: no gun \"%\"'', l->>''gun''; end if;
        end if;
        insert into public.light_compatibility (light_product_id, rail_type, fitment_type, key_or_adapter, gun_make, gun_id, gun_model_text, confirmed, notes)
        values (v_product_id, l->>''rail_type'', (l->>''fitment_type'')::public.light_fitment_type, l->>''key_or_adapter'', l->>''gun_make'',
                v_other_id, l->>''gun_model_text'', coalesce((l->>''confirmed'')::boolean, false), l->>''notes'');
      elsif v_key = ''adapter_footprints'' then
        select string_agg(k, '', '') into v_bad from jsonb_object_keys(l) k where k <> all (array[''footprint'',''plate_included'',''notes'']);
        if v_bad is not null then raise exception ''create_product: adapter_footprints: unknown field(s): %'', v_bad; end if;
        if not l ? ''plate_included'' then raise exception ''create_product: adapter_footprints: say whether the plate is included''; end if;
        select fp.id into v_other_id from public.footprints fp where fp.slug = l->>''footprint'';
        if v_other_id is null then raise exception ''create_product: adapter_footprints: no footprint \"%\"'', l->>''footprint''; end if;
        insert into public.optic_adapter_footprints (optic_product_id, footprint_id, plate_included, notes)
        values (v_product_id, v_other_id, (l->>''plate_included'')::boolean, l->>''notes'');
      else
        select string_agg(k, '', '') into v_bad from jsonb_object_keys(l) k where k <> all (array[''product'',''source'',''compatibility_note'']);
        if v_bad is not null then raise exception ''create_product: %: unknown field(s): %'', v_key, v_bad; end if;
        v_want := case v_key when ''slides'' then ''slide'' when ''barrels'' then ''barrel'' when ''frames'' then ''frame'' else ''magwell'' end;
        select pr.id into v_other_id from public.products pr where pr.slug = l->>''product'' and pr.category = v_want;
        if v_other_id is null then
          raise exception ''create_product: %: there is no % with slug \"%\"'', v_key, v_want, l->>''product'';
        end if;
        if v_key in (''slides'',''barrels'') then
          insert into public.barrel_slide_requirements (barrel_product_id, slide_product_id, source, compatibility_note)
          values (case when v_key = ''slides'' then v_product_id else v_other_id end,
                  case when v_key = ''slides'' then v_other_id else v_product_id end,
                  l->>''source'', l->>''compatibility_note'');
        elsif v_category::text = ''magazine'' then
          -- a magazine''s frames: its own table, the same shape as a magwell''s
          insert into public.magazine_frame_requirements (magazine_product_id, frame_product_id, source, compatibility_note)
          values (v_product_id, v_other_id, coalesce(l->>''source'', ''manufacturer''), l->>''compatibility_note'');
        elsif l ? ''source'' then
          insert into public.magwell_frame_requirements (magwell_product_id, frame_product_id, source, compatibility_note)
          values (case when v_key = ''frames'' then v_product_id else v_other_id end,
                  case when v_key = ''frames'' then v_other_id else v_product_id end,
                  l->>''source'', l->>''compatibility_note'');
        else
          insert into public.magwell_frame_requirements (magwell_product_id, frame_product_id, compatibility_note)
          values (case when v_key = ''frames'' then v_product_id else v_other_id end,
                  case when v_key = ''frames'' then v_other_id else v_product_id end,
                  l->>''compatibility_note'');
        end if;
      end if;
    end loop;
  end loop;

  -- ── things the admin should know, but that do not block ───────────────────
  if v_category = ''slide'' and not f ? ''barrels'' then
    select string_agg(distinct pr.slug, '', '') into v_bad
      from public.barrel_slide_requirements b join public.products pr on pr.id = b.barrel_product_id;
    if v_bad is not null then
      v_warn := v_warn || (''These barrels only fit the slides listed for them, so they will show as NOT fitting this slide: '' || v_bad);
    end if;
  end if;
  if v_category = ''frame'' and not f ? ''magwells'' then
    select string_agg(distinct pr.slug, '', '') into v_bad
      from public.magwell_frame_requirements b join public.products pr on pr.id = b.magwell_product_id;
    if v_bad is not null then
      v_warn := v_warn || (''These magwells only fit the frames listed for them, so they will show as NOT fitting this frame: '' || v_bad);
    end if;
  end if;

  -- ── swap the build''s pending custom part for this product ─────────────────
  -- variantSpecs is not written into the snapshot here: its formula lives in
  -- js/variant-label.js and _variant-label.mjs, and a third copy in SQL would
  -- drift. The build page reads the spec line from the live variant.
  if p_build_id is not null then
    select b.parts_snapshot -> p_part_index into v_part from public.builds b where b.id = p_build_id for update;
    if not found then raise exception ''create_product: no build %'', p_build_id; end if;
    if v_part is null then raise exception ''create_product: build has no part at index %'', p_part_index; end if;
    if (v_part->>''pending'')::boolean is not true or v_part->>''refId'' is not null then
      raise exception ''create_product: part % (\"%\") on that build is not a pending custom part'', p_part_index, v_part->>''name'';
    end if;
    if v_build_variant is null then
      select pv.id into v_build_variant from public.product_variants pv where pv.product_id = v_product_id and pv.is_default;
    end if;
    update public.builds b set parts_snapshot = jsonb_set(b.parts_snapshot, array[p_part_index::text],
        v_part
        || jsonb_strip_nulls(jsonb_build_object(''name'', v_name, ''brand'', v_brand_name, ''refId'', v_product_id,
             ''imageUrl'', pv.primary_image_url, ''variantId'', pv.id, ''variantColor'', pv.color,
             ''variantLabel'', pv.variant_label, ''variantFinish'', pv.finish))
        || jsonb_build_object(''pending'', false)
        -- Other Parts (stored as `misc`) is the catch-all: a part typed there
        -- takes the product''s own category, so it renders in its real section
        -- (the DMP recoil spring under Recoil Springs). Every other section
        -- keeps the category it was saved under.
        || case when v_part->>''category'' = ''misc'' then jsonb_build_object(''category'', v_category::text) else ''{}''::jsonb end)
    from public.product_variants pv
    where b.id = p_build_id and pv.id = v_build_variant;
  end if;

  -- ── completeness, and the confidence it allows ────────────────────────────
  v_status := public.product_data_status(v_product_id);
  if v_confidence <> ''unverified'' then
    if not (v_status->>''approved'')::boolean then
      raise exception ''create_product: fitment confidence \"%\" needs an approved part. Still missing: %'',
        v_confidence, (select string_agg(x, '', '') from jsonb_array_elements_text(v_status->''missing'') x);
    end if;
    update public.products set fitment_confidence = v_confidence where id = v_product_id;
  end if;

  v_result := jsonb_build_object(
    ''product_id'', v_product_id, ''slug'', v_slug, ''category'', v_category,
    ''brand'', v_brand_name, ''brand_created'', v_brand_created, ''build_relinked'', p_build_id is not null,
    ''has_spec_sheet'', v_has_specs, ''fitment_confidence'', v_confidence, ''warnings'', to_jsonb(v_warn),
    ''restricted_states'', to_jsonb(v_states),
    ''variants'', (select jsonb_agg(jsonb_build_object(''id'', pv.id, ''slug'', pv.slug, ''label'', pv.variant_label, ''default'', pv.is_default,
                    ''photos'', (select count(*) from public.variant_images vi where vi.variant_id = pv.id),
                    ''links'', (select count(*) from public.affiliate_links al where al.variant_id = pv.id),
                    -- one entry per retailer link: tracked_url is the link the buy
                    -- button will use, null when none was built (no commission)
                    ''retailers'', coalesce((select jsonb_agg(jsonb_build_object(''partner'', pa.slug, ''partner_name'', pa.name,
                                     ''url'', al.url, ''tracked_url'', al.affiliate_url) order by pa.slug, al.url)
                                   from public.affiliate_links al join public.partners pa on pa.id = al.partner_id
                                  where al.variant_id = pv.id), ''[]''::jsonb))
                  order by pv.is_default desc, pv.slug)
                 from public.product_variants pv where pv.product_id = v_product_id))
    || v_status;

  if p_dry_run then
    raise exception ''create_product: dry run, nothing was written'' using errcode = ''P0DRY'', detail = v_result::text;
  end if;
  return v_result;
end;
$fn$;

comment on function public.create_product(jsonb, jsonb, jsonb, jsonb, uuid, integer, boolean) is
  ''Admin / service_role only. Creates one product in one transaction: brand (found or created), product, platforms, spec sheet (keys from spec_field_rules; a sight''''s three lists and a magazine''''s style and capacity refused in words), variants with photos and retailer links (Awin links built), fits-with rules (magazine: frames), restricted_states (two-letter codes, checked), and optionally re-links a build''''s pending custom part. Returns product_data_status(); p_dry_run raises P0DRY with the result in DETAIL.'';

-- grants: create or replace keeps them; restated so this file says the whole
-- of what is live.
revoke all on function public.create_product(jsonb, jsonb, jsonb, jsonb, uuid, integer, boolean) from public, anon;
grant execute on function public.create_product(jsonb, jsonb, jsonb, jsonb, uuid, integer, boolean) to authenticated, service_role;

-- ── the TTI part: basepad -> magazine ───────────────────────────────────────
-- Exactly one product, by slug. Its basepad_specs row (basepad_type
-- completed-mag, fits_mag_type 17rd-xmacro, capacity_change 3) is NOT
-- deleted — nothing in this file deletes.
update public.products set category = ''magazine''
 where slug = ''tti-xmacro-completed-mag-w-basepad'' and category = ''basepad'';

do $tti$
declare n int;
begin
  select count(*) into n from public.products where slug = ''tti-xmacro-completed-mag-w-basepad'' and category = ''magazine'';
  if n <> 1 then
    raise exception ''magazine_category: expected exactly one product at slug tti-xmacro-completed-mag-w-basepad under magazine after the move, found %'', n;
  end if;
end $tti$;

insert into public.magazine_specs (product_id, category)
select id, category from public.products where slug = ''tti-xmacro-completed-mag-w-basepad'';

-- ── the TTI sheet, filled in the same transaction so the part never drops ──
-- off the site. Values from Taran Tactical''s product page
-- (https://tarantacticalinnovations.com/sig-x-macro-completed-magazine-w-tti-versatile-basepad/),
-- supplied by Alex 2026-10-13. restricted_states stays NULL: the page lists none.
update public.magazine_specs
   set capacity = 20,
       caliber = ''9mm'',
       mag_style = ''Extended'',
       fits_models = ''P365-XMACRO, also fits all P365 9mm models'',
       body_material = ''Steel'',
       witness_holes = ''Rear witness holes'',
       included_extras = ''TTI Versatile Basepad installed (factory 17rd mag, +3)''
 where product_id = (select id from public.products where slug = ''tti-xmacro-completed-mag-w-basepad'');

-- Refuse the whole transaction unless the part reads approved afterwards.
do $chk$
declare st jsonb;
begin
  st := public.product_data_status((select id from public.products where slug = ''tti-xmacro-completed-mag-w-basepad''));
  if not coalesce((st->>''approved'')::boolean, false) then
    raise exception ''magazine_category: the TTI part would not be approved after the move. Missing: %'', st->>''missing'';
  end if;
end $chk$;"}', 'magazine_category', 'ag.gamboa94@gmail.com', NULL, NULL);

